(332,'additionalhtmltopofbody','<!-- AI Chatbot Floating Bubble -->\r\n<style>\r\n    .ai-chat-bubble {\r\n        position: fixed;\r\n        bottom: 24px;\r\n        right: 24px;\r\n        z-index: 9999;\r\n        font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, sans-serif;\r\n    }\r\n    .ai-chat-btn {\r\n        width: 56px;\r\n        height: 56px;\r\n        background: linear-gradient(135deg, #3b82f6, #6366f1);\r\n        border: none;\r\n        border-radius: 50%;\r\n        cursor: pointer;\r\n        font-size: 24px;\r\n        color: white;\r\n        box-shadow: 0 4px 16px rgba(59,130,246,0.4);\r\n        transition: transform 0.2s;\r\n    }\r\n    .ai-chat-btn:hover { transform: scale(1.1); }\r\n    .ai-chat-box {\r\n        display: none;\r\n        position: absolute;\r\n        bottom: 70px;\r\n        right: 0;\r\n        width: 340px;\r\n        height: 450px;\r\n        background: #0f172a;\r\n        border-radius: 16px;\r\n        border: 1px solid #334155;\r\n        box-shadow: 0 20px 40px rgba(0,0,0,0.5);\r\n        overflow: hidden;\r\n    }\r\n    .ai-chat-box.active { display: block; }\r\n    .ai-chat-header {\r\n        background: #1e293b;\r\n        padding: 14px 18px;\r\n        color: #f1f5f9;\r\n        font-weight: 600;\r\n        font-size: 14px;\r\n        display: flex;\r\n        justify-content: space-between;\r\n        align-items: center;\r\n    }\r\n    .ai-chat-close {\r\n        background: none;\r\n        border: none;\r\n        color: #94a3b8;\r\n        cursor: pointer;\r\n        font-size: 18px;\r\n    }\r\n    .ai-chat-messages {\r\n        height: 320px;\r\n        overflow-y: auto;\r\n        padding: 14px;\r\n    }\r\n  .ai-msg {\r\n    padding: 8px 12px;\r\n    border-radius: 10px;\r\n    margin-bottom: 8px;\r\n    max-width: 85%;\r\n    word-wrap: break-word;\r\n    font-size: 13px;\r\n    line-height: 1.6;\r\n    white-space: pre-line;\r\n}\r\n    .ai-user { background: #3b82f6; color: white; margin-left: auto; }\r\n    .ai-bot { background: #1e293b; color: #e2e8f0; }\r\n    .ai-chat-input {\r\n        display: flex;\r\n        padding: 10px;\r\n        border-top: 1px solid #334155;\r\n    }\r\n    .ai-chat-input input {\r\n        flex: 1;\r\n        padding: 10px 14px;\r\n        border-radius: 20px;\r\n        border: 1px solid #334155;\r\n        background: #1e293b;\r\n        color: #f1f5f9;\r\n        font-size: 13px;\r\n    }\r\n    .ai-chat-input button {\r\n        margin-left: 8px;\r\n        padding: 10px 16px;\r\n        background: #3b82f6;\r\n        color: white;\r\n        border: none;\r\n        border-radius: 20px;\r\n        cursor: pointer;\r\n        font-size: 13px;\r\n    }\r\n</style>\r\n\r\n<div class=\"ai-chat-bubble\">\r\n    <button class=\"ai-chat-btn\" onclick=\"toggleChat()\">🤖</button>\r\n    <div class=\"ai-chat-box\" id=\"aiChatBox\">\r\n        <div class=\"ai-chat-header\">\r\n            <span>🤖 AI Assistant</span>\r\n            <button class=\"ai-chat-close\" onclick=\"toggleChat()\">✕</button>\r\n        </div>\r\n        <div class=\"ai-chat-messages\" id=\"aiMessages\"></div>\r\n        <div class=\"ai-chat-input\">\r\n            <input type=\"text\" id=\"aiInput\" placeholder=\"Ketik pertanyaan...\" onkeypress=\"if(event.key===\'Enter\') aiSend()\">\r\n            <button onclick=\"aiSend()\">Kirim</button>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<script>\r\n    function toggleChat() {\r\n        document.getElementById(\'aiChatBox\').classList.toggle(\'active\');\r\n    }\r\n    function aiAddMsg(text, type) {\r\n        var d = document.getElementById(\'aiMessages\');\r\n        var m = document.createElement(\'div\');\r\n        m.className = \'ai-msg ai-\' + type;\r\n        m.textContent = text;\r\n        d.appendChild(m);\r\n        d.scrollTop = d.scrollHeight;\r\n    }\r\n    async function aiSend() {\r\n        var input = document.getElementById(\'aiInput\');\r\n        var msg = input.value.trim();\r\n        if (!msg) return;\r\n        aiAddMsg(msg, \'user\');\r\n        input.value = \'\';\r\n        aiAddMsg(\'...\', \'bot\');\r\n        try {\r\n            var r = await fetch(\'/chatbot.php\', { method: \'POST\', headers: {\'Content-Type\': \'application/x-www-form-urlencoded\'}, body: \'message=\' + encodeURIComponent(msg) });\r\n            var d = await r.json();\r\n            document.querySelectorAll(\'.ai-bot\').forEach(function(el) {\r\n                if (el.textContent === \'...\') el.textContent = d.reply;\r\n            });\r\n        } catch(e) {\r\n            document.querySelectorAll(\'.ai-bot\').forEach(function(el) {\r\n                if (el.textContent === \'...\') el.textContent = \'Error: Gagal terhubung.\';\r\n            });\r\n        }\r\n    }\r\n</script>'),
