(1873,2,1780407966,NULL,'additionalhtmlhead','<!-- Font Awesome 6 (CDN Standar) -->\r\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0-beta3/css/all.min.css\">','<!-- Font Awesome untuk Kopere -->\r\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0-beta3/css/all.min.css\">'),
(1874,2,1780408131,NULL,'additionalhtmlhead','<style>\r\n    /* Font Awesome fallback - Ikon dasar untuk Kopere */\r\n    .fa, .fas, .far, .fal, .fab, .fad {\r\n        font-family: \"Font Awesome 6 Free\", \"Font Awesome 6 Brands\" !important;\r\n        font-weight: 900;\r\n    }\r\n    \r\n    /* Ikon spesifik yang digunakan Kopere */\r\n    .fa-area-chart:before {\r\n        content: \"\\f1fe\";\r\n    }\r\n    .fa-users:before {\r\n        content: \"\\f0c0\";\r\n    }\r\n    .fa-cog:before {\r\n        content: \"\\f013\";\r\n    }\r\n    .fa-dashboard:before {\r\n        content: \"\\f625\";\r\n    }\r\n    .fa-school:before {\r\n        content: \"\\f549\";\r\n    }\r\n    .fa-book:before {\r\n        content: \"\\f02d\";\r\n    }\r\n    .fa-user:before {\r\n        content: \"\\f007\";\r\n    }\r\n    .fa-group:before {\r\n        content: \"\\f0c0\";\r\n    }\r\n    .fa-docs:before {\r\n        content: \"\\f15c\";\r\n    }\r\n    .fa-article:before {\r\n        content: \"\\f15c\";\r\n    }\r\n    .fa-speed:before {\r\n        content: \"\\f0e4\";\r\n    }\r\n    .fa-backup:before {\r\n        content: \"\\f187\";\r\n    }\r\n    .fa-permissions:before {\r\n        content: \"\\f023\";\r\n    }\r\n    .fa-settings:before {\r\n        content: \"\\f013\";\r\n    }\r\n    .fa-logo_dev:before {\r\n        content: \"\\f121\";\r\n    }\r\n    .fa-about:before {\r\n        content: \"\\f05a\";\r\n    }\r\n</style>','<!-- Font Awesome 6 (CDN Standar) -->\r\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0-beta3/css/all.min.css\">'),
(1875,2,1780408306,NULL,'additionalhtmlhead','<style>\r\n    /* Force semua ikon Font Awesome */\r\n    [class^=\"fa-\"], [class*=\" fa-\"] {\r\n        font-family: \"Font Awesome 6 Free\" !important;\r\n        font-weight: 900 !important;\r\n        display: inline-block !important;\r\n        font-style: normal !important;\r\n        font-variant: normal !important;\r\n        text-rendering: auto !important;\r\n        line-height: 1 !important;\r\n    }\r\n    \r\n    /* Mapping ikon yang hilang */\r\n    .fa-area-chart:before {\r\n        content: \"\\f1fe\" !important;\r\n    }\r\n    .fa-users:before, .fa-group:before {\r\n        content: \"\\f0c0\" !important;\r\n    }\r\n    .fa-cog:before, .fa-settings:before {\r\n        content: \"\\f013\" !important;\r\n    }\r\n    .fa-dashboard:before {\r\n        content: \"\\f625\" !important;\r\n    }\r\n    .fa-docs:before, .fa-article:before {\r\n        content: \"\\f15c\" !important;\r\n    }\r\n    .fa-speed:before {\r\n        content: \"\\f0e4\" !important;\r\n    }\r\n    .fa-backup:before {\r\n        content: \"\\f187\" !important;\r\n    }\r\n</style>','<style>\r\n    /* Font Awesome fallback - Ikon dasar untuk Kopere */\r\n    .fa, .fas, .far, .fal, .fab, .fad {\r\n        font-family: \"Font Awesome 6 Free\", \"Font Awesome 6 Brands\" !important;\r\n        font-weight: 900;\r\n    }\r\n    \r\n    /* Ikon spesifik yang digunakan Kopere */\r\n    .fa-area-chart:before {\r\n        content: \"\\f1fe\";\r\n    }\r\n    .fa-users:before {\r\n        content: \"\\f0c0\";\r\n    }\r\n    .fa-cog:before {\r\n        content: \"\\f013\";\r\n    }\r\n    .fa-dashboard:before {\r\n        content: \"\\f625\";\r\n    }\r\n    .fa-school:before {\r\n        content: \"\\f549\";\r\n    }\r\n    .fa-book:before {\r\n        content: \"\\f02d\";\r\n    }\r\n    .fa-user:before {\r\n        content: \"\\f007\";\r\n    }\r\n    .fa-group:before {\r\n        content: \"\\f0c0\";\r\n    }\r\n    .fa-docs:before {\r\n        content: \"\\f15c\";\r\n    }\r\n    .fa-article:before {\r\n        content: \"\\f15c\";\r\n    }\r\n    .fa-speed:before {\r\n        content: \"\\f0e4\";\r\n    }\r\n    .fa-backup:before {\r\n        content: \"\\f187\";\r\n    }\r\n    .fa-permissions:before {\r\n        content: \"\\f023\";\r\n    }\r\n    .fa-settings:before {\r\n        content: \"\\f013\";\r\n    }\r\n    .fa-logo_dev:before {\r\n        content: \"\\f121\";\r\n    }\r\n    .fa-about:before {\r\n        content: \"\\f05a\";\r\n    }\r\n</style>'),
(1876,2,1780408488,NULL,'additionalhtmlhead','<!-- Google Material Icons -->\r\n<link href=\"https://fonts.googleapis.com/icon?family=Material+Icons\" rel=\"stylesheet\">\r\n\r\n<!-- Fallback jika Material Icons tidak muncul -->\r\n<style>\r\n    .kopere_dashboard-material-icon {\r\n        font-family: \'Material Icons\' !important;\r\n        font-weight: normal !important;\r\n        font-style: normal !important;\r\n        font-size: 24px !important;\r\n        display: inline-block !important;\r\n        line-height: 1 !important;\r\n        text-transform: none !important;\r\n        letter-spacing: normal !important;\r\n        word-wrap: normal !important;\r\n        white-space: nowrap !important;\r\n        direction: ltr !important;\r\n        -webkit-font-smoothing: antialiased !important;\r\n        text-rendering: optimizeLegibility !important;\r\n        -moz-osx-font-smoothing: grayscale !important;\r\n        font-feature-settings: \'liga\' !important;\r\n    }\r\n</style>','<style>\r\n    /* Force semua ikon Font Awesome */\r\n    [class^=\"fa-\"], [class*=\" fa-\"] {\r\n        font-family: \"Font Awesome 6 Free\" !important;\r\n        font-weight: 900 !important;\r\n        display: inline-block !important;\r\n        font-style: normal !important;\r\n        font-variant: normal !important;\r\n        text-rendering: auto !important;\r\n        line-height: 1 !important;\r\n    }\r\n    \r\n    /* Mapping ikon yang hilang */\r\n    .fa-area-chart:before {\r\n        content: \"\\f1fe\" !important;\r\n    }\r\n    .fa-users:before, .fa-group:before {\r\n        content: \"\\f0c0\" !important;\r\n    }\r\n    .fa-cog:before, .fa-settings:before {\r\n        content: \"\\f013\" !important;\r\n    }\r\n    .fa-dashboard:before {\r\n        content: \"\\f625\" !important;\r\n    }\r\n    .fa-docs:before, .fa-article:before {\r\n        content: \"\\f15c\" !important;\r\n    }\r\n    .fa-speed:before {\r\n        content: \"\\f0e4\" !important;\r\n    }\r\n    .fa-backup:before {\r\n        content: \"\\f187\" !important;\r\n    }\r\n</style>'),
