INSERT INTO `mdl_course_sections` VALUES
(6,2,0,'Pendahuluan','<p>pada modul lms ini memuat teori kolb tentang ELT</p>\n<p class=\"isSelectedEnd\">Teori Kolb menekankan bahwa pembelajaran terjadi melalui pengalaman. Siklus belajar Kolb terdiri dari empat tahap:</p>\n<ol start=\"1\" data-spread=\"false\">\n<li>Concrete Experience (Pengalaman Nyata)</li>\n<li>Reflective Observation (Refleksi)</li>\n<li>Abstract Conceptualization (Konseptualisasi)</li>\n<li>Active Experimentation (Eksperimen Aktif)</li>\n</ol>',1,'4,5,6,7,8,9,10',1,'{\"op\":\"&\",\"c\":[],\"showc\":[]}',NULL,NULL,1780043993),
(7,2,1,'Concrete Experience (Pengalaman Nyata)','',1,'11,12,13,14,16,17',1,NULL,NULL,NULL,1780043994),
(8,2,2,'Reflective Observation (Refleksi)','<p>Penjumlahan</p>\n<p></p>',1,'18,19,20,21,22,90',1,'{\"op\":\"&\",\"c\":[],\"showc\":[]}',NULL,NULL,1780043996),
