INSERT INTO `mdl_glossary_entries` VALUES
(1,4,12,'ALU (Arithmetic Logic Unit)','<p>Bagian dari CPU yang berfungsi membentuk fungsi-fungsi pengolahan data aritmatika (penjumlahan, pengurangan) dan logika (AND, OR, NOT).</p>',1,0,'',1780543414,1780543414,1,0,0,0,0,1),
(2,4,12,'Address Bus','<p>Jalur fisik (kumpulan kabel) yang digunakan CPU untuk mengirimkan alamat memori atau perangkat I/O yang ingin diakses</p>',1,0,'',1780543452,1780543452,1,0,0,0,0,1),
(3,4,12,'Cache Memory','<p data-path-to-node=\"5,3,0\">Memori berkecepatan tinggi yang ukurannya relatif kecil, ditempatkan di antara CPU dan memori utama untuk mempercepat akses data.</p>',1,0,'',1780543502,1780543502,1,0,0,0,0,1),
(4,4,12,'CPU (Central Processing Unit)','<p>Otak dari komputer yang mengeksekusi instruksi program dan mengendalikan semua komponen hardware lainnya.</p>',1,0,'',1780543523,1780543523,1,0,0,0,0,1),
(5,4,12,'Fetch-Execute Cycle','<p>Siklus dasar kerja komputer yang terdiri dari mengambil instruksi dari memori (<i data-path-to-node=\"8,3,0\" data-index-in-node=\"100\">fetch</i>), menerjemahkannya (<i data-path-to-node=\"8,3,0\" data-index-in-node=\"126\">decode</i>), dan menjalankannya (<i data-path-to-node=\"8,3,0\" data-index-in-node=\"155\">execute</i>).</p>',1,0,'',1780543546,1780543546,1,0,0,0,0,1),
(6,4,12,'RAM (Random Access Memory)','<p>Memori utama komputer yang bersifat <i data-path-to-node=\"11,2,0\" data-index-in-node=\"64\">volatile</i> (datanya hilang saat listrik padam), digunakan untuk menyimpan data dan program yang sedang diproses.</p>',1,0,'',1780543567,1780543567,1,0,0,0,0,1),
(7,4,12,'ROM (Read-Only Memory)','<p data-path-to-node=\"11,4,0\">Memori non-volatile yang datanya sudah diisi oleh pabrik dan umumnya hanya bisa dibaca, biasanya berisi instruksi dasar booting (BIOS).</p>',1,0,'',1780543593,1780543593,1,0,0,0,0,1),
(8,4,12,'System Bus','<p>Struktur sirkuit yang menghubungkan komponen-komponen utama komputer (CPU, Memori, I/O). Terdiri dari Data Bus, Address Bus, dan Control Bus.</p>',1,0,'',1780543610,1780543610,1,0,0,0,0,1);
