(21,'H5P.CoursePresentation','Course Presentation',1,27,17,1,1,1,'iframe','dist/h5p-course-presentation.js','dist/h5p-course-presentation.css','','[\n  {\n    \"name\": \"presentation\",\n    \"type\": \"group\",\n    \"importance\": \"high\",\n    \"widget\": \"coursepresentation\",\n    \"fields\": [\n      {\n        \"name\": \"slides\",\n        \"importance\": \"high\",\n        \"type\": \"list\",\n        \"entity\": \"slide\",\n        \"field\": {\n          \"name\": \"slide\",\n          \"importance\": \"high\",\n          \"type\": \"group\",\n          \"fields\": [\n            {\n              \"name\": \"elements\",\n              \"importance\": \"high\",\n              \"type\": \"list\",\n              \"entity\": \"element\",\n              \"field\": {\n                \"name\": \"element\",\n                \"importance\": \"high\",\n                \"type\": \"group\",\n                \"fields\": [\n                  {\n                    \"name\": \"x\",\n                    \"importance\": \"low\",\n                    \"type\": \"number\",\n                    \"widget\": \"none\"\n                  },\n                  {\n                    \"name\": \"y\",\n                    \"importance\": \"low\",\n                    \"type\": \"number\",\n                    \"widget\": \"none\"\n                  },\n                  {\n                    \"name\": \"width\",\n                    \"importance\": \"low\",\n                    \"type\": \"number\",\n                    \"widget\": \"none\",\n                    \"optional\": true\n                  },\n                  {\n                    \"name\": \"height\",\n                    \"importance\": \"low\",\n                    \"type\": \"number\",\n                    \"widget\": \"none\",\n                    \"optional\": true\n                  },\n                  {\n                    \"name\": \"action\",\n                    \"type\": \"library\",\n                    \"importance\": \"high\",\n                    \"options\": [\n                      \"H5P.AdvancedText 1.1\",\n                      \"H5P.Link 1.3\",\n                      \"H5P.Image 1.1\",\n                      \"H5P.Shape 1.0\",\n                      \"H5P.Video 1.6\",\n                      \"H5P.Audio 1.5\",\n                      \"H5P.Blanks 1.14\",\n                      \"H5P.SingleChoiceSet 1.11\",\n                      \"H5P.MultiChoice 1.16\",\n                      \"H5P.TrueFalse 1.8\",\n                      \"H5P.DragQuestion 1.15\",\n                      \"H5P.Summary 1.10\",\n                      \"H5P.DragText 1.10\",\n                      \"H5P.MarkTheWords 1.11\",\n                      \"H5P.Dialogcards 1.9\",\n                      \"H5P.ContinuousText 1.2\",\n                      \"H5P.ExportableTextArea 1.3\",\n                      \"H5P.Table 1.2\",\n                      \"H5P.InteractiveVideo 1.28\",\n                      \"H5P.TwitterUserFeed 1.0\",\n                      \"H5P.AudioRecorder 1.0\",\n                      \"H5P.MultiMediaChoice 0.3\"\n                    ],\n                    \"optional\": true\n                  },\n                  {\n                    \"name\": \"solution\",\n                    \"type\": \"text\",\n                    \"widget\": \"html\",\n                    \"optional\": true,\n                    \"label\": \"Comments\",\n                    \"importance\": \"low\",\n                    \"description\": \"The comments are shown when the user displays the suggested answers for all slides.\",\n                    \"enterMode\": \"p\",\n                    \"tags\": [\n                      \"strong\",\n                      \"em\",\n                      \"del\",\n                      \"a\",\n                      \"ul\",\n                      \"ol\",\n                      \"h2\",\n                      \"h3\",\n                      \"hr\",\n                      \"pre\",\