(36,'H5P.IFrameEmbed','Iframe Embedder',1,0,29,1,1,1,'','iframe-embed.js','','','[\n  {\n    \"label\": \"Width\",\n    \"importance\": \"high\",\n    \"name\": \"width\",\n    \"type\": \"text\",\n    \"description\": \"Width of iFrame in CSS compliant format. Default: \\\"500px\\\"\"\n  },\n  {\n    \"label\": \"Minimum width\",\n    \"importance\": \"high\",\n    \"name\": \"minWidth\",\n    \"type\": \"text\",\n    \"description\": \"Minimum width of iFrame in CSS compliant format. Default: \\\"300px\\\"\"\n  },\n  {\n    \"label\": \"Height\",\n    \"name\": \"height\",\n    \"type\": \"text\",\n    \"description\": \"Height of iFrame in CSS compliant format. Default: \\\"500px\\\"\"\n  },\n  {\n    \"label\": \"Source\",\n    \"importance\": \"high\",\n    \"name\": \"source\",\n    \"type\": \"text\",\n    \"description\": \"URI to external document, or path to document found inside H5P (under /content)\"\n  },\n  {\n    \"name\": \"resizeSupported\",\n    \"type\": \"boolean\",\n    \"label\": \"Resize supported\",\n    \"importance\": \"medium\",\n    \"description\": \"If enabled, fullscreen button will be displayed, and H5P will be resized to fit its surroundings\",\n    \"default\": true\n  }\n]\n',NULL,NULL,NULL,NULL,NULL,NULL),
(37,'H5P.IVHotspot','Navigation Hotspot',1,2,26,0,1,0,'','scripts/iv-hotspot.js','styles/iv-hotspot.css','','[\n  {\n    \"name\": \"destination\",\n    \"label\": \"Destination\",\n    \"type\": \"group\",\n    \"importance\": \"high\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"type\",\n        \"label\": \"Type\",\n        \"type\": \"select\",\n        \"importance\": \"high\",\n        \"widget\": \"selectToggleFields\",\n        \"options\": [\n          {\n            \"value\": \"timecode\",\n            \"label\": \"Timecode\",\n            \"hideFields\": [\n              \"url\"\n            ]\n          },\n          {\n            \"value\": \"url\",\n            \"label\": \"Another page (URL)\",\n            \"hideFields\": [\n              \"time\"\n            ]\n          }\n        ],\n        \"default\": \"timecode\"\n      },\n      {\n        \"name\": \"time\",\n        \"type\": \"number\",\n        \"widget\": \"timecode\",\n        \"label\": \"Go To\",\n        \"importance\": \"high\",\n        \"description\": \"The target time the user will be taken to upon pressing the hotspot. Enter timecode in the format M:SS.\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"url\",\n        \"type\": \"group\",\n        \"label\": \"URL\",\n        \"importance\": \"high\",\n        \"widget\": \"linkWidget\",\n        \"optional\": true,\n        \"fields\": [\n          {\n            \"name\": \"protocol\",\n            \"type\": \"select\",\n            \"label\": \"Protocol\",\n            \"importance\": \"high\",\n            \"options\": [\n              {\n                \"value\": \"http://\",\n                \"label\": \"http://\"\n              },\n              {\n                \"value\": \"https://\",\n                \"label\": \"https://\"\n              },\n              {\n                \"value\": \"/\",\n                \"label\": \"(root relative)\"\n              },\n   