(56,'H5P.SimpleMultiChoice','Simple Multi Choice',1,1,22,0,1,0,'','dist/dist.js','dist/styles.css','','[\n  {\n    \"name\": \"question\",\n    \"label\": \"Question\",\n    \"importance\": \"high\",\n    \"type\": \"text\"\n  },\n  {\n    \"name\": \"inputType\",\n    \"label\": \"Multiple choice type\",\n    \"importance\": \"high\",\n    \"type\": \"select\",\n    \"options\": [\n      {\n        \"label\": \"Multiple answers\",\n        \"value\": \"checkbox\"\n      },\n      {\n        \"label\": \"Single answer\",\n        \"value\": \"radio\"\n      }\n    ],\n    \"default\": \"checkbox\"\n  },\n  {\n    \"name\": \"alternatives\",\n    \"label\": \"Answer alternatives\",\n    \"type\": \"list\",\n    \"importance\": \"high\",\n    \"entity\": \"Alternative\",\n    \"min\": 2,\n    \"field\": {\n      \"type\": \"group\",\n      \"name\": \"alternative\",\n      \"label\": \"Alternative\",\n      \"fields\": [\n        {\n          \"name\": \"text\",\n          \"label\": \"Text\",\n          \"importance\": \"high\",\n          \"type\": \"text\"\n        },\n        {\n          \"name\": \"feedback\",\n          \"type\": \"group\",\n          \"label\": \"Feedback\",\n          \"importance\": \"low\",\n          \"optional\": true,\n          \"fields\": [\n            {\n              \"name\": \"chosenFeedback\",\n              \"type\": \"text\",\n              \"widget\": \"html\",\n              \"label\": \"Message displayed if answer is selected\",\n              \"importance\": \"low\",\n              \"description\": \"Message will appear below the answer on \\\"continue\\\" if this answer is selected.\",\n              \"optional\": true,\n              \"tags\": [\n                \"strong\",\n                \"em\",\n                \"sub\",\n                \"sup\",\n                \"a\",\n                \"code\"\n              ]\n            },\n            {\n              \"name\": \"notChosenFeedback\",\n              \"type\": \"text\",\n              \"widget\": \"html\",\n              \"label\": \"Message displayed if answer is not selected\",\n              \"importance\": \"low\",\n              \"description\": \"Message will appear below the answer on \\\"continue\\\" if this answer is not selected.\",\n              \"optional\": true,\n              \"tags\": [\n                \"strong\",\n                \"em\",\n                \"sub\",\n                \"sup\",\n                \"a\",\n                \"code\"\n              ]\n            }\n          ]\n        }\n      ]\n    }\n  }\n]\n',NULL,NULL,NULL,NULL,NULL,NULL),
(57,'H5P.SingleChoiceSet','Single Choice Set',1,11,88,1,1,0,'iframe','scripts/stop-watch.js, scripts/sound-effects.js, scripts/xapi-event-builder.js, scripts/result-slide.js, scripts/single-choice-alternative.js, scripts/single-choice.js, scripts/single-choice-set.js','styles/single-choice-set.css','','[\n  {\n    \"name\": \"choices\",\n    \"type\": \"list\",\n    \"label\": \"List of questions\",\n    \"importance\": \"high\",\n    \"entity\": \"question\",\n    \"min\": 1,\n    \"defaultNum\": 2,\n    \"widgets\": [\n      {\n        \"name\": \"ListEditor\",\n        \"label\": \"Default\"\n      },\n      {\n        \"name\": \"SingleChoiceSetTextualEditor\",\n        \"label\": \"Textual\"\n      }\n    ],\n    \"field\": {\n      \"name\": \"choice\",\n      \"type\": \"group\",\n      \"isSubContent\": true,\n      \"label\": \"Question & alternatives\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"question\",\n          \"type\": \"text\",\n          \"widget\": \"html\",\n          \"tags\": [\n            \"p\",\n            \"br\",\n            \"strong\",\n            \"em\",\n            \"code\"\n          ],\n          \"label\": \"Question\",\n          \"importance\": \"high\"\n        },\n        {\n          \"name\": \"answers\",\n          \"type\": \"list\",\n          \"label\": \"Alternatives - first alternative is the correct one.\",\n          \"importance\": \"medium\",\n          \"entity\": \"answer\",\n          \"min\": 2,\n          \"max\": 4,\n          \"defaultNum\": 2,\n          \"field\": {\n            \"name\": \"answer\",\n            \"type\": \"text\",\n            \"widget\": \"html\",\n            \"tags\": [\n              \"p\",\n              \"br\",\n              \"strong\",\n              \"em\",\n              \"code\"\n            ],\n            \"label\": \"Alternative\",\n            \"importance\": \"medium\"\n          }\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"overallFeedback\",\n    \"type\": \"group\",\n    \"label\": \"Overall Feedback\",\n    \"importance\": \"low\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"overallFeedback\",\n        \"type\": \"list\",\n        \"widgets\": [\n          {\n            \"name\": \"RangeList\",\n            \"label\": \"Default\"\n          }\n        ],\n        \"importance\": \"high\",\n        \"label\": \"Define custom feedback for any score range\",\n        \"description\": \"Click the \\\"Add range\\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!\",\n        \"entity\": \"range\",\n        \"min\": 1,\n        \"defaultNum\": 1,\n        \"optional\": true,\n        \"field\": {\n          \"name\": \"overallFeedback\",\n          \"type\": \"group\",\n          \"importance\": \"low\",\n          \"fields\": [\n            {\n              \"name\": \"from\",\n              \"type\": \"number\",\n              \"label\": \"Score Range\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 0,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"to\",\n              \"type\": \"number\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 100,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"feedback\",\n              \"type\": \"text\",\n              \"label\": \"Feedback for defined score range\",\n              \"importance\": \"low\",\n              \"placeholder\": \"Fill in the feedback\",\n              \"optional\": true\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"fields\": [\n      {\n        \"name\": \"autoContinue\",\n        \"type\": \"boolean\",\n        \"label\": \"Auto continue\",\n        \"description\": \"Automatically go to next question when alternative is selected. This needs to be turned off to make the content fully accessible when using a screen reader.\",\n        \"default\": true\n      },\n      {\n        \"name\": \"timeoutCorrect\",\n        \"type\": \"number\",\n        \"label\": \"Timeout on correct answers\",\n        \"importance\": \"low\",\n        \"description\": \"Value in milliseconds\",\n        \"default\": 2000,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"autoContinue\",\n              \"equals\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"timeoutWrong\",\n        \"type\": \"number\",\n        \"label\": \"Timeout on wrong answers\",\n        \"importance\": \"low\",\n        \"description\": \"Value in milliseconds\",\n        \"default\": 3000,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"autoContinue\",\n              \"equals\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"soundEffectsEnabled\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable sound effects\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableRetry\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable retry button\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableSolutionsButton\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable show solution button\",\n        \"description\": \"This feature is not applicable when the new look and feel is enabled.\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"passPercentage\",\n        \"type\": \"number\",\n        \"label\": \"Pass percentage\",\n        \"description\": \"Percentage of Total score required for passing the quiz.\",\n        \"min\": 0,\n        \"max\": 100,\n        \"step\": 1,\n        \"default\": 100\n      }\n    ]\n  },\n  {\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"label\": \"Localize single choice set\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"name\": \"nextButtonLabel\",\n        \"type\": \"text\",\n        \"label\": \"Label for the \\\"Next\\\" button\",\n        \"importance\": \"low\",\n        \"default\": \"Next question\"\n      },\n      {\n        \"name\": \"nextButton\",\n        \"type\": \"text\",\n        \"label\": \"Visual label for the \\\"Next\\\" button\",\n        \"importance\": \"low\",\n        \"default\": \"Next\"\n      },\n      {\n        \"name\": \"showResultsButtonLabel\",\n        \"type\": \"text\",\n        \"label\": \"Label for the \\\"Show results\\\" button\",\n        \"importance\": \"low\",\n        \"default\": \"Show results\"\n      },\n      {\n        \"name\": \"retryButtonLabel\",\n        \"type\": \"text\",\n        \"label\": \"Label for the \\\"Retry\\\" button\",\n        \"importance\": \"low\",\n        \"default\": \"Retry\"\n      },\n      {\n        \"name\": \"solutionViewTitle\",\n        \"type\": \"text\",\n        \"label\": \"Title for the show solution view\",\n        \"importance\": \"low\",\n        \"default\": \"Solution list\"\n      },\n      {\n        \"name\": \"correctText\",\n        \"type\": \"text\",\n        \"label\": \"Readspeaker text for correct answer\",\n        \"importance\": \"low\",\n        \"default\": \"Correct!\"\n      },\n      {\n        \"name\": \"incorrectText\",\n        \"type\": \"text\",\n        \"label\": \"Readspeaker text for incorrect answer\",\n        \"importance\": \"low\",\n        \"default\": \"Incorrect!\"\n      },\n      {\n        \"name\": \"shouldSelect\",\n        \"type\": \"text\",\n        \"label\": \"Option should have been selected\",\n        \"importance\": \"low\",\n        \"default\": \"Should have been selected\"\n      },\n      {\n        \"name\": \"shouldNotSelect\",\n        \"type\": \"text\",\n        \"label\": \"Option should not have been selected\",\n        \"importance\": \"low\",\n        \"default\": \"Should not have been selected\"\n      },\n      {\n        \"name\": \"muteButtonLabel\",\n        \"type\": \"text\",\n        \"label\": \"Label for the \\\"mute\\\" button, to disable feedback sound\",\n        \"importance\": \"low\",\n        \"default\": \"Mute feedback sound\"\n      },\n      {\n        \"name\": \"closeButtonLabel\",\n        \"type\": \"text\",\n        \"label\": \"Label for the \\\"Close\\\" button\",\n        \"importance\": \"low\",\n        \"default\": \"Close\"\n      },\n      {\n        \"name\": \"slideOfTotal\",\n        \"type\": \"text\",\n        \"label\": \"Slide number text\",\n        \"importance\": \"low\",\n        \"description\": \"Announces current slide and total number of slides, variables are :num and :total\",\n        \"default\": \"Slide :num of :total\"\n      },\n      {\n        \"name\": \"scoreBarLabel\",\n        \"type\": \"text\",\n        \"label\": \"Textual representation of the score bar for those using a readspeaker\",\n        \"default\": \"You got :num out of :total points\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"solutionListQuestionNumber\",\n        \"type\": \"text\",\n        \"label\": \"Label for the question number in the solution list\",\n        \"importance\": \"low\",\n        \"description\": \"Announces current question index in solution list, variables are :num\",\n        \"default\": \"Question :num\"\n      },\n      {\n        \"name\": \"a11yShowSolution\",\n        \"type\": \"text\",\n        \"label\": \"Assistive technology description for \\\"Show Solution\\\" button\",\n        \"default\": \"Show the solution. The task will be marked with its correct solution.\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"a11yRetry\",\n        \"type\": \"text\",\n        \"label\": \"Assistive technology description for \\\"Retry\\\" button\",\n        \"default\": \"Retry the task. Reset all responses and start the task over again.\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"resultHeader\",\n        \"type\": \"text\",\n        \"label\": \"The main header of the result screen\",\n        \"default\": \"Your result:\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"totalScore\",\n        \"type\": \"text\",\n        \"label\": \"The score header of the result screen\",\n        \"default\": \":score of :maxScore correct\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"resultTableHeader\",\n        \"type\": \"text\",\n        \"label\": \"The Question header of the result screen table\",\n        \"default\": \"Question\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"resultScoreTableHeader\",\n        \"type\": \"text\",\n        \"label\": \"The Score header of the result screen table\",\n        \"default\": \"Score\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"correctAnswerIntroduction\",\n        \"type\": \"text\",\n        \"label\": \"Correct answer introduction\",\n        \"default\": \"Correct answer\",\n        \"importance\": \"low\"\n      }\n    ]\n  }\n]\n',NULL,1,28,NULL,NULL,NULL),
(58,'H5P.StandardPage','Standard page',1,5,22,0,1,0,'','standard-page.js','standard-page.css','','[\n  {\n    \"name\": \"elementList\",\n    \"label\": \"Elements\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"entity\": \"element\",\n    \"field\": {\n      \"name\": \"element\",\n      \"type\": \"library\",\n      \"label\": \"Element type\",\n      \"importance\": \"high\",\n      \"description\": \"Library for this page.\",\n      \"options\": [\n        \"H5P.Text 1.1\",\n        \"H5P.TextInputField 1.2\",\n        \"H5P.Image 1.1\",\n        \"H5P.Accordion 1.0\"\n      ]\n    }\n  },\n  {\n    \"name\": \"helpTextLabel\",\n    \"label\": \"Label for help text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Label for showing additional helpful information to the user.\",\n    \"default\": \"More information\"\n  },\n  {\n    \"name\": \"helpText\",\n    \"label\": \"Fill in additional help information\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Here you can fill in additional information for the user, which will be available when clicked.\",\n    \"enterMode\": \"p\",\n    \"optional\": true,\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  }\n]\n',NULL,1,28,NULL,NULL,NULL),
(59,'H5P.Summary','Summary',1,10,32,1,1,0,'iframe','js/stop-watch.js, js/xapi-event-builder.js, js/summary.js','css/summary.css','','[\n  {\n    \"name\": \"intro\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"label\": \"Introduction text\",\n    \"importance\": \"high\",\n    \"default\": \"Choose the correct statement.\",\n    \"description\": \"Will be displayed above the summary task.\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"common\": false\n  },\n  {\n    \"name\": \"summaries\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"widgets\": [\n      {\n        \"name\": \"ListEditor\",\n        \"label\": \"Default\"\n      },\n      {\n        \"name\": \"SummaryTextualEditor\",\n        \"label\": \"Textual\"\n      }\n    ],\n    \"label\": \"Summary\",\n    \"entity\": \"statements\",\n    \"max\": 100,\n    \"min\": 1,\n    \"field\": {\n      \"name\": \"statements\",\n      \"type\": \"group\",\n      \"label\": \"Set of statements\",\n      \"importance\": \"high\",\n      \"isSubContent\": true,\n      \"fields\": [\n        {\n          \"name\": \"summary\",\n          \"type\": \"list\",\n          \"label\": \"List of statements for the summary - the first statement is correct.\",\n          \"entity\": \"statement\",\n          \"importance\": \"medium\",\n          \"min\": 2,\n          \"field\": {\n            \"name\": \"text\",\n            \"type\": \"text\",\n            \"label\": \"Statement\",\n            \"importance\": \"medium\",\n            \"widget\": \"html\",\n            \"enterMode\": \"p\",\n            \"tags\": []\n          }\n        },\n        {\n          \"name\": \"tip\",\n          \"type\": \"group\",\n          \"label\": \"Tip\",\n          \"importance\": \"low\",\n          \"optional\": true,\n          \"fields\": [\n            {\n              \"name\": \"tip\",\n              \"label\": \"Tip text\",\n              \"importance\": \"low\",\n              \"type\": \"text\",\n              \"widget\": \"html\",\n              \"tags\": [\n                \"p\",\n                \"br\",\n                \"strong\",\n                \"em\",\n                \"code\"\n              ],\n              \"optional\": true\n            }\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"overallFeedback\",\n    \"type\": \"group\",\n    \"label\": \"Overall Feedback\",\n    \"importance\": \"low\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"overallFeedback\",\n        \"type\": \"list\",\n        \"widgets\": [\n          {\n            \"name\": \"RangeList\",\n            \"label\": \"Default\"\n          }\n        ],\n        \"importance\": \"high\",\n        \"label\": \"Define custom feedback for any score range\",\n        \"description\": \"Click the \\\"Add range\\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!\",\n        \"entity\": \"range\",\n        \"min\": 1,\n        \"defaultNum\": 1,\n        \"optional\": true,\n        \"field\": {\n          \"name\": \"overallFeedback\",\n          \"type\": \"group\",\n          \"importance\": \"low\",\n          \"fields\": [\n            {\n              \"name\": \"from\",\n              \"type\": \"number\",\n              \"label\": \"Score Range\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 0,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"to\",\n              \"type\": \"number\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 100,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"feedback\",\n              \"type\": \"text\",\n              \"label\": \"Feedback for defined score range\",\n              \"importance\": \"low\",\n              \"placeholder\": \"Fill in the feedback\",\n              \"optional\": true\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"solvedLabel\",\n    \"type\": \"text\",\n    \"label\": \"Text displayed before number of statements solved in the summary task.\",\n    \"importance\": \"low\",\n    \"default\": \"Progress:\",\n    \"description\": \"Will be displayed above the statements. Example: \'Progress: 2/5\'\",\n    \"common\": true\n  },\n  {\n    \"name\": \"scoreLabel\",\n    \"type\": \"text\",\n    \"label\": \"Text displayed before number of wrong statements selected in the summary task.\",\n    \"importance\": \"low\",\n    \"default\": \"Wrong answers:\",\n    \"description\": \"Will be displayed above the statements. Example: \'Wrong answers: 4\'\",\n    \"common\": true\n  },\n  {\n    \"name\": \"resultLabel\",\n    \"type\": \"text\",\n    \"label\": \"Summary feedback header\",\n    \"importance\": \"low\",\n    \"default\": \"Your result\",\n    \"description\": \"Will be displayed above the summary feedback.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"labelCorrect\",\n    \"type\": \"text\",\n    \"label\": \"Readspeaker text for correct answer\",\n    \"importance\": \"low\",\n    \"default\": \"Correct.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"labelIncorrect\",\n    \"type\": \"text\",\n    \"label\": \"Readspeaker text for announcing incorrect answer\",\n    \"importance\": \"low\",\n    \"default\": \"Incorrect! Please try again.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"alternativeIncorrectLabel\",\n    \"type\": \"text\",\n    \"label\": \"Readspeaker label for incorrect answer\",\n    \"importance\": \"low\",\n    \"default\": \"Incorrect\",\n    \"common\": true\n  },\n  {\n    \"name\": \"labelCorrectAnswers\",\n    \"type\": \"text\",\n    \"label\": \"Label list of correct answers\",\n    \"importance\": \"low\",\n    \"default\": \"Correct answers.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"tipButtonLabel\",\n    \"type\": \"text\",\n    \"label\": \"Label for the show tip button\",\n    \"importance\": \"low\",\n    \"default\": \"Show tip\",\n    \"common\": true\n  },\n  {\n    \"name\": \"scoreBarLabel\",\n    \"type\": \"text\",\n    \"label\": \"Textual representation of the score bar for those using a readspeaker\",\n    \"description\": \":num and :total are special keywords which are programmatically updated\",\n    \"default\": \"You got :num out of :total points\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"name\": \"progressText\",\n    \"type\": \"text\",\n    \"label\": \"Text used for readspeakers to communicate progress\",\n    \"description\": \":num and :total are special keywords which are programmatically updated\",\n    \"default\": \"Progress :num of :total\",\n    \"importance\": \"low\",\n    \"common\": true\n  }\n]\n',NULL,1,28,NULL,NULL,NULL),
