             \"importance\": \"medium\",\n              \"description\": \"YYYY,MM,DD (Minimum YYYY required)\",\n              \"optional\": true,\n              \"regexp\": {\n                \"pattern\": \"^-?\\\\d{1,}(,(1[012]|[0]?[1-9])(,([12][0-9]|3[01]|[0]?[1-9]))?)?$\"\n              }\n            },\n            {\n              \"name\": \"headline\",\n              \"type\": \"text\",\n              \"label\": \"Headline\",\n              \"importance\": \"medium\",\n              \"description\": \"Headline for the date entry\"\n            },\n            {\n              \"name\": \"text\",\n              \"type\": \"text\",\n              \"label\": \"Body text\",\n              \"importance\": \"medium\",\n              \"widget\": \"html\",\n              \"optional\": true,\n              \"description\": \"Body for the date entry\",\n              \"tags\": [\n                \"strong\",\n                \"em\",\n                \"del\",\n                \"a\",\n                \"ul\",\n                \"ol\",\n                \"h2\",\n                \"h3\",\n                \"hr\",\n                \"pre\",\n                \"code\"\n              ]\n            },\n            {\n              \"name\": \"tag\",\n              \"type\": \"text\",\n              \"label\": \"Tags\",\n              \"importance\": \"medium\",\n              \"description\": \"Enter Tags (categories)\",\n              \"optional\": true\n            },\n            {\n              \"name\": \"asset\",\n              \"type\": \"group\",\n              \"label\": \"Asset\",\n              \"importance\": \"low\",\n              \"description\": \"\",\n              \"optional\": true,\n              \"fields\": [\n                {\n                  \"name\": \"media\",\n                  \"type\": \"text\",\n                  \"label\": \"Media\",\n                  \"importance\": \"low\",\n                  \"description\": \"URL to the media (Twitter, YouTub