},\n            {\n              \"name\": \"endDate\",\n              \"type\": \"text\",\n              \"label\": \"End date\",\n              \"importance\": \"medium\",\n              \"description\": \"YYYY,MM,DD (Minimum YYYY required)\",\n              \"optional\": true,\n              \"regexp\": {\n                \"pattern\": \"^-?\\\\d{1,}(,(1[012]|[0]?[1-9])(,([12][0-9]|3[01]|[0]?[1-9]))?)?$\"\n              }\n            },\n            {\n              \"name\": \"headline\",\n              \"type\": \"text\",\n              \"label\": \"Headline\",\n              \"importance\": \"medium\",\n              \"description\": \"Era headline\"\n            },\n            {\n              \"name\": \"text\",\n              \"type\": \"text\",\n              \"label\": \"Text\",\n              \"importance\": \"medium\",\n              \"widget\": \"html\",\n              \"optional\": true,\n              \"description\": \"Era body\",\n              \"tags\": [\n                \"strong\",\n                \"em\",\n                \"del\",\n                \"a\",\n                \"ul\",\n                \"ol\",\n                \"hr\",\n                \"code\"\n              ]\n            },\n            {\n              \"name\": \"tag\",\n              \"type\": \"text\",\n              \"label\": \"Tag\",\n              \"importance\": \"medium\",\n              \"description\": \"Era tags (categories)\",\n              \"optional\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"language\",\n        \"type\": \"select\",\n        \"label\": \"Language\",\n        \"importance\": \"medium\",\n        \"optional\": true,\n        \"description\": \"The language of the user interface\",\n        \"options\": [\n          {\n            \"value\": \"af\",\n            \"label\": \"Afrikaans\"\n          },\n          {\n            \"value\": \"ar\",\n            \"label\": \"Arabic\"\n          },\n          {\n            \"value\": \"hy\",\n            \"label\": \"Armenian\"\n          },\n          {\n            \"value\": \"eu\",\n            \"label\": \"Basque\"\n          },\n          {\n            \"value\": \"bg\",\n            \"label\": \"Bulgarian\"\n          },\n          {\n            \"value\": \"ca\",\n            \"label\": \"Catalan\"\n          },\n          {\n            \"value\": \"zh-cn\",\n            \"label\": \"Chinese\"\n          },\n          {\n            \"value\": \"hr\",\n            \"label\": \"Croatian / Hrvatski\"\n          },\n          {\n            \"value\": \"cz\",\n            \"label\": \"Czech\"\n          },\n          {\n            \"value\": \"da\",\n            \"label\": \"Danish\"\n          },\n          {\n            \"value\": \"nl\",\n            \"label\": \"Dutch\"\n          },\n          {\n            \"value\": \"en\",\n            \"label\": \"English\"\n          },\n          {\n            \"value\": \"en-24hr\",\n            \"label\": \"English (24-hour time)\"\n          },\n          {\n            \"value\": \"eo\",\n            \"label\": \"Esperanto\"\n          },\n          {\n            \"value\": \"et\",\n            \"label\": \"Estonian\"\n          },\n          {\n            \"value\": \"fo\",\n            \"label\": \"Faroese\"\n          },\n          {\n            \"value\": \"fa\",\n            \"label\": \"Farsi\"\n          },\n          {\n            \"value\": \"fi\",\n            \"label\": \"Finnish\"\n          },\n          {\n            \"value\": \"fr\",\n            \"label\": \"French\"\n          },\n          {\n            \"value\": \"gl\",\n            \"label\": \"Galician\"\n          },\n          {\n            \"value\": \"ka\",\n            \"label\": \"Georgian\"\n          },\n          {\n            \"value\": \"de\",\n            \"label\": \"German / Deutsch\"\n          },\n          {\n            \"value\": \"el\",\n            \"label\": \"