(100,'H5P.Agamotto','Agamotto',1,6,11,1,1,0,'iframe','dist/h5p-agamotto.js','dist/h5p-agamotto.css','','[\n  {\n    \"name\": \"title\",\n    \"label\": \"Heading\",\n    \"importance\": \"high\",\n    \"type\": \"text\",\n    \"optional\": true,\n    \"placeholder\": \"Here you can add an optional heading.\",\n    \"description\": \"The heading you\'d like to show above the image\"\n  },\n  {\n    \"name\": \"items\",\n    \"type\": \"list\",\n    \"label\": \"Items\",\n    \"entity\": \"item\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\"\n      }\n    ],\n    \"importance\": \"medium\",\n    \"min\": 2,\n    \"max\": 50,\n    \"field\": {\n      \"name\": \"item\",\n      \"type\": \"group\",\n      \"label\": \"Item\",\n      \"importance\": \"low\",\n      \"expanded\": true,\n      \"fields\": [\n        {\n          \"name\": \"image\",\n          \"type\": \"library\",\n          \"label\": \"Image\",\n          \"importance\": \"low\",\n          \"options\": [\n            \"H5P.Image 1.1\"\n          ],\n          \"optional\": false\n        },\n        {\n          \"name\": \"labelText\",\n          \"label\": \"Label\",\n          \"importance\": \"low\",\n          \"type\": \"text\",\n          \"optional\": true,\n          \"description\": \"Optional label for a tick. Please make sure it\'s not too long, or it will be hidden.\"\n        },\n        {\n          \"name\": \"description\",\n          \"type\": \"text\",\n          \"importance\": \"low\",\n          \"widget\": \"html\",\n          \"label\": \"Description\",\n          \"optional\": true,\n          \"placeholder\": \"My image description ...\",\n          \"description\": \"Optional description for the image\",\n          \"enterMode\": \"p\",\n          \"tags\": [\n            \"strong\",\n            \"em\",\n            \"sub\",\n            \"sup\",\n            \"h3\",\n            \"h4\",\n            \"ul\",\n           