(122,'H5P.Column','Column',1,13,0,1,1,0,'iframe','scripts/h5p-column.js','styles/h5p-column.css','','[\n  {\n    \"name\": \"content\",\n    \"label\": \"List of Column Content\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"min\": 1,\n    \"entity\": \"content\",\n    \"field\": {\n      \"name\": \"content\",\n      \"type\": \"group\",\n      \"fields\": [\n        {\n          \"name\": \"content\",\n          \"type\": \"library\",\n          \"importance\": \"high\",\n          \"label\": \"Content\",\n          \"options\": [\n            \"H5P.Accordion 1.0\",\n            \"H5P.Agamotto 1.5\",\n            \"H5P.Audio 1.4\",\n            \"H5P.AudioRecorder 1.0\",\n            \"H5P.Blanks 1.12\",\n            \"H5P.Chart 1.2\",\n            \"H5P.Collage 0.3\",\n            \"H5P.CoursePresentation 1.22\",\n            \"H5P.Dialogcards 1.8\",\n            \"H5P.DocumentationTool 1.8\",\n            \"H5P.DragQuestion 1.13\",\n            \"H5P.DragText 1.8\",\n            \"H5P.Essay 1.2\",\n            \"H5P.GuessTheAnswer 1.4\",\n            \"H5P.Table 1.1\",\n            \"H5P.AdvancedText 1.1\",\n            \"H5P.IFrameEmbed 1.0\",\n            \"H5P.Image 1.1\",\n            \"H5P.ImageHotspots 1.8\",\n            \"H5P.ImageHotspotQuestion 1.8\",\n            \"H5P.ImageSlider 1.1\",\n            \"H5P.InteractiveVideo 1.22\",\n            \"H5P.Link 1.3\",\n            \"H5P.MarkTheWords 1.9\",\n            \"H5P.MemoryGame 1.3\",\n            \"H5P.MultiChoice 1.14\",\n            \"H5P.Questionnaire 1.3\",\n            \"H5P.QuestionSet 1.17\",\n            \"H5P.SingleChoiceSet 1.11\",\n            \"H5P.Summary 1.10\",\n            \"H5P.Timeline 1.1\",\n            \"H5P.TrueFalse 1.6\",\n            \"H5P.TwitterUserFeed 1.0\",\n            \"H5P.Video 1.5\"\n          ]\n        },\n        {\n          \"name\": \"useSeparator\",\n          \"type\": \"select\",\n          \"importance\": \"low\",\n          \"label\": \"Separate content with a horizontal ruler\",\n          \"default\": \"auto\",\n          \"options\": [\n            {\n              \"value\": \"auto\",\n              \"label\": \"Automatic (default)\"\n            },\n            {\n              \"value\": \"disabled\",\n              \"label\": \"Never use ruler above\"\n            },\n            {\n              \"value\": \"enabled\",\n              \"label\": \"Always use ruler above\"\n            }\n          ]\n        }\n      ]\n    }\n  }\n]\n',NULL,1,19,NULL,NULL,NULL),
(123,'H5P.InteractiveBook','Interactive Book',1,15,0,1,1,1,'iframe','dist/h5p-interactive-book.js','dist/h5p-interactive-book.css','','[\n  {\n    \"name\": \"showCoverPage\",\n    \"type\": \"boolean\",\n    \"label\": \"Enable book cover\",\n    \"description\": \"A cover that shows info regarding the book before access\",\n    \"importance\": \"low\",\n    \"default\": false\n  },\n  {\n    \"name\": \"bookCover\",\n    \"type\": \"group\",\n    \"label\": \"Cover Page\",\n    \"importance\": \"medium\",\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"showCoverPage\",\n          \"equals\": true\n        }\n      ]\n    },\n    \"fields\": [\n      {\n        \"name\": \"coverDescription\",\n        \"type\": \"text\",\n        \"widget\": \"html\",\n        \"label\": \"Cover description\",\n        \"importance\": \"medium\",\n        \"optional\": true,\n        \"description\": \"This text will be the description of your book.\",\n        \"default\": \"<p style=\\\"text-align: center;\\\"></p>\",\n        \"enterMode\": \"p\",\n        \"tags\": [\n          \"sub\",\n          \"sup\",\n          \"strong\",\n          \"em\",\n          \"p\",\n          \"code\",\n          \"u\",\n          \"del\",\n          \"a\",\n          \"ul\",\n          \"ol\",\n          \"h1\",\n          \"h2\",\n          \"h3\",\n          \"h4\",\n          \"h5\",\n          \"h6\",\n          \"pre\",\n          \"hr\",\n          \"table\"\n        ],\n        \"font\": {\n          \"size\": true,\n          \"color\": true,\n          \"background\": true\n        }\n      },\n      {\n        \"name\": \"coverMedium\",\n        \"type\": \"library\",\n        \"label\": \"Cover media\",\n        \"description\": \"Optional media to display on the cover.\",\n        \"optional\": true,\n        \"options\": [\n          \"H5P.Image 1.1\",\n          \"H5P.Video 1.6\"\n        ]\n      }\n    ]\n  },\n  {\n    \"name\": \"chapters\",\n    \"type\": \"list\",\n    \"label\": \"Pages\",\n    \"entity\": \"Page\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\"\n      }\n    ],\n    \"importance\": \"high\",\n    \"min\": 1,\n    \"max\": 50,\n    \"field\": {\n      \"name\": \"item\",\n      \"type\": \"group\",\n      \"label\": \"Item\",\n      \"importance\": \"low\",\n      \"expanded\": true,\n      \"fields\": [\n        {\n          \"label\": \"Page\",\n          \"name\": \"chapter\",\n          \"type\": \"library\",\n          \"options\": [\n            \"H5P.Column 1.22\"\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"importance\": \"low\",\n    \"label\": \"Behavioural settings\",\n    \"fields\": [\n      {\n        \"name\": \"baseColor\",\n        \"type\": \"text\",\n        \"label\": \"Base color\",\n        \"description\": \"Set the base color that will define the overall color scheme of the book. Please ensure a high enough contrast.\",\n        \"optional\": true,\n        \"widget\": \"colorSelector\",\n        \"default\": \"#1768c4\",\n        \"spectrum\": {\n          \"showInput\": true,\n          \"showInitial\": true,\n          \"showPalette\": true,\n          \"palette\": [\n            [\n              \"#1768C4\"\n            ],\n            [\n              \"#D9B323\"\n            ],\n            [\n              \"#D32F2F\"\n            ],\n            [\n              \"#1EB224\"\n            ],\n            [\n              \"#7E57C2\"\n            ]\n          ]\n        }\n      },\n      {\n        \"name\": \"defaultTableOfContents\",\n        \"type\": \"boolean\",\n        \"label\": \"Display table of contents as default\",\n        \"description\": \"When enabled the table of contents is showed when opening the book\",\n        \"default\": true\n      },\n      {\n        \"name\": \"progressIndicators\",\n        \"type\": \"boolean\",\n        \"label\": \"Display Progress Indicators\",\n        \"description\": \"When enabled there will be indicators per page showing the user if he is done with the page or not.\",\n        \"default\": true\n      },\n      {\n        \"name\": \"progressAuto\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable automatic progress\",\n        \"description\": \"If enabled a page without tasks is considered done when viewed. A page with tasks when all tasks are done. If disabled there will be a button at the bottom of every page for the user to click when done with the page.\",\n        \"default\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"progressIndicators\",\n              \"equals\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"displaySummary\",\n        \"type\": \"boolean\",\n        \"label\": \"Display summary\",\n        \"description\": \"When enabled the user can see a summary and submit the progress/answers\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableRetry\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable \\\"Restart\\\" button\",\n        \"description\": \"When enabled the user can initiate a restart on the summary page.\",\n        \"default\": true,\n        \"optional\": true\n      }\n    ]\n  },\n  {\n    \"name\": \"read\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Read\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Read\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"displayTOC\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Display \'Table of contents\'\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Display \'Table of contents\'\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"hideTOC\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Hide \'Table of contents\'\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Hide \'Table of contents\'\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"page\",\n    \"type\": \"text\",\n    \"label\": \"Label for page counter\",\n    \"importance\": \"low\",\n    \"default\": \"Page\",\n    \"common\": true\n  },\n  {\n    \"name\": \"next\",\n    \"type\": \"text\",\n    \"label\": \"Label for forwards navigation button\",\n    \"importance\": \"low\",\n    \"default\": \"Next\",\n    \"common\": true\n  },\n  {\n    \"name\": \"nextPage\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Next page\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Next page\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"previous\",\n    \"type\": \"text\",\n    \"label\": \"Label for backwards navigation button\",\n    \"importance\": \"low\",\n    \"default\": \"Previous\",\n    \"common\": true\n  },\n  {\n    \"name\": \"previousPage\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Previous page\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Previous page\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"chapterCompleted\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Page completed!\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Page completed!\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"partCompleted\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"@pages of @total completed\\\" (@pages and @total will be replaced by actual values)\",\n    \"importance\": \"low\",\n    \"default\": \"@pages of @total completed\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"incompleteChapter\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Incomplete page\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Incomplete page\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"navigateToTop\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Navigate to the top\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Navigate to the top\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"markAsFinished\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"I have finished this page\\\"\",\n    \"default\": \"I have finished this page\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"fullscreen\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Fullscreen button label\",\n    \"default\": \"Fullscreen\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"exitFullscreen\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Exit fullscreen button label\",\n    \"default\": \"Exit fullscreen\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"bookProgressSubtext\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Page progress in book\",\n    \"description\": \"\\\"@count\\\" will be replaced by page count, and \\\"@total\\\" with the total number of pages\",\n    \"default\": \"@count of @total pages\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"interactionsProgressSubtext\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Interaction progress\",\n    \"description\": \"\\\"@count\\\" will be replaced by interaction count, and \\\"@total\\\" with the total number of interactions\",\n    \"default\": \"@count of @total interactions\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"submitReport\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"Submit report\\\"\",\n    \"default\": \"Submit Report\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"restartLabel\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Label for \\\"restart\\\" button\",\n    \"default\": \"Restart\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"summaryHeader\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Summary header\",\n    \"default\": \"Summary\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"allInteractions\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"All interactions\\\"\",\n    \"default\": \"All interactions\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"unansweredInteractions\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"Unanswered interactions\\\"\",\n    \"default\": \"Unanswered interactions\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"scoreText\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Score\",\n    \"description\": \"\\\"@score\\\" will be replaced with current score, and \\\"@maxscore\\\" will be replaced with max achievable score\",\n    \"default\": \"@score / @maxscore\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"leftOutOfTotalCompleted\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Per page interactions completion\",\n    \"description\": \"\\\"@left\\\" will be replaced with remaining interactions, and \\\"@max\\\" will be replaced with total number of interactions on the page\",\n    \"default\": \"@left of @max interactions completed\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"noInteractions\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"No interactions\\\"\",\n    \"default\": \"No interactions\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"score\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"Score\\\"\",\n    \"default\": \"Score\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"summaryAndSubmit\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Label for \\\"Summary &amp; submit\\\" button\",\n    \"default\": \"Summary &amp; submit\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"noChapterInteractionBoldText\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"You have not interacted with any pages.\\\"\",\n    \"default\": \"You have not interacted with any pages.\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"noChapterInteractionText\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"You have to interact with at least one page before you can see the summary.\\\"\",\n    \"default\": \"You have to interact with at least one page before you can see the summary.\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"yourAnswersAreSubmittedForReview\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"Your answers are submitted for review!\\\"\",\n    \"default\": \"Your answers are submitted for review!\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"bookProgress\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Summary progress label\",\n    \"default\": \"Book progress\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"interactionsProgress\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Interactions progress label\",\n    \"default\": \"Interactions progress\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"totalScoreLabel\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Total score label\",\n    \"default\": \"Total score\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"a11y\",\n    \"type\": \"group\",\n    \"label\": \"Accessibility texts\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"name\": \"progress\",\n        \"type\": \"text\",\n        \"label\": \"Page progress textual alternative\",\n        \"description\": \"An alternative text for the visual page progress. @page and @total variables available.\",\n        \"default\": \"Page @page of @total.\"\n      },\n      {\n        \"name\": \"menu\",\n        \"type\": \"text\",\n        \"label\": \"Label for expanding/collapsing navigation menu\",\n        \"default\": \"Toggle navigation menu\"\n      }\n    ]\n  }\n]\n',NULL,1,28,NULL,'https://h5p.org/content-types/interactive-book',NULL),
(124,'H5P.KewArCode','KewAr Code',1,2,2,1,1,0,'iframe','dist/h5p-kewar-code.js','dist/h5p-kewar-code.css','','[\n  {\n    \"name\": \"introduction\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"label\": \"Introductory text\",\n    \"importance\": \"medium\",\n    \"optional\": true,\n    \"description\": \"This text can optionally be presented along with your code.\",\n    \"enterMode\": \"div\",\n    \"tags\": [\n      \"sub\",\n      \"sup\",\n      \"strong\",\n      \"em\",\n      \"p\",\n      \"code\",\n      \"u\",\n      \"del\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h1\",\n      \"h2\",\n      \"h3\",\n      \"h4\",\n      \"h5\",\n      \"h6\",\n      \"pre\",\n      \"hr\",\n      \"table\"\n    ],\n    \"font\": {\n      \"size\": true,\n      \"color\": true,\n      \"background\": true\n    }\n  },\n  {\n    \"name\": \"codeType\",\n    \"type\": \"select\",\n    \"label\": \"Code type\",\n    \"description\": \"Select what kind of code you want to generate\",\n    \"options\": [\n      {\n        \"value\": \"contact\",\n        \"label\": \"Contact\"\n      },\n      {\n        \"value\": \"event\",\n        \"label\": \"Event\"\n      },\n      {\n        \"value\": \"email\",\n        \"label\": \"Email address\"\n      },\n      {\n        \"value\": \"h5p\",\n        \"label\": \"H5P\"\n      },\n      {\n        \"value\": \"location\",\n        \"label\": \"Location\"\n      },\n      {\n        \"value\": \"phone\",\n        \"label\": \"Phone number\"\n      },\n      {\n        \"value\": \"sms\",\n        \"label\": \"SMS\"\n      },\n      {\n        \"value\": \"text\",\n        \"label\": \"Text\"\n      },\n      {\n        \"value\": \"url\",\n        \"label\": \"URL\"\n      }\n    ],\n    \"default\": \"url\",\n    \"widget\": \"editorKewArCode\"\n  },\n  {\n    \"name\": \"contact\",\n    \"type\": \"group\",\n    \"label\": \"Contact\",\n    \"importance\": \"high\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"name\",\n        \"type\": \"text\",\n        \"label\": \"Name\",\n        \"placeholder\": \"John Smith\",\n        \"maxLength\": 150\n      },\n      {\n        \"name\": \"organization\",\n        \"type\": \"text\",\n        \"label\": \"Organization\",\n        \"placeholder\": \"H5P fan club\",\n        \"optional\": true,\n        \"maxLength\": 150\n      },\n      {\n        \"name\": \"title\",\n        \"type\": \"text\",\n        \"label\": \"Title\",\n        \"placeholder\": \"Master of None\",\n        \"optional\": true,\n        \"maxLength\": 100\n      },\n      {\n        \"name\": \"number\",\n        \"type\": \"text\",\n        \"label\": \"Phone number\",\n        \"description\": \"Phone number (please use the format +12 345 67890)\",\n        \"placeholder\": \"+12 345 67890\",\n        \"optional\": true,\n        \"regexp\": {\n          \"pattern\": \"^\\\\+[0-9]{1,3}[\\\\ ]?[0-9]{1,4}[\\\\ ]?[0-9]{1,8}$\",\n          \"modifiers\": \"\"\n        }\n      },\n      {\n        \"name\": \"email\",\n        \"type\": \"text\",\n        \"label\": \"Email address\",\n        \"description\": \"Email address to write message to\",\n        \"placeholder\": \"john@fictional-h5p-fan-club.org\",\n        \"optional\": true,\n        \"maxLength\": 150,\n        \"regexp\": {\n          \"pattern\": \"^[A-Z0-9\\\\._%+-]+@[A-Z0-9.-]+\\\\.[A-Z]{2,}$\",\n          \"modifiers\": \"i\"\n        }\n      },\n      {\n        \"name\": \"address\",\n        \"type\": \"group\",\n        \"label\": \"Address\",\n        \"importance\": \"medium\",\n        \"expanded\": true,\n        \"fields\": [\n          {\n            \"name\": \"extended\",\n            \"type\": \"text\",\n            \"label\": \"Extended address\",\n            \"description\": \"c/o information, etc.\",\n            \"placeholder\": \"c/o H5P Fan Club\",\n            \"optional\": true,\n            \"maxLength\": 150\n          },\n          {\n            \"name\": \"street\",\n            \"type\": \"text\",\n            \"label\": \"Street\",\n            \"description\": \"Street including number\",\n            \"placeholder\": \"1308 W. Dayton Street\",\n            \"optional\": true,\n            \"maxLength\": 150\n          },\n          {\n            \"name\": \"locality\",\n            \"type\": \"text\",\n            \"label\": \"Locality\",\n            \"description\": \"City name, etc.\",\n            \"placeholder\": \"Madison\",\n            \"optional\": true,\n            \"maxLength\": 100\n          },\n          {\n            \"name\": \"region\",\n            \"type\": \"text\",\n            \"label\": \"Region\",\n            \"description\": \"Federal state, county, etc.\",\n            \"placeholder\": \"WI\",\n            \"optional\": true,\n            \"maxLength\": 100\n          },\n          {\n            \"name\": \"zip\",\n            \"type\": \"text\",\n            \"label\": \"ZIP code\",\n            \"description\": \"ZIP code\",\n            \"placeholder\": \"53715\",\n            \"optional\": true,\n            \"maxLength\": 50\n          },\n          {\n            \"name\": \"country\",\n            \"type\": \"text\",\n            \"label\": \"Country\",\n            \"description\": \"Country\",\n            \"placeholder\": \"USA\",\n            \"optional\": true,\n            \"maxLength\": 100\n          }\n        ]\n      },\n      {\n        \"name\": \"url\",\n        \"type\": \"text\",\n        \"label\": \"Website\",\n        \"description\": \"Website to link to (must start with https:// or http://)\",\n        \"placeholder\": \"https://fictional-h5p-fan-club.org\",\n        \"regexp\": {\n          \"pattern\": \"https?://([0-9a-z.-]+).[a-z.]{2,}([0-9a-z.-_]*)*/?\",\n          \"modifiers\": \"i\"\n        },\n        \"optional\": true,\n        \"maxLength\": 300\n      },\n      {\n        \"name\": \"note\",\n        \"type\": \"text\",\n        \"label\": \"Note\",\n        \"description\": \"Note\",\n        \"placeholder\": \"John loves H5P.\",\n        \"optional\": true,\n        \"maxLength\": 500\n      }\n    ],\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"codeType\",\n          \"equals\": \"contact\"\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"event\",\n    \"type\": \"group\",\n    \"label\": \"Event\",\n    \"importance\": \"high\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"title\",\n        \"type\": \"text\",\n        \"label\": \"Title\",\n        \"description\": \"Title for the calendar event\",\n        \"placeholder\": \"H5P Conference 2020\",\n        \"maxLength\": 200\n      },\n      {\n        \"name\": \"allDay\",\n        \"type\": \"boolean\",\n        \"label\": \"All day event\",\n        \"description\": \"Check if event will be valid all day long\"\n      },\n      {\n        \"name\": \"dateStart\",\n        \"type\": \"text\",\n        \"label\": \"Start date\",\n        \"description\": \"Start date of the event (please use the format yyyy/mm/dd)\",\n        \"placeholder\": \"2020/05/18\",\n        \"regexp\": {\n          \"pattern\": \"^[0-9]{4,}/0*([1-9]|1[0-2])/0*([1-9]|[12][0-9]|3[01])$\",\n          \"modifiers\": \"\"\n        }\n      },\n      {\n        \"name\": \"timeStart\",\n        \"type\": \"text\",\n        \"label\": \"Start time\",\n        \"description\": \"Start time of the event (please use the format hh:mm)\",\n        \"placeholder\": \"09:00\",\n        \"regexp\": {\n          \"pattern\": \"^0*([1-9]|1[0-9]|2[0-3]):0*([0-9]|[1-4][0-9]|5[0-9])$\",\n          \"modifiers\": \"\"\n        },\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"allDay\",\n              \"equals\": false\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"dateEnd\",\n        \"type\": \"text\",\n        \"label\": \"End date\",\n        \"description\": \"End date of the event (please use the format yyyy/mm/dd)\",\n        \"placeholder\": \"2020/05/20\",\n        \"regexp\": {\n          \"pattern\": \"^[0-9]{4,}/0*([1-9]|1[0-2])/0*([1-9]|[12][0-9]|3[01])$\",\n          \"modifiers\": \"\"\n        }\n      },\n      {\n        \"name\": \"timeEnd\",\n        \"type\": \"text\",\n        \"label\": \"End time\",\n        \"description\": \"End time of the event (please use the format hh:mm)\",\n        \"placeholder\": \"16:00\",\n        \"regexp\": {\n          \"pattern\": \"^0*([1-9]|1[0-9]|2[0-3]):0*([0-9]|[1-4][0-9]|5[0-9])$\",\n          \"modifiers\": \"\"\n        },\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"allDay\",\n              \"equals\": false\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"timezone\",\n        \"type\": \"select\",\n        \"label\": \"Timezone\",\n        \"description\": \"Select the time zone the event is supposed to take place in\",\n        \"options\": [\n          {\n            \"value\": \"-12:00\",\n            \"label\": \"UTC-12:00\"\n          },\n          {\n            \"value\": \"-11:00\",\n            \"label\": \"UTC-11:00\"\n          },\n          {\n            \"value\": \"-10:00\",\n            \"label\": \"UTC-10:00\"\n          },\n          {\n            \"value\": \"-9:30\",\n            \"label\": \"UTC-9:30\"\n          },\n          {\n            \"value\": \"-9:00\",\n            \"label\": \"UTC-9:00\"\n          },\n          {\n            \"value\": \"-8:00\",\n            \"label\": \"UTC-8:00\"\n          },\n          {\n            \"value\": \"-7:00\",\n            \"label\": \"UTC-7:00\"\n          },\n          {\n            \"value\": \"-6:00\",\n            \"label\": \"UTC-6:00\"\n          },\n          {\n            \"value\": \"-5:00\",\n            \"label\": \"UTC-5:00\"\n          },\n          {\n            \"value\": \"-4:00\",\n            \"label\": \"UTC-4:00\"\n          },\n          {\n            \"value\": \"-3:30\",\n            \"label\": \"UTC-3:30\"\n          },\n          {\n            \"value\": \"-3:00\",\n            \"label\": \"UTC-3:00\"\n          },\n          {\n            \"value\": \"-2:00\",\n            \"label\": \"UTC-2:00\"\n          },\n          {\n            \"value\": \"-1:00\",\n            \"label\": \"UTC-1:00\"\n          },\n          {\n            \"value\": \"0:00\",\n            \"label\": \"UTC\"\n          },\n          {\n            \"value\": \"1:00\",\n            \"label\": \"UTC+1:00\"\n          },\n          {\n            \"value\": \"2:00\",\n            \"label\": \"UTC+2:00\"\n          },\n          {\n            \"value\": \"3:00\",\n            \"label\": \"UTC+3:00\"\n          },\n          {\n            \"value\": \"3:30\",\n            \"label\": \"UTC+3:30\"\n          },\n          {\n            \"value\": \"4:00\",\n            \"label\": \"UTC+4:00\"\n          },\n          {\n            \"value\": \"4:00\",\n            \"label\": \"UTC+4:30\"\n          },\n          {\n            \"value\": \"5:00\",\n            \"label\": \"UTC+5:00\"\n          },\n          {\n            \"value\": \"5:30\",\n            \"label\": \"UTC+5:30\"\n          },\n          {\n            \"value\": \"5:45\",\n            \"label\": \"UTC+5:45\"\n          },\n          {\n            \"value\": \"6:00\",\n            \"label\": \"UTC+6:00\"\n          },\n          {\n            \"value\": \"6:30\",\n            \"label\": \"UTC+6:30\"\n          },\n          {\n            \"value\": \"7:00\",\n            \"label\": \"UTC+7:00\"\n          },\n          {\n            \"value\": \"8:00\",\n            \"label\": \"UTC+8:00\"\n          },\n          {\n            \"value\": \"9:00\",\n