(146,'H5P.FindTheWords','Find The Words',1,4,4,1,1,0,'iframe','scripts/h5p-find-the-words.js, scripts/h5p-find-the-words-word-grid.js, scripts/h5p-find-the-words-vocabulary.js, scripts/h5p-find-the-words-timer.js, scripts/h5p-find-the-words-counter.js','styles/h5p-find-the-words.css','','[\n  {\n    \"label\": \"Task description\",\n    \"name\": \"taskDescription\",\n    \"type\": \"text\",\n    \"description\": \"Description of the Game\",\n    \"default\": \"Find the words from the grid\",\n    \"importance\": \"high\"\n  },\n  {\n    \"name\": \"wordList\",\n    \"type\": \"text\",\n    \"label\": \"Word list\",\n    \"description\": \"Comma Separated list of words. Special Characters, White Spaces and Numbers Not allowed\",\n    \"default\": \"one,two,three\",\n    \"regexp\": {\n      \"pattern\": \"^(?!(?:.*[\\\"!#$%&./:;<=>?@\\\\[\\\\]^_`\\\\{|}~\'()\\\\-*+\\\\d]|^[,])).*$\"\n    },\n    \"importance\": \"high\"\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the game behaves.\",\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"orientations\",\n        \"type\": \"group\",\n        \"label\": \"Orientations\",\n        \"description\": \"An array containing the names of the word directions that should be used when creating the puzzle\",\n        \"fields\": [\n          {\n            \"name\": \"horizontal\",\n            \"type\": \"boolean\",\n            \"label\": \"Horizontal- left to right\",\n            \"default\": true\n          },\n          {\n            \"name\": \"horizontalBack\",\n            \"type\": \"boolean\",\n            \"label\": \"Horizontal- right to left\",\n            \"default\": true\n          },\n          {\n            \"name\": \"vertical\",\n            \"type\": \"boolean\",\n            \"label\": \"Vertical downwards\",\n            \"default\": true\n          },\n          {\n            \"name\": \"verticalUp\",\n            \"type\": \"boolean\",\n            \"label\": \"Vertical upwards\",\n            \"default\": true\n          },\n          {\n            \"name\": \"diagonal\",\n            \"type\": \"boolean\",\n            \"label\": \"Diagonal downwards- left to right\",\n            \"default\": true\n          },\n          {\n            \"name\": \"diagonalBack\",\n            \"type\": \"boolean\",\n            \"label\": \"Diagonal downwards- right to left\",\n            \"default\": true\n          },\n          {\n            \"name\": \"diagonalUp\",\n            \"type\": \"boolean\",\n            \"label\": \"Diagonal upwards- left to right\",\n            \"default\": true\n          },\n          {\n            \"name\": \"diagonalUpBack\",\n            \"type\": \"boolean\",\n            \"label\": \"Diagonal upwards- right to left\",\n            \"default\": true\n          }\n        ]\n      },\n      {\n        \"name\": \"fillPool\",\n        \"type\": \"text\",\n        \"label\": \"Vertical downwards\",\n        \"description\": \"pool of letters from which the blanks to be filled\",\n        \"default\": \"abcdefghijklmnopqrstuvwxyz\",\n        \"regexp\": {\n          \"pattern\": \"^[^\\t\\n .<>?;:\\\"\'`!@#$%^&*()\\\\[\\\\]{}_+=|\\\\-]*$\"\n        }\n      },\n      {\n        \"name\": \"preferOverlap\",\n        \"type\": \"boolean\",\n        \"label\": \"Prefer overlap\",\n        \"description\": \"Determines how wordfind decides where to place a word within the puzzle.   When true, it randomly selects amongst the positions the highest number of letters that overlap creating a more compact puzzle.   When false, it randomly selects amongst all valid positions creating a less compact puzzle.\",\n        \"default\": true\n      },\n      {\n        \"name\": \"showVocabulary\",\n        \"type\": \"boolean\",\n        \"label\": \"Show vocabulary\",\n        \"description\": \"Determines whether to show vocabularies to the player\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableShowSolution\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable show solution\",\n        \"description\": \"Add a show solution button for the game\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableRetry\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable retry\",\n        \"description\": \"Add a retry button for the game\",\n        \"default\": true\n      }\n    ]\n  },\n  {\n    \"label\": \"Localization\",\n    \"importance\": \"low\",\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"label\": \"Text for \\\"Check\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"check\",\n        \"type\": \"text\",\n        \"default\": \"Check\"\n      },\n      {\n        \"label\": \"Text for \\\"Retry\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"tryAgain\",\n        \"type\": \"text\",\n        \"default\": \"Retry\"\n      },\n      {\n        \"label\": \"Text for \\\"Show Solution\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"showSolution\",\n        \"type\": \"text\",\n        \"default\": \"Show Solution\"\n      },\n      {\n        \"label\": \"Counter text\",\n        \"importance\": \"low\",\n        \"name\": \"found\",\n        \"type\": \"text\",\n        \"default\": \"@found of @totalWords found\",\n        \"description\": \"Feedback text, variables available: @found and @totalWords. Example: \'@found of @totalWords found\'\"\n      },\n      {\n        \"label\": \"Time spent text\",\n        \"importance\": \"low\",\n        \"name\": \"timeSpent\",\n        \"type\": \"text\",\n        \"default\": \"Time Spent\",\n        \"description\": \"label for showing the time spent while playing the game\"\n      },\n      {\n        \"label\": \"Feedback text\",\n        \"importance\": \"low\",\n        \"name\": \"score\",\n        \"type\": \"text\",\n        \"default\": \"You got @score of @total points\",\n        \"description\": \"Feedback text, variables available: @score and @total. Example: \'You got @score of @total possible points\'\"\n      },\n      {\n        \"label\": \"Word list header\",\n        \"importance\": \"low\",\n        \"name\": \"wordListHeader\",\n        \"type\": \"text\",\n        \"default\": \"Find the words\",\n        \"maxLength\": 20\n      }\n    ]\n  }\n]\n',NULL,NULL,NULL,NULL,'https://h5p.org/find-the-words',NULL),
(147,'H5P.Column','Page',1,20,0,1,1,0,'iframe','scripts/h5p-column.js','styles/h5p-column.css','','[\n  {\n    \"name\": \"content\",\n    \"label\": \"List of Column Content\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"min\": 1,\n    \"entity\": \"content\",\n    \"field\": {\n      \"name\": \"content\",\n      \"type\": \"group\",\n      \"fields\": [\n        {\n          \"name\": \"content\",\n          \"type\": \"library\",\n          \"importance\": \"high\",\n          \"label\": \"Content\",\n          \"options\": [\n            \"H5P.Accordion 1.0\",\n            \"H5P.Agamotto 1.6\",\n            \"H5P.Audio 1.5\",\n            \"H5P.AudioRecorder 1.0\",\n            \"H5P.Blanks 1.14\",\n            \"H5P.Chart 1.2\",\n            \"H5P.Collage 0.3\",\n            \"H5P.CoursePresentation 1.27\",\n            \"H5P.Dialogcards 1.9\",\n            \"H5P.DocumentationTool 1.8\",\n            \"H5P.DragQuestion 1.15\",\n            \"H5P.DragText 1.10\",\n            \"H5P.Essay 1.5\",\n            \"H5P.GuessTheAnswer 1.5\",\n            \"H5P.Table 1.2\",\n            \"H5P.AdvancedText 1.1\",\n            \"H5P.IFrameEmbed 1.0\",\n            \"H5P.Image 1.1\",\n            \"H5P.ImageHotspots 1.10\",\n            \"H5P.ImageHotspotQuestion 1.8\",\n            \"H5P.ImageSlider 1.1\",\n            \"H5P.InteractiveVideo 1.28\",\n            \"H5P.Link 1.3\",\n            \"H5P.MarkTheWords 1.11\",\n            \"H5P.MemoryGame 1.3\",\n            \"H5P.MultiChoice 1.16\",\n            \"H5P.Questionnaire 1.3\",\n            \"H5P.QuestionSet 1.21\",\n            \"H5P.Row 1.1\",\n            \"H5P.SingleChoiceSet 1.11\",\n            \"H5P.Summary 1.10\",\n            \"H5P.Timeline 1.1\",\n            \"H5P.TrueFalse 1.8\",\n            \"H5P.Video 1.6\",\n            \"H5P.MultiMediaChoice 0.3\"\n          ]\n        },\n        {\n          \"name\": \"useSeparator\",\n          \"type\": \"select\",\n          \"importance\": \"low\",\n          \"label\": \"Separate content with a horizontal ruler\",\n          \"default\": \"auto\",\n          \"options\": [\n            {\n              \"value\": \"auto\",\n              \"label\": \"Automatic (default)\"\n            },\n            {\n              \"value\": \"disabled\",\n              \"label\": \"Never use ruler above\"\n            },\n            {\n              \"value\": \"enabled\",\n              \"label\": \"Always use ruler above\"\n            }\n          ]\n        }\n      ]\n    }\n  }\n]\n',NULL,1,28,NULL,NULL,NULL),
(148,'H5P.InteractiveBook','Interactive Book',1,13,5,1,1,1,'iframe','dist/h5p-interactive-book.js','dist/h5p-interactive-book.css','','[\n  {\n    \"name\": \"showCoverPage\",\n    \"type\": \"boolean\",\n    \"label\": \"Enable book cover\",\n    \"description\": \"A cover that shows info regarding the book before access\",\n    \"importance\": \"low\",\n    \"default\": false\n  },\n  {\n    \"name\": \"bookCover\",\n    \"type\": \"group\",\n    \"label\": \"Cover Page\",\n    \"importance\": \"medium\",\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"showCoverPage\",\n          \"equals\": true\n        }\n      ]\n    },\n    \"fields\": [\n      {\n        \"name\": \"coverDescription\",\n        \"type\": \"text\",\n        \"widget\": \"html\",\n        \"label\": \"Cover description\",\n        \"importance\": \"medium\",\n        \"optional\": true,\n        \"description\": \"This text will be the description of your book.\",\n        \"default\": \"<p style=\\\"text-align: center;\\\"></p>\",\n        \"enterMode\": \"p\",\n        \"tags\": [\n          \"sub\",\n          \"sup\",\n          \"strong\",\n          \"em\",\n          \"p\",\n          \"code\",\n          \"u\",\n          \"del\",\n          \"a\",\n          \"ul\",\n          \"ol\",\n          \"h1\",\n          \"h2\",\n          \"h3\",\n          \"h4\",\n          \"h5\",\n          \"h6\",\n          \"pre\",\n          \"hr\",\n          \"table\"\n        ],\n        \"font\": {\n          \"size\": true,\n          \"color\": true,\n          \"background\": true\n        }\n      },\n      {\n        \"name\": \"coverMedium\",\n        \"type\": \"library\",\n        \"label\": \"Cover media\",\n        \"description\": \"Optional media to display on the cover.\",\n        \"optional\": true,\n        \"options\": [\n          \"H5P.Image 1.1\",\n          \"H5P.Video 1.6\"\n        ]\n      }\n    ]\n  },\n  {\n    \"name\": \"chapters\",\n    \"type\": \"list\",\n    \"label\": \"Pages\",\n    \"entity\": \"Page\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\"\n      }\n    ],\n    \"importance\": \"high\",\n    \"min\": 1,\n    \"max\": 50,\n    \"field\": {\n      \"name\": \"item\",\n      \"type\": \"group\",\n      \"label\": \"Item\",\n      \"importance\": \"low\",\n      \"expanded\": true,\n      \"fields\": [\n        {\n          \"label\": \"Page\",\n          \"name\": \"chapter\",\n          \"type\": \"library\",\n          \"options\": [\n            \"H5P.Column 1.20\"\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"importance\": \"low\",\n    \"label\": \"Behavioural settings\",\n    \"fields\": [\n      {\n        \"name\": \"baseColor\",\n        \"type\": \"text\",\n        \"label\": \"Base color\",\n        \"description\": \"Set the base color that will define the overall color scheme of the book. Please ensure a high enough contrast.\",\n        \"optional\": true,\n        \"widget\": \"colorSelector\",\n        \"default\": \"#1768c4\",\n        \"spectrum\": {\n          \"showInput\": true,\n          \"showInitial\": true,\n          \"showPalette\": true,\n          \"palette\": [\n            [\n              \"#1768C4\"\n            ],\n            [\n              \"#D9B323\"\n            ],\n            [\n              \"#D32F2F\"\n            ],\n            [\n              \"#1EB224\"\n            ],\n            [\n              \"#7E57C2\"\n            ]\n          ]\n        }\n      },\n      {\n        \"name\": \"defaultTableOfContents\",\n        \"type\": \"boolean\",\n        \"label\": \"Display table of contents as default\",\n        \"description\": \"When enabled the table of contents is showed when opening the book\",\n        \"default\": true\n      },\n      {\n        \"name\": \"progressIndicators\",\n        \"type\": \"boolean\",\n        \"label\": \"Display Progress Indicators\",\n        \"description\": \"When enabled there will be indicators per page showing the user if he is done with the page or not.\",\n        \"default\": true\n      },\n      {\n        \"name\": \"progressAuto\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable automatic progress\",\n        \"description\": \"If enabled a page without tasks is considered done when viewed. A page with tasks when all tasks are done. If disabled there will be a button at the bottom of every page for the user to click when done with the page.\",\n        \"default\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"progressIndicators\",\n              \"equals\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"displaySummary\",\n        \"type\": \"boolean\",\n        \"label\": \"Display summary\",\n        \"description\": \"When enabled the user can see a summary and submit the progress/answers\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableRetry\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable \\\"Restart\\\" button\",\n        \"description\": \"When enabled the user can initiate a restart on the summary page.\",\n        \"default\": true,\n        \"optional\": true\n      }\n    ]\n  },\n  {\n    \"name\": \"read\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Read\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Read\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"displayTOC\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Display \'Table of contents\'\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Display \'Table of contents\'\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"hideTOC\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Hide \'Table of contents\'\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Hide \'Table of contents\'\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"page\",\n    \"type\": \"text\",\n    \"label\": \"Label for page counter\",\n    \"importance\": \"low\",\n    \"default\": \"Page\",\n    \"common\": true\n  },\n  {\n    \"name\": \"next\",\n    \"type\": \"text\",\n    \"label\": \"Label for forwards navigation button\",\n    \"importance\": \"low\",\n    \"default\": \"Next\",\n    \"common\": true\n  },\n  {\n    \"name\": \"nextPage\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Next page\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Next page\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"previous\",\n    \"type\": \"text\",\n    \"label\": \"Label for backwards navigation button\",\n    \"importance\": \"low\",\n    \"default\": \"Previous\",\n    \"common\": true\n  },\n  {\n    \"name\": \"previousPage\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Previous page\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Previous page\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"chapterCompleted\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Page completed!\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Page completed!\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"partCompleted\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"@pages of @total completed\\\" (@pages and @total will be replaced by actual values)\",\n    \"importance\": \"low\",\n    \"default\": \"@pages of @total completed\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"incompleteChapter\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Incomplete page\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Incomplete page\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"navigateToTop\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Navigate to the top\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Navigate to the top\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"markAsFinished\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"I have finished this page\\\"\",\n    \"default\": \"I have finished this page\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"fullscreen\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Fullscreen button label\",\n    \"default\": \"Fullscreen\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"exitFullscreen\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Exit fullscreen button label\",\n    \"default\": \"Exit fullscreen\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"bookProgressSubtext\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Page progress in book\",\n    \"description\": \"\\\"@count\\\" will be replaced by page count, and \\\"@total\\\" with the total number of pages\",\n    \"default\": \"@count of @total pages\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"interactionsProgressSubtext\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Interaction progress\",\n    \"description\": \"\\\"@count\\\" will be replaced by interaction count, and \\\"@total\\\" with the total number of interactions\",\n    \"default\": \"@count of @total interactions\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"submitReport\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"Submit report\\\"\",\n    \"default\": \"Submit Report\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"restartLabel\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Label for \\\"restart\\\" button\",\n    \"default\": \"Restart\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"summaryHeader\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Summary header\",\n    \"default\": \"Summary\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"allInteractions\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"All interactions\\\"\",\n    \"default\": \"All interactions\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"unansweredInteractions\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"Unanswered interactions\\\"\",\n    \"default\": \"Unanswered interactions\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"scoreText\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Score\",\n    \"description\": \"\\\"@score\\\" will be replaced with current score, and \\\"@maxscore\\\" will be replaced with max achievable score\",\n    \"default\": \"@score / @maxscore\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"leftOutOfTotalCompleted\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Per page interactions completion\",\n    \"description\": \"\\\"@left\\\" will be replaced with remaining interactions, and \\\"@max\\\" will be replaced with total number of interactions on the page\",\n    \"default\": \"@left of @max interactions completed\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"noInteractions\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"No interactions\\\"\",\n    \"default\": \"No interactions\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"score\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"Score\\\"\",\n    \"default\": \"Score\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"summaryAndSubmit\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Label for \\\"Summary &amp; submit\\\" button\",\n    \"default\": \"Summary &amp; submit\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"noChapterInteractionBoldText\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"You have not interacted with any pages.\\\"\",\n    \"default\": \"You have not interacted with any pages.\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"noChapterInteractionText\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"You have to interact with at least one page before you can see the summary.\\\"\",\n    \"default\": \"You have to interact with at least one page before you can see the summary.\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"yourAnswersAreSubmittedForReview\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"Your answers are submitted for review!\\\"\",\n    \"default\": \"Your answers are submitted for review!\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"bookProgress\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Summary progress label\",\n    \"default\": \"Book progress\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"interactionsProgress\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Interactions progress label\",\n    \"default\": \"Interactions progress\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"totalScoreLabel\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Total score label\",\n    \"default\": \"Total score\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"a11y\",\n    \"type\": \"group\",\n    \"label\": \"Accessibility texts\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"name\": \"progress\",\n        \"type\": \"text\",\n        \"label\": \"Page progress textual alternative\",\n        \"description\": \"An alternative text for the visual page progress. @page and @total variables available.\",\n        \"default\": \"Page @page of @total.\"\n      },\n      {\n        \"name\": \"menu\",\n        \"type\": \"text\",\n        \"label\": \"Label for expanding/collapsing navigation menu\",\n        \"default\": \"Toggle navigation menu\"\n      }\n    ]\n  }\n]\n',NULL,1,28,NULL,NULL,NULL),
(149,'H5P.Row','Row',1,1,0,0,1,0,'iframe','h5p-row.js','h5p-row.css','','[\n  {\n    \"name\": \"columns\",\n    \"type\": \"list\",\n    \"label\": \"Columns\",\n    \"importance\": \"high\",\n    \"max\": 4,\n    \"field\": {\n      \"name\": \"column\",\n      \"type\": \"group\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"width\",\n          \"label\": \"Width\",\n          \"type\": \"number\",\n          \"description\": \"Column width in percentage.\",\n          \"optional\": true,\n          \"max\": 100\n        },\n        {\n          \"name\": \"content\",\n          \"label\": \"Column\",\n          \"type\": \"library\",\n          \"options\": [\n            \"H5P.RowColumn 1.1\"\n          ]\n        }\n      ]\n    }\n  }\n]\n',NULL,1,24,NULL,NULL,NULL),
(150,'H5P.RowColumn','Column',1,1,0,0,1,0,'iframe','scripts/h5p-column.js','styles/h5p-column.css','','[\n  {\n    \"name\": \"content\",\n    \"label\": \"List of Column Content\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"min\": 1,\n    \"entity\": \"content\",\n    \"field\": {\n      \"name\": \"content\",\n      \"type\": \"group\",\n      \"fields\": [\n        {\n          \"name\": \"content\",\n          \"type\": \"library\",\n          \"importance\": \"high\",\n          \"label\": \"Content\",\n          \"options\": [\n            \"H5P.Accordion 1.0\",\n            \"H5P.Agamotto 1.6\",\n            \"H5P.Audio 1.5\",\n            \"H5P.AudioRecorder 1.0\",\n            \"H5P.Blanks 1.14\",\n            \"H5P.Chart 1.2\",\n            \"H5P.Collage 0.3\",\n            \"H5P.CoursePresentation 1.27\",\n            \"H5P.Dialogcards 1.9\",\n            \"H5P.DocumentationTool 1.8\",\n            \"H5P.DragQuestion 1.15\",\n            \"H5P.DragText 1.10\",\n            \"H5P.Essay 1.5\",\n            \"H5P.GuessTheAnswer 1.5\",\n            \"H5P.Table 1.2\",\n            \"H5P.AdvancedText 1.1\",\n            \"H5P.IFrameEmbed 1.0\",\n            \"H5P.Image 1.1\",\n            \"H5P.ImageHotspots 1.10\",\n            \"H5P.ImageHotspotQuestion 1.8\",\n            \"H5P.ImageSlider 1.1\",\n            \"H5P.InteractiveVideo 1.28\",\n            \"H5P.Link 1.3\",\n            \"H5P.MarkTheWords 1.11\",\n            \"H5P.MemoryGame 1.3\",\n            \"H5P.MultiChoice 1.16\",\n            \"H5P.Questionnaire 1.3\",\n            \"H5P.QuestionSet 1.21\",\n            \"H5P.SingleChoiceSet 1.11\",\n            \"H5P.Summary 1.10\",\n            \"H5P.Timeline 1.1\",\n            \"H5P.TrueFalse 1.8\",\n            \"H5P.Video 1.6\",\n            \"H5P.MultiMediaChoice 0.3\"\n          ]\n        }\n      ]\n    }\n  }\n]\n',NULL,1,28,NULL,NULL,NULL);
