INSERT INTO `mdl_local_kopere_bi_element` VALUES
(1,'report_3_users_online','lang::report_page_001_title::local_kopere_bi',1,2,'maps','light','',NULL,NULL,'  SELECT lastip\n    FROM mdl_local_kopere_bi_online\n   WHERE currenttime > UNIX_TIMESTAMP() - (5 * 60)\nGROUP BY userid, lastip','none','1m','[]',1780646819),
(2,'report_3_users_online_list','lang::report_page_001_block_1_element_2_title::local_kopere_bi',1,1,'table','light','',NULL,NULL,'SELECT DISTINCT \n       u.id AS u_id,\n       u.firstname,\n       u.lastname,\n       kbo.city_name,\n       kbo.country_name\n  FROM mdl_local_kopere_bi_online kbo\n  JOIN mdl_user u ON u.id = kbo.userid\n WHERE kbo.currenttime > UNIX_TIMESTAMP() - (5 * 60)','none','none','{\"column\":{\"u_id\":{\"key\":\"u_id\",\"title\":\"#\",\"type\":\"userphotoRenderer\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::u_fullname::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{u_id}}}\\\"\\r\\n   target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"lang::lastname::moodle\",\"type\":\"none\",\"mustache\":\"\"},\"city_name\":{\"key\":\"city_name\",\"title\":\"lang::city_name::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"{{{city_name}}}\"},\"country_name\":{\"key\":\"country_name\",\"title\":\"lang::country_name::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"{{{country_name}}}\"}}}',1780646819),
(3,'report_3_course_access_time','lang::report_page_001_block_2_element_1_title::local_kopere_bi',2,1,'line','light','','','<div class=\"alert alert-info\">\nData from the last 30 days only\n</div>','   SELECT c.fullname,\n          count(DISTINCT kbo.userid) AS \'lang::num_user::local_kopere_bi\',\n          SUM(kbo.seconds)           AS \'lang::seconds::local_kopere_bi\'\n     FROM mdl_course c\nLEFT JOIN mdl_local_kopere_bi_online kbo ON kbo.courseid = c.id\n    WHERE kbo.currenttime > UNIX_TIMESTAMP() - (30 * 24 * 60 * 60)\n GROUP BY c.id','30m','30m','{\"chart_options\":\"{\\r\\n    colors : [\\\"#2E93fA\\\", \\\"#66DA26\\\", \\\"#546E7A\\\", \\\"#E91E63\\\", \\\"#FF9800\\\"],\\r\\n    stroke : {\\r\\n        colors : [\\\"#2E93fA\\\", \\\"#66DA26\\\", \\\"#546E7A\\\", \\\"#E91E63\\\", \\\"#FF9800\\\"],\\r\\n    },\\r\\n    yaxis : {\\r\\n        labels : {\\r\\n            formatter: (value, index, outro) => { \\r\\n                if(index.seriesIndex==0) \\r\\n                    return value;\\r\\n                var hours = Math.floor(value \\/ 3600);\\r\\n                var minutes = Math.floor((value % 3600) \\/ 60);\\r\\n                return `${hours}h ${minutes}m`;\\r\\n            },\\r\\n        },\\r\\n    },\\r\\n    toolbar: {\\r\\n        show    : true,\\r\\n        offsetX : 0,\\r\\n        offsetY : 0\\r\\n    }\\r\\n}\"}',1780646819),
(4,'report_3_top_browsers','lang::report_page_001_block_3_element_1_title::local_kopere_bi',3,2,'pie','light','',NULL,NULL,'  SELECT kbo.client_name,\n         SUM(kbo.seconds) as times\n    FROM mdl_local_kopere_bi_online kbo\n    JOIN mdl_user c ON c.id = kbo.userid\nGROUP BY kbo.client_name\nORDER BY times DESC\n   LIMIT 15','30m','30m','{\"chart_options\":\"{\\r\\n    colors : [\\\"#4285F4\\\", \\\"#FF7139\\\", \\\"#0078D7\\\", \\\"#5AC8FA\\\", \\\"#FF1B2D\\\", \\\"#AAAAAA\\\"],\\r\\n    yaxis : {\\r\\n        labels : {\\r\\n            formatter: (seconds) => { \\r\\n                var hours = Math.floor(seconds \\/ 3600);\\r\\n                var minutes = Math.floor((seconds % 3600) \\/ 60);\\r\\n                return `${hours}h ${minutes}m`;\\r\\n            },\\r\\n        },\\r\\n    },\\r\\n}\"}',1780646819),
(5,'report_3_operating_systems','lang::report_page_001_block_3_element_2_title::local_kopere_bi',3,3,'pie','light','',NULL,NULL,'  SELECT kbo.os_name,\n         SUM(kbo.seconds) as times\n    FROM mdl_local_kopere_bi_online kbo\n    JOIN mdl_user c ON c.id = kbo.userid\nGROUP BY kbo.os_name\nORDER BY times DESC\n   LIMIT 15','30m','30m','{\"chart_options\":\"{\\r\\n    colors: [\\\"#9467bd\\\", \\\"#8c564b\\\", \\\"#e377c2\\\", \\\"#7f7f7f\\\", \\\"#bcbd22\\\", \\\"#17becf\\\", \\\"#1f77b4\\\", \\\"#ff7f0e\\\", \\\"#2ca02c\\\", \\\"#d62728\\\" ],\\r\\n    yaxis : {\\r\\n        labels : {\\r\\n            formatter: (seconds) => { \\r\\n                var hours = Math.floor(seconds \\/ 3600);\\r\\n                var minutes = Math.floor((seconds % 3600) \\/ 60);\\r\\n                return `${hours}h ${minutes}m`;\\r\\n            },\\r\\n        },\\r\\n    },\\r\\n}\"}',1780646819),
(6,'report_3_top_country_access','lang::report_page_001_block_3_element_3_title::local_kopere_bi',3,1,'pie','light','',NULL,NULL,'  SELECT CONCAT(kbo.city_name, \'/\', kbo.country_name) AS country_name, \n         SUM(kbo.seconds) as times\n    FROM mdl_local_kopere_bi_online kbo\n    JOIN mdl_user c ON c.id = kbo.userid\nGROUP BY kbo.city_name, kbo.country_name\nORDER BY times DESC\n   LIMIT 10','30m','30m','{\"chart_options\":\"{\\r\\n    colors : [ \\\"#ff7f0e\\\", \\\"#2ca02c\\\", \\\"#d62728\\\", \\\"#9467bd\\\", \\\"#8c564b\\\", \\\"#e377c2\\\", \\\"#7f7f7f\\\", \\\"#bcbd22\\\", \\\"#17becf\\\", \\\"#1f77b4\\\" ],\\r\\n    yaxis : {\\r\\n        labels : {\\r\\n            formatter: (seconds) => { \\r\\n                console.log(seconds);\\r\\n                var hours = Math.floor(seconds \\/ 3600);\\r\\n                var minutes = Math.floor((seconds % 3600) \\/ 60);\\r\\n                return `${hours}h ${minutes}m`;\\r\\n            },\\r\\n        },\\r\\n    },\\r\\n}\"}',1780646819),
(7,'report_1_user_summary','lang::report_page_002_block_1_element_1_title::local_kopere_bi',4,1,'table','light','',NULL,NULL,'SELECT \n    u.id AS u_id,\n    u.firstname,\n    u.lastname,\n    c.id AS c_id,\n    c.fullname AS c_fullname,\n    u.email,\n    u.lastaccess,\n    u.timecreated,\n    ROUND(\n        AVG(\n            CASE\n                WHEN g.rawgrademax > 0\n                THEN (g.finalgrade / g.rawgrademax) * 100\n                ELSE g.finalgrade \n            END\n        ), 0\n    ) AS g_finalgrade,\n    MAX(ca.completed_activities) AS ca_completed_activities\nFROM \n    mdl_course c\nJOIN \n    mdl_context ctx ON ctx.instanceid = c.id\nJOIN \n    mdl_role_assignments ra ON ra.contextid = ctx.id\n                            AND ra.roleid = 5\nJOIN \n    mdl_user u ON u.id = ra.userid\nLEFT JOIN (\n        SELECT \n            COUNT(id) AS completed_activities, \n            userid\n        FROM \n            mdl_course_modules_completion\n        WHERE \n            id > 1\n            AND completionstate IN (1, 2)\n        GROUP BY \n            userid\n    ) ca ON ca.userid = u.id\nLEFT JOIN \n    mdl_grade_items gi ON gi.courseid = c.id \n                       AND gi.itemtype = \'course\'\nLEFT JOIN \n    mdl_grade_grades g ON g.itemid = gi.id \n                      AND g.userid = u.id \n                      AND g.finalgrade IS NOT NULL\nWHERE u.id        > 1\n  AND u.deleted   = 0\n  AND u.suspended = 0\n  AND u.username != \'guest\'\nGROUP BY u.id','30m','30m','{\"column\":{\"u_id\":{\"key\":\"u_id\",\"title\":\"#\",\"type\":\"none\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::u_fullname::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{u_id}}}\\\"\\r\\n   target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"lang::lastname::moodle\",\"type\":\"none\",\"mustache\":\"\"},\"c_id\":{\"key\":\"c_id\",\"title\":\"lang::report_field_c_id_title::local_kopere_bi\",\"type\":\"none\",\"mustache\":\"\"},\"c_fullname\":{\"key\":\"c_fullname\",\"title\":\"lang::c_fullname::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{c_id}}}\\\"\\r\\n   target=\\\"course\\\">{{{c_fullname}}}<\\/a>\"},\"email\":{\"key\":\"email\",\"title\":\"lang::email::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"lastaccess\":{\"key\":\"lastaccess\",\"title\":\"lang::lastaccess::moodle\",\"type\":\"datetimeRenderer\",\"mustache\":\"\"},\"timecreated\":{\"key\":\"timecreated\",\"title\":\"lang::timecreated::moodle\",\"type\":\"datetimeRenderer\",\"mustache\":\"\"},\"g_finalgrade\":{\"key\":\"g_finalgrade\",\"title\":\"lang::g_finalgrade::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"ca_completed_activities\":{\"key\":\"ca_completed_activities\",\"title\":\"lang::ca_completed_activities::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646819),
(8,'report_2_completion_progress','lang::report_page_003_block_1_element_1_title::local_kopere_bi',5,1,'table','light','','','','SELECT u.id AS u_id,\n       u.firstname,\n       u.lastname,\n       u.email,\n       u.institution,\n       u.department,\n       u.phone1,\n       u.phone2,\n       u.address,\n       u.city,\n       u.country,\n       u.timezone,\n       u.firstaccess,\n       u.lastaccess,\n       ue.timecreated,\n       MAX(cc.timecompleted) AS timecompleted,\n       ROUND(((MAX(cmc.completed) / MAX(m.modules)) * 100), 0) AS course_completed\n  FROM {user_enrolments} ue\n  JOIN {user} u ON u.id = ue.userid\n  JOIN {enrol} e ON e.id = ue.enrolid\n  JOIN {course} c ON c.id = e.courseid\n  LEFT JOIN {course_completions} cc ON cc.timecompleted > 0\n                                   AND cc.course = e.courseid\n                                   AND cc.userid = ue.userid\n  LEFT JOIN (\n        SELECT course,\n               COUNT(id) AS modules\n          FROM {course_modules}\n         WHERE visible = 1\n           AND completion > 0\n           AND deletioninprogress = 0\n      GROUP BY course\n      ) AS m ON m.course = c.id\n  LEFT JOIN (\n        SELECT cm_i.course,\n               cmc_i.userid,\n               COUNT(DISTINCT cmc_i.id) AS completed\n          FROM {course_modules} cm_i,\n               {course_modules_completion} cmc_i\n         WHERE cmc_i.coursemoduleid = cm_i.id\n           AND cm_i.visible = 1\n           AND cmc_i.completionstate IN (1, 2)\n           AND cm_i.deletioninprogress = 0\n      GROUP BY cm_i.course,\n               cmc_i.userid\n      ) AS cmc ON cmc.course = c.id\n              AND cmc.userid = ue.userid\n WHERE ue.id > 0\n   AND u.id > 1\n   AND u.deleted = 0\n   AND u.suspended = 0\n   AND ue.status = 0\n   AND e.status = 0\n   AND c.id = :courseid\nGROUP BY u.id, ue.timecreated','6h','30m','{\"column\":{\"u_id\":{\"key\":\"u_id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::u_fullname::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{u_id}}}\\\"\\r\\n   target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"lang::lastname::moodle\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::email::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"institution\":{\"key\":\"institution\",\"title\":\"lang::institution::moodle\",\"type\":\"none\",\"mustache\":\"{{{institution}}}\"},\"department\":{\"key\":\"department\",\"title\":\"lang::department::moodle\",\"type\":\"none\",\"mustache\":\"{{{department}}}\"},\"phone1\":{\"key\":\"phone1\",\"title\":\"lang::phone1::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone1}}}\\\" target=\\\"_blank\\\">{{{phone1}}}<\\/a>\"},\"phone2\":{\"key\":\"phone2\",\"title\":\"lang::phone2::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone2}}}\\\" target=\\\"_blank\\\">{{{phone2}}}<\\/a>\"},\"address\":{\"key\":\"address\",\"title\":\"lang::address::moodle\",\"type\":\"none\",\"mustache\":\"{{{address}}}\"},\"city\":{\"key\":\"city\",\"title\":\"lang::city::moodle\",\"type\":\"none\",\"mustache\":\"{{{city}}}\"},\"country\":{\"key\":\"country\",\"title\":\"lang::country::moodle\",\"type\":\"none\",\"mustache\":\"{{{country}}}\"},\"timezone\":{\"key\":\"timezone\",\"title\":\"lang::timezone::moodle\",\"type\":\"none\",\"mustache\":\"\"},\"firstaccess\":{\"key\":\"firstaccess\",\"title\":\"lang::firstaccess::moodle\",\"type\":\"datetimeRenderer\",\"mustache\":\"\"},\"lastaccess\":{\"key\":\"lastaccess\",\"title\":\"lang::lastaccess::moodle\",\"type\":\"datetimeRenderer\",\"mustache\":\"\"},\"timecreated\":{\"key\":\"timecreated\",\"title\":\"lang::timecreated::moodle\",\"type\":\"datetimeRenderer\",\"mustache\":\"\"},\"timecompleted\":{\"key\":\"timecompleted\",\"title\":\"lang::timecompleted::local_kopere_bi\",\"type\":\"datetimeRenderer\",\"mustache\":\"\"},\"course_completed\":{\"key\":\"course_completed\",\"title\":\"lang::course_completed::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"{{#course_completed}}\\r\\n    {{{course_completed}}}%\\r\\n{{\\/course_completed}}\\r\\n{{^course_completed}}\\r\\n    -\\r\\n{{\\/course_completed}}\"}}}',1780646819),
(9,'report_2_course_progress','lang::report_page_003_block_2_element_1_title::local_kopere_bi',6,1,'table','light','',NULL,NULL,'SELECT u.id AS u_id,\n       u.firstname,\n       u.lastname,\n       u.email,\n       MIN(gc.grade) AS grade\n  FROM mdl_user_enrolments ue\n  LEFT JOIN mdl_user u ON u.id = ue.userid\n  LEFT JOIN mdl_enrol e ON e.id = ue.enrolid\n  LEFT JOIN mdl_course c ON c.id = e.courseid\n  LEFT JOIN (\n             SELECT course, COUNT(id) AS cmnums\n               FROM mdl_course_modules\n              WHERE visible = 1\n           GROUP BY course\n            ) AS cm ON cm.course = c.id\n  LEFT JOIN (\n             SELECT course, COUNT(id) AS cmnumx\n               FROM mdl_course_modules\n              WHERE visible = 1\n                AND completion > 0\n           GROUP BY course\n            ) cmx ON cmx.course = c.id\n  LEFT JOIN (\n             SELECT cm.course, cmc.userid, COUNT(cmc.id) AS cmcnums\n               FROM mdl_course_modules cm,\n                    mdl_course_modules_completion cmc\n              WHERE cmc.coursemoduleid = cm.id\n                AND cm.visible = 1\n                AND cmc.completionstate IN (1, 2)\n           GROUP BY cm.course, cmc.userid\n            ) cmc ON cmc.course = c.id\n                AND cmc.userid = u.id\n  LEFT JOIN (\n             SELECT cm.course, cmc.userid, COUNT(cmc.id) AS cmcnuma\n               FROM mdl_course_modules cm,\n                    mdl_course_modules_completion cmc\n              WHERE cmc.coursemoduleid = cm.id\n                AND cm.module = 1\n                AND cm.visible = 1\n                AND cmc.completionstate IN (1, 2)\n           GROUP BY cm.course, cmc.userid\n            ) AS cmca ON cmca.course = c.id\n                   AND cmca.userid = u.id\n  LEFT JOIN (\n             SELECT gi.courseid,\n                    g.userid,\n                    ROUND((CASE WHEN g.rawgrademax > 0 THEN (g.finalgrade / g.rawgrademax) * 100 ELSE g.finalgrade END), 0) AS grade\n               FROM mdl_grade_items gi,\n                    mdl_grade_grades g\n              WHERE gi.itemtype = \'course\'\n                AND g.itemid = gi.id\n                AND g.finalgrade IS NOT NULL\n           GROUP BY gi.courseid, g.userid, g.finalgrade, g.rawgrademax\n            ) AS gc ON gc.courseid = c.id\n                AND gc.userid = u.id\n WHERE ue.id > 0\n   AND e.courseid = :courseid\n   AND u.deleted = 0\n   AND u.suspended = 0\n   AND c.visible = 1\nGROUP BY u.id, c.id','none','none','{\"column\":{\"u_id\":{\"key\":\"u_id\",\"title\":\"#\",\"type\":\"none\",\"mustache\":\"{{{u_id}}}\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::u_fullname::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{u_id}}}\\\"\\r\\n   target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"lang::lastname::moodle\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::email::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::grade::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646819),
(10,'report_2_course_access_statistics','lang::report_page_003_block_3_element_1_title::local_kopere_bi',7,1,'table','light','','','','SELECT u.id                    AS u_id,\n       u.firstname,\n       u.lastname,\n       u.email,\n       l.contextinstanceid     AS cm_cmid,\n       CONCAT(\'lang::modulename::\', l.objecttable) AS module_name,\n       l.origin                AS l_origin,\n       l.ip                    AS l_ip,\n       l.timecreated           AS l_timecreated,\n       l.objecttable\n       \n     FROM mdl_local_kopere_bi_log_tmp l\nLEFT JOIN mdl_course       c  ON c.id = l.courseid\nLEFT JOIN mdl_user         u  ON u.id = l.userid\nLEFT JOIN mdl_modules      m  ON m.name = SUBSTRING(l.component, 5)\nLEFT JOIN mdl_course_modules cm ON cm.id = l.contextinstanceid\n\nWHERE u.id > 1\n  AND l.component LIKE \'%mod_%\'\n  AND l.courseid = :courseid\n  AND u.deleted = 0\n  AND u.suspended = 0\n  AND c.visible = 1\n  AND cm.visible = 1','6h','30m','{\"column\":{\"u_id\":{\"key\":\"u_id\",\"title\":\"#\",\"type\":\"userphotoRenderer\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::u_fullname::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{u_id}}}\\\"\\r\\n   target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"lang::lastname::moodle\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::email::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"cm_cmid\":{\"key\":\"cm_cmid\",\"title\":\"lang::cm_cmid::local_kopere_bi\",\"type\":\"none\",\"mustache\":\"\"},\"module_name\":{\"key\":\"module_name\",\"title\":\"lang::module_name::local_kopere_bi\",\"type\":\"translate\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/mod\\/{{{objecttable}}}\\/view.php?id={{{cm_cmid}}}\\\"\\r\\n   target=\\\"_blank\\\">\\r\\n    {{{module_name}}}\\r\\n<\\/a>\"},\"l_origin\":{\"key\":\"l_origin\",\"title\":\"lang::l_origin::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"{{{l_origin}}}\"},\"l_ip\":{\"key\":\"l_ip\",\"title\":\"lang::l_ip::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"https:\\/\\/www.geodatatool.com\\/?ip={{{l_ip}}}\\\" target=\\\"geoip\\\">{{{l_ip}}}<\\/a>\"},\"l_timecreated\":{\"key\":\"l_timecreated\",\"title\":\"lang::l_timecreated::local_kopere_bi\",\"type\":\"datetimeRenderer\",\"mustache\":\"\"},\"objecttable\":{\"key\":\"objecttable\",\"title\":\"lang::report_field_objecttable_title::local_kopere_bi\",\"type\":\"none\",\"mustache\":\"{{{objecttable}}}\"}}}',1780646819),
(11,'report_2_course_analysis_participation_completion','lang::report_page_003_block_4_element_1_title::local_kopere_bi',8,1,'table','light','','','','SELECT u.id        AS u_id,\n       u.firstname,\n       u.lastname,\n       u.email,\n       CASE \n           WHEN ul.id IS NULL THEN \'lang::case_never_accessed::local_kopere_bi\'\n           WHEN comp.userid IS NOT NULL THEN \'lang::case_complete::local_kopere_bi\'\n           ELSE \'lang::case_incomplete::local_kopere_bi\'\n       END AS status\n       \nFROM mdl_role_assignments ra\n       JOIN mdl_context ctx                                   ON ctx.id = ra.contextid \n                                                            AND ctx.contextlevel = 50\n       JOIN mdl_course c                                     ON c.id = ctx.instanceid\n       JOIN mdl_user u                                      ON u.id = ra.userid\n       \n       LEFT JOIN (SELECT cm.course, cmc.userid\n                  FROM   mdl_course_modules cm\n                         JOIN mdl_course_modules_completion cmc ON cmc.coursemoduleid = cm.id \n                                                              AND cmc.completionstate = 1\n                  WHERE  cmc.id > 0\n                  GROUP BY cm.course, cmc.userid\n                 ) comp ON comp.userid = u.id \n                         AND comp.course = c.id\n       \n       LEFT JOIN mdl_user_lastaccess ul                         ON ul.courseid = c.id \n                                                            AND ul.userid = ra.userid\n       \nWHERE  c.id = :courseid \n  AND  u.deleted = 0 \n  AND  u.suspended = 0  \n  AND  c.visible = 1 \n  AND  ra.roleid = 5\nGROUP BY u.id','6h','30m','{\"column\":{\"u_id\":{\"key\":\"u_id\",\"title\":\"#\",\"type\":\"userphotoRenderer\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::u_fullname::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{u_id}}}\\\"\\r\\n   target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"lang::lastname::moodle\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::email::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"status\":{\"key\":\"status\",\"title\":\"lang::status::moodle\",\"type\":\"statusRenderer\",\"mustache\":\"{{#status}}\\r\\n    <span class=\\\"w-100 badge bg-success\\\">\\r\\n        {{#str}} active,moodle {{\\/str}}\\r\\n    <\\/span>\\r\\n{{\\/status}}\\r\\n{{^status}}\\r\\n    <span class=\\\"w-100 badge bg-danger\\\">\\r\\n        {{#str}} inactive,moodle {{\\/str}}\\r\\n    <\\/span>\\r\\n{{\\/status}}\"}}}',1780646819),
(12,'report_4_coursesenrollmentstatus','lang::report_page_004_block_1_element_1_title::local_kopere_bi',9,1,'table','light','','','','SELECT \n    u.id AS u_id,\n    u.firstname,\n    u.lastname,\n    u.email,\n    u.city,\n    u.country,\n    c.id       AS c_id,\n    c.fullname AS c_fullname,\n    cm.id      AS cm_cmid,\n    m.name AS module_name,\n    ROUND(\n        CASE\n            WHEN g.rawgrademax > 0 THEN (g.finalgrade / g.rawgrademax) * 100\n            ELSE g.finalgrade\n        END, 0\n    ) AS grade,\n    CASE\n        WHEN cmc.completionstate = 0 THEN \'lang::report_4_completionstate_0::local_kopere_bi\'\n        WHEN cmc.completionstate = 1 THEN \'lang::report_4_completionstate_1::local_kopere_bi\'\n        WHEN cmc.completionstate = 2 THEN \'lang::report_4_completionstate_2::local_kopere_bi\'\n        WHEN cmc.completionstate = 3 THEN \'lang::report_4_completionstate_3::local_kopere_bi\'\n        WHEN cmc.completionstate = 4 THEN \'lang::report_4_completionstate_4::local_kopere_bi\'\n        ELSE \'lang::report_4_completionstate_none::local_kopere_bi\'\n    END AS completionstate_status,\n    CASE\n        WHEN cm.completion = 0 THEN \'lang::report_4_completion_0::local_kopere_bi\'\n        WHEN cm.completion = 1 THEN \'lang::report_4_completion_1::local_kopere_bi\'\n        WHEN cm.completion = 2 THEN \'lang::report_4_completion_2::local_kopere_bi\'\n        ELSE \'lang::report_4_completion_none::local_kopere_bi\'\n    END AS completion_status,\n    ue.enrol_status AS enrol_status,\n    ue.timeend       AS enrol_timeend\nFROM (\n    SELECT MIN(ue1.id) AS id, \n           ue1.userid, \n           e1.courseid, \n           MIN(ue1.status) AS enrol_status, \n           MIN(ue1.timeend) AS timeend\n    FROM mdl_user_enrolments ue1\n    JOIN mdl_enrol e1 ON e1.id = ue1.enrolid\n    GROUP BY ue1.userid, e1.courseid\n) ue\nJOIN mdl_user u \n         ON u.id = ue.userid\nJOIN mdl_course c \n         ON c.id = ue.courseid\nJOIN mdl_course_modules cm \n         ON cm.course = c.id\n        AND cm.instance > 0\nJOIN mdl_modules m \n         ON m.id = cm.module\nLEFT JOIN mdl_grade_items gi \n         ON gi.itemtype = \'mod\'\n        AND gi.iteminstance = cm.instance\n        AND gi.itemmodule = m.name\n        AND gi.gradetype = 1\nLEFT JOIN mdl_grade_grades g \n         ON g.itemid = gi.id\n        AND g.userid = u.id\nLEFT JOIN mdl_course_modules_completion cmc \n         ON cmc.coursemoduleid = cm.id\n        AND cmc.userid = u.id\n\nWHERE c.id = :courseid\n  AND u.deleted = 0\n  AND u.suspended = 0\n  AND c.visible = 1\n  AND cm.visible = 1','30m','30m','{\"column\":{\"u_id\":{\"key\":\"u_id\",\"title\":\"#\",\"type\":\"userphotoRenderer\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{u_id}}}\\\"\\r\\n   target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::u_fullname::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{u_id}}}\\\"\\r\\n   target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::email::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"city\":{\"key\":\"city\",\"title\":\"lang::city_name::local_kopere_bi\",\"type\":\"none\",\"mustache\":\"\"},\"country\":{\"key\":\"country\",\"title\":\"lang::country_name::local_kopere_bi\",\"type\":\"none\",\"mustache\":\"\"},\"c_id\":{\"key\":\"c_id\",\"title\":\"lang::report_field_c_id_title::local_kopere_bi\",\"type\":\"none\",\"mustache\":\"\"},\"c_fullname\":{\"key\":\"c_fullname\",\"title\":\"lang::c_fullname::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{c_id}}}\\\"\\r\\n   target=\\\"course\\\">{{{c_fullname}}}<\\/a>\"},\"cm_cmid\":{\"key\":\"cm_cmid\",\"title\":\"lang::report_field_cm_cmid_title::local_kopere_bi\",\"type\":\"none\",\"mustache\":\"{{{cm_cmid}}}\"},\"module_name\":{\"key\":\"module_name\",\"title\":\"lang::module_name::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/mod\\/{{{module_name}}}\\/view.php?id={{{cm_cmid}}}\\\">\\r\\n    {{#str}} modulename,{{{module_name}}} {{\\/str}}\\r\\n<\\/a>\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::grade::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completionstate_status\":{\"key\":\"completionstate_status\",\"title\":\"lang::completionstate_status::local_kopere_bi\",\"type\":\"translate\",\"mustache\":\"\"},\"completion_status\":{\"key\":\"completion_status\",\"title\":\"lang::completion_status::local_kopere_bi\",\"type\":\"translate\",\"mustache\":\"\"},\"enrol_status\":{\"key\":\"enrol_status\",\"title\":\"lang::enrol_status::local_kopere_bi\",\"type\":\"statusRenderer\",\"mustache\":\"<span class=\\\"w-100 badge {{^enrol_status}}bg-success{{\\/enrol_status}}{{#enrol_status}}bg-danger{{\\/enrol_status}}\\\">\\r\\n    {{#enrol_status}} {{#str}} inactive,moodle {{\\/str}} {{\\/enrol_status}}\\r\\n    {{^enrol_status}} {{#str}}   active,moodle {{\\/str}} {{\\/enrol_status}}\\r\\n<\\/span>\"},\"enrol_timeend\":{\"key\":\"enrol_timeend\",\"title\":\"lang::enrol_timeend::local_kopere_bi\",\"type\":\"dateRenderer\",\"mustache\":\"\"}}}',1780646819),
(13,'report_4_enrolpercourse_1','lang::report_page_004_block_2_element_1_title::local_kopere_bi',10,1,'area','light','',NULL,NULL,'SELECT c.fullname,\n       SUM(CASE \n               WHEN ue.status = 0 AND (ue.timeend = 0 OR ue.timeend > UNIX_TIMESTAMP()) THEN 1\n               ELSE 0\n           END) AS \'lang::active_enrolments::local_kopere_bi\',\n       SUM(CASE \n               WHEN ue.status = 1 THEN 1\n               ELSE 0\n           END) AS \'lang::inactive_enrolments::local_kopere_bi\',\n       SUM(CASE \n               WHEN ue.status = 0 AND ue.timeend > 0 AND ue.timeend < UNIX_TIMESTAMP() THEN 1\n               ELSE 0\n           END) AS \'lang::expired_enrolments::local_kopere_bi\'\nFROM mdl_course c\nJOIN mdl_enrol e ON e.courseid = c.id\nJOIN mdl_user_enrolments ue ON ue.enrolid = e.id\nGROUP BY c.id\nORDER BY c.fullname','30m','30m','{\"chart_options\":\"{\\r\\n    stroke : {\\r\\n        colors : [\\\"#2E93fA\\\", \\\"#66DA26\\\", \\\"#546E7A\\\", \\\"#E91E63\\\", \\\"#FF9800\\\"]\\r\\n    },\\r\\n    yaxis : {\\r\\n        labels : {\\r\\n            formatter: (value) => { return value },\\r\\n        },\\r\\n    },\\r\\n}\"}',1780646819),
(14,'report_7_users_not_accessed_course','lang::report_page_005_block_1_element_1_title::local_kopere_bi',11,1,'table','light','','','','SELECT u.id        AS u_id,\n       u.firstname,\n       u.lastname,\n       c.id       AS c_id,\n       c.fullname AS c_fullname,\n       u.email,\n       u.phone1,\n       u.city,\n       u.country,\n       u.firstaccess,\n       u.lastaccess,\n       u.lastlogin,\n       u.lastip,\n       (SELECT r.name\n           FROM {user_enrolments} ue2\n           JOIN {enrol} e ON e.id = ue2.enrolid\n           JOIN {role}  r ON e.id = r.id\n          WHERE ue2.userid = u.id\n            AND e.courseid = c.id ) AS rolename\n  FROM mdl_user_enrolments ue\n  JOIN mdl_enrol  e ON e.id = ue.enrolid\n  JOIN mdl_course c ON c.id = e.courseid\n  JOIN mdl_user   u ON u.id = ue.userid\nLEFT JOIN {user_lastaccess} ul ON ul.userid = u.id\n WHERE ul.timeaccess IS NULL','30m','30m','{\"column\":{\"u_id\":{\"key\":\"u_id\",\"title\":\"#\",\"type\":\"userphotoRenderer\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::u_fullname::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{u_id}}}\\\"\\r\\n   target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"c_id\":{\"key\":\"c_id\",\"title\":\"lang::report_field_c_id_title::local_kopere_bi\",\"type\":\"none\",\"mustache\":\"\"},\"c_fullname\":{\"key\":\"c_fullname\",\"title\":\"lang::c_fullname::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{c_id}}}\\\"\\r\\n   target=\\\"course\\\">{{{c_fullname}}}<\\/a>\"},\"email\":{\"key\":\"email\",\"title\":\"lang::email::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"phone1\":{\"key\":\"phone1\",\"title\":\"lang::phone1::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone1}}}\\\" target=\\\"_blank\\\">{{{phone1}}}<\\/a>\"},\"city\":{\"key\":\"city\",\"title\":\"lang::city::moodle\",\"type\":\"string\",\"mustache\":\"{{{city}}}\"},\"country\":{\"key\":\"country\",\"title\":\"lang::country::moodle\",\"type\":\"string\",\"mustache\":\"{{{country}}}\"},\"firstaccess\":{\"key\":\"firstaccess\",\"title\":\"lang::firstaccess::moodle\",\"type\":\"datetimeRenderer\",\"mustache\":\"{{{firstaccess}}}\"},\"lastaccess\":{\"key\":\"lastaccess\",\"title\":\"lang::lastaccess::moodle\",\"type\":\"datetimeRenderer\",\"mustache\":\"{{{lastaccess}}}\"},\"lastlogin\":{\"key\":\"lastlogin\",\"title\":\"lang::lastlogin::moodle\",\"type\":\"datetimeRenderer\",\"mustache\":\"{{{lastlogin}}}\"},\"lastip\":{\"key\":\"lastip\",\"title\":\"lang::lastip::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"https:\\/\\/www.geodatatool.com\\/?ip={{{lastip}}}\\\" target=\\\"geoip\\\">{{{lastip}}}<\\/a>\"},\"rolename\":{\"key\":\"rolename\",\"title\":\"lang::rolename::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"{{{rolename}}}\"}}}',1780646820),
(15,'reports_report_user-5','lang::report_page_006_block_1_element_1_title::local_kopere_bi',12,1,'table','light','',NULL,NULL,'SELECT u.id        AS u_id, \n       u.firstname, \n       u.lastname, \n       u.email,\n       u.phone1, \n       u.phone2, \n       u.city, \n       u.country, \n       u.timecreated\n  FROM mdl_user u\n WHERE u.deleted    = 0\n   AND u.id         > 1\n   AND u.lastlogin  = 0\n   AND u.lastaccess = 0','30m','30m','{\"column\":{\"u_id\":{\"key\":\"u_id\",\"title\":\"#\",\"type\":\"userphotoRenderer\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::u_fullname::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{u_id}}}\\\"\\r\\n   target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::email::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"phone1\":{\"key\":\"phone1\",\"title\":\"lang::phone1::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone1}}}\\\" target=\\\"_blank\\\">{{{phone1}}}<\\/a>\"},\"phone2\":{\"key\":\"phone2\",\"title\":\"lang::phone2::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone2}}}\\\" target=\\\"_blank\\\">{{{phone2}}}<\\/a>\"},\"city\":{\"key\":\"city\",\"title\":\"lang::city::moodle\",\"type\":\"string\",\"mustache\":\"{{{city}}}\"},\"country\":{\"key\":\"country\",\"title\":\"lang::country::moodle\",\"type\":\"string\",\"mustache\":\"{{{country}}}\"},\"timecreated\":{\"key\":\"timecreated\",\"title\":\"lang::timecreated::moodle\",\"type\":\"datetimeRenderer\",\"mustache\":\"\"}}}',1780646820),
(16,'reports_report_user-4','lang::report_page_006_block_2_element_1_title::local_kopere_bi',13,2,'table','light','','','','SELECT u.id        AS u_id, \n       u.firstname,\n       u.lastname,\n       u.email,\n       u.phone1,\n       u.phone2,\n       u.city,\n       u.country,\n       u.firstaccess,\n       u.lastaccess,\n       u.lastlogin,\n       u.lastip, \n       u.timecreated\n  FROM mdl_user u\n WHERE u.deleted     = 0\n   AND u.id          > 1\n   AND u.firstaccess > 0','none','none','{\"column\":{\"u_id\":{\"key\":\"u_id\",\"title\":\"#\",\"type\":\"userphotoRenderer\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::u_fullname::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{u_id}}}\\\"\\r\\n   target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::email::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"phone1\":{\"key\":\"phone1\",\"title\":\"lang::phone1::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone1}}}\\\" target=\\\"_blank\\\">{{{phone1}}}<\\/a>\"},\"phone2\":{\"key\":\"phone2\",\"title\":\"lang::phone2::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone2}}}\\\" target=\\\"_blank\\\">{{{phone2}}}<\\/a>\"},\"city\":{\"key\":\"city\",\"title\":\"lang::city::moodle\",\"type\":\"string\",\"mustache\":\"{{{city}}} \\/ {{{country}}}\"},\"country\":{\"key\":\"country\",\"title\":\"lang::country::moodle\",\"type\":\"none\",\"mustache\":\"{{{country}}}\"},\"firstaccess\":{\"key\":\"firstaccess\",\"title\":\"lang::firstaccess::moodle\",\"type\":\"dateRenderer\",\"mustache\":\"\"},\"lastaccess\":{\"key\":\"lastaccess\",\"title\":\"lang::lastaccess::moodle\",\"type\":\"dateRenderer\",\"mustache\":\"\"},\"lastlogin\":{\"key\":\"lastlogin\",\"title\":\"lang::lastlogin::moodle\",\"type\":\"dateRenderer\",\"mustache\":\"\"},\"lastip\":{\"key\":\"lastip\",\"title\":\"lang::lastip::moodle\",\"type\":\"string\",\"mustache\":\"<a href=\\\"https:\\/\\/www.geodatatool.com\\/?ip={{{lastip}}}\\\" target=\\\"geoip\\\">{{{lastip}}}<\\/a>\"},\"timecreated\":{\"key\":\"timecreated\",\"title\":\"lang::timecreated::moodle\",\"type\":\"dateRenderer\",\"mustache\":\"\"}}}',1780646820),
(17,'report_8_teacher_access','lang::report_page_007_block_1_element_1_title::local_kopere_bi',14,1,'table','light','',NULL,NULL,'SELECT \n    kbi_u.id        AS u_id,\n    kbi_u.firstname,\n    kbi_u.lastname,\n    COUNT(DISTINCT kbi_ctx.instanceid)  AS num_courses,\n    SUM(l.learners)                 AS num_learners,\n    SUM(l1.activelearners)          AS num_activelearners,\n    SUM(cc.completed)               AS num_completedlearners,\n    AVG(kbi_g.grade)                    AS grade\nFROM mdl_user kbi_u\nLEFT JOIN mdl_role_assignments kbi_ra ON kbi_ra.userid = kbi_u.id\nLEFT JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\nJOIN mdl_course kbi_c ON kbi_ctx.instanceid = kbi_c.id AND kbi_c.visible = 1\nLEFT JOIN (\n    SELECT \n        kbi_ctx.instanceid, \n        COUNT(DISTINCT kbi_ra.userid) AS learners\n    FROM mdl_role_assignments kbi_ra, mdl_context kbi_ctx\n    WHERE \n        kbi_ctx.id = kbi_ra.contextid\n        AND kbi_ctx.contextlevel = 50\n        AND kbi_ra.roleid = 5\n    GROUP BY \n        kbi_ctx.instanceid\n) AS l ON l.instanceid = kbi_ctx.instanceid\nLEFT JOIN (\n    SELECT \n        kbi_ctx.instanceid, \n        COUNT(DISTINCT kbi_ra.userid) AS activelearners\n    FROM mdl_role_assignments kbi_ra, mdl_user kbi_u, mdl_context kbi_ctx\n    WHERE \n        kbi_ctx.id = kbi_ra.contextid\n        AND kbi_ctx.contextlevel = 50\n        AND kbi_u.id = kbi_ra.userid\n        -- AND kbi_u.lastaccess BETWEEN 1707755694 AND 1710347694\n        AND kbi_u.deleted = 0\n        AND kbi_u.suspended = 0\n        AND kbi_ra.roleid = 5\n    GROUP BY \n        kbi_ctx.instanceid\n) AS l1 ON l1.instanceid = kbi_ctx.instanceid\nLEFT JOIN (\n    SELECT \n        course, \n        COUNT(id) AS completed\n    FROM \n        mdl_course_completions\n    WHERE \n        timecompleted > 0\n    GROUP BY \n        course\n) cc ON cc.course = kbi_ctx.instanceid\nLEFT JOIN (\n    SELECT \n        kbi_gi.courseid,\n        ROUND(AVG(CASE\n            WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n            ELSE kbi_g.finalgrade \n        END), 0) AS grade\n    FROM mdl_grade_items kbi_gi, mdl_grade_grades kbi_g\n    WHERE \n        kbi_gi.itemtype = \'course\'\n        AND kbi_g.itemid = kbi_gi.id\n        AND kbi_g.finalgrade IS NOT NULL\n    GROUP BY \n        kbi_gi.courseid\n) g ON kbi_g.courseid = kbi_ctx.instanceid\nWHERE kbi_ctx.contextlevel = 50\n  AND kbi_ra.roleid        = 3\n  AND kbi_u.deleted        = 0\n  AND kbi_u.suspended      = 0\nGROUP BY kbi_u.id, kbi_u.firstname, kbi_u.lastname','30m','30m','{\"column\":{\"u_id\":{\"key\":\"u_id\",\"title\":\"#\",\"type\":\"userphotoRenderer\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::u_fullname::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{u_id}}}\\\"\\r\\n   target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"num_courses\":{\"key\":\"num_courses\",\"title\":\"lang::num_courses::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"num_learners\":{\"key\":\"num_learners\",\"title\":\"lang::num_learners::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"num_activelearners\":{\"key\":\"num_activelearners\",\"title\":\"lang::num_activelearners::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"num_completedlearners\":{\"key\":\"num_completedlearners\",\"title\":\"lang::num_completedlearners::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::grade::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646820),
(18,'report_2_total_engagement','lang::report_page_007_block_2_element_1_title::local_kopere_bi',15,1,'table','light','','','','SELECT kbi_c.id       AS c_id,\n       kbi_c.fullname AS c_fullname,\n       COUNT(DISTINCT kbi_ra.userid) AS num_learners,\n       COUNT(DISTINCT CASE\n           WHEN comp.userid IS NOT NULL AND kbi_ula.id IS NOT NULL THEN kbi_u.id\n           ELSE NULL \n       END) AS completed_learners,\n       COUNT(DISTINCT CASE\n           WHEN comp.userid IS NULL AND kbi_ula.id IS NOT NULL THEN kbi_u.id\n           ELSE NULL \n       END) AS not_completed_learners,\n       COUNT(DISTINCT CASE \n           WHEN kbi_ula.id IS NULL THEN kbi_u.id \n           ELSE NULL \n       END) AS not_accessed_learners\nFROM mdl_role_assignments kbi_ra\nJOIN mdl_context kbi_ctx \n    ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\nJOIN mdl_course kbi_c \n    ON kbi_c.id = kbi_ctx.instanceid\nJOIN mdl_user kbi_u \n    ON kbi_u.id = kbi_ra.userid\nLEFT JOIN (\n    SELECT kbi_cm.course, kbi_cmc.userid\n    FROM mdl_course_modules kbi_cm\n    JOIN mdl_course_modules_completion kbi_cmc \n        ON kbi_cmc.coursemoduleid = kbi_cm.id AND kbi_cmc.completionstate = 1\n    WHERE kbi_cmc.id > 0\n    GROUP BY kbi_cm.course, kbi_cmc.userid\n) comp \n    ON comp.userid = kbi_u.id AND comp.course = kbi_c.id\nLEFT JOIN mdl_user_lastaccess kbi_ula \n    ON kbi_ula.courseid = kbi_c.id AND kbi_ula.userid = kbi_ra.userid\nWHERE kbi_c.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_c.visible = 1\n  AND kbi_ra.roleid = 5\nGROUP BY kbi_c.id','30m','30m','{\"column\":{\"c_id\":{\"key\":\"c_id\",\"title\":\"#\",\"type\":\"none\",\"mustache\":\"\"},\"c_fullname\":{\"key\":\"c_fullname\",\"title\":\"lang::c_fullname::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{c_id}}}\\\"\\r\\n   target=\\\"course\\\">{{{c_fullname}}}<\\/a>\"},\"num_learners\":{\"key\":\"num_learners\",\"title\":\"lang::num_learners::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completed_learners\":{\"key\":\"completed_learners\",\"title\":\"lang::completed_learners::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<div id=\\\"{{{uniqid}}}\\\" class=\\\"progress-bar-container\\\" style=\\\"background: #E0E0E0;height: 30px;position: relative;border-radius: 4px;overflow: hidden;\\\">\\r\\n    <div class=\\\"progress-bar\\\" style=\\\"position: absolute;background-color: #6eafe6;\\\"><\\/div>\\r\\n    <div class=\\\"progress-text\\\" style=\\\"height: 30px;display: flex;position: absolute;align-items: center;justify-content: center;width: 100%;\\\">\\r\\n        {{{completed_learners}}} \\/ {{{num_learners}}}\\r\\n    <\\/div>\\r\\n<\\/div>\\r\\n<script>\\r\\n    var percentage = ({{{completed_learners}}} \\/ {{{num_learners}}}) * 100;\\r\\n    $(\\\"#{{{uniqid}}} .progress-bar\\\")\\r\\n        .css({\\r\\n            width : percentage+\\\"%\\\"\\r\\n        })\\r\\n<\\/script>\"},\"not_completed_learners\":{\"key\":\"not_completed_learners\",\"title\":\"lang::not_completed_learners::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<div id=\\\"{{{uniqid}}}\\\" class=\\\"progress-bar-container\\\" style=\\\"background: #E0E0E0;height: 30px;position: relative;border-radius: 4px;overflow: hidden;\\\">\\r\\n    <div class=\\\"progress-bar\\\" style=\\\"position: absolute;background-color: #6eafe6;\\\"><\\/div>\\r\\n    <div class=\\\"progress-text\\\" style=\\\"height: 30px;display: flex;position: absolute;align-items: center;justify-content: center;width: 100%;\\\">\\r\\n        {{{not_completed_learners}}} \\/ {{{num_learners}}}\\r\\n    <\\/div>\\r\\n<\\/div>\\r\\n<script>\\r\\n    var percentage = ({{{not_completed_learners}}} \\/ {{{num_learners}}}) * 100;\\r\\n    $(\\\"#{{{uniqid}}} .progress-bar\\\")\\r\\n        .css({\\r\\n            width : percentage+\\\"%\\\"\\r\\n        })\\r\\n<\\/script>\"},\"not_accessed_learners\":{\"key\":\"not_accessed_learners\",\"title\":\"lang::not_accessed_learners::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<div id=\\\"{{{uniqid}}}\\\" class=\\\"progress-bar-container\\\" style=\\\"background: #E0E0E0;height: 30px;position: relative;border-radius: 4px;overflow: hidden;\\\">\\r\\n    <div class=\\\"progress-bar\\\" style=\\\"position: absolute;background-color: #6eafe6;\\\"><\\/div>\\r\\n    <div class=\\\"progress-text\\\" style=\\\"height: 30px;display: flex;position: absolute;align-items: center;justify-content: center;width: 100%;\\\">\\r\\n        {{{not_accessed_learners}}} \\/ {{{num_learners}}}\\r\\n    <\\/div>\\r\\n<\\/div>\\r\\n<script>\\r\\n    var percentage = ({{{not_accessed_learners}}} \\/ {{{num_learners}}}) * 100;\\r\\n    $(\\\"#{{{uniqid}}} .progress-bar\\\")\\r\\n        .css({\\r\\n            width : percentage+\\\"%\\\"\\r\\n        })\\r\\n<\\/script>\"}}}',1780646820),
(19,'report_dashboard_page_1_users','lang::report_page_008_block_1_element_1_title::local_kopere_bi',16,1,'info','blue','','','','SELECT CONCAT(\n    (SELECT count(*) AS num FROM mdl_user WHERE id > 1 AND deleted = 0),\n    \' / \',\n    (SELECT count(*) AS num FROM mdl_user WHERE id > 1 AND deleted = 0 AND lastaccess > 0)\n)','1h','none','[]',1780646820),
(20,'report_dashboard_page_1_online','lang::report_page_008_block_1_element_2_title::local_kopere_bi',16,2,'info','green','','','','SELECT CONCAT(\n    (\n         SELECT count(id)\n           FROM mdl_user\n          WHERE lastaccess > UNIX_TIMESTAMP() - 300\n       GROUP BY id\n    ),\n    \' / \',\n    (\n        SELECT count(id)\n          FROM mdl_user\n         WHERE lastaccess > UNIX_TIMESTAMP() - 3600\n      GROUP BY id\n    )\n)','1h','none','[]',1780646820),
(21,'report_dashboard_page_1_cursos','lang::report_page_008_block_1_element_3_title::local_kopere_bi',16,3,'info','orange','','','','SELECT CONCAT(\n    (\n        SELECT count(*) FROM mdl_course WHERE id > 1\n    ),\n    \' / \',\n    (\n        SELECT count(*) FROM mdl_course WHERE id > 1 AND visible = 1\n    )\n)','1h','none','[]',1780646820),
(22,'report_4_enrolpercourse_2','lang::report_page_008_block_2_element_1_title::local_kopere_bi',17,1,'line','light','','','','SELECT c.fullname,\n       SUM(CASE \n               WHEN ue.status = 0 AND (ue.timeend = 0 OR ue.timeend > UNIX_TIMESTAMP()) THEN 1\n               ELSE 0\n           END) AS \'lang::active_enrolments::local_kopere_bi\',\n       SUM(CASE \n               WHEN ue.status = 1 THEN 1\n               ELSE 0\n           END) AS \'lang::inactive_enrolments::local_kopere_bi\',\n       SUM(CASE \n               WHEN ue.status = 0 AND ue.timeend > 0 AND ue.timeend < UNIX_TIMESTAMP() THEN 1\n               ELSE 0\n           END) AS \'lang::expired_enrolments::local_kopere_bi\'\nFROM mdl_course c\nJOIN mdl_enrol e ON e.courseid = c.id\nJOIN mdl_user_enrolments ue ON ue.enrolid = e.id\nGROUP BY c.id\nORDER BY c.fullname','1h','none','{\"chart_options\":\"{\\r\\n    stroke : {\\r\\n        colors : [\\\"#2E93fA\\\", \\\"#66DA26\\\", \\\"#546E7A\\\", \\\"#E91E63\\\", \\\"#FF9800\\\"]\\r\\n    },\\r\\n    yaxis : {\\r\\n        labels : {\\r\\n            formatter: (value) => { return value },\\r\\n        },\\r\\n    },\\r\\n}\"}',1780646820),
(23,'report_dashboard_page_1_newusers','lang::report_page_008_block_3_element_1_title::local_kopere_bi',18,1,'line','light','','','','  SELECT FROM_UNIXTIME(timecreated, \'%m/%Y\') AS yearmonth,\n         COUNT(id) AS \'lang::num_user::local_kopere_bi\'\n    FROM mdl_user\n   WHERE deleted = 0\n     AND confirmed = 1\n     AND timecreated >= UNIX_TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 12 MONTH))\nGROUP BY yearmonth\nORDER BY yearmonth DESC','none','none','{\"chart_options\":\"{\\r\\n    stroke : {\\r\\n        colors : [\\\"#2E93fA\\\", \\\"#66DA26\\\", \\\"#546E7A\\\", \\\"#E91E63\\\", \\\"#FF9800\\\"]\\r\\n    },\\r\\n    yaxis : {\\r\\n        labels : {\\r\\n            formatter: (value) => { return value },\\r\\n        },\\r\\n    },\\r\\n}\"}',1780646820),
(24,'report_9_report_1','lang::report_page_009_block_1_element_1_title::local_kopere_bi',19,1,'table','light','','','','  SELECT CONCAT(\'lang::modulename::\', m.name) AS lang_module_name, \r\n         m.name AS module_name,\r\n         COUNT(cm.id) AS module_count,\r\n         cm.course\r\n    FROM mdl_course_modules cm\r\n    JOIN mdl_modules         m ON cm.module = m.id\r\n   WHERE cm.deletioninprogress = 0\r\nGROUP BY m.name\r\nORDER BY module_count DESC','1h','1h','{\"column\":{\"lang_module_name\":{\"key\":\"lang_module_name\",\"title\":\"lang::module_name::local_kopere_bi\",\"type\":\"translate\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/mod\\/{{{module_name}}}\\/view.php?id={{{cm_cmid}}}\\\">\\r\\n    {{{lang_module_name}}}\\r\\n<\\/a>\"},\"module_name\":{\"key\":\"module_name\",\"title\":\"lang::module_name::local_kopere_bi\",\"type\":\"none\",\"mustache\":\"\"},\"module_count\":{\"key\":\"module_count\",\"title\":\"lang::module_count::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"none\",\"mustache\":\"\"}}}',1780646820),
(25,'kbi_el_cohort_success_and_progress_lear','lang::report_page_010_title::local_kopere_bi',20,1,'table','light','','','','SELECT kbi_ue.id                             AS id,\n       kbi_cri.gradepass                     AS gradepass,\n       kbi_ue.timecreated                    as started,\n       ROUND((CASE\n                WHEN (kbi_g.rawgrademax - kbi_g.rawgrademin) > 0\n                        THEN ((kbi_g.finalgrade - kbi_g.rawgrademin) / (kbi_g.rawgrademax - kbi_g.rawgrademin)) * 100\n                ELSE kbi_g.finalgrade END),\n             0)                          AS grade,\n       ROUND((CASE\n                WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                ELSE kbi_g.finalgrade END),\n             0)                          AS grade_real,\n       kbi_cc.timecompleted                  as complete,\n       kbi_c.id                              as cid,\n       kbi_c.fullname,\n       kbi_e.enrol,\n       kbi_u.email,\n       kbi_u.id                              AS userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_c.enablecompletion,\n       (SELECT COUNT(DISTINCT kbi_cmc.id)\n        FROM mdl_course_modules_completion kbi_cmc, mdl_course_modules kbi_cm\n        WHERE kbi_cm.visible = 1\n          AND kbi_cmc.coursemoduleid = kbi_cm.id\n          AND kbi_cmc.completionstate IN (1, 2)\n          AND kbi_cm.completion > 0\n          AND kbi_cm.course = kbi_c.id\n          AND kbi_cmc.userid = kbi_u.id)         AS completed,\n       (SELECT ROUND((CASE\n                        WHEN (kbi_g.rawgrademax - kbi_g.rawgrademin) > 0\n                                THEN ((kbi_g.finalgrade - kbi_g.rawgrademin) / (kbi_g.rawgrademax - kbi_g.rawgrademin)) * 100\n                        ELSE kbi_g.finalgrade END), 0)\n        FROM mdl_grade_items kbi_gi, mdl_grade_grades kbi_g\n        WHERE kbi_gi.itemtype = \'course\'\n          AND kbi_g.itemid = kbi_gi.id\n          AND kbi_g.finalgrade IS NOT NULL\n          AND kbi_gi.courseid = kbi_c.id\n        LIMIT 1)                         AS average,\n       (SELECT GROUP_CONCAT(DISTINCT CONCAT(kbi_u.firstname, \' \', kbi_u.lastname) SEPARATOR \', \')\n        FROM mdl_role_assignments kbi_ra\n               JOIN mdl_user kbi_u ON kbi_ra.userid = kbi_u.id\n               JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n        WHERE kbi_ctx.instanceid = kbi_c.id\n          AND kbi_ctx.contextlevel = 50\n          AND kbi_ra.roleid = 3) AS teacher,\n       \'\'                                as cohortname,\n       lit.timespend                     AS timespend,\n       lit.visits                        AS visits\nFROM mdl_user_enrolments kbi_ue\n       LEFT JOIN mdl_user kbi_u ON kbi_u.id = kbi_ue.userid\n       LEFT JOIN mdl_enrol kbi_e ON kbi_e.id = kbi_ue.enrolid\n       LEFT JOIN mdl_course kbi_c ON kbi_c.id = kbi_e.courseid\n       LEFT JOIN mdl_course_completions kbi_cc ON kbi_cc.course = kbi_e.courseid AND kbi_cc.userid = kbi_ue.userid\n       LEFT JOIN mdl_course_completion_criteria kbi_cri ON kbi_cri.course = kbi_e.courseid AND kbi_cri.criteriatype = 6\n       LEFT JOIN mdl_grade_items kbi_gi ON kbi_gi.courseid = kbi_c.id AND kbi_gi.itemtype = \'course\'\n       LEFT JOIN mdl_grade_grades kbi_g ON kbi_g.itemid = kbi_gi.id AND kbi_g.userid = kbi_u.id\n       LEFT JOIN (SELECT userid, courseid, SUM(timespend) as timespend, SUM(visits) as visits\n                  FROM mdl_local_kopere_bi_tracking\n                  WHERE id > 0\n                    AND courseid = :courseid\n                  GROUP BY userid, courseid) lit ON lit.courseid = kbi_c.id AND lit.userid = kbi_u.id\nWHERE kbi_ue.id > 0\n  AND kbi_e.courseid = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_ue.status = 0\n  AND kbi_e.status = 0','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"gradepass\":{\"key\":\"gradepass\",\"title\":\"lang::report_field_gradepass_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"started\":{\"key\":\"started\",\"title\":\"lang::report_field_started_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade_real\":{\"key\":\"grade_real\",\"title\":\"lang::report_field_grade_real_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"complete\":{\"key\":\"complete\",\"title\":\"lang::report_field_complete_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"cid\":{\"key\":\"cid\",\"title\":\"lang::report_field_cid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{cid}}}\\\" target=\\\"course\\\">{{{fullname}}}<\\/a>\"},\"enrol\":{\"key\":\"enrol\",\"title\":\"lang::report_field_enrol_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"enablecompletion\":{\"key\":\"enablecompletion\",\"title\":\"lang::report_field_enablecompletion_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"completed\":{\"key\":\"completed\",\"title\":\"lang::report_field_completed_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"average\":{\"key\":\"average\",\"title\":\"lang::report_field_average_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"teacher\":{\"key\":\"teacher\",\"title\":\"lang::report_field_teacher_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"cohortname\":{\"key\":\"cohortname\",\"title\":\"lang::report_field_cohortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646820),
(26,'kbi_el_inactive_users_in_course_s','lang::report_page_011_title::local_kopere_bi',21,1,'table','light','','','','SELECT DISTINCT kbi_u.id                                     AS userid,\n                kbi_u.firstname,\n                kbi_u.lastname,\n                kbi_u.email,\n                coo.cohortname                           AS cohorts,\n                kbi_ue.timecreated,\n                kbi_u.lastlogin,\n                kbi_lit.firstaccess,\n                kbi_ul.timeaccess                            AS lastaccess,\n                m.modules,\n                kbi_cmc.completed,\n                kbi_cc1.timecompleted                        as course_completion,\n                kbi_c.id                                     AS course_id,\n                kbi_c.fullname                               AS course_name,\n                (SELECT DISTINCT CONCAT(kbi_u.firstname, \' \', kbi_u.lastname)\n                 FROM mdl_role_assignments kbi_ra\n                        JOIN mdl_user kbi_u ON kbi_ra.userid = kbi_u.id\n                        JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n                 WHERE kbi_ctx.instanceid = kbi_c.id\n                   AND kbi_ctx.contextlevel = 50\n                   AND kbi_ra.roleid = 3\n                 LIMIT 1)                                AS teacher\nFROM mdl_course kbi_c\n       JOIN mdl_enrol kbi_e ON kbi_e.courseid = kbi_c.id\n       JOIN mdl_user_enrolments kbi_ue ON kbi_ue.enrolid = kbi_e.id\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ue.userid\n       LEFT JOIN (SELECT kbi_ch.userid, GROUP_CONCAT(DISTINCT kbi_coh.name SEPARATOR \', \') as cohortname\n                  FROM mdl_cohort kbi_coh\n                         JOIN mdl_cohort_members kbi_ch ON kbi_ch.cohortid = kbi_coh.id\n                  GROUP BY kbi_ch.userid) coo ON coo.userid = kbi_u.id\n       LEFT JOIN mdl_course_completions kbi_cc1 ON kbi_cc1.userid = kbi_u.id AND kbi_cc1.course = kbi_c.id\n       LEFT JOIN (SELECT kbi_cm.course, COUNT(kbi_cm.id) AS modules\n                  FROM mdl_course_modules kbi_cm\n                  WHERE kbi_cm.deletioninprogress = 0\n                    AND kbi_cm.visible = 1\n                  GROUP BY kbi_cm.course) m ON m.course = kbi_c.id\n       LEFT JOIN (SELECT kbi_cm.course, kbi_cmc.userid, COUNT(kbi_cmc.id) AS completed\n                  FROM mdl_course_modules kbi_cm, mdl_course_modules_completion kbi_cmc\n                  WHERE kbi_cmc.coursemoduleid = kbi_cm.id\n                    AND kbi_cm.visible = 1\n                    AND kbi_cmc.completionstate IN (1, 2)\n                  GROUP BY kbi_cm.course, kbi_cmc.userid) cmc ON kbi_cmc.course = kbi_c.id AND kbi_cmc.userid = kbi_u.id\n       LEFT JOIN mdl_local_kopere_bi_tracking kbi_lit ON kbi_lit.page = \'course\' AND kbi_lit.param = kbi_c.id AND kbi_lit.userid = kbi_u.id\n       LEFT JOIN mdl_user_lastaccess kbi_ul ON kbi_ul.courseid = kbi_c.id AND kbi_ul.userid = kbi_u.id\nWHERE kbi_c.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_ue.status = 0\n  AND kbi_e.status = 0\n  AND (kbi_ul.timeaccess < (UNIX_TIMESTAMP() - 2592000) OR kbi_ul.timeaccess IS NULL)\nGROUP BY kbi_u.id, kbi_c.id, kbi_u.firstname, kbi_u.lastname, kbi_u.email, cohorts, kbi_ue.timecreated,\n         kbi_u.lastlogin, kbi_lit.firstaccess, kbi_ul.timeaccess, m.modules, kbi_cmc.completed, course_completion, course_id,\n         course_name, teacher','1h','none','{\"column\":{\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"cohorts\":{\"key\":\"cohorts\",\"title\":\"lang::report_field_cohorts_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timecreated\":{\"key\":\"timecreated\",\"title\":\"lang::report_field_timecreated_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"lastlogin\":{\"key\":\"lastlogin\",\"title\":\"lang::report_field_lastlogin_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"firstaccess\":{\"key\":\"firstaccess\",\"title\":\"lang::report_field_firstaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"lastaccess\":{\"key\":\"lastaccess\",\"title\":\"lang::report_field_lastaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"modules\":{\"key\":\"modules\",\"title\":\"lang::report_field_modules_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completed\":{\"key\":\"completed\",\"title\":\"lang::report_field_completed_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course_completion\":{\"key\":\"course_completion\",\"title\":\"lang::report_field_course_completion_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"course_id\":{\"key\":\"course_id\",\"title\":\"lang::report_field_course_id_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course_name\":{\"key\":\"course_name\",\"title\":\"lang::report_field_course_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teacher\":{\"key\":\"teacher\",\"title\":\"lang::report_field_teacher_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(27,'kbi_el_inactive_users_in_system_inacti','lang::report_page_012_title::local_kopere_bi',22,1,'table','light','','','','SELECT DISTINCT kbi_u.id,\n                kbi_u.firstname,\n                kbi_u.lastname,\n                kbi_u.email,\n                kbi_u.timecreated,\n                kbi_u.firstaccess,\n                kbi_u.lastaccess,\n                kbi_u.lastlogin\nFROM mdl_user kbi_u\nWHERE kbi_u.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_u.lastaccess < (UNIX_TIMESTAMP() - 2592000)','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"timecreated\":{\"key\":\"timecreated\",\"title\":\"lang::report_field_timecreated_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"firstaccess\":{\"key\":\"firstaccess\",\"title\":\"lang::report_field_firstaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"lastaccess\":{\"key\":\"lastaccess\",\"title\":\"lang::report_field_lastaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"lastlogin\":{\"key\":\"lastlogin\",\"title\":\"lang::report_field_lastlogin_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(28,'kbi_el_learner_success_and_progress','lang::report_page_013_title::local_kopere_bi',23,1,'table','light','','','','SELECT CASE\n         WHEN kbi_gi.grademax > 0 THEN (kbi_cri.gradepass / kbi_gi.grademax) * 100\n         ELSE kbi_cri.gradepass END            AS gradepass,\n       kbi_cri.gradepass                       AS gradepass_raw,\n       kbi_u.email,\n       kbi_ue.userid,\n       kbi_ue.started,\n       kbi_c.id                                AS cid,\n       kbi_c.fullname,\n       kbi_ue.enrolment,\n       kbi_c.startdate,\n       kbi_lit.lastaccess,\n       git.average,\n       ROUND((CASE\n                WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                ELSE kbi_g.finalgrade END), 2) AS grade,\n       ROUND((CASE\n                WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                ELSE kbi_g.finalgrade END), 2) AS grade_raw,\n       ROUND((CASE\n                WHEN (kbi_g.rawgrademax - kbi_g.rawgrademin) > 0\n                        THEN ((kbi_g.finalgrade - kbi_g.rawgrademin) / (kbi_g.rawgrademax - kbi_g.rawgrademin)) * 100\n                ELSE kbi_g.finalgrade END), 2) AS grade_percent,\n       kbi_cmc.completed,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_lit.timespend,\n       kbi_lit.visits,\n       kbi_c.enablecompletion,\n       kbi_cc.timecompleted                    AS complete\nFROM (SELECT DISTINCT kbi_e.courseid,\n                      kbi_ue.userid,\n                      (CASE\n                         WHEN kbi_ue.timestart > 0\n                                 THEN kbi_ue.timestart\n                         ELSE kbi_ue.timecreated\n                          END) AS started,\n                      (CASE\n                         WHEN kbi_e.name IS NULL\n                                 THEN kbi_e.enrol\n                         ELSE CONCAT(kbi_e.enrol, \'(\', kbi_e.name, \')\')\n                          END) AS enrolment\n      FROM mdl_enrol kbi_e\n             JOIN mdl_user_enrolments kbi_ue ON kbi_ue.enrolid = kbi_e.id\n             JOIN mdl_context kbi_ctx ON kbi_ctx.contextlevel = 50 AND kbi_ctx.instanceid = kbi_e.courseid\n             JOIN mdl_role_assignments kbi_ra\n               ON kbi_ra.contextid = kbi_ctx.id AND kbi_ra.userid = kbi_ue.userid AND kbi_ra.roleid = 5\n      WHERE kbi_ue.userid > 0\n        AND kbi_e.status = 0\n        AND kbi_ue.status = 0\n        AND kbi_e.courseid = :courseid) ue\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ue.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_ue.courseid\n       LEFT JOIN mdl_course_completions kbi_cc ON kbi_cc.course = kbi_c.id AND kbi_cc.userid = kbi_u.id\n       LEFT JOIN mdl_course_completion_criteria kbi_cri ON kbi_cri.course = kbi_c.id AND kbi_cri.criteriatype = 6\n       LEFT JOIN mdl_grade_items kbi_gi ON kbi_gi.courseid = kbi_c.id AND kbi_gi.itemtype = \'course\'\n       LEFT JOIN mdl_grade_grades kbi_g ON kbi_g.itemid = kbi_gi.id AND kbi_g.userid = kbi_u.id\n       LEFT JOIN (SELECT kbi_lit.userid,\n                         kbi_lit.courseid,\n                         SUM(kbi_lit.timespend)  as timespend,\n                         SUM(kbi_lit.visits)     as visits,\n                         MAX(kbi_lit.lastaccess) as lastaccess\n                  FROM mdl_local_kopere_bi_tracking kbi_lit\n                  WHERE kbi_lit.courseid > 0\n                    AND kbi_lit.courseid = :courseid\n                  GROUP BY kbi_lit.courseid, kbi_lit.userid) lit ON kbi_lit.courseid = kbi_c.id AND kbi_lit.userid = kbi_u.id\n       LEFT JOIN (SELECT kbi_gi.courseid,\n                         ROUND(AVG(CASE\n                                     WHEN (kbi_g.rawgrademax - kbi_g.rawgrademin) > 0\n                                             THEN ((kbi_g.finalgrade - kbi_g.rawgrademin) / (kbi_g.rawgrademax - kbi_g.rawgrademin)) * 100\n                                     ELSE kbi_g.finalgrade END), 2) AS average\n                  FROM mdl_grade_items kbi_gi, mdl_grade_grades kbi_g\n                  WHERE kbi_gi.itemtype = \'course\'\n                    AND kbi_g.itemid = kbi_gi.id\n                    AND kbi_g.finalgrade IS NOT NULL\n                    AND kbi_gi.courseid = :courseid\n                  GROUP BY kbi_gi.courseid) git ON git.courseid = kbi_c.id\n       LEFT JOIN (SELECT kbi_cmc.userid, kbi_cm.course, COUNT(kbi_cmc.id) as completed\n                  FROM mdl_course_modules_completion kbi_cmc, mdl_course_modules kbi_cm\n                  WHERE kbi_cm.visible = 1\n                    AND kbi_cmc.coursemoduleid = kbi_cm.id\n                    AND kbi_cmc.completionstate IN (1, 2)\n                    AND kbi_cm.course = :courseid\n                  GROUP BY kbi_cm.course, kbi_cmc.userid) cmc ON kbi_cmc.course = kbi_c.id AND kbi_cmc.userid = kbi_u.id\nWHERE kbi_u.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1','1h','none','{\"column\":{\"gradepass\":{\"key\":\"gradepass\",\"title\":\"lang::report_field_gradepass_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"gradepass_raw\":{\"key\":\"gradepass_raw\",\"title\":\"lang::report_field_gradepass_raw_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"started\":{\"key\":\"started\",\"title\":\"lang::report_field_started_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"cid\":{\"key\":\"cid\",\"title\":\"lang::report_field_cid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{cid}}}\\\" target=\\\"course\\\">{{{fullname}}}<\\/a>\"},\"enrolment\":{\"key\":\"enrolment\",\"title\":\"lang::report_field_enrolment_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"startdate\":{\"key\":\"startdate\",\"title\":\"lang::report_field_startdate_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"lastaccess\":{\"key\":\"lastaccess\",\"title\":\"lang::report_field_lastaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"average\":{\"key\":\"average\",\"title\":\"lang::report_field_average_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade_raw\":{\"key\":\"grade_raw\",\"title\":\"lang::report_field_grade_raw_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade_percent\":{\"key\":\"grade_percent\",\"title\":\"lang::report_field_grade_percent_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completed\":{\"key\":\"completed\",\"title\":\"lang::report_field_completed_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"enablecompletion\":{\"key\":\"enablecompletion\",\"title\":\"lang::report_field_enablecompletion_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"complete\":{\"key\":\"complete\",\"title\":\"lang::report_field_complete_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"}}}',1780646820),
(29,'kbi_el_login_statistics','lang::report_page_014_title::local_kopere_bi',24,1,'table','light','','','','SELECT kbi_u.id,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_u.phone1,\n       kbi_u.phone2,\n       kbi_u.institution,\n       kbi_u.department,\n       kbi_u.address,\n       kbi_u.city,\n       kbi_u.country,\n       kbi_u.timecreated,\n       kbi_u.firstaccess,\n       kbi_u.lastaccess,\n       lit1.timespend_site,\n       lit2.timespend_courses,\n       lit3.timespend_activities\nFROM mdl_user kbi_u\n       LEFT JOIN (SELECT kbi_t.userid, SUM(timespend) AS timespend_site\n                  FROM mdl_local_kopere_bi_tracking kbi_t\n                  WHERE kbi_t.id > 0\n                  GROUP BY kbi_t.userid) lit1 ON lit1.userid = kbi_u.id\n       LEFT JOIN (SELECT kbi_t.userid, SUM(timespend) AS timespend_courses\n                  FROM mdl_local_kopere_bi_tracking kbi_t\n                  WHERE kbi_t.courseid > 0\n                  GROUP BY kbi_t.userid) lit2 ON lit2.userid = kbi_u.id\n       LEFT JOIN (SELECT kbi_t.userid, SUM(timespend) AS timespend_activities\n                  FROM mdl_local_kopere_bi_tracking kbi_t\n                  WHERE kbi_t.page = \'module\'\n                  GROUP BY kbi_t.userid) lit3 ON lit3.userid = kbi_u.id\nWHERE kbi_u.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"phone1\":{\"key\":\"phone1\",\"title\":\"lang::report_field_phone1_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone1}}}\\\" target=\\\"_blank\\\">{{{phone1}}}<\\/a>\"},\"phone2\":{\"key\":\"phone2\",\"title\":\"lang::report_field_phone2_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone2}}}\\\" target=\\\"_blank\\\">{{{phone2}}}<\\/a>\"},\"institution\":{\"key\":\"institution\",\"title\":\"lang::report_field_institution_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"department\":{\"key\":\"department\",\"title\":\"lang::report_field_department_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"address\":{\"key\":\"address\",\"title\":\"lang::report_field_address_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"city\":{\"key\":\"city\",\"title\":\"lang::report_field_city_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"country\":{\"key\":\"country\",\"title\":\"lang::report_field_country_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timecreated\":{\"key\":\"timecreated\",\"title\":\"lang::report_field_timecreated_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"firstaccess\":{\"key\":\"firstaccess\",\"title\":\"lang::report_field_firstaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"lastaccess\":{\"key\":\"lastaccess\",\"title\":\"lang::report_field_lastaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timespend_site\":{\"key\":\"timespend_site\",\"title\":\"lang::report_field_timespend_site_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"timespend_courses\":{\"key\":\"timespend_courses\",\"title\":\"lang::report_field_timespend_courses_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"timespend_activities\":{\"key\":\"timespend_activities\",\"title\":\"lang::report_field_timespend_activities_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"}}}',1780646820),
(30,'kbi_el_logins_logouts','lang::report_page_015_title::local_kopere_bi',25,1,'table','light','','','','SELECT kbi_l1.id, kbi_l1.userid, kbi_l1.timecreated AS loggedout\nFROM mdl_local_kopere_bi_log_tmp kbi_l1\nWHERE kbi_l1.action = \'loggedout\'\n  AND kbi_l1.contextid = 1\nORDER BY kbi_l1.id ASC','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"loggedout\":{\"key\":\"loggedout\",\"title\":\"lang::report_field_loggedout_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(31,'el_report111_os_and_browser_stats_by_user','lang::report_page_016_title::local_kopere_bi',26,1,'table','light','','','','SELECT MAX(lit.id) AS id,\n       u.id        AS userid,\n       u.firstname,\n       u.lastname,\n       u.email,\n       u.idnumber,\n       c.id        AS courseid,\n       c.fullname  AS course,\n       cc.name     AS category_name,\n       ROUND((SUM(CASE WHEN lit.useragent = \'Firefox\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)    AS firefox,\n       ROUND((SUM(CASE WHEN lit.useragent = \'Chrome\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)    AS chrome,\n       ROUND((SUM(CASE WHEN lit.useragent = \'Safari\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)    AS safari,\n       ROUND((SUM(CASE\n                    WHEN lit.useragent = \'Microsoft Edge\' OR lit.useragent = \'Edge\' THEN lit.timespend\n                    ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)    AS microsoft_edge,\n       ROUND((SUM(CASE WHEN lit.useragent = \'Opera\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)    AS opera,\n       ROUND((SUM(CASE WHEN lit.useragent = \'Mobile browser\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)    AS mobile_browser,\n       ROUND((SUM(CASE\n                    WHEN lit.useragent = \'Unknown Browser\' OR lit.useragent IS NULL THEN lit.timespend\n                    ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)    AS other_browser,\n       ROUND((SUM(CASE WHEN lit.useros LIKE \'Windows%\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)    AS windows,\n       ROUND((SUM(CASE WHEN lit.useros LIKE \'Mac OS%\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)    AS mac_os,\n       ROUND((SUM(CASE WHEN lit.useros = \'Linux\' OR lit.useros = \'Ubuntu\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)    AS linux,\n       ROUND((SUM(CASE\n                    WHEN lit.useros = \'iPhone\' OR lit.useros = \'iPod\' OR lit.useros = \'iPad\' THEN lit.timespend\n                    ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)    AS ios,\n       ROUND((SUM(CASE WHEN lit.useros = \'Android\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)    AS android,\n       ROUND((SUM(CASE WHEN lit.useros = \'Mobile\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)    AS mobile,\n       ROUND((SUM(CASE\n                    WHEN lit.useros = \'Unknown OS Platform\' OR lit.useros IS NULL THEN lit.timespend\n                    ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)    AS other_platform\nFROM mdl_local_kopere_bi_tracking lit\n       LEFT JOIN mdl_course c ON c.id = lit.courseid\n       LEFT JOIN mdl_course_categories cc ON cc.id = c.category\n       LEFT JOIN mdl_user u ON u.id = lit.userid\nWHERE lit.page = \'course\'\n  AND lit.courseid > 1\n  AND c.id IS NOT NULL\n  AND u.deleted = 0\n  AND u.suspended = 0\n  AND u.username != \'guest\'\n  AND c.visible = 1\nGROUP BY lit.courseid, lit.userid, u.id, c.id, cc.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"idnumber\":{\"key\":\"idnumber\",\"title\":\"lang::report_field_idnumber_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"category_name\":{\"key\":\"category_name\",\"title\":\"lang::report_field_category_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"firefox\":{\"key\":\"firefox\",\"title\":\"lang::report_field_firefox_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"chrome\":{\"key\":\"chrome\",\"title\":\"lang::report_field_chrome_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"safari\":{\"key\":\"safari\",\"title\":\"lang::report_field_safari_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"microsoft_edge\":{\"key\":\"microsoft_edge\",\"title\":\"lang::report_field_microsoft_edge_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"opera\":{\"key\":\"opera\",\"title\":\"lang::report_field_opera_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"mobile_browser\":{\"key\":\"mobile_browser\",\"title\":\"lang::report_field_mobile_browser_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"other_browser\":{\"key\":\"other_browser\",\"title\":\"lang::report_field_other_browser_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"windows\":{\"key\":\"windows\",\"title\":\"lang::report_field_windows_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"mac_os\":{\"key\":\"mac_os\",\"title\":\"lang::report_field_mac_os_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"linux\":{\"key\":\"linux\",\"title\":\"lang::report_field_linux_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"ios\":{\"key\":\"ios\",\"title\":\"lang::report_field_ios_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"android\":{\"key\":\"android\",\"title\":\"lang::report_field_android_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"mobile\":{\"key\":\"mobile\",\"title\":\"lang::report_field_mobile_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"other_platform\":{\"key\":\"other_platform\",\"title\":\"lang::report_field_other_platform_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(32,'kbi_el_overdue_users','lang::report_page_017_title::local_kopere_bi',27,1,'table','light','','','','SELECT kbi_ue.id,\n       kbi_ue.timecreated                      as enrolled,\n       kbi_cc.timecompleted                    as complete,\n       ROUND((CASE\n                WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                ELSE kbi_g.finalgrade END), 0) AS grade,\n       kbi_u.id                                as uid,\n       kbi_u.email,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_c.id                                as cid,\n       kbi_c.enablecompletion,\n       kbi_c.fullname                          as course,\n       \'\'                                  as cohortname\nFROM mdl_user_enrolments kbi_ue\n       JOIN mdl_enrol kbi_e ON kbi_e.id = kbi_ue.enrolid\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ue.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_e.courseid\n       LEFT JOIN mdl_course_completions kbi_cc ON kbi_cc.course = kbi_e.courseid AND kbi_cc.userid = kbi_u.id\n       LEFT JOIN mdl_grade_items kbi_gi ON kbi_gi.courseid = kbi_e.courseid AND kbi_gi.itemtype = \'course\'\n       LEFT JOIN mdl_grade_grades kbi_g ON kbi_g.itemid = kbi_gi.id AND kbi_g.userid = kbi_u.id\nWHERE kbi_ue.id > 0\n  AND kbi_c.id = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_ue.status = 0\n  AND kbi_e.status = 0\nORDER BY kbi_c.fullname, kbi_u.lastname, kbi_u.firstname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"enrolled\":{\"key\":\"enrolled\",\"title\":\"lang::report_field_enrolled_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"complete\":{\"key\":\"complete\",\"title\":\"lang::report_field_complete_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"uid\":{\"key\":\"uid\",\"title\":\"lang::report_field_uid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{uid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"cid\":{\"key\":\"cid\",\"title\":\"lang::report_field_cid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"enablecompletion\":{\"key\":\"enablecompletion\",\"title\":\"lang::report_field_enablecompletion_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{cid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"cohortname\":{\"key\":\"cohortname\",\"title\":\"lang::report_field_cohortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(33,'kbi_el_user_engagement','lang::report_page_018_title::local_kopere_bi',28,1,'table','light','','','','SELECT kbi_u.id,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_u.timecreated,\n       COUNT(DISTINCT kbi_ctx.instanceid) as courses,\n       MAX(lit.timesite)              AS timesite,\n       MAX(lit.timecourses)           AS timecourses,\n       MAX(lit.timeactivities)        AS timeactivities\nFROM mdl_role_assignments kbi_ra\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ra.userid\n       JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\n       LEFT JOIN (SELECT userid,\n                         SUM(timespend)                                              as timesite,\n                         SUM(CASE WHEN courseid > 0 THEN timespend ELSE null END)    as timecourses,\n                         SUM(CASE WHEN page = \'module\' THEN timespend ELSE null END) as timeactivities\n                  FROM mdl_local_kopere_bi_tracking\n                  GROUP BY userid) as lit ON lit.userid = kbi_u.id\nWHERE kbi_u.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_ra.roleid = 5\nGROUP BY kbi_u.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"timecreated\":{\"key\":\"timecreated\",\"title\":\"lang::report_field_timecreated_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"courses\":{\"key\":\"courses\",\"title\":\"lang::report_field_courses_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timesite\":{\"key\":\"timesite\",\"title\":\"lang::report_field_timesite_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"timecourses\":{\"key\":\"timecourses\",\"title\":\"lang::report_field_timecourses_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"timeactivities\":{\"key\":\"timeactivities\",\"title\":\"lang::report_field_timeactivities_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"}}}',1780646820),
(34,'kbi_el_user_profile_information_learne','lang::report_page_019_title::local_kopere_bi',29,1,'table','light','','','','SELECT kbi_u.id,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.middlename,\n       kbi_u.email,\n       kbi_u.idnumber,\n       kbi_u.username,\n       kbi_u.phone1,\n       kbi_u.phone2,\n       kbi_u.institution,\n       kbi_u.department,\n       kbi_u.address,\n       kbi_u.city,\n       kbi_u.country,\n       kbi_u.auth,\n       kbi_u.confirmed,\n       kbi_u.suspended,\n       kbi_u.deleted,\n       kbi_u.timecreated,\n       kbi_u.timemodified,\n       kbi_u.firstaccess,\n       kbi_u.lastaccess,\n       kbi_u.lastlogin,\n       kbi_u.currentlogin,\n       kbi_u.lastip\nFROM mdl_user kbi_u\nWHERE kbi_u.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\nORDER BY kbi_u.lastname, kbi_u.firstname, kbi_u.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"middlename\":{\"key\":\"middlename\",\"title\":\"lang::report_field_middlename_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"idnumber\":{\"key\":\"idnumber\",\"title\":\"lang::report_field_idnumber_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"username\":{\"key\":\"username\",\"title\":\"lang::report_field_username_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"phone1\":{\"key\":\"phone1\",\"title\":\"lang::report_field_phone1_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone1}}}\\\" target=\\\"_blank\\\">{{{phone1}}}<\\/a>\"},\"phone2\":{\"key\":\"phone2\",\"title\":\"lang::report_field_phone2_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone2}}}\\\" target=\\\"_blank\\\">{{{phone2}}}<\\/a>\"},\"institution\":{\"key\":\"institution\",\"title\":\"lang::report_field_institution_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"department\":{\"key\":\"department\",\"title\":\"lang::report_field_department_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"address\":{\"key\":\"address\",\"title\":\"lang::report_field_address_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"city\":{\"key\":\"city\",\"title\":\"lang::report_field_city_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"country\":{\"key\":\"country\",\"title\":\"lang::report_field_country_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"auth\":{\"key\":\"auth\",\"title\":\"lang::report_field_auth_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"confirmed\":{\"key\":\"confirmed\",\"title\":\"lang::report_field_confirmed_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"suspended\":{\"key\":\"suspended\",\"title\":\"lang::report_field_suspended_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"deleted\":{\"key\":\"deleted\",\"title\":\"lang::report_field_deleted_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timecreated\":{\"key\":\"timecreated\",\"title\":\"lang::report_field_timecreated_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"timemodified\":{\"key\":\"timemodified\",\"title\":\"lang::report_field_timemodified_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"firstaccess\":{\"key\":\"firstaccess\",\"title\":\"lang::report_field_firstaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"lastaccess\":{\"key\":\"lastaccess\",\"title\":\"lang::report_field_lastaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"lastlogin\":{\"key\":\"lastlogin\",\"title\":\"lang::report_field_lastlogin_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"currentlogin\":{\"key\":\"currentlogin\",\"title\":\"lang::report_field_currentlogin_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"lastip\":{\"key\":\"lastip\",\"title\":\"lang::report_field_lastip_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(35,'kbi_el_user_role_modification_learner_roles','lang::report_page_020_title::local_kopere_bi',30,1,'table','light','','','','SELECT MIN(kbi_ra.id),\n       kbi_c.id                                                                    AS courseid,\n       kbi_c.fullname                                                              AS course_name,\n       GROUP_CONCAT(DISTINCT kbi_r0.shortname)                                     AS role,\n       MIN(kbi_lsl.all_count)                                                      AS all_count,\n       CASE WHEN MIN(kbi_lsl.all_count) > 1 THEN MAX(kbi_r.shortname) ELSE \'-\' END     AS action_role,\n       CASE WHEN MIN(kbi_lsl.all_count) > 1 THEN MAX(kbi_log.action) ELSE \'-\' END      AS action,\n       CASE WHEN MIN(kbi_lsl.all_count) > 1 THEN MAX(kbi_log.timecreated) ELSE \'-\' END AS timecreated,\n       CASE\n         WHEN MIN(kbi_lsl.all_count) > 1 THEN MAX(CONCAT(kbi_u_action.firstname, \' \', kbi_u_action.lastname))\n         ELSE \'-\' END                                                          AS user_action,\n       MAX(kbi_u_action.id)                                                        AS user_action_id,\n       MAX(kbi_u_related.firstname)                                                AS firstname,\n       MAX(kbi_u_related.lastname)                                                 AS lastname,\n       MAX(kbi_u_related.email)                                                    AS email,\n       MAX(kbi_u_related.id)                                                       AS user_related_id\nFROM mdl_role_assignments kbi_ra\n       JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\n       LEFT JOIN mdl_role kbi_r0 ON kbi_r0.id = kbi_ra.roleid\n       LEFT JOIN mdl_course kbi_c ON kbi_c.id = kbi_ctx.instanceid\n       LEFT JOIN (SELECT kbi_lsl.courseid, kbi_lsl.relateduserid, MAX(kbi_lsl.id) AS last_change, COUNT(kbi_lsl.id) AS all_count\n                  FROM mdl_local_kopere_bi_log_tmp kbi_lsl\n                         JOIN mdl_role_assignments kbi_ra1 ON kbi_ra1.userid = kbi_lsl.relateduserid\n                         JOIN mdl_context kbi_ctx1 ON kbi_ctx1.id = kbi_ra1.contextid AND kbi_ctx1.instanceid = kbi_lsl.courseid\n                  WHERE (kbi_lsl.action = \'assigned\' OR kbi_lsl.action = \'unassigned\')\n                    AND kbi_lsl.target = \'role\'\n                    AND kbi_lsl.contextlevel = 50\n                    AND kbi_ctx1.contextlevel = 50\n                  GROUP BY kbi_lsl.courseid, kbi_lsl.relateduserid) lsl ON kbi_lsl.courseid = kbi_c.id AND kbi_lsl.relateduserid = kbi_ra.userid\n       LEFT JOIN mdl_local_kopere_bi_log_tmp kbi_log ON kbi_log.id = kbi_lsl.last_change\n       LEFT JOIN mdl_role kbi_r ON kbi_r.id = kbi_log.objectid\n       LEFT JOIN mdl_user kbi_u_action ON kbi_u_action.id = kbi_log.userid\n       LEFT JOIN mdl_user kbi_u_related ON kbi_u_related.id = kbi_log.relateduserid\nWHERE kbi_ra.id > 0\n  AND kbi_c.id = :courseid\nGROUP BY kbi_ra.userid, kbi_c.id','1h','none','{\"column\":{\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course_name\":{\"key\":\"course_name\",\"title\":\"lang::report_field_course_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"role\":{\"key\":\"role\",\"title\":\"lang::report_field_role_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"all_count\":{\"key\":\"all_count\",\"title\":\"lang::report_field_all_count_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"action_role\":{\"key\":\"action_role\",\"title\":\"lang::report_field_action_role_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"action\":{\"key\":\"action\",\"title\":\"lang::report_field_action_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timecreated\":{\"key\":\"timecreated\",\"title\":\"lang::report_field_timecreated_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"user_action\":{\"key\":\"user_action\",\"title\":\"lang::report_field_user_action_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"user_action_id\":{\"key\":\"user_action_id\",\"title\":\"lang::report_field_user_action_id_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"user_related_id\":{\"key\":\"user_related_id\",\"title\":\"lang::report_field_user_related_id_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646820),
(36,'kbi_el_user_site_summary_detail','lang::report_page_021_title::local_kopere_bi',31,1,'table','light','','','','SELECT kbi_u.id,\n       CONCAT(kbi_u.firstname, \' \', kbi_u.lastname) as user,\n       kbi_u.email,\n       kbi_u.timecreated,\n       sub.grade,\n       sub.courses,\n       sub.completed_courses,\n       kbi_lit.timespend                        AS timespend,\n       kbi_lit.visits                           AS visits\nFROM mdl_user kbi_u\n       LEFT JOIN (SELECT kbi_ue.userid,\n                         ROUND(AVG(CASE\n                                     WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                                     ELSE kbi_g.finalgrade END), 0) AS grade,\n                         COUNT(DISTINCT kbi_e.courseid)             as courses,\n                         COUNT(DISTINCT kbi_cc.course)              as completed_courses\n                  FROM mdl_user_enrolments kbi_ue\n                         LEFT JOIN mdl_enrol kbi_e ON kbi_e.id = kbi_ue.enrolid\n                         LEFT JOIN mdl_course_completions kbi_cc\n                           ON kbi_cc.timecompleted > 0 AND kbi_cc.course = kbi_e.courseid AND kbi_cc.userid = kbi_ue.userid\n                         LEFT JOIN mdl_grade_items kbi_gi ON kbi_gi.itemtype = \'course\' AND kbi_gi.courseid = kbi_e.courseid\n                         LEFT JOIN mdl_grade_grades kbi_g\n                           ON kbi_g.userid = kbi_ue.userid AND kbi_g.itemid = kbi_gi.id AND kbi_g.finalgrade IS NOT NULL\n                  WHERE kbi_ue.userid > 0\n                    AND kbi_ue.status = 0\n                    AND kbi_e.status = 0\n                  GROUP BY kbi_ue.userid) sub ON sub.userid = kbi_u.id\n       LEFT JOIN (SELECT kbi_lit.userid, SUM(kbi_lil.timespend) as timespend, SUM(kbi_lil.visits) as visits\n                  FROM mdl_local_kopere_bi_tracking kbi_lit\n                         JOIN mdl_local_kopere_bi_track_log kbi_lil ON kbi_lil.trackid = kbi_lit.id\n                  WHERE kbi_lil.id > 0\n                  GROUP BY kbi_lit.userid) lit ON kbi_lit.userid = kbi_u.id\nWHERE kbi_u.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"user\":{\"key\":\"user\",\"title\":\"lang::report_field_user_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"timecreated\":{\"key\":\"timecreated\",\"title\":\"lang::report_field_timecreated_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"courses\":{\"key\":\"courses\",\"title\":\"lang::report_field_courses_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"completed_courses\":{\"key\":\"completed_courses\",\"title\":\"lang::report_field_completed_courses_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646820),
(37,'kbi_el_user_site_use_summary','lang::report_page_022_title::local_kopere_bi',32,1,'table','light','','','','SELECT kbi_u.id,\n       kbi_u.lastaccess,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       grd.grade,\n       sls.roles,\n       kbi_u.timecreated,\n       grd.courses,\n       kbi_lit.timespend AS timespend,\n       kbi_lit.visits    AS visits\nFROM mdl_user kbi_u\n       LEFT JOIN (SELECT kbi_ra.userid,\n                         ROUND(AVG(CASE\n                                     WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                                     ELSE kbi_g.finalgrade END), 0) AS grade,\n                         COUNT(DISTINCT kbi_ctx.instanceid)         as courses\n                  FROM mdl_role_assignments kbi_ra\n                         JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND\n                                                    kbi_ctx.contextlevel = 50\n                         JOIN mdl_user kbi_u ON kbi_u.id = kbi_ra.userid\n                         LEFT JOIN mdl_grade_items kbi_gi ON kbi_gi.courseid = kbi_ctx.instanceid AND\n                                                         kbi_gi.itemtype = \'course\'\n                         LEFT JOIN mdl_grade_grades kbi_g ON kbi_g.itemid = kbi_gi.id AND\n                                                         kbi_g.userid = kbi_ra.userid AND\n                                                         kbi_g.finalgrade IS NOT NULL\n                         JOIN mdl_course kbi_c ON kbi_ctx.instanceid = kbi_c.id AND\n                                              kbi_c.visible = 1\n                  WHERE kbi_gi.itemtype = \'course\'\n                    AND kbi_ra.roleid = 5\n                  GROUP BY kbi_ra.userid) grd ON grd.userid = kbi_u.id\n       LEFT JOIN (SELECT kbi_ra.userid, GROUP_CONCAT(DISTINCT (kbi_r.shortname) SEPARATOR \',\') AS roles\n                  FROM mdl_context kbi_ctx\n                         JOIN mdl_role_assignments kbi_ra ON kbi_ra.contextid = kbi_ctx.id\n                         JOIN mdl_role kbi_r ON kbi_ra.roleid = kbi_r.id\n                  WHERE kbi_ctx.contextlevel = 10\n                  GROUP BY kbi_ra.userid) sls ON sls.userid = kbi_u.id\n       LEFT JOIN (SELECT kbi_lit.userid, SUM(kbi_lil.timespend) as timespend, SUM(kbi_lil.visits) as visits\n                  FROM mdl_local_kopere_bi_tracking kbi_lit\n                         JOIN mdl_local_kopere_bi_track_log kbi_lil ON kbi_lil.trackid = kbi_lit.id\n                  WHERE kbi_lil.id > 0\n                  GROUP BY kbi_lit.userid) lit ON kbi_lit.userid = kbi_u.id\nWHERE kbi_u.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"lastaccess\":{\"key\":\"lastaccess\",\"title\":\"lang::report_field_lastaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"roles\":{\"key\":\"roles\",\"title\":\"lang::report_field_roles_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timecreated\":{\"key\":\"timecreated\",\"title\":\"lang::report_field_timecreated_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"courses\":{\"key\":\"courses\",\"title\":\"lang::report_field_courses_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646820),
(38,'kbi_el_user_status','lang::report_page_023_title::local_kopere_bi',33,1,'table','light','','','','SELECT kbi_ue.id,\n       kbi_ue.timecreated                      AS enrolled,\n       kbi_ue.timeend,\n       kbi_ue.status                           AS enroll_status,\n       kbi_ul.timeaccess,\n       ROUND((CASE\n                WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                ELSE kbi_g.finalgrade END), 0) AS grade,\n       kbi_c.enablecompletion,\n       kbi_cc.timecompleted                    AS complete,\n       kbi_u.id                                AS uid,\n       kbi_u.email,\n       kbi_u.idnumber,\n       kbi_u.phone1,\n       kbi_u.phone2,\n       kbi_u.institution,\n       kbi_u.department,\n       kbi_u.address,\n       kbi_u.city,\n       kbi_u.country,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.username,\n       kbi_e.enrol                             AS enrols,\n       kbi_c.id                                AS cid,\n       kbi_c.fullname                          AS course,\n       kbi_c.shortname,\n       kbi_c.timemodified                      AS start_date,\n       \'\'                                  as cohortname,\n       l.timespend,\n       l.visits\nFROM mdl_user_enrolments kbi_ue\n       JOIN mdl_enrol kbi_e ON kbi_e.id = kbi_ue.enrolid\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ue.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_e.courseid\n       LEFT JOIN mdl_user_lastaccess kbi_ul ON kbi_ul.courseid = kbi_c.id AND kbi_ul.userid = kbi_u.id\n       LEFT JOIN mdl_course_completions kbi_cc ON kbi_cc.course = kbi_e.courseid AND kbi_cc.userid = kbi_ue.userid\n       LEFT JOIN mdl_grade_items kbi_gi ON kbi_gi.itemtype = \'course\' AND kbi_gi.courseid = kbi_e.courseid\n       LEFT JOIN mdl_grade_grades kbi_g ON kbi_g.userid = kbi_u.id AND kbi_g.itemid = kbi_gi.id AND kbi_g.finalgrade IS NOT NULL\n       LEFT JOIN (SELECT courseid,\n                         userid,\n                         SUM(timespend) AS timespend,\n                         SUM(visits)    AS visits\n                  FROM mdl_local_kopere_bi_tracking\n                  GROUP BY courseid, userid) l ON l.courseid = kbi_c.id AND l.userid = kbi_u.id\nWHERE kbi_ue.id > 0\n  AND kbi_c.id = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_ue.status = 0\n  AND kbi_e.status = 0\nORDER BY kbi_c.fullname, kbi_u.lastname, kbi_u.firstname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"enrolled\":{\"key\":\"enrolled\",\"title\":\"lang::report_field_enrolled_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"timeend\":{\"key\":\"timeend\",\"title\":\"lang::report_field_timeend_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"enroll_status\":{\"key\":\"enroll_status\",\"title\":\"lang::report_field_enroll_status_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"timeaccess\":{\"key\":\"timeaccess\",\"title\":\"lang::report_field_timeaccess_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"enablecompletion\":{\"key\":\"enablecompletion\",\"title\":\"lang::report_field_enablecompletion_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"complete\":{\"key\":\"complete\",\"title\":\"lang::report_field_complete_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"uid\":{\"key\":\"uid\",\"title\":\"lang::report_field_uid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"idnumber\":{\"key\":\"idnumber\",\"title\":\"lang::report_field_idnumber_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"phone1\":{\"key\":\"phone1\",\"title\":\"lang::report_field_phone1_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone1}}}\\\" target=\\\"_blank\\\">{{{phone1}}}<\\/a>\"},\"phone2\":{\"key\":\"phone2\",\"title\":\"lang::report_field_phone2_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone2}}}\\\" target=\\\"_blank\\\">{{{phone2}}}<\\/a>\"},\"institution\":{\"key\":\"institution\",\"title\":\"lang::report_field_institution_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"department\":{\"key\":\"department\",\"title\":\"lang::report_field_department_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"address\":{\"key\":\"address\",\"title\":\"lang::report_field_address_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"city\":{\"key\":\"city\",\"title\":\"lang::report_field_city_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"country\":{\"key\":\"country\",\"title\":\"lang::report_field_country_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{uid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"username\":{\"key\":\"username\",\"title\":\"lang::report_field_username_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"enrols\":{\"key\":\"enrols\",\"title\":\"lang::report_field_enrols_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"cid\":{\"key\":\"cid\",\"title\":\"lang::report_field_cid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{cid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"start_date\":{\"key\":\"start_date\",\"title\":\"lang::report_field_start_date_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"cohortname\":{\"key\":\"cohortname\",\"title\":\"lang::report_field_cohortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646820),
(39,'kbi_el_user_status_summary','lang::report_page_024_title::local_kopere_bi',34,1,'table','light','','','','SELECT kbi_u.id,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_u.lastaccess,\n       kbi_u.timecreated                          as registered,\n       ROUND(AVG(CASE\n                   WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                   ELSE kbi_g.finalgrade END), 0) as grade,\n       COUNT(DISTINCT kbi_ctx.instanceid)         as courses,\n       COUNT(DISTINCT kbi_cc.id)                  as completed_courses,\n       MAX(ca.completed_activities)           AS completed_activities,\n       MAX(lit.timespend)                     AS timespend,\n       MAX(lit.visits)                        AS visits,\n       \'\'                                     as cohortname\nFROM mdl_user kbi_u\n       LEFT JOIN mdl_role_assignments kbi_ra ON kbi_ra.userid = kbi_u.id\n       LEFT JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\n       LEFT JOIN (SELECT COUNT(id) AS completed_activities, userid\n                  FROM mdl_course_modules_completion\n                  WHERE id > 0\n                    AND completionstate IN (1, 2)\n                  GROUP BY userid) ca ON ca.userid = kbi_u.id\n       LEFT JOIN mdl_course_completions kbi_cc ON kbi_cc.course = kbi_ctx.instanceid AND\n                                              kbi_cc.userid = kbi_u.id AND kbi_cc.timecompleted > 0\n       LEFT JOIN mdl_grade_items kbi_gi ON kbi_gi.courseid = kbi_ctx.instanceid AND\n                                       kbi_gi.itemtype = \'course\'\n       LEFT JOIN mdl_grade_grades kbi_g ON kbi_g.itemid = kbi_gi.id AND kbi_g.userid = kbi_u.id AND\n                                       kbi_g.finalgrade IS NOT NULL\n       LEFT JOIN (SELECT kbi_t.userid, SUM(kbi_t.timespend) as timespend, SUM(kbi_t.visits) as visits\n                  FROM mdl_local_kopere_bi_tracking kbi_t\n                         JOIN mdl_course kbi_c ON kbi_t.courseid = kbi_c.id AND kbi_c.visible = 1\n                  WHERE kbi_t.courseid > 0\n                  GROUP BY kbi_t.userid) as lit ON lit.userid = kbi_u.id\nWHERE kbi_u.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\nGROUP BY kbi_u.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"lastaccess\":{\"key\":\"lastaccess\",\"title\":\"lang::report_field_lastaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"registered\":{\"key\":\"registered\",\"title\":\"lang::report_field_registered_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"courses\":{\"key\":\"courses\",\"title\":\"lang::report_field_courses_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"completed_courses\":{\"key\":\"completed_courses\",\"title\":\"lang::report_field_completed_courses_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completed_activities\":{\"key\":\"completed_activities\",\"title\":\"lang::report_field_completed_activities_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"cohortname\":{\"key\":\"cohortname\",\"title\":\"lang::report_field_cohortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(40,'kbi_el_assignments_graded_by_instructor','lang::report_page_025_title::local_kopere_bi',35,1,'table','light','','','','SELECT kbi_gi.itemname                            AS activity_name,\n       kbi_g.userid,\n       kbi_u.username,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_c.fullname,\n       kbi_cc1.name                               AS course_category,\n       kbi_c.shortname,\n       CONCAT(kbi_gu.firstname, \' \', kbi_gu.lastname) AS grader_name,\n       kbi_g.timemodified                         AS graduated,\n       ROUND((CASE\n                WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                ELSE kbi_g.finalgrade END), 0)    AS grade,\n       ROUND((CASE\n                WHEN (kbi_g.rawgrademax - kbi_g.rawgrademin) > 0\n                        THEN ((kbi_g.finalgrade - kbi_g.rawgrademin) / (kbi_g.rawgrademax - kbi_g.rawgrademin)) * 100\n                ELSE kbi_g.finalgrade END), 0)    AS grade_percent,\n       kbi_gi.itemtype,\n       kbi_sg.timemodified                        AS need_grade_assignment,\n       kbi_ass.timemodified                       AS submission_date,\n       kbi_ul.timeaccess                          AS course_lastaccess\nFROM mdl_course kbi_c\n       JOIN mdl_course_categories kbi_cc1 ON kbi_cc1.id = kbi_c.category\n       JOIN mdl_modules kbi_m ON kbi_m.name = \'assign\'\n       JOIN mdl_course_modules kbi_cm ON kbi_cm.course = kbi_c.id AND kbi_cm.module = kbi_m.id\n       JOIN (SELECT kbi_ctx.instanceid, kbi_ra.userid\n             FROM mdl_context kbi_ctx\n                    JOIN mdl_role_assignments kbi_ra ON kbi_ra.contextid = kbi_ctx.id AND kbi_ra.roleid = 5\n             WHERE kbi_ctx.contextlevel = 50\n             GROUP BY kbi_ctx.instanceid, kbi_ra.userid) ra ON kbi_ra.instanceid = kbi_c.id\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ra.userid\n       JOIN mdl_grade_items kbi_gi ON kbi_gi.iteminstance = kbi_cm.instance AND kbi_gi.itemmodule = \'assign\'\n       LEFT JOIN mdl_grade_grades kbi_g ON kbi_gi.id = kbi_g.itemid AND kbi_g.userid = kbi_u.id\n       LEFT JOIN mdl_assign_submission kbi_ass\n         ON kbi_ass.userid = kbi_u.id AND kbi_ass.assignment = kbi_cm.instance AND kbi_ass.status = \'submitted\' AND kbi_ass.latest = 1\n       LEFT JOIN mdl_assign_grades kbi_sg\n         ON kbi_ass.assignment = kbi_sg.assignment AND kbi_ass.userid = kbi_sg.userid AND kbi_sg.attemptnumber = kbi_ass.attemptnumber AND\n            kbi_sg.grade > -1\n       LEFT JOIN mdl_user kbi_gu ON kbi_gu.id = kbi_sg.grader\n       LEFT JOIN mdl_user_lastaccess kbi_ul ON kbi_ul.courseid = kbi_c.id AND kbi_ul.userid = kbi_u.id\nWHERE kbi_c.id > 0\n  AND kbi_c.id = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1','1h','none','{\"column\":{\"activity_name\":{\"key\":\"activity_name\",\"title\":\"lang::report_field_activity_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"username\":{\"key\":\"username\",\"title\":\"lang::report_field_username_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"course_category\":{\"key\":\"course_category\",\"title\":\"lang::report_field_course_category_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"grader_name\":{\"key\":\"grader_name\",\"title\":\"lang::report_field_grader_name_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"graduated\":{\"key\":\"graduated\",\"title\":\"lang::report_field_graduated_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade_percent\":{\"key\":\"grade_percent\",\"title\":\"lang::report_field_grade_percent_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"itemtype\":{\"key\":\"itemtype\",\"title\":\"lang::report_field_itemtype_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"need_grade_assignment\":{\"key\":\"need_grade_assignment\",\"title\":\"lang::report_field_need_grade_assignment_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"submission_date\":{\"key\":\"submission_date\",\"title\":\"lang::report_field_submission_date_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"course_lastaccess\":{\"key\":\"course_lastaccess\",\"title\":\"lang::report_field_course_lastaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(41,'kbi_el_forum_stats_summary_by_instructor','lang::report_page_026_title::local_kopere_bi',36,1,'table','light','','','','SELECT kbi_c.id,\n       kbi_c.fullname,\n       MAX(v.visits)      AS visits,\n       MAX(v.timespend)   AS timespend,\n       MAX(d.discussions) AS discussions,\n       MAX(p.posts)       AS posts,\n       COUNT(*)           AS total,\n       tchr.teacher\nFROM mdl_course kbi_c\n       LEFT JOIN mdl_forum kbi_f ON kbi_f.course = kbi_c.id\n       LEFT JOIN (SELECT kbi_lit.courseid, SUM(kbi_lit.timespend) as timespend, SUM(kbi_lit.visits) as visits\n                  FROM mdl_local_kopere_bi_tracking kbi_lit, mdl_course_modules kbi_cm, mdl_modules kbi_m\n                  WHERE kbi_lit.page = \'module\'\n                    and kbi_cm.id = kbi_lit.param\n                    and kbi_m.id = kbi_cm.module\n                    and kbi_m.name = \'forum\'\n                  GROUP BY kbi_lit.courseid) v ON v.courseid = kbi_c.id\n       LEFT JOIN (SELECT course, count(*) discussions FROM mdl_forum_discussions group by course) d ON d.course = kbi_c.id\n       LEFT JOIN (SELECT kbi_fd.course, count(*) posts\n                  FROM mdl_forum_discussions kbi_fd, mdl_forum_posts kbi_fp\n                  WHERE kbi_fp.discussion = kbi_fd.id\n                  group by kbi_fd.course) p ON p.course = kbi_c.id\n       LEFT JOIN (SELECT GROUP_CONCAT(DISTINCT CONCAT(kbi_u.firstname, \' \', kbi_u.lastname) SEPARATOR \', \') AS teacher,\n                         kbi_ctx.instanceid\n                  FROM mdl_role_assignments kbi_ra\n                         JOIN mdl_user kbi_u ON kbi_ra.userid = kbi_u.id\n                         JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n                  WHERE kbi_ctx.contextlevel = 50\n                    AND kbi_ra.roleid = 3\n                  GROUP BY kbi_ctx.instanceid) tchr ON tchr.instanceid = kbi_c.id\nWHERE kbi_c.id > 0\n  AND kbi_c.visible = 1\n  AND kbi_c.id = :courseid\nGROUP BY kbi_c.id, tchr.teacher','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"discussions\":{\"key\":\"discussions\",\"title\":\"lang::report_field_discussions_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"posts\":{\"key\":\"posts\",\"title\":\"lang::report_field_posts_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"total\":{\"key\":\"total\",\"title\":\"lang::report_field_total_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"teacher\":{\"key\":\"teacher\",\"title\":\"lang::report_field_teacher_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(42,'kbi_el_instructor_activity_engagement_detail','lang::report_page_027_title::local_kopere_bi',37,1,'table','light','','','','SELECT kbi_lit.id                                                        AS lid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_c.fullname,\n       kbi_c.shortname,\n       CASE WHEN kbi_lit.visits IS NULL THEN 0 ELSE kbi_lit.visits END       AS visits,\n       CASE WHEN kbi_lit.timespend IS NULL THEN 0 ELSE kbi_lit.timespend END AS timespend,\n       kbi_lit.firstaccess,\n       kbi_lit.lastaccess,\n       kbi_cm.instance,\n       kbi_m.name                                                        AS module\nFROM mdl_role_assignments kbi_ra\n       JOIN mdl_user kbi_u ON kbi_ra.userid = kbi_u.id\n       JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_ctx.instanceid\n       LEFT JOIN mdl_course_modules kbi_cm ON kbi_cm.course = kbi_c.id\n       LEFT JOIN mdl_modules kbi_m ON kbi_m.id = kbi_cm.module\n       LEFT JOIN mdl_local_kopere_bi_tracking kbi_lit ON kbi_lit.userid = kbi_u.id AND kbi_lit.param = kbi_cm.id AND kbi_lit.page = \'module\'\nWHERE kbi_ctx.contextlevel = 50\n  AND kbi_c.id = :courseid\n  AND kbi_ra.roleid = 3\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_cm.visible = 1','1h','none','{\"column\":{\"lid\":{\"key\":\"lid\",\"title\":\"lang::report_field_lid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"firstaccess\":{\"key\":\"firstaccess\",\"title\":\"lang::report_field_firstaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"lastaccess\":{\"key\":\"lastaccess\",\"title\":\"lang::report_field_lastaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"instance\":{\"key\":\"instance\",\"title\":\"lang::report_field_instance_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"module\":{\"key\":\"module\",\"title\":\"lang::report_field_module_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(43,'kbi_el_instructor_assignment_engagement','lang::report_page_028_title::local_kopere_bi',38,1,'table','light','','','','SELECT kbi_ra.id AS id,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_c.fullname,\n       kbi_c.shortname,\n       stat.assignments,\n       stat.completed,\n       stat.submissions,\n       stat.grades,\n       kbi_l.timespend,\n       visits\nFROM mdl_role_assignments kbi_ra\n       JOIN mdl_user kbi_u ON kbi_ra.userid = kbi_u.id\n       JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_ctx.instanceid\n       LEFT JOIN (SELECT kbi_a.course                           AS courseid,\n                         COUNT(distinct kbi_a.id)               AS assignments,\n                         COUNT(distinct kbi_cmc.coursemoduleid) AS completed,\n                         COUNT(distinct kbi_s.assignment)       AS submissions,\n                         COUNT(distinct kbi_g.assignment)       AS grades\n                  FROM mdl_assign kbi_a\n                         LEFT JOIN mdl_modules kbi_m ON kbi_m.name = \'assign\'\n                         LEFT JOIN mdl_course_modules kbi_cm ON kbi_cm.instance = kbi_a.id AND kbi_cm.module = kbi_m.id\n                         LEFT JOIN mdl_course_modules_completion kbi_cmc ON kbi_cmc.coursemoduleid = kbi_cm.id AND\n                                                                        kbi_cmc.completionstate IN\n                                                                        (1,\n                                                                         2)\n                         LEFT JOIN mdl_assign_submission kbi_s ON kbi_s.status = \'submitted\' AND kbi_s.assignment = kbi_a.id\n                         LEFT JOIN mdl_assign_grades kbi_g ON kbi_g.assignment = kbi_a.id\n                  WHERE kbi_a.course > 0\n                    AND kbi_a.course = :courseid\n                  GROUP BY kbi_a.course) stat ON stat.courseid = kbi_c.id\n       LEFT JOIN (SELECT kbi_l.userid, kbi_l.courseid, SUM(kbi_l.timespend) as timespend, SUM(kbi_l.visits) as visits\n                  FROM mdl_local_kopere_bi_tracking kbi_l, mdl_modules kbi_m, mdl_course_modules kbi_cm\n                  WHERE kbi_l.page = \'module\'\n                    and kbi_m.name = \'assign\'\n                    AND kbi_cm.id = kbi_l.param\n                    AND kbi_cm.module = kbi_m.id\n                    AND kbi_l.courseid = :courseid\n                  GROUP BY kbi_l.userid, kbi_l.courseid) l ON kbi_l.userid = kbi_u.id AND kbi_l.courseid = kbi_c.id\nWHERE kbi_ctx.contextlevel = 50\n  AND kbi_c.id = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_ra.roleid = 3','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"assignments\":{\"key\":\"assignments\",\"title\":\"lang::report_field_assignments_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"completed\":{\"key\":\"completed\",\"title\":\"lang::report_field_completed_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"submissions\":{\"key\":\"submissions\",\"title\":\"lang::report_field_submissions_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"grades\":{\"key\":\"grades\",\"title\":\"lang::report_field_grades_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646820),
(44,'kbi_el_instructor_engagement_ratio','lang::report_page_029_title::local_kopere_bi',39,1,'table','light','','','','SELECT kbi_ra.id,\n       kbi_c.id                                                               AS courseid,\n       kbi_c.fullname                                                         AS course_name,\n       kbi_c.timecreated                                                      AS course_created,\n       kbi_u.id                                                               AS teacher_id,\n       kbi_u.lastname,\n       kbi_u.firstname,\n       kbi_u.email,\n       kbi_u.picture                                                          AS teacher_picture,\n       kbi_u.firstnamephonetic                                                AS teacher_firstnamephonetic,\n       kbi_u.lastnamephonetic                                                 AS teacher_lastnamephonetic,\n       kbi_u.middlename                                                       AS teacher_middlename,\n       kbi_u.alternatename                                                    AS teacher_alternatename,\n       kbi_u.imagealt                                                         AS teacher_imagealt,\n       (SELECT COUNT(distinct kbi_ras.userid)\n        FROM mdl_role_assignments kbi_ras, mdl_context kbi_con\n        WHERE kbi_con.id = kbi_ras.contextid\n          AND kbi_con.contextlevel = 50\n          AND kbi_ras.roleid = 5\n          AND kbi_con.instanceid = kbi_c.id)                                      AS enrolled_students,\n       (SELECT COUNT(kbi_ass.id) FROM mdl_assign kbi_ass WHERE kbi_ass.course = kbi_c.id) AS assignments,\n       (SELECT COUNT(DISTINCT kbi_sub.id)\n        FROM mdl_assign_submission kbi_sub\n               LEFT JOIN mdl_assign_grades kbi_as_grade\n                 ON kbi_as_grade.userid = kbi_sub.userid AND kbi_as_grade.assignment = kbi_sub.assignment AND\n                    kbi_as_grade.attemptnumber = kbi_sub.attemptnumber\n               JOIN mdl_assign kbi_ass ON kbi_ass.id = kbi_sub.assignment\n        WHERE kbi_sub.status = \'submitted\'\n          AND kbi_sub.latest = 1\n          AND kbi_sub.timecreated > (UNIX_TIMESTAMP() - 2592000)\n          AND (kbi_as_grade.grade IS NULL OR kbi_as_grade.grade < 0)\n          AND kbi_ass.course = kbi_c.id)                                          AS needs_grading,\n       (SELECT AVG(kbi_as_grade.timecreated - kbi_sub.timecreated)\n        FROM mdl_assign_submission kbi_sub\n               LEFT JOIN mdl_assign_grades kbi_as_grade\n                 ON kbi_as_grade.userid = kbi_sub.userid AND kbi_as_grade.assignment = kbi_sub.assignment AND\n                    kbi_as_grade.attemptnumber = kbi_sub.attemptnumber\n               JOIN mdl_assign kbi_ass ON kbi_ass.id = kbi_sub.assignment\n        WHERE kbi_sub.status = \'submitted\'\n          AND kbi_sub.latest = 1\n          AND kbi_as_grade.grade IS NOT NULL\n          AND kbi_as_grade.grade >= 0\n          AND kbi_ass.course = kbi_c.id)                                          AS avg_time_to_grade,\n       (SELECT SUM(kbi_lil.visits) / COUNT(DISTINCT timepoint)\n        FROM mdl_local_kopere_bi_tracking kbi_lit, mdl_local_kopere_bi_track_log kbi_lil\n        WHERE kbi_lil.trackid = kbi_lit.id\n          AND kbi_lit.courseid = kbi_c.id)                                        AS logins_by_teacher,\n       (SELECT COUNT(DISTINCT kbi_fd.id)\n        FROM mdl_forum_discussions kbi_fd, mdl_forum_posts kbi_fp\n        WHERE kbi_fp.discussion = kbi_fd.id\n          AND kbi_fd.course = kbi_c.id)                                           AS teacher_discussions,\n       (SELECT COUNT(DISTINCT kbi_fp.id)\n        FROM mdl_forum_discussions kbi_fd, mdl_forum_posts kbi_fp\n        WHERE kbi_fp.discussion = kbi_fd.id\n          AND kbi_fd.course = kbi_c.id)                                           AS teacher_posts,\n       (SELECT COUNT(DISTINCT kbi_fp.id)\n        FROM mdl_role_assignments kbi_ras, mdl_context kbi_con, mdl_forum_discussions kbi_fd, mdl_forum_posts kbi_fp\n        WHERE kbi_con.id = kbi_ras.contextid\n          AND kbi_ras.roleid = 5\n          AND kbi_con.contextlevel = 50\n          AND kbi_fp.discussion = kbi_fd.id\n          AND kbi_fd.course = kbi_con.instanceid\n          AND kbi_con.instanceid = kbi_c.id)                                      AS students_posts,\n       (SELECT COUNT(distinct id) FROM mdl_event WHERE userid = kbi_u.id)     AS teacher_events,\n       (SELECT COUNT(distinct kbi_e.id)\n        FROM mdl_event kbi_e, mdl_role_assignments kbi_ras, mdl_context kbi_con\n        WHERE kbi_ras.userid = kbi_e.userid\n          AND kbi_ras.roleid = 5\n          AND kbi_con.id = kbi_ras.contextid\n          AND kbi_con.contextlevel = 50\n          AND kbi_e.courseid = kbi_con.instanceid\n          AND kbi_con.instanceid = kbi_c.id)                                      AS students_events,\n       (SELECT COUNT(id) FROM mdl_course_modules WHERE course = kbi_c.id)     AS added_course_module\nFROM mdl_role_assignments kbi_ra\n       JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_ctx.instanceid\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ra.userid\nWHERE kbi_ra.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_ra.roleid = 3','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course_name\":{\"key\":\"course_name\",\"title\":\"lang::report_field_course_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"course_created\":{\"key\":\"course_created\",\"title\":\"lang::report_field_course_created_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teacher_id\":{\"key\":\"teacher_id\",\"title\":\"lang::report_field_teacher_id_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"teacher_picture\":{\"key\":\"teacher_picture\",\"title\":\"lang::report_field_teacher_picture_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teacher_firstnamephonetic\":{\"key\":\"teacher_firstnamephonetic\",\"title\":\"lang::report_field_teacher_firstnamephonetic_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teacher_lastnamephonetic\":{\"key\":\"teacher_lastnamephonetic\",\"title\":\"lang::report_field_teacher_lastnamephonetic_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teacher_middlename\":{\"key\":\"teacher_middlename\",\"title\":\"lang::report_field_teacher_middlename_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teacher_alternatename\":{\"key\":\"teacher_alternatename\",\"title\":\"lang::report_field_teacher_alternatename_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teacher_imagealt\":{\"key\":\"teacher_imagealt\",\"title\":\"lang::report_field_teacher_imagealt_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"enrolled_students\":{\"key\":\"enrolled_students\",\"title\":\"lang::report_field_enrolled_students_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"assignments\":{\"key\":\"assignments\",\"title\":\"lang::report_field_assignments_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"needs_grading\":{\"key\":\"needs_grading\",\"title\":\"lang::report_field_needs_grading_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"avg_time_to_grade\":{\"key\":\"avg_time_to_grade\",\"title\":\"lang::report_field_avg_time_to_grade_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"logins_by_teacher\":{\"key\":\"logins_by_teacher\",\"title\":\"lang::report_field_logins_by_teacher_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teacher_discussions\":{\"key\":\"teacher_discussions\",\"title\":\"lang::report_field_teacher_discussions_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teacher_posts\":{\"key\":\"teacher_posts\",\"title\":\"lang::report_field_teacher_posts_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"students_posts\":{\"key\":\"students_posts\",\"title\":\"lang::report_field_students_posts_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"teacher_events\":{\"key\":\"teacher_events\",\"title\":\"lang::report_field_teacher_events_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"students_events\":{\"key\":\"students_events\",\"title\":\"lang::report_field_students_events_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"added_course_module\":{\"key\":\"added_course_module\",\"title\":\"lang::report_field_added_course_module_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(45,'kbi_el_instructor_engagement_stats_by_course','lang::report_page_030_title::local_kopere_bi',40,1,'table','light','','','','SELECT kbi_ra.id,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_c.fullname,\n       kbi_c.shortname,\n       e.enrolled                                                AS enrolled,\n       cc.completed                                              AS completed,\n       CASE WHEN l.timespend IS NULL THEN 0 ELSE l.timespend END AS timespend,\n       CASE WHEN l.visits IS NULL THEN 0 ELSE l.visits END       AS visits,\n       CASE\n         WHEN l.last_access IS NULL THEN kbi_mla.timeaccess\n         ELSE l.last_access END                                  AS last_access\nFROM mdl_user kbi_u\n       JOIN mdl_role_assignments kbi_ra ON kbi_ra.userid = kbi_u.id AND kbi_ra.roleid = 3\n       JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_ctx.instanceid AND kbi_c.id = :courseid\n       LEFT JOIN (SELECT userid,\n                         courseid,\n                         SUM(kbi_t1.timespend)  AS timespend,\n                         SUM(kbi_t1.visits)     AS visits,\n                         MAX(kbi_t1.lastaccess) AS last_access\n                  FROM mdl_local_kopere_bi_tracking kbi_t1\n                  WHERE kbi_t1.id > 0\n                    AND kbi_t1.courseid = :courseid\n                  GROUP BY kbi_t1.courseid, kbi_t1.userid) l ON l.userid = kbi_u.id AND l.courseid = kbi_c.id\n       JOIN mdl_user_lastaccess kbi_mla ON kbi_mla.userid = kbi_u.id AND kbi_mla.courseid = kbi_c.id\n       LEFT JOIN (SELECT kbi_ctx1.instanceid, COUNT(DISTINCT kbi_ra1.userid) AS enrolled\n                  FROM mdl_role_assignments kbi_ra1\n                         JOIN mdl_context kbi_ctx1 ON kbi_ctx1.id = kbi_ra1.contextid AND kbi_ctx1.contextlevel = 50\n                  WHERE kbi_ra1.roleid = 5\n                    AND kbi_ctx1.instanceid = :courseid\n                  GROUP BY kbi_ctx1.instanceid) e ON e.instanceid = kbi_c.id\n       LEFT JOIN (SELECT course, COUNT(id) AS completed\n                  FROM mdl_course_completions kbi_cc1\n                  WHERE timecompleted > 0\n                    AND kbi_cc1.course = :courseid\n                  GROUP BY course) cc ON cc.course = kbi_c.id\nWHERE kbi_ra.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\nGROUP BY kbi_ra.id, kbi_u.id, kbi_c.id, e.enrolled, cc.completed, kbi_u.firstname, kbi_u.lastname, kbi_u.email, kbi_c.fullname, kbi_c.shortname,\n         l.timespend, l.visits, l.last_access, kbi_mla.timeaccess','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"enrolled\":{\"key\":\"enrolled\",\"title\":\"lang::report_field_enrolled_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"completed\":{\"key\":\"completed\",\"title\":\"lang::report_field_completed_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"last_access\":{\"key\":\"last_access\",\"title\":\"lang::report_field_last_access_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(46,'kbi_el_instructor_forum_engagement','lang::report_page_031_title::local_kopere_bi',41,1,'table','light','','','','SELECT MAX(kbi_ra.id)                             AS id,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_c.fullname,\n       kbi_c.shortname,\n       COUNT(distinct kbi_f.id)                   as forums,\n       MAX(coalesce(kbi_d.discussions, 0))        AS discussions,\n       MAX(coalesce(kbi_p.posts, 0))              AS posts,\n       MAX(coalesce(d1.users_discussions, 0)) AS users_discussions,\n       MAX(coalesce(p1.users_posts, 0))       AS users_posts,\n       MAX(kbi_l.timespend)                       AS timespend,\n       MAX(kbi_l.visits)                          AS visits\nFROM mdl_role_assignments kbi_ra\n       JOIN mdl_user kbi_u ON kbi_ra.userid = kbi_u.id\n       JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_ctx.instanceid\n       LEFT JOIN mdl_forum kbi_f ON kbi_f.course = kbi_c.id\n       LEFT JOIN mdl_modules kbi_m ON kbi_m.name = \'forum\'\n       LEFT JOIN mdl_course_modules kbi_cm ON kbi_cm.instance = kbi_f.id AND kbi_cm.module = kbi_m.id\n       LEFT JOIN (SELECT course, COUNT(id) AS discussions FROM mdl_forum_discussions kbi_d GROUP BY course) d\n         ON kbi_d.course = kbi_c.id\n       LEFT JOIN (SELECT kbi_d.course, COUNT(kbi_p.id) AS posts\n                  FROM mdl_forum_discussions kbi_d\n                         JOIN mdl_forum_posts kbi_p ON kbi_p.discussion = kbi_d.id AND kbi_p.parent > 0\n                  GROUP BY kbi_d.course) p ON kbi_p.course = kbi_c.id\n       LEFT JOIN (SELECT COUNT(id) AS users_discussions, course, userid\n                  FROM mdl_forum_discussions kbi_d\n                  GROUP BY course, userid) d1 ON d1.course = kbi_c.id AND d1.userid = kbi_u.id\n       LEFT JOIN (SELECT COUNT(kbi_p.id) AS users_posts, kbi_d.course, kbi_p.userid\n                  FROM mdl_forum_discussions kbi_d\n                         JOIN mdl_forum_posts kbi_p ON kbi_p.discussion = kbi_d.id AND kbi_p.parent > 0\n                  GROUP BY kbi_d.course, kbi_p.userid) p1 ON p1.course = kbi_c.id AND p1.userid = kbi_u.id\n       LEFT JOIN (SELECT kbi_l.userid, kbi_l.courseid, SUM(kbi_l.timespend) as timespend, SUM(kbi_l.visits) as visits\n                  FROM mdl_local_kopere_bi_tracking kbi_l, mdl_modules kbi_m, mdl_course_modules kbi_cm\n                  WHERE kbi_l.page = \'module\'\n                    and kbi_m.name = \'forum\'\n                    AND kbi_cm.id = kbi_l.param\n                    AND kbi_cm.module = kbi_m.id\n                  GROUP BY kbi_l.userid, kbi_l.courseid) l ON kbi_l.userid = kbi_u.id AND kbi_l.courseid = kbi_c.id\nWHERE kbi_ctx.contextlevel = 50\n  AND kbi_c.id = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_ra.roleid = 3\nGROUP BY kbi_u.id, kbi_c.id, kbi_u.firstname, kbi_u.lastname, kbi_u.email, kbi_c.fullname, kbi_c.shortname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"forums\":{\"key\":\"forums\",\"title\":\"lang::report_field_forums_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"discussions\":{\"key\":\"discussions\",\"title\":\"lang::report_field_discussions_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"posts\":{\"key\":\"posts\",\"title\":\"lang::report_field_posts_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"users_discussions\":{\"key\":\"users_discussions\",\"title\":\"lang::report_field_users_discussions_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"users_posts\":{\"key\":\"users_posts\",\"title\":\"lang::report_field_users_posts_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646820),
(47,'kbi_el_instructor_load_summary','lang::report_page_032_title::local_kopere_bi',42,1,'table','light','','','','SELECT kbi_u.id,\n       CONCAT(kbi_u.firstname, \' \', kbi_u.lastname) as teacher,\n       COUNT(DISTINCT kbi_ctx.instanceid)       as courses,\n       SUM(l.learners)                      as learners,\n       SUM(l1.activelearners)               as activelearners,\n       SUM(cc.completed)                    as completedlearners,\n       AVG(kbi_g.grade)                         as grade\nFROM mdl_user kbi_u\n       LEFT JOIN mdl_role_assignments kbi_ra ON kbi_ra.userid = kbi_u.id\n       LEFT JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n       JOIN mdl_course kbi_c ON kbi_ctx.instanceid = kbi_c.id AND\n                            kbi_c.visible = 1\n       LEFT JOIN (SELECT kbi_ctx.instanceid, count(distinct kbi_ra.userid) as learners\n                  FROM mdl_role_assignments kbi_ra, mdl_context kbi_ctx\n                  WHERE kbi_ctx.id = kbi_ra.contextid\n                    AND kbi_ctx.contextlevel = 50\n                    AND kbi_ra.roleid = 5\n                  GROUP BY kbi_ctx.instanceid) AS l ON l.instanceid = kbi_ctx.instanceid\n       LEFT JOIN (SELECT kbi_ctx.instanceid, count(distinct kbi_ra.userid) as activelearners\n                  FROM mdl_role_assignments kbi_ra, mdl_user kbi_u, mdl_context kbi_ctx\n                  WHERE kbi_ctx.id = kbi_ra.contextid\n                    AND kbi_ctx.contextlevel = 50\n                    AND kbi_u.id = kbi_ra.userid\n                    AND kbi_u.deleted = 0\n                    AND kbi_u.suspended = 0\n                    AND kbi_ra.roleid = 5\n                  GROUP BY kbi_ctx.instanceid) AS l1 ON l1.instanceid = kbi_ctx.instanceid\n       LEFT JOIN (SELECT course, count(id) as completed\n                  FROM mdl_course_completions\n                  WHERE timecompleted > 0\n                  GROUP BY course) cc ON cc.course = kbi_ctx.instanceid\n       LEFT JOIN (SELECT kbi_gi.courseid,\n                         ROUND(AVG(CASE\n                                     WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                                     ELSE kbi_g.finalgrade END), 0) AS grade\n                  FROM mdl_grade_items kbi_gi, mdl_grade_grades kbi_g\n                  WHERE kbi_gi.itemtype = \'course\'\n                    AND kbi_g.itemid = kbi_gi.id\n                    AND kbi_g.finalgrade IS NOT NULL\n                  GROUP BY kbi_gi.courseid) g ON kbi_g.courseid = kbi_ctx.instanceid\nWHERE kbi_ctx.contextlevel = 50\n  AND kbi_ra.roleid = 3\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\nGROUP BY kbi_u.id, kbi_u.firstname, kbi_u.lastname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"teacher\":{\"key\":\"teacher\",\"title\":\"lang::report_field_teacher_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"courses\":{\"key\":\"courses\",\"title\":\"lang::report_field_courses_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"learners\":{\"key\":\"learners\",\"title\":\"lang::report_field_learners_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"activelearners\":{\"key\":\"activelearners\",\"title\":\"lang::report_field_activelearners_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completedlearners\":{\"key\":\"completedlearners\",\"title\":\"lang::report_field_completedlearners_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646820),
(48,'kbi_el_instructor_site_use_summary','lang::report_page_033_title::local_kopere_bi',43,1,'table','light','','','','SELECT kbi_u.id,\n       CONCAT(kbi_u.firstname, \' \', kbi_u.lastname)                               AS name,\n       COUNT(DISTINCT kbi_ctx.instanceid)                                     as courses,\n       SUM(v.learners)                                                    as learners,\n       MAX(CASE WHEN kbi_lit.timespend IS NULL THEN 0 ELSE kbi_lit.timespend END) AS timespend,\n       MAX(CASE WHEN kbi_lit.visits IS NULL THEN 0 ELSE kbi_lit.visits END)       AS visits\nFROM mdl_role_assignments kbi_ra\n       JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\n       JOIN mdl_course kbi_c ON kbi_ctx.instanceid = kbi_c.id AND kbi_c.visible = 1\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ra.userid\n       LEFT JOIN (SELECT kbi_ctx.instanceid, COUNT(DISTINCT kbi_ra.userid) as learners\n                  FROM mdl_role_assignments kbi_ra\n                         JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n                         JOIN mdl_course kbi_c ON kbi_ctx.instanceid = kbi_c.id AND kbi_c.visible = 1\n                  WHERE kbi_ra.userid > 0\n                    AND kbi_ra.roleid = 5\n                  GROUP BY kbi_ctx.instanceid) v ON v.instanceid = kbi_ctx.instanceid\n       LEFT JOIN (SELECT kbi_lit.userid,\n                         SUM(CASE WHEN kbi_lil.timespend IS NULL THEN 0 ELSE kbi_lil.timespend END) AS timespend,\n                         SUM(CASE WHEN kbi_lil.visits IS NULL THEN 0 ELSE kbi_lil.visits END)       AS visits\n                  FROM mdl_role_assignments kbi_ra\n                         JOIN mdl_context kbi_ctx ON kbi_ctx.contextlevel = 50 AND kbi_ctx.id = kbi_ra.contextid\n                         JOIN mdl_course kbi_c ON kbi_c.id = kbi_ctx.instanceid AND kbi_c.visible = 1\n                         LEFT JOIN mdl_local_kopere_bi_tracking kbi_lit\n                           ON kbi_lit.userid = kbi_ra.userid AND kbi_lit.courseid = kbi_ctx.instanceid\n                         LEFT JOIN mdl_local_kopere_bi_track_log kbi_lil ON kbi_lil.trackid = kbi_lit.id\n                  WHERE kbi_lil.id > 0\n                    AND kbi_ra.roleid = 3\n                  GROUP BY kbi_lit.userid) lit ON kbi_lit.userid = kbi_ra.userid\nWHERE kbi_u.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_ra.roleid = 3\nGROUP BY kbi_u.id, kbi_u.firstname, kbi_u.lastname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"name\":{\"key\":\"name\",\"title\":\"lang::report_field_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"courses\":{\"key\":\"courses\",\"title\":\"lang::report_field_courses_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"learners\":{\"key\":\"learners\",\"title\":\"lang::report_field_learners_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646820),
(49,'kbi_el_instructor_and_learner_engagem','lang::report_page_034_title::local_kopere_bi',44,1,'table','light','','','','SELECT kbi_ra.id,\n       kbi_c.id                                                                           AS courseid,\n       kbi_c.fullname                                                                     AS course_name,\n       kbi_c.timecreated                                                                  AS course_created,\n       kbi_c.startdate,\n       kbi_u.id                                                                           AS teacher_id,\n       kbi_u.lastname,\n       kbi_u.firstname,\n       (SELECT COUNT(distinct kbi_ras.userid)\n        FROM mdl_role_assignments kbi_ras, mdl_context kbi_con\n        WHERE kbi_con.id = kbi_ras.contextid\n          AND kbi_con.contextlevel = 50\n          AND kbi_ras.roleid = 5\n          AND kbi_con.instanceid = kbi_c.id)                                                  AS learners,\n       (SELECT COUNT(distinct kbi_e.id)\n        FROM mdl_event kbi_e, mdl_role_assignments kbi_ras, mdl_context kbi_con\n        WHERE kbi_ras.userid = kbi_e.userid\n          AND kbi_ras.roleid = 5\n          AND kbi_con.id = kbi_ras.contextid\n          AND kbi_con.contextlevel = 50\n          AND kbi_e.courseid = kbi_con.instanceid\n          AND kbi_con.instanceid = kbi_c.id)                                                  AS events,\n       (SELECT CASE\n                 WHEN (TO_DAYS(NOW()) - TO_DAYS(FROM_UNIXTIME(kbi_c.timecreated))) > 0 THEN (COUNT(DISTINCT kbi_fp.id) /\n                                                                                         (TO_DAYS(NOW()) - TO_DAYS(FROM_UNIXTIME(kbi_c.timecreated))))\n                 ELSE 0 END\n        FROM mdl_role_assignments kbi_ras, mdl_context kbi_con, mdl_forum_discussions kbi_fd, mdl_forum_posts kbi_fp\n        WHERE kbi_con.id = kbi_ras.contextid\n          AND kbi_ras.roleid = 5\n          AND kbi_con.contextlevel = 50\n          AND kbi_fd.course = kbi_con.instanceid\n          AND kbi_fp.userid = kbi_ras.userid\n          AND kbi_fp.discussion = kbi_fd.id\n          AND kbi_con.instanceid = kbi_c.id)                                                  AS post_per_day,\n       (SELECT CASE\n                 WHEN COUNT(DISTINCT timepoint) > 0 THEN (SUM(kbi_lil.visits) / COUNT(DISTINCT timepoint))\n                 ELSE 0 END\n        FROM mdl_role_assignments kbi_ras, mdl_context kbi_con, mdl_local_kopere_bi_tracking kbi_lit, mdl_local_kopere_bi_track_log kbi_lil\n        WHERE kbi_con.id = kbi_ras.contextid\n          AND kbi_ras.roleid = 5\n          AND kbi_con.contextlevel = 50\n          AND kbi_con.instanceid = kbi_lit.courseid\n          AND kbi_ras.userid = kbi_lit.userid\n          AND kbi_lil.trackid = kbi_lit.id\n          AND kbi_con.instanceid = kbi_c.id)                                                  AS visits,\n       (SELECT COUNT(DISTINCT kbi_cm.id) FROM mdl_course_modules kbi_cm WHERE kbi_cm.course = kbi_c.id\n                                                                  AND kbi_cm.visible = 1) AS modules,\n       (SELECT COUNT(DISTINCT kbi_cmc.id)\n        FROM mdl_course_modules kbi_cm\n               LEFT JOIN mdl_course_modules_completion kbi_cmc ON kbi_cmc.coursemoduleid = kbi_cm.id AND\n                                                              kbi_cmc.completionstate IN\n                                                              (1, 2) AND\n                                                              kbi_cm.visible = 1\n        WHERE kbi_cm.course = kbi_c.id)                                                       AS completed_modules,\n       (SELECT COUNT(id) FROM mdl_assign WHERE course = kbi_c.id)                         AS assignment,\n       (SELECT COUNT(id) FROM mdl_quiz WHERE course = kbi_c.id)                           AS quiz,\n       (SELECT COUNT(id) FROM mdl_workshop WHERE course = kbi_c.id)                       AS workshop\nFROM mdl_role_assignments kbi_ra\n       JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_ctx.instanceid\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ra.userid\nWHERE kbi_ra.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_ra.roleid = 3\nORDER BY kbi_c.fullname asc','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course_name\":{\"key\":\"course_name\",\"title\":\"lang::report_field_course_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"course_created\":{\"key\":\"course_created\",\"title\":\"lang::report_field_course_created_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"startdate\":{\"key\":\"startdate\",\"title\":\"lang::report_field_startdate_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"teacher_id\":{\"key\":\"teacher_id\",\"title\":\"lang::report_field_teacher_id_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"learners\":{\"key\":\"learners\",\"title\":\"lang::report_field_learners_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"events\":{\"key\":\"events\",\"title\":\"lang::report_field_events_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"post_per_day\":{\"key\":\"post_per_day\",\"title\":\"lang::report_field_post_per_day_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"modules\":{\"key\":\"modules\",\"title\":\"lang::report_field_modules_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completed_modules\":{\"key\":\"completed_modules\",\"title\":\"lang::report_field_completed_modules_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"assignment\":{\"key\":\"assignment\",\"title\":\"lang::report_field_assignment_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"quiz\":{\"key\":\"quiz\",\"title\":\"lang::report_field_quiz_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"workshop\":{\"key\":\"workshop\",\"title\":\"lang::report_field_workshop_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(50,'kbi_el_course_access','lang::report_page_035_title::local_kopere_bi',45,1,'table','light','','','','SELECT kbi_c.id,\n       kbi_c.fullname,\n       kbi_c.shortname,\n       kbi_ca.name                             AS category,\n       kbi_c.startdate,\n       x.users,\n       (kbi_ue.enrolled - x.users)             AS inactiveusers,\n       kbi_ue.enrolled,\n       kbi_cc.completed,\n       x.timespend,\n       x.visits,\n       x.lastaccess,\n       completed_activities,\n       (SELECT GROUP_CONCAT(DISTINCT CONCAT(kbi_u.firstname, \' \', kbi_u.lastname) SEPARATOR \', \')\n        FROM mdl_role_assignments kbi_ra\n               JOIN mdl_user kbi_u ON kbi_ra.userid = kbi_u.id\n               JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n        WHERE kbi_ctx.instanceid = kbi_c.id\n          AND kbi_ctx.contextlevel = 50\n          AND kbi_ra.roleid = 3) AS teacher\nFROM mdl_course kbi_c\n       LEFT JOIN mdl_course_categories kbi_ca ON kbi_ca.id = kbi_c.category\n       LEFT JOIN (SELECT course, COUNT(*) AS completed\n                  FROM mdl_course_completions\n                  WHERE timecompleted > 0\n                    AND course = :courseid\n                  GROUP BY course) cc ON kbi_cc.course = kbi_c.id\n       LEFT JOIN (SELECT kbi_cc.course, COUNT(*) as completed_activities\n                  FROM mdl_course_modules_completion kbi_cmc\n                         JOIN mdl_course_modules kbi_cc ON kbi_cc.id = kbi_cmc.coursemoduleid\n                  WHERE 1 = 1\n                    AND kbi_cmc.completionstate IN (1, 2)\n                    AND kbi_cc.course = :courseid\n                  GROUP BY kbi_cc.course) compl ON compl.course = kbi_c.id\n       LEFT JOIN (SELECT kbi_e.courseid, COUNT(DISTINCT kbi_ue.userid) AS enrolled\n                  FROM mdl_enrol kbi_e\n                         JOIN mdl_user_enrolments kbi_ue ON kbi_ue.enrolid = kbi_e.id\n                  WHERE 1 = 1\n                    AND kbi_ue.status = 0\n                    AND kbi_e.status = 0\n                    AND kbi_e.courseid = :courseid\n                  GROUP BY kbi_e.courseid) ue ON kbi_ue.courseid = kbi_c.id\n       LEFT JOIN (SELECT kbi_t.courseid,\n                         COUNT(DISTINCT kbi_t.userid) as users,\n                         MAX(lastaccess)          AS lastaccess,\n                         SUM(kbi_l.timespend)         AS timespend,\n                         SUM(kbi_l.visits)            AS visits\n                  FROM mdl_local_kopere_bi_tracking kbi_t\n                         JOIN mdl_local_kopere_bi_track_log kbi_l ON kbi_l.trackid = kbi_t.id\n                  WHERE 1 = 1\n                    AND kbi_t.courseid = :courseid\n                  GROUP BY kbi_t.courseid) x ON x.courseid = kbi_c.id\nWHERE kbi_c.id > 1\n  AND kbi_c.id = :courseid\n  AND kbi_c.visible = 1','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"category\":{\"key\":\"category\",\"title\":\"lang::report_field_category_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"startdate\":{\"key\":\"startdate\",\"title\":\"lang::report_field_startdate_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"users\":{\"key\":\"users\",\"title\":\"lang::report_field_users_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"inactiveusers\":{\"key\":\"inactiveusers\",\"title\":\"lang::report_field_inactiveusers_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"enrolled\":{\"key\":\"enrolled\",\"title\":\"lang::report_field_enrolled_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"completed\":{\"key\":\"completed\",\"title\":\"lang::report_field_completed_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"lastaccess\":{\"key\":\"lastaccess\",\"title\":\"lang::report_field_lastaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"completed_activities\":{\"key\":\"completed_activities\",\"title\":\"lang::report_field_completed_activities_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"teacher\":{\"key\":\"teacher\",\"title\":\"lang::report_field_teacher_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(51,'kbi_el_course_access_details','lang::report_page_036_title::local_kopere_bi',46,1,'table','light','','','','SELECT max(kbi_t.id)             AS tid,\n       kbi_u.id                  AS id,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_c.fullname,\n       kbi_c.shortname,\n       kbi_ca.name               AS category,\n       MAX(kbi_cc.timecompleted) AS timecompleted,\n       SUM(kbi_l.timespend)      AS timespend,\n       SUM(kbi_l.visits)         AS visits\nFROM mdl_local_kopere_bi_track_log kbi_l\n       JOIN mdl_local_kopere_bi_tracking kbi_t ON kbi_t.id = kbi_l.trackid\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_t.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_t.courseid\n       JOIN mdl_course_categories kbi_ca ON kbi_ca.id = kbi_c.category\n       LEFT JOIN mdl_course_completions kbi_cc ON kbi_cc.userid = kbi_u.id AND kbi_cc.course = kbi_c.id\nWHERE kbi_l.id > 0\n  AND kbi_c.id = :courseid\nGROUP BY kbi_u.id, kbi_c.id, kbi_ca.id','1h','none','{\"column\":{\"tid\":{\"key\":\"tid\",\"title\":\"lang::report_field_tid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"category\":{\"key\":\"category\",\"title\":\"lang::report_field_category_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timecompleted\":{\"key\":\"timecompleted\",\"title\":\"lang::report_field_timecompleted_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646820),
(52,'kbi_el_course_activity_overview','lang::report_page_037_title::local_kopere_bi',47,1,'table','light','','','','SELECT kbi_ue.id,\n       kbi_u.email,\n       kbi_u.idnumber,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_c.id         AS course_id,\n       kbi_c.shortname,\n       kbi_ue.status    AS enroll_status,\n       kbi_ue.timestart AS enroll_started,\n       kbi_ue.timeend,\n       kbi_lit.lastaccess,\n       kbi_ra.roles     AS role_name\nFROM mdl_course kbi_c\n       JOIN mdl_enrol kbi_e ON kbi_e.courseid = kbi_c.id\n       JOIN mdl_user_enrolments kbi_ue ON kbi_ue.enrolid = kbi_e.id\n       JOIN (SELECT kbi_ra.userid,\n                    kbi_ctx.instanceid     AS course_id,\n                    GROUP_CONCAT(DISTINCT(CASE WHEN kbi_r.name = \'\' THEN kbi_r.shortname ELSE kbi_r.name END) SEPARATOR\n                                 \', \') AS roles\n             FROM mdl_role_assignments kbi_ra\n                    JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\n                    JOIN mdl_role kbi_r ON kbi_r.id = kbi_ra.roleid\n             WHERE kbi_ra.id > 0\n               AND kbi_ra.roleid = 5\n               AND kbi_ctx.instanceid = :courseid\n             GROUP BY kbi_ra.userid, kbi_ctx.instanceid) ra ON kbi_ra.userid = kbi_ue.userid AND kbi_ra.course_id = kbi_e.courseid\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ra.userid AND kbi_ue.userid = kbi_u.id\n       LEFT JOIN mdl_local_kopere_bi_tracking kbi_lit ON kbi_lit.userid = kbi_u.id AND kbi_lit.page = \'course\' AND kbi_lit.param = kbi_c.id\nWHERE kbi_u.id IS NOT NULL\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"idnumber\":{\"key\":\"idnumber\",\"title\":\"lang::report_field_idnumber_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"course_id\":{\"key\":\"course_id\",\"title\":\"lang::report_field_course_id_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"enroll_status\":{\"key\":\"enroll_status\",\"title\":\"lang::report_field_enroll_status_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"enroll_started\":{\"key\":\"enroll_started\",\"title\":\"lang::report_field_enroll_started_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timeend\":{\"key\":\"timeend\",\"title\":\"lang::report_field_timeend_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"lastaccess\":{\"key\":\"lastaccess\",\"title\":\"lang::report_field_lastaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"role_name\":{\"key\":\"role_name\",\"title\":\"lang::report_field_role_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(53,'kbi_el_course_content_logs','lang::report_page_038_title::local_kopere_bi',48,1,'table','light','','','','SELECT kbi_l.id,\n       kbi_l.courseid,\n       kbi_l.userid,\n       kbi_l.contextinstanceid          AS cmid,\n       kbi_l.objecttable,\n       kbi_l.origin,\n       kbi_l.ip,\n       kbi_c.fullname                   AS course,\n       kbi_c.shortname,\n       kbi_ca.name                      AS category,\n       kbi_u.email,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_l.timecreated,\n       (CASE\n          WHEN kbi_l.objecttable = \'forum_discussions\' THEN (SELECT name FROM mdl_forum_discussions WHERE id = kbi_l.objectid)\n          ELSE (CASE\n                  WHEN kbi_l.objecttable = \'forum_posts\' THEN (SELECT subject FROM mdl_forum_posts WHERE id = kbi_l.objectid)\n                  ELSE \'\' END) END) AS forumitem\nFROM mdl_local_kopere_bi_log_tmp kbi_l\n       LEFT JOIN mdl_course kbi_c ON kbi_c.id = kbi_l.courseid\n       LEFT JOIN mdl_course_categories kbi_ca ON kbi_ca.id = kbi_c.category\n       LEFT JOIN mdl_user kbi_u ON kbi_u.id = kbi_l.userid\n       LEFT JOIN mdl_modules kbi_m ON kbi_m.name = SUBSTRING(kbi_l.component, 5)\n       LEFT JOIN mdl_course_modules kbi_cm ON kbi_cm.id = kbi_l.contextinstanceid\nWHERE kbi_l.component LIKE \'%mod_%\'\n  AND kbi_l.courseid = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_cm.visible = 1','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"cmid\":{\"key\":\"cmid\",\"title\":\"lang::report_field_cmid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"objecttable\":{\"key\":\"objecttable\",\"title\":\"lang::report_field_objecttable_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"origin\":{\"key\":\"origin\",\"title\":\"lang::report_field_origin_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"ip\":{\"key\":\"ip\",\"title\":\"lang::report_field_ip_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"category\":{\"key\":\"category\",\"title\":\"lang::report_field_category_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"timecreated\":{\"key\":\"timecreated\",\"title\":\"lang::report_field_timecreated_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"forumitem\":{\"key\":\"forumitem\",\"title\":\"lang::report_field_forumitem_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(54,'kbi_el_course_content_utilization','lang::report_page_039_title::local_kopere_bi',49,1,'table','light','','','','SELECT kbi_l.id,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_c.fullname,\n       kbi_c.shortname,\n       kbi_ca.name  AS category,\n       kbi_l.param,\n       kbi_l.visits,\n       kbi_l.timespend,\n       kbi_l.firstaccess,\n       kbi_l.lastaccess,\n       kbi_l.useragent,\n       kbi_l.useros,\n       kbi_l.userlang,\n       kbi_l.userip,\n       kbi_l.userid,\n       kbi_l.courseid,\n       kbi_cm.added as created,\n       kbi_m.name   as module\nFROM mdl_local_kopere_bi_tracking kbi_l\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_l.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_l.courseid\n       LEFT JOIN mdl_course_categories kbi_ca ON kbi_ca.id = kbi_c.category\n       LEFT JOIN mdl_course_modules kbi_cm ON kbi_cm.id = kbi_l.param\n       LEFT JOIN mdl_modules kbi_m ON kbi_m.id = kbi_cm.module\nWHERE kbi_l.page = \'module\'\n  AND kbi_l.courseid = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_cm.visible = 1','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{fullname}}}<\\/a>\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"category\":{\"key\":\"category\",\"title\":\"lang::report_field_category_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"param\":{\"key\":\"param\",\"title\":\"lang::report_field_param_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"firstaccess\":{\"key\":\"firstaccess\",\"title\":\"lang::report_field_firstaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"lastaccess\":{\"key\":\"lastaccess\",\"title\":\"lang::report_field_lastaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"useragent\":{\"key\":\"useragent\",\"title\":\"lang::report_field_useragent_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"useros\":{\"key\":\"useros\",\"title\":\"lang::report_field_useros_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"userlang\":{\"key\":\"userlang\",\"title\":\"lang::report_field_userlang_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"userip\":{\"key\":\"userip\",\"title\":\"lang::report_field_userip_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"created\":{\"key\":\"created\",\"title\":\"lang::report_field_created_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"module\":{\"key\":\"module\",\"title\":\"lang::report_field_module_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(55,'kbi_el_course_inactivity','lang::report_page_040_title::local_kopere_bi',50,1,'table','light','','','','SELECT kbi_ue.id,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_ue.timecreated                      as enrolled,\n       kbi_ue.userid,\n       kbi_e.enrol                             AS enrols,\n       kbi_ul.timeaccess                       AS lastaccess,\n       ROUND((CASE\n                WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                ELSE kbi_g.finalgrade END), 0) AS grade,\n       kbi_c.id                                as cid,\n       kbi_c.shortname,\n       kbi_ca.name                             AS category,\n       kbi_c.fullname                          as course\nFROM mdl_user_enrolments kbi_ue\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ue.userid\n       JOIN mdl_enrol kbi_e ON kbi_e.id = kbi_ue.enrolid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_e.courseid\n       LEFT JOIN mdl_course_categories kbi_ca ON kbi_ca.id = kbi_c.category\n       LEFT JOIN mdl_user_lastaccess kbi_ul ON kbi_ul.courseid = kbi_c.id AND kbi_ul.userid = kbi_u.id\n       LEFT JOIN mdl_grade_items kbi_gi ON kbi_gi.itemtype = \'course\' AND kbi_gi.courseid = kbi_e.courseid\n       LEFT JOIN mdl_grade_grades kbi_g ON kbi_g.userid = kbi_u.id AND kbi_g.itemid = kbi_gi.id AND kbi_g.finalgrade IS NOT NULL\n       LEFT JOIN (SELECT MAX(kbi_t.id) AS id, kbi_t.userid, kbi_t.courseid\n                  FROM mdl_local_kopere_bi_tracking kbi_t, mdl_local_kopere_bi_track_log kbi_l\n                  WHERE kbi_l.trackid = kbi_t.id\n                  GROUP BY kbi_t.courseid, kbi_t.userid) as l ON kbi_l.courseid = kbi_e.courseid AND kbi_l.userid = kbi_ue.userid\nWHERE kbi_l.id IS NULL\n  AND kbi_c.id = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_ue.status = 0\n  AND kbi_e.status = 0','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"enrolled\":{\"key\":\"enrolled\",\"title\":\"lang::report_field_enrolled_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"enrols\":{\"key\":\"enrols\",\"title\":\"lang::report_field_enrols_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"lastaccess\":{\"key\":\"lastaccess\",\"title\":\"lang::report_field_lastaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"cid\":{\"key\":\"cid\",\"title\":\"lang::report_field_cid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"category\":{\"key\":\"category\",\"title\":\"lang::report_field_category_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{cid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"}}}',1780646820),
(56,'kbi_el_course_progress','lang::report_page_041_title::local_kopere_bi',51,1,'table','light','','','','SELECT MIN(kbi_ue.id)                                    AS id,\n       kbi_u.id                                          AS userid,\n       kbi_u.email,\n       ((MAX(cmca.cmcnuma) / MAX(cma.cmnuma)) * 100) AS assignments,\n       ((MAX(kbi_cmc.cmcnums) / MAX(cmx.cmnumx)) * 100)  AS participations,\n       ((MAX(lit.vsts) / MAX(kbi_cm.cmnums)) * 100)      AS visits,\n       MAX(cma.cmnuma)                               AS assigns,\n       kbi_c.fullname                                    AS course,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       MIN(gc.grade)                                 AS grade\nFROM mdl_user_enrolments kbi_ue\n       LEFT JOIN mdl_user kbi_u ON kbi_u.id = kbi_ue.userid\n       LEFT JOIN mdl_enrol kbi_e ON kbi_e.id = kbi_ue.enrolid\n       LEFT JOIN mdl_course kbi_c ON kbi_c.id = kbi_e.courseid\n       LEFT JOIN (SELECT COUNT(DISTINCT id) AS vsts, courseid, userid\n                  FROM mdl_local_kopere_bi_tracking\n                  WHERE page = \'module\'\n                  GROUP BY userid, courseid) lit ON lit.courseid = kbi_c.id AND lit.userid = kbi_u.id\n       LEFT JOIN (SELECT course, count(id) as cmnums FROM mdl_course_modules WHERE visible = 1 GROUP BY course) as cm\n         ON kbi_cm.course = kbi_c.id\n       LEFT JOIN (SELECT course, count(id) as cmnumx\n                  FROM mdl_course_modules\n                  WHERE visible = 1\n                    and completion > 0\n                  GROUP BY course) cmx ON cmx.course = kbi_c.id\n       LEFT JOIN (SELECT kbi_cm.course, count(kbi_cm.id) as cmnuma\n                  FROM mdl_course_modules kbi_cm\n                         JOIN mdl_modules kbi_m ON kbi_m.id = kbi_cm.module\n                  WHERE kbi_cm.visible = 1\n                    and kbi_m.name = \'assign\'\n                  GROUP BY kbi_cm.course) cma ON cma.course = kbi_c.id\n       LEFT JOIN (SELECT kbi_cm.course, kbi_cmc.userid, count(kbi_cmc.id) as cmcnums\n                  FROM mdl_course_modules kbi_cm, mdl_course_modules_completion kbi_cmc\n                  WHERE kbi_cmc.coursemoduleid = kbi_cm.id\n                    AND kbi_cm.visible = 1\n                    AND kbi_cmc.completionstate IN (1, 2)\n                  GROUP BY kbi_cm.course, kbi_cmc.userid) cmc ON kbi_cmc.course = kbi_c.id AND kbi_cmc.userid = kbi_u.id\n       LEFT JOIN (SELECT kbi_cm.course, kbi_cmc.userid, count(kbi_cmc.id) as cmcnuma\n                  FROM mdl_course_modules kbi_cm, mdl_course_modules_completion kbi_cmc\n                  WHERE kbi_cmc.coursemoduleid = kbi_cm.id\n                    AND kbi_cm.module = 1\n                    AND kbi_cm.visible = 1\n                    AND kbi_cmc.completionstate IN (1, 2)\n                  GROUP BY kbi_cm.course, kbi_cmc.userid) as cmca ON cmca.course = kbi_c.id AND cmca.userid = kbi_u.id\n       LEFT JOIN (SELECT kbi_gi.courseid,\n                         kbi_g.userid,\n                         ROUND((CASE\n                                  WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                                  ELSE kbi_g.finalgrade END), 0) AS grade\n                  FROM mdl_grade_items kbi_gi, mdl_grade_grades kbi_g\n                  WHERE kbi_gi.itemtype = \'course\'\n                    AND kbi_g.itemid = kbi_gi.id\n                    AND kbi_g.finalgrade IS NOT NULL\n                  GROUP BY kbi_gi.courseid, kbi_g.userid, kbi_g.finalgrade, kbi_g.rawgrademax) as gc\n         ON gc.courseid = kbi_c.id AND gc.userid = kbi_u.id\nWHERE kbi_ue.id > 0\n  AND kbi_e.courseid = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\nGROUP BY kbi_u.id, kbi_c.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"assignments\":{\"key\":\"assignments\",\"title\":\"lang::report_field_assignments_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"participations\":{\"key\":\"participations\",\"title\":\"lang::report_field_participations_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"assigns\":{\"key\":\"assigns\",\"title\":\"lang::report_field_assigns_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646820),
(57,'kbi_el_course_site_summary','lang::report_page_042_title::local_kopere_bi',52,1,'table','light','','','','SELECT kbi_c.id, kbi_c.fullname, l.learners, kbi_cc.completed, kbi_g.grade, kbi_lit.timespend AS timespend, kbi_lit.visits AS visits\nFROM mdl_course kbi_c\n       LEFT JOIN (SELECT kbi_ctx.instanceid, COUNT(DISTINCT kbi_ra.userid) AS learners\n                  FROM mdl_context kbi_ctx\n                         JOIN mdl_role_assignments kbi_ra ON kbi_ra.contextid = kbi_ctx.id\n                         JOIN mdl_enrol kbi_e ON kbi_e.courseid = kbi_ctx.instanceid\n                         JOIN mdl_user_enrolments kbi_ue ON kbi_ue.enrolid = kbi_e.id AND kbi_ue.userid = kbi_ra.userid\n                  WHERE kbi_ctx.instanceid > 0\n                    AND kbi_ctx.contextlevel = 50\n                    AND kbi_ctx.instanceid = :courseid\n                    AND kbi_ra.roleid = 5\n                    AND kbi_e.status = 0\n                    AND kbi_ue.status = 0\n                  GROUP BY kbi_ctx.instanceid) l ON l.instanceid = kbi_c.id\n       LEFT JOIN (SELECT kbi_gi.courseid,\n                         ROUND(AVG(CASE\n                                     WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                                     ELSE kbi_g.finalgrade END), 0) AS grade\n                  FROM mdl_grade_items kbi_gi\n                         LEFT JOIN mdl_grade_grades kbi_g ON kbi_g.itemid = kbi_gi.id\n                  WHERE kbi_gi.courseid > 0\n                    AND kbi_gi.itemtype = \'course\'\n                    AND kbi_gi.courseid = :courseid\n                  GROUP BY kbi_gi.courseid) g ON kbi_g.courseid = kbi_c.id\n       LEFT JOIN (SELECT kbi_cc.course, COUNT(DISTINCT kbi_cc.userid) AS completed\n                  FROM mdl_course_completions kbi_cc\n                  WHERE kbi_cc.course > 0\n                    AND kbi_cc.timecompleted > 0\n                    AND kbi_cc.course = :courseid\n                  GROUP BY kbi_cc.course) cc ON kbi_cc.course = kbi_c.id\n       LEFT JOIN (SELECT kbi_lit.courseid, SUM(kbi_lil.timespend) AS timespend, SUM(kbi_lil.visits) AS visits\n                  FROM mdl_local_kopere_bi_tracking kbi_lit\n                         JOIN mdl_local_kopere_bi_track_log kbi_lil ON kbi_lil.trackid = kbi_lit.id\n                         JOIN mdl_context kbi_ctx ON kbi_ctx.instanceid = kbi_lit.courseid AND kbi_ctx.contextlevel = 50\n                         JOIN mdl_role_assignments kbi_ra ON kbi_ra.contextid = kbi_ctx.id AND kbi_ra.userid = kbi_lit.userid\n                  WHERE kbi_lit.courseid > 0\n                    AND kbi_lit.courseid = :courseid\n                    AND kbi_ra.roleid = 5\n                  GROUP BY kbi_lit.courseid) lit ON kbi_lit.courseid = kbi_c.id\nWHERE kbi_c.id > 1\n  AND kbi_c.visible = 1\n  AND kbi_c.id = :courseid','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"learners\":{\"key\":\"learners\",\"title\":\"lang::report_field_learners_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completed\":{\"key\":\"completed\",\"title\":\"lang::report_field_completed_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646820),
(58,'kbi_el_course_stats','lang::report_page_043_title::local_kopere_bi',53,1,'table','light','','','','SELECT kbi_c.id,\n       kbi_c.fullname                                                     AS course,\n       kbi_c.shortname,\n       kbi_c.timecreated                                                  AS created,\n       kbi_c.idnumber,\n       kbi_c.enablecompletion,\n       kbi_c.visible,\n       ROUND(AVG(CASE\n                   WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                   ELSE kbi_g.finalgrade END), 0)                         AS grade,\n       MAX(l.timespend)                                               AS timespend,\n       MAX(l.visits)                                                  AS visits,\n       COUNT(DISTINCT kbi_cc.userid)                                      AS completed,\n       COUNT(DISTINCT uc.userid)                                      AS learners,\n       (SELECT COUNT(id) FROM mdl_course_modules WHERE visible = 1\n                                                   AND course = kbi_c.id) AS modules,\n       (SELECT name FROM mdl_course_categories WHERE id = kbi_c.category) AS category\nFROM mdl_course kbi_c\n       LEFT JOIN (SELECT kbi_e.courseid, kbi_ue.userid\n                  FROM mdl_enrol kbi_e\n                         JOIN mdl_user_enrolments kbi_ue ON kbi_ue.enrolid = kbi_e.id AND kbi_ue.status = 0\n                         JOIN mdl_context kbi_ctx ON kbi_ctx.contextlevel = 50 AND kbi_ctx.instanceid = kbi_e.courseid\n                         JOIN mdl_role_assignments kbi_ra\n                           ON kbi_ra.userid = kbi_ue.userid AND kbi_ra.contextid = kbi_ctx.id AND kbi_ra.roleid = 5\n                  WHERE kbi_e.courseid > 0\n                    AND kbi_e.status = 0\n                  GROUP BY kbi_e.courseid, kbi_ue.userid) uc ON uc.courseid = kbi_c.id\n       LEFT JOIN mdl_course_completions kbi_cc ON kbi_cc.course = kbi_c.id AND kbi_cc.userid = uc.userid AND kbi_cc.timecompleted > 0\n       LEFT JOIN mdl_grade_items kbi_gi ON kbi_gi.itemtype = \'course\' AND kbi_gi.courseid = kbi_c.id\n       LEFT JOIN mdl_grade_grades kbi_g ON kbi_g.userid = uc.userid AND kbi_g.itemid = kbi_gi.id AND kbi_g.finalgrade IS NOT NULL\n       LEFT JOIN (SELECT courseid, SUM(timespend) AS timespend, SUM(visits) AS visits\n                  FROM mdl_local_kopere_bi_tracking\n                  WHERE id > 0\n                  GROUP BY courseid) l ON l.courseid = kbi_c.id\nWHERE kbi_c.id > 1\n  AND kbi_c.id = :courseid\n  AND kbi_c.visible = 1\nGROUP BY kbi_c.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"created\":{\"key\":\"created\",\"title\":\"lang::report_field_created_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"idnumber\":{\"key\":\"idnumber\",\"title\":\"lang::report_field_idnumber_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"enablecompletion\":{\"key\":\"enablecompletion\",\"title\":\"lang::report_field_enablecompletion_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"visible\":{\"key\":\"visible\",\"title\":\"lang::report_field_visible_title::local_kopere_bi\",\"type\":\"visible\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completed\":{\"key\":\"completed\",\"title\":\"lang::report_field_completed_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"learners\":{\"key\":\"learners\",\"title\":\"lang::report_field_learners_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"modules\":{\"key\":\"modules\",\"title\":\"lang::report_field_modules_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"category\":{\"key\":\"category\",\"title\":\"lang::report_field_category_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646820),
(59,'kbi_el_course_stats_advanced','lang::report_page_044_title::local_kopere_bi',54,1,'table','light','','','','SELECT kbi_c.id,\n       kbi_c.fullname                                                          AS course,\n       kbi_c.shortname,\n       kbi_c.timecreated                                                       AS created,\n       kbi_c.idnumber,\n       kbi_c.enablecompletion,\n       kbi_c.visible,\n       MAX(kbi_e.grade)                                                        AS grade,\n       MAX(l.timespend)                                                    AS timespend,\n       MAX(l.visits)                                                       AS visits,\n       MAX(kbi_e.completed)                                                    AS completed,\n       MAX(kbi_e.learners)                                                     AS learners,\n       (SELECT COUNT(id) FROM mdl_course_modules WHERE course = kbi_c.id\n                                                   AND deletioninprogress = 0\n                                                   AND visible = 1)        AS modules,\n       MAX(kbi_cat.name)                                                       AS category,\n       (SELECT name FROM mdl_course_categories WHERE id = MAX(kbi_cat.parent)) AS parent_category,\n       MAX(t.teachers)                                                     AS teachers,\n       MAX(t.teachers_count)                                               AS teachers_count,\n       MAX(t.teachers_timespend)                                           AS teachers_timespend,\n       MAX(s.avg_learners_timespend)                                       AS avg_learners_timespend\nFROM mdl_course kbi_c\n       JOIN (SELECT kbi_e.courseid,\n                    ROUND(AVG(CASE\n                                WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                                ELSE kbi_g.finalgrade END), 0) AS grade,\n                    COUNT(DISTINCT kbi_cc.userid)              AS completed,\n                    COUNT(DISTINCT kbi_ue.userid)              AS learners\n             FROM mdl_enrol kbi_e\n                    JOIN mdl_user_enrolments kbi_ue ON kbi_ue.enrolid = kbi_e.id\n                    JOIN mdl_context kbi_ctx ON kbi_ctx.instanceid = kbi_e.courseid AND kbi_ctx.contextlevel = 50\n                    JOIN mdl_role_assignments kbi_ra ON kbi_ra.contextid = kbi_ctx.id AND kbi_ra.userid = kbi_ue.userid\n                    LEFT JOIN mdl_course_completions kbi_cc\n                      ON kbi_cc.timecompleted > 0 AND kbi_cc.course = kbi_e.courseid AND kbi_cc.userid = kbi_ue.userid\n                    JOIN mdl_grade_items kbi_gi ON kbi_gi.itemtype = \'course\' AND kbi_gi.courseid = kbi_e.courseid\n                    LEFT JOIN mdl_grade_grades kbi_g\n                      ON kbi_g.userid = kbi_ue.userid AND kbi_g.itemid = kbi_gi.id AND kbi_g.finalgrade IS NOT NULL\n             WHERE kbi_e.courseid > 0\n               AND kbi_e.courseid = :courseid\n               AND kbi_ue.status = 0\n               AND kbi_e.status = 0\n               AND kbi_ra.roleid = 5\n             GROUP BY kbi_e.courseid) e ON kbi_e.courseid = kbi_c.id\n       LEFT JOIN (SELECT courseid, SUM(timespend) AS timespend, SUM(visits) AS visits\n                  FROM (SELECT kbi_ctx.instanceid, kbi_ra.userid\n                        FROM mdl_role_assignments kbi_ra\n                               JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n                        WHERE kbi_ctx.contextlevel = 50\n                          AND kbi_ctx.instanceid = :courseid\n                        GROUP BY kbi_ctx.instanceid, kbi_ra.userid) cu\n                         LEFT JOIN mdl_local_kopere_bi_tracking kbi_ltu\n                           ON kbi_ltu.courseid = cu.instanceid AND kbi_ltu.userid = cu.userid\n                  WHERE cu.instanceid > 0\n                  GROUP BY kbi_ltu.courseid) l ON l.courseid = kbi_c.id\n       LEFT JOIN mdl_course_categories kbi_cat ON kbi_cat.id = kbi_c.category\n       LEFT JOIN (SELECT ct.instanceid,\n                         GROUP_CONCAT(DISTINCT CONCAT(kbi_u.firstname, \' \', kbi_u.lastname) SEPARATOR \', \') AS teachers,\n                         COUNT(DISTINCT kbi_u.id)                                                       AS teachers_count,\n                         SUM(timespend)                                                             AS teachers_timespend\n                  FROM (SELECT kbi_ctx.instanceid, kbi_ra.userid\n                        FROM mdl_role_assignments kbi_ra\n                               JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n                        WHERE kbi_ctx.contextlevel = 50\n                          AND kbi_ctx.instanceid = :courseid\n                          AND kbi_ra.roleid = 3\n                        GROUP BY kbi_ctx.instanceid, kbi_ra.userid) ct\n                         JOIN mdl_user kbi_u ON ct.userid = kbi_u.id\n                         LEFT JOIN mdl_local_kopere_bi_tracking kbi_lit\n                           ON kbi_lit.courseid = ct.instanceid AND kbi_lit.userid = kbi_u.id\n                  GROUP BY ct.instanceid) t ON t.instanceid = kbi_c.id\n       LEFT JOIN (SELECT cl.instanceid, SUM(kbi_lit.timespend) / COUNT(DISTINCT(cl.userid)) AS avg_learners_timespend\n                  FROM (SELECT kbi_ctx.instanceid, kbi_ra.userid\n                        FROM mdl_role_assignments kbi_ra\n                               JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n                        WHERE kbi_ctx.contextlevel = 50\n                          AND kbi_ctx.instanceid = :courseid\n                          AND kbi_ra.roleid = 5\n                        GROUP BY kbi_ctx.instanceid, kbi_ra.userid) cl\n                         LEFT JOIN mdl_local_kopere_bi_tracking kbi_lit\n                           ON kbi_lit.courseid = cl.instanceid AND kbi_lit.userid = cl.userid\n                  GROUP BY cl.instanceid) s ON s.instanceid = kbi_c.id\nWHERE kbi_c.id > 0\n  AND kbi_c.id = :courseid\n  AND kbi_c.visible = 1\nGROUP BY kbi_c.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"created\":{\"key\":\"created\",\"title\":\"lang::report_field_created_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"idnumber\":{\"key\":\"idnumber\",\"title\":\"lang::report_field_idnumber_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"enablecompletion\":{\"key\":\"enablecompletion\",\"title\":\"lang::report_field_enablecompletion_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"visible\":{\"key\":\"visible\",\"title\":\"lang::report_field_visible_title::local_kopere_bi\",\"type\":\"visible\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completed\":{\"key\":\"completed\",\"title\":\"lang::report_field_completed_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"learners\":{\"key\":\"learners\",\"title\":\"lang::report_field_learners_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"modules\":{\"key\":\"modules\",\"title\":\"lang::report_field_modules_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"category\":{\"key\":\"category\",\"title\":\"lang::report_field_category_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"parent_category\":{\"key\":\"parent_category\",\"title\":\"lang::report_field_parent_category_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teachers\":{\"key\":\"teachers\",\"title\":\"lang::report_field_teachers_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teachers_count\":{\"key\":\"teachers_count\",\"title\":\"lang::report_field_teachers_count_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"teachers_timespend\":{\"key\":\"teachers_timespend\",\"title\":\"lang::report_field_teachers_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"avg_learners_timespend\":{\"key\":\"avg_learners_timespend\",\"title\":\"lang::report_field_avg_learners_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"}}}',1780646820),
(60,'kbi_el_engaged_not_engaged_totals_by_course','lang::report_page_045_title::local_kopere_bi',55,1,'table','light','','','','SELECT kbi_c.id,\n       kbi_c.fullname,\n       COUNT(DISTINCT kbi_ra.userid)                                        as all_learners,\n       COUNT(DISTINCT CASE\n                        WHEN comp.userid IS NOT NULL AND kbi_ula.id IS NOT NULL THEN kbi_u.id\n                        ELSE NULL END)                                  as completed_learners,\n       COUNT(DISTINCT CASE\n                        WHEN comp.userid IS NULL AND kbi_ula.id IS NOT NULL THEN kbi_u.id\n                        ELSE NULL END)                                  as not_completed_learners,\n       COUNT(DISTINCT CASE WHEN kbi_ula.id IS NULL THEN kbi_u.id ELSE NULL END) as not_accessed_learners\nFROM mdl_role_assignments kbi_ra\n       JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_ctx.instanceid\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ra.userid\n       LEFT JOIN (SELECT kbi_cm.course, kbi_cmc.userid\n                  FROM mdl_course_modules kbi_cm\n                         JOIN mdl_course_modules_completion kbi_cmc\n                           ON kbi_cmc.coursemoduleid = kbi_cm.id AND kbi_cmc.completionstate = 1\n                  WHERE kbi_cmc.id > 0\n                  GROUP BY kbi_cm.course, kbi_cmc.userid) comp ON comp.userid = kbi_u.id AND comp.course = kbi_c.id\n       LEFT JOIN mdl_user_lastaccess kbi_ula ON kbi_ula.courseid = kbi_c.id AND kbi_ula.userid = kbi_ra.userid\nWHERE kbi_c.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_ra.roleid = 5\nGROUP BY kbi_c.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"all_learners\":{\"key\":\"all_learners\",\"title\":\"lang::report_field_all_learners_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completed_learners\":{\"key\":\"completed_learners\",\"title\":\"lang::report_field_completed_learners_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"not_completed_learners\":{\"key\":\"not_completed_learners\",\"title\":\"lang::report_field_not_completed_learners_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"not_accessed_learners\":{\"key\":\"not_accessed_learners\",\"title\":\"lang::report_field_not_accessed_learners_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646820),
(61,'kbi_el_engaged_not_engaged_totals_by','lang::report_page_046_title::local_kopere_bi',56,1,'table','light','','','','SELECT kbi_c.id                                              courseid,\n       kbi_c.fullname                                     AS course_name,\n       kbi_u.id                                           AS userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       CASE\n         WHEN MIN(comp.userid) IS NOT NULL AND MIN(kbi_ul.id) IS NOT NULL THEN 1\n         ELSE 0 END                                   as completed,\n       CASE\n         WHEN MIN(comp.userid) IS NULL AND MIN(kbi_ul.id) IS NOT NULL THEN 1\n         ELSE 0 END                                   as not_completed,\n       CASE WHEN MIN(kbi_ul.id) IS NULL THEN 1 ELSE 0 END as not_accessed\nFROM mdl_role_assignments kbi_ra\n       JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_ctx.instanceid\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ra.userid\n       LEFT JOIN (SELECT kbi_cm.course, kbi_cmc.userid\n                  FROM mdl_course_modules kbi_cm\n                         JOIN mdl_course_modules_completion kbi_cmc\n                           ON kbi_cmc.coursemoduleid = kbi_cm.id AND kbi_cmc.completionstate = 1\n                  WHERE kbi_cmc.id > 0\n                  GROUP BY kbi_cm.course, kbi_cmc.userid) comp ON comp.userid = kbi_u.id AND comp.course = kbi_c.id\n       LEFT JOIN mdl_user_lastaccess kbi_ul ON kbi_ul.courseid = kbi_c.id AND kbi_ul.userid = kbi_ra.userid\nWHERE kbi_c.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_ra.roleid = 5\nGROUP BY kbi_c.id, kbi_u.id','1h','none','{\"column\":{\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course_name\":{\"key\":\"course_name\",\"title\":\"lang::report_field_course_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"completed\":{\"key\":\"completed\",\"title\":\"lang::report_field_completed_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"not_completed\":{\"key\":\"not_completed\",\"title\":\"lang::report_field_not_completed_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"not_accessed\":{\"key\":\"not_accessed\",\"title\":\"lang::report_field_not_accessed_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646821),
(62,'el_report110_os_and_browser_stats_by_course','lang::report_page_047_title::local_kopere_bi',57,1,'table','light','','','','SELECT c.id,\n       c.fullname AS course,\n       cc.name    AS category_name,\n       ROUND((SUM(CASE WHEN lit.useragent = \'Firefox\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)   AS firefox,\n       ROUND((SUM(CASE WHEN lit.useragent = \'Chrome\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)   AS chrome,\n       ROUND((SUM(CASE WHEN lit.useragent = \'Safari\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)   AS safari,\n       ROUND((SUM(CASE\n                    WHEN lit.useragent = \'Microsoft Edge\' OR lit.useragent = \'Edge\' THEN lit.timespend\n                    ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)   AS microsoft_edge,\n       ROUND((SUM(CASE WHEN lit.useragent = \'Opera\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)   AS opera,\n       ROUND((SUM(CASE WHEN lit.useragent = \'Mobile browser\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)   AS mobile_browser,\n       ROUND((SUM(CASE\n                    WHEN lit.useragent = \'Unknown Browser\' OR lit.useragent IS NULL THEN lit.timespend\n                    ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)   AS other_browser,\n       ROUND((SUM(CASE WHEN lit.useros LIKE \'Windows%\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)   AS windows,\n       ROUND((SUM(CASE WHEN lit.useros LIKE \'Mac OS%\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)   AS mac_os,\n       ROUND((SUM(CASE WHEN lit.useros = \'Linux\' OR lit.useros = \'Ubuntu\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)   AS linux,\n       ROUND((SUM(CASE\n                    WHEN lit.useros = \'iPhone\' OR lit.useros = \'iPod\' OR lit.useros = \'iPad\' THEN lit.timespend\n                    ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)   AS ios,\n       ROUND((SUM(CASE WHEN lit.useros = \'Android\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)   AS android,\n       ROUND((SUM(CASE WHEN lit.useros = \'Mobile\' THEN lit.timespend ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)   AS mobile,\n       ROUND((SUM(CASE\n                    WHEN lit.useros = \'Unknown OS Platform\' OR lit.useros IS NULL THEN lit.timespend\n                    ELSE 0 END) * 100) / SUM(lit.timespend),\n             2)   AS other_platform\nFROM mdl_local_kopere_bi_tracking lit\n       LEFT JOIN mdl_course c ON c.id = lit.courseid\n       LEFT JOIN mdl_course_categories cc ON cc.id = c.category\nWHERE lit.courseid > 1\n  AND c.id IS NOT NULL\n  AND c.visible = 1\nGROUP BY lit.courseid, c.id, cc.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"category_name\":{\"key\":\"category_name\",\"title\":\"lang::report_field_category_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"firefox\":{\"key\":\"firefox\",\"title\":\"lang::report_field_firefox_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"chrome\":{\"key\":\"chrome\",\"title\":\"lang::report_field_chrome_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"safari\":{\"key\":\"safari\",\"title\":\"lang::report_field_safari_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"microsoft_edge\":{\"key\":\"microsoft_edge\",\"title\":\"lang::report_field_microsoft_edge_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"opera\":{\"key\":\"opera\",\"title\":\"lang::report_field_opera_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"mobile_browser\":{\"key\":\"mobile_browser\",\"title\":\"lang::report_field_mobile_browser_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"other_browser\":{\"key\":\"other_browser\",\"title\":\"lang::report_field_other_browser_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"windows\":{\"key\":\"windows\",\"title\":\"lang::report_field_windows_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"mac_os\":{\"key\":\"mac_os\",\"title\":\"lang::report_field_mac_os_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"linux\":{\"key\":\"linux\",\"title\":\"lang::report_field_linux_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"ios\":{\"key\":\"ios\",\"title\":\"lang::report_field_ios_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"android\":{\"key\":\"android\",\"title\":\"lang::report_field_android_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"mobile\":{\"key\":\"mobile\",\"title\":\"lang::report_field_mobile_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"other_platform\":{\"key\":\"other_platform\",\"title\":\"lang::report_field_other_platform_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646821),
(63,'kbi_el_course_enrollments_with_complet','lang::report_page_048_title::local_kopere_bi',58,1,'table','light','','','','SELECT kbi_c.id,\n       kbi_c.fullname,\n       COUNT(DISTINCT kbi_ue.userid)                                          users,\n       COUNT(DISTINCT kbi_cc.userid)                                       as completed,\n       ROUND(COUNT(DISTINCT kbi_cc.userid) / COUNT(DISTINCT kbi_ue.userid), 2) as progress\nFROM mdl_user_enrolments kbi_ue\n       INNER JOIN mdl_user kbi_u ON kbi_u.id = kbi_ue.userid\n       LEFT JOIN mdl_enrol kbi_e ON kbi_e.id = kbi_ue.enrolid\n       LEFT JOIN mdl_course kbi_c ON kbi_c.id = kbi_e.courseid\n       LEFT JOIN mdl_course_completions kbi_cc ON kbi_cc.course = kbi_e.courseid AND kbi_cc.userid = kbi_ue.userid AND kbi_cc.timecompleted > 0\nWHERE kbi_c.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_ue.status = 0\n  AND kbi_e.status = 0\nGROUP BY kbi_c.id, kbi_c.fullname\nORDER BY kbi_c.fullname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"users\":{\"key\":\"users\",\"title\":\"lang::report_field_users_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completed\":{\"key\":\"completed\",\"title\":\"lang::report_field_completed_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"progress\":{\"key\":\"progress\",\"title\":\"lang::report_field_progress_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646821),
(64,'kbi_el_course_revenue_generation','lang::report_page_049_title::local_kopere_bi',59,1,'table','light','','','','SELECT kbi_ue.id,\n       kbi_c.fullname,\n       kbi_ue.timecreated,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_e.enrol,\n       kbi_e.cost,\n       kbi_e.currency\nFROM mdl_user_enrolments kbi_ue\n       JOIN mdl_enrol kbi_e ON kbi_e.id = kbi_ue.enrolid\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ue.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_e.courseid\nWHERE kbi_e.cost IS NOT NULL\n  AND kbi_c.id = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_ue.status = 0\n  AND kbi_e.status = 0\nORDER BY kbi_ue.timecreated DESC, kbi_c.fullname, kbi_u.lastname, kbi_u.firstname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timecreated\":{\"key\":\"timecreated\",\"title\":\"lang::report_field_timecreated_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"enrol\":{\"key\":\"enrol\",\"title\":\"lang::report_field_enrol_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"cost\":{\"key\":\"cost\",\"title\":\"lang::report_field_cost_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"currency\":{\"key\":\"currency\",\"title\":\"lang::report_field_currency_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646821),
(65,'kbi_el_enrollment_method_details','lang::report_page_050_title::local_kopere_bi',60,1,'table','light','','','','SELECT kbi_ue.id,\n       kbi_ue.timecreated                         AS enrolstart,\n       kbi_ue.timeend                             AS enrolend,\n       kbi_ccc.timeend,\n       kbi_c.enablecompletion,\n       kbi_cc.timecompleted                       AS complete,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_ue.userid,\n       kbi_e.courseid,\n       kbi_e.enrol                                AS enrols,\n       CONCAT(kbi_u1.firstname, \' \', kbi_u1.lastname) AS endrolled_by,\n       kbi_ue.status                              AS enrol_status,\n       kbi_ra.roles                               AS course_roles,\n       kbi_c.fullname                             AS course,\n       kbi_c.startdate                            AS startdate,\n       kbi_c.enddate                              AS enddate\nFROM mdl_user_enrolments kbi_ue\n       JOIN mdl_enrol kbi_e ON kbi_e.id = kbi_ue.enrolid\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ue.userid\n       JOIN (SELECT kbi_ctx.instanceid,\n                    kbi_ra.userid,\n                    MIN(kbi_ra.modifierid)                                 AS modifierid,\n                    GROUP_CONCAT(DISTINCT(kbi_r.shortname) SEPARATOR \', \') AS roles\n             FROM mdl_context kbi_ctx\n                    JOIN mdl_role_assignments kbi_ra ON kbi_ra.contextid = kbi_ctx.id\n                    JOIN mdl_role kbi_r ON kbi_r.id = kbi_ra.roleid\n             WHERE kbi_ctx.contextlevel = 50\n             GROUP BY kbi_ctx.instanceid, kbi_ra.userid) ra ON kbi_ra.instanceid = kbi_e.courseid AND kbi_ra.userid = kbi_ue.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_e.courseid\n       LEFT JOIN mdl_user kbi_u1 ON kbi_u1.id = kbi_ra.modifierid\n       LEFT JOIN mdl_course_completions kbi_cc ON kbi_cc.course = kbi_e.courseid AND kbi_cc.userid = kbi_ue.userid\n       LEFT JOIN mdl_course_completion_criteria kbi_ccc ON kbi_ccc.course = kbi_e.courseid AND kbi_ccc.criteriatype = 2\nWHERE kbi_ue.id > 0\n  AND kbi_c.id = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_ue.status = 0\n  AND kbi_e.status = 0\nORDER BY kbi_c.fullname, kbi_u.lastname, kbi_u.firstname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"enrolstart\":{\"key\":\"enrolstart\",\"title\":\"lang::report_field_enrolstart_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"enrolend\":{\"key\":\"enrolend\",\"title\":\"lang::report_field_enrolend_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timeend\":{\"key\":\"timeend\",\"title\":\"lang::report_field_timeend_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"enablecompletion\":{\"key\":\"enablecompletion\",\"title\":\"lang::report_field_enablecompletion_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"complete\":{\"key\":\"complete\",\"title\":\"lang::report_field_complete_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"enrols\":{\"key\":\"enrols\",\"title\":\"lang::report_field_enrols_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"endrolled_by\":{\"key\":\"endrolled_by\",\"title\":\"lang::report_field_endrolled_by_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"enrol_status\":{\"key\":\"enrol_status\",\"title\":\"lang::report_field_enrol_status_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"course_roles\":{\"key\":\"course_roles\",\"title\":\"lang::report_field_course_roles_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"startdate\":{\"key\":\"startdate\",\"title\":\"lang::report_field_startdate_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"enddate\":{\"key\":\"enddate\",\"title\":\"lang::report_field_enddate_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"}}}',1780646821),
(66,'kbi_el_enrollment_method_summary','lang::report_page_051_title::local_kopere_bi',61,1,'table','light','','','','SELECT MAX(kbi_e.id)                  AS id,\n       kbi_e.enrol                    as enrol,\n       COUNT(DISTINCT kbi_e.courseid) as courses,\n       COUNT(kbi_ue.userid)           as users,\n       COUNT(DISTINCT kbi_ue.userid)  as uniusers\nFROM mdl_enrol kbi_e\n       LEFT JOIN mdl_user_enrolments kbi_ue ON kbi_ue.enrolid = kbi_e.id\nWHERE kbi_e.id > 0\n  AND kbi_e.status = 0\n  AND kbi_ue.status = 0\nGROUP BY kbi_e.enrol\nORDER BY users DESC, kbi_e.enrol','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"enrol\":{\"key\":\"enrol\",\"title\":\"lang::report_field_enrol_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"courses\":{\"key\":\"courses\",\"title\":\"lang::report_field_courses_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"users\":{\"key\":\"users\",\"title\":\"lang::report_field_users_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"uniusers\":{\"key\":\"uniusers\",\"title\":\"lang::report_field_uniusers_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646821),
(67,'kbi_el_pending_grading_items','lang::report_page_052_title::local_kopere_bi',62,1,'table','light','','','','SELECT kbi_waiting.*\nFROM (\n       SELECT CONCAT(\'assign-\', kbi_s.id) AS id,\n              kbi_c.id                   AS courseid,\n              kbi_c.fullname             AS course,\n              kbi_cm.id                  AS cmid,\n              kbi_a.id                   AS activityid,\n              kbi_a.name                 AS activity_name,\n              \'assign\'                   AS activity_type,\n              kbi_u.id                   AS userid,\n              kbi_u.firstname,\n              kbi_u.lastname,\n              kbi_u.email,\n              kbi_a.duedate,\n              kbi_s.timemodified         AS submitted_at,\n              kbi_g.timemodified         AS graded_at,\n              NULL                       AS slot,\n              NULL                       AS attemptid,\n              NULL                       AS question_name,\n              kbi_teachers.teacher_names AS teachers\n       FROM mdl_assign_submission kbi_s\n              JOIN mdl_assign kbi_a ON kbi_a.id = kbi_s.assignment\n              JOIN mdl_course kbi_c ON kbi_c.id = kbi_a.course\n              JOIN mdl_modules kbi_m ON kbi_m.name = \'assign\'\n              JOIN mdl_course_modules kbi_cm ON kbi_cm.course = kbi_c.id\n                    AND kbi_cm.module = kbi_m.id\n                    AND kbi_cm.instance = kbi_a.id\n              JOIN mdl_user kbi_u ON kbi_u.id = kbi_s.userid\n              JOIN mdl_enrol kbi_e ON kbi_e.courseid = kbi_c.id\n              JOIN mdl_user_enrolments kbi_ue ON kbi_ue.enrolid = kbi_e.id AND kbi_ue.userid = kbi_u.id\n              LEFT JOIN mdl_assign_grades kbi_g ON kbi_g.assignment = kbi_s.assignment\n                    AND kbi_g.userid = kbi_s.userid\n                    AND kbi_g.attemptnumber = kbi_s.attemptnumber\n              LEFT JOIN (\n                    SELECT kbi_ctx.instanceid AS courseid,\n                           GROUP_CONCAT(DISTINCT CONCAT(kbi_t.firstname, \' \', kbi_t.lastname) ORDER BY kbi_t.lastname, kbi_t.firstname SEPARATOR \', \') AS teacher_names\n                    FROM mdl_role_assignments kbi_ra\n                           JOIN mdl_role kbi_r ON kbi_r.id = kbi_ra.roleid AND kbi_r.shortname IN (\'editingteacher\', \'teacher\')\n                           JOIN mdl_user kbi_t ON kbi_t.id = kbi_ra.userid\n                           JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\n                    WHERE kbi_t.deleted = 0\n                      AND kbi_t.suspended = 0\n                    GROUP BY kbi_ctx.instanceid\n              ) kbi_teachers ON kbi_teachers.courseid = kbi_c.id\n       WHERE kbi_s.latest = 1\n         AND kbi_s.status = \'submitted\'\n         AND (kbi_g.id IS NULL OR kbi_g.grade IS NULL OR kbi_g.grade < 0 OR kbi_s.timemodified > COALESCE(kbi_g.timemodified, 0))\n         AND kbi_c.visible = 1\n         AND kbi_cm.visible = 1\n         AND kbi_e.status = 0\n         AND kbi_ue.status = 0\n         AND kbi_u.deleted = 0\n         AND kbi_u.suspended = 0\n         AND kbi_u.username <> \'guest\'\n\n       UNION ALL\n\n       SELECT CONCAT(\'quiz-\', kbi_qa.id, \'-\', kbi_qatt.id) AS id,\n              kbi_c.id                                    AS courseid,\n              kbi_c.fullname                              AS course,\n              kbi_cm.id                                   AS cmid,\n              kbi_qz.id                                   AS activityid,\n              kbi_qz.name                                 AS activity_name,\n              \'quiz\'                                      AS activity_type,\n              kbi_u.id                                    AS userid,\n              kbi_u.firstname,\n              kbi_u.lastname,\n              kbi_u.email,\n              kbi_qz.timeclose                            AS duedate,\n              kbi_qa.timefinish                           AS submitted_at,\n              NULL                                        AS graded_at,\n              kbi_qatt.slot                               AS slot,\n              kbi_qa.id                                   AS attemptid,\n              kbi_q.name                                  AS question_name,\n              kbi_teachers.teacher_names                  AS teachers\n       FROM mdl_quiz_attempts kbi_qa\n              JOIN mdl_quiz kbi_qz ON kbi_qz.id = kbi_qa.quiz\n              JOIN mdl_course kbi_c ON kbi_c.id = kbi_qz.course\n              JOIN mdl_user kbi_u ON kbi_u.id = kbi_qa.userid\n              JOIN mdl_question_attempts kbi_qatt ON kbi_qatt.questionusageid = kbi_qa.uniqueid\n              JOIN mdl_question kbi_q ON kbi_q.id = kbi_qatt.questionid\n              JOIN mdl_question_attempt_steps kbi_qas ON kbi_qas.questionattemptid = kbi_qatt.id\n                    AND kbi_qas.sequencenumber = (\n                        SELECT MAX(kbi_qas2.sequencenumber)\n                        FROM mdl_question_attempt_steps kbi_qas2\n                        WHERE kbi_qas2.questionattemptid = kbi_qatt.id\n                    )\n              JOIN mdl_modules kbi_m ON kbi_m.name = \'quiz\'\n              JOIN mdl_course_modules kbi_cm ON kbi_cm.course = kbi_c.id\n                    AND kbi_cm.module = kbi_m.id\n                    AND kbi_cm.instance = kbi_qz.id\n              JOIN mdl_enrol kbi_e ON kbi_e.courseid = kbi_c.id\n              JOIN mdl_user_enrolments kbi_ue ON kbi_ue.enrolid = kbi_e.id AND kbi_ue.userid = kbi_u.id\n              LEFT JOIN (\n                    SELECT kbi_ctx.instanceid AS courseid,\n                           GROUP_CONCAT(DISTINCT CONCAT(kbi_t.firstname, \' \', kbi_t.lastname) ORDER BY kbi_t.lastname, kbi_t.firstname SEPARATOR \', \') AS teacher_names\n                    FROM mdl_role_assignments kbi_ra\n                           JOIN mdl_role kbi_r ON kbi_r.id = kbi_ra.roleid AND kbi_r.shortname IN (\'editingteacher\', \'teacher\')\n                           JOIN mdl_user kbi_t ON kbi_t.id = kbi_ra.userid\n                           JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\n                    WHERE kbi_t.deleted = 0\n                      AND kbi_t.suspended = 0\n                    GROUP BY kbi_ctx.instanceid\n              ) kbi_teachers ON kbi_teachers.courseid = kbi_c.id\n       WHERE kbi_qa.preview = 0\n         AND kbi_qa.state = \'finished\'\n         AND kbi_qas.state = \'needsgrading\'\n         AND kbi_c.visible = 1\n         AND kbi_cm.visible = 1\n         AND kbi_e.status = 0\n         AND kbi_ue.status = 0\n         AND kbi_u.deleted = 0\n         AND kbi_u.suspended = 0\n         AND kbi_u.username <> \'guest\'\n) kbi_waiting\nORDER BY kbi_waiting.course, kbi_waiting.activity_name, kbi_waiting.submitted_at DESC','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"string\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"cmid\":{\"key\":\"cmid\",\"title\":\"lang::report_field_cmid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"activityid\":{\"key\":\"activityid\",\"title\":\"lang::report_field_activityid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"activity_name\":{\"key\":\"activity_name\",\"title\":\"lang::report_field_activity_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"activity_type\":{\"key\":\"activity_type\",\"title\":\"lang::report_field_activity_type_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"duedate\":{\"key\":\"duedate\",\"title\":\"lang::report_field_duedate_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"submitted_at\":{\"key\":\"submitted_at\",\"title\":\"lang::report_field_submitted_at_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"graded_at\":{\"key\":\"graded_at\",\"title\":\"lang::report_field_graded_at_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"slot\":{\"key\":\"slot\",\"title\":\"lang::report_field_slot_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"attemptid\":{\"key\":\"attemptid\",\"title\":\"lang::report_field_attemptid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"question_name\":{\"key\":\"question_name\",\"title\":\"lang::report_field_question_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teachers\":{\"key\":\"teachers\",\"title\":\"lang::report_field_teachers_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646821),
(68,'kbi_el_course_gradebook_by_category','lang::report_page_053_title::local_kopere_bi',63,1,'table','light','','','','SELECT kbi_u.id,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.idnumber,\n       kbi_c.id AS courseid,\n       kbi_c.fullname\nFROM mdl_course kbi_c\n       JOIN mdl_context kbi_con ON kbi_con.contextlevel = 50 AND kbi_con.instanceid = kbi_c.id\n       JOIN mdl_role_assignments kbi_ra ON kbi_ra.contextid = kbi_con.id\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ra.userid\n       LEFT JOIN (SELECT t.userid, t.courseid\n                  FROM (SELECT kbi_gg.itemid, kbi_gg.userid, kbi_gi.courseid\n                        FROM mdl_grade_grades kbi_gg\n                               JOIN mdl_grade_items kbi_gi ON kbi_gi.id = kbi_gg.itemid\n                        WHERE kbi_gg.itemid IN ()) t\n                  GROUP BY t.userid, t.courseid) gt ON gt.userid = kbi_u.id AND gt.courseid = kbi_c.id\nWHERE kbi_c.id > 0\n  AND kbi_c.visible = 1\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_ra.roleid = 5\nGROUP BY kbi_u.id, kbi_c.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"idnumber\":{\"key\":\"idnumber\",\"title\":\"lang::report_field_idnumber_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{fullname}}}<\\/a>\"}}}',1780646821),
(69,'kbi_el_gradebook_overview','lang::report_page_054_title::local_kopere_bi',64,1,'table','light','','','','SELECT kbi_c.id                                AS courseid,\n       kbi_c.fullname,\n       kbi_u.id                                AS userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_m.name,\n       kbi_gi.itemname                         AS activity,\n       kbi_cm.id                               as cmid,\n       0                                   AS slot,\n       0                                   AS attempt,\n       ROUND((CASE\n                WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                ELSE kbi_g.finalgrade END), 0) AS grade,\n       kbi_g.finalgrade                        AS finalgrade,\n       kbi_g.timemodified                      AS graded,\n       kbi_c.startdate                         AS startdate,\n       kbi_c.enddate                           AS enddate\nFROM mdl_course kbi_c\n       JOIN (SELECT kbi_con.instanceid, kbi_ra.userid\n             FROM mdl_context kbi_con\n                    JOIN mdl_role_assignments kbi_ra ON kbi_ra.contextid = kbi_con.id\n             WHERE kbi_con.contextlevel = 50\n               AND kbi_ra.roleid = 5\n             GROUP BY kbi_con.instanceid, kbi_ra.userid) student ON student.instanceid = kbi_c.id\n       JOIN mdl_user kbi_u ON kbi_u.id = student.userid\n       JOIN mdl_course_modules kbi_cm ON kbi_cm.course = kbi_c.id\n       JOIN mdl_modules kbi_m ON kbi_m.id = kbi_cm.module\n       JOIN mdl_grade_items kbi_gi ON kbi_gi.itemtype = \'mod\' AND kbi_gi.itemmodule = kbi_m.name AND kbi_gi.iteminstance = kbi_cm.instance\n       LEFT JOIN mdl_grade_grades kbi_g ON kbi_g.userid = kbi_u.id AND kbi_g.itemid = kbi_gi.id\nWHERE kbi_c.id > 0\n  AND kbi_c.id = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_cm.visible = 1','1h','none','{\"column\":{\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{fullname}}}<\\/a>\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"name\":{\"key\":\"name\",\"title\":\"lang::report_field_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"activity\":{\"key\":\"activity\",\"title\":\"lang::report_field_activity_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"cmid\":{\"key\":\"cmid\",\"title\":\"lang::report_field_cmid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"slot\":{\"key\":\"slot\",\"title\":\"lang::report_field_slot_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"attempt\":{\"key\":\"attempt\",\"title\":\"lang::report_field_attempt_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"finalgrade\":{\"key\":\"finalgrade\",\"title\":\"lang::report_field_finalgrade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"graded\":{\"key\":\"graded\",\"title\":\"lang::report_field_graded_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"startdate\":{\"key\":\"startdate\",\"title\":\"lang::report_field_startdate_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"enddate\":{\"key\":\"enddate\",\"title\":\"lang::report_field_enddate_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"}}}',1780646821),
(70,'kbi_el_activity_completion_stats','lang::report_page_055_title::local_kopere_bi',65,1,'table','light','','','','SELECT max(kbi_ue.id)                                              AS id,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       MAX(kbi_ue.timecreated)                                     as enrolled,\n       kbi_c.id                                                    AS courseid,\n       kbi_u.id                                                    AS userid,\n       kbi_c.fullname,\n       ROUND(AVG(CASE\n                   WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                   ELSE kbi_g.finalgrade END), 0)                  AS grade,\n       MAX(m.modules)                                          AS modules,\n       MAX(kbi_cc.timecompleted)                                   AS timecompleted,\n       MAX(cmc.completed)                                      as modules_completed,\n       round(((MAX(cmc.completed) / MAX(m.modules)) * 100), 0) as progress\nFROM mdl_user_enrolments kbi_ue\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ue.userid\n       JOIN mdl_enrol kbi_e ON kbi_e.id = kbi_ue.enrolid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_e.courseid\n       LEFT JOIN mdl_cohort_members kbi_cm ON kbi_cm.userid = kbi_u.id\n       LEFT JOIN mdl_grade_items kbi_gi ON kbi_gi.courseid = kbi_c.id AND kbi_gi.itemtype = \'course\'\n       LEFT JOIN mdl_grade_grades kbi_g ON kbi_gi.id = kbi_g.itemid AND kbi_g.userid = kbi_u.id\n       LEFT JOIN mdl_course_completions kbi_cc ON kbi_cc.timecompleted > 0 AND kbi_cc.course = kbi_e.courseid and kbi_cc.userid = kbi_ue.userid\n       LEFT JOIN (SELECT course, count(id) as modules\n                  FROM mdl_course_modules\n                  WHERE visible = 1\n                    AND completion > 0\n                    AND instance > 0\n                  GROUP BY course) as m ON m.course = kbi_c.id\n       LEFT JOIN (SELECT kbi_cm.course, kbi_x.userid, COUNT(DISTINCT kbi_x.id) as completed\n                  FROM mdl_course_modules kbi_cm, mdl_course_modules_completion kbi_x\n                  WHERE kbi_x.coursemoduleid = kbi_cm.id\n                    AND kbi_cm.visible = 1\n                    AND kbi_x.completionstate IN (1, 2)\n                  GROUP BY kbi_cm.course, kbi_x.userid) as cmc ON cmc.course = kbi_c.id AND cmc.userid = kbi_ue.userid\nWHERE kbi_ue.id > 0\n  AND kbi_c.id = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_ue.status = 0\n  AND kbi_e.status = 0\nGROUP BY kbi_u.id, kbi_c.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"enrolled\":{\"key\":\"enrolled\",\"title\":\"lang::report_field_enrolled_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{fullname}}}<\\/a>\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"modules\":{\"key\":\"modules\",\"title\":\"lang::report_field_modules_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timecompleted\":{\"key\":\"timecompleted\",\"title\":\"lang::report_field_timecompleted_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"modules_completed\":{\"key\":\"modules_completed\",\"title\":\"lang::report_field_modules_completed_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"progress\":{\"key\":\"progress\",\"title\":\"lang::report_field_progress_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646821),
(71,'kbi_el_activity_grades_with_dates','lang::report_page_056_title::local_kopere_bi',66,1,'table','light','','','','SELECT DISTINCT kbi_gi.itemname                                                 AS activity_name,\n                kbi_g.userid,\n                kbi_u.username,\n                kbi_u.firstname,\n                kbi_u.lastname,\n                kbi_c.fullname,\n                kbi_cc1.name                                                    AS course_category,\n                kbi_c.shortname,\n                tcrs.teachers                                               as courseteachers,\n                kbi_g.timemodified                                              AS graduated,\n                ROUND((CASE\n                         WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                         ELSE kbi_g.finalgrade END), 0)                         AS grade,\n                ROUND((CASE\n                         WHEN (kbi_g.rawgrademax - kbi_g.rawgrademin) > 0\n                                 THEN ((kbi_g.finalgrade - kbi_g.rawgrademin) / (kbi_g.rawgrademax - kbi_g.rawgrademin)) * 100\n                         ELSE kbi_g.finalgrade END), 0)                         AS grade_percent,\n                kbi_wg.firstname                                                AS who_graded_first_name,\n                kbi_wg.lastname                                                 AS who_graded_last_name,\n                kbi_gi.itemtype,\n                CASE WHEN kbi_m.name = \'assign\' THEN kbi_sg.timemodified ELSE 0 END AS need_grade_assignment,\n                kbi_ul.timeaccess                                               AS course_lastaccess\nFROM mdl_course kbi_c\n       LEFT JOIN mdl_course_categories kbi_cc1 ON kbi_cc1.id = kbi_c.category\n       LEFT JOIN (SELECT kbi_cx.instanceid, GROUP_CONCAT(CONCAT(kbi_u.firstname, \' \', kbi_u.lastname) SEPARATOR \', \') as teachers\n                  FROM mdl_context kbi_cx\n                         JOIN mdl_role_assignments kbi_ra ON kbi_ra.contextid = kbi_cx.id AND\n                                                         kbi_ra.roleid IN (1, 2, 3, 4)\n                         JOIN mdl_user kbi_u ON kbi_u.id = kbi_ra.userid\n                  WHERE kbi_cx.contextlevel = 50\n                  GROUP BY kbi_cx.instanceid) tcrs ON tcrs.instanceid = kbi_c.id\n       JOIN mdl_context kbi_ctx ON kbi_ctx.instanceid = kbi_c.id AND kbi_ctx.contextlevel = 50\n       JOIN mdl_role_assignments kbi_ra ON kbi_ra.contextid = kbi_ctx.id\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ra.userid\n       LEFT JOIN mdl_grade_items kbi_gi ON kbi_gi.courseid = kbi_c.id AND (kbi_gi.itemtype = \'mod\' OR kbi_gi.itemtype = \'course\')\n       LEFT JOIN mdl_grade_grades kbi_g ON kbi_gi.id = kbi_g.itemid AND kbi_g.userid = kbi_u.id\n       LEFT JOIN mdl_user kbi_wg ON kbi_wg.id = kbi_g.usermodified\n       LEFT JOIN mdl_modules kbi_m ON kbi_m.name = kbi_gi.itemmodule\n       LEFT JOIN mdl_course_modules kbi_cm ON kbi_cm.instance = kbi_gi.iteminstance AND kbi_cm.module = kbi_m.id\n       LEFT JOIN mdl_course_modules_completion kbi_cmc ON kbi_cmc.coursemoduleid = kbi_cm.id AND kbi_cmc.userid = kbi_u.id\n       LEFT JOIN mdl_assign_submission kbi_ass ON kbi_ass.userid = kbi_u.id AND kbi_ass.assignment = kbi_cm.instance AND\n                                              kbi_ass.status = \'submitted\' AND kbi_ass.latest = 1\n       LEFT JOIN mdl_assign_grades kbi_sg ON kbi_ass.assignment = kbi_sg.assignment AND kbi_ass.userid = kbi_sg.userid AND\n                                         kbi_sg.attemptnumber = kbi_ass.attemptnumber AND\n                                         (kbi_ass.timemodified >= kbi_sg.timemodified OR kbi_sg.timemodified IS NULL OR\n                                          kbi_sg.grade IS NULL)\n       LEFT JOIN mdl_user_lastaccess kbi_ul ON kbi_ul.courseid = kbi_c.id AND kbi_ul.userid = kbi_u.id\nWHERE kbi_c.id > 0\n  AND kbi_c.id = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\nORDER BY kbi_c.fullname, kbi_gi.itemname, kbi_u.lastname, kbi_u.firstname','1h','none','{\"column\":{\"activity_name\":{\"key\":\"activity_name\",\"title\":\"lang::report_field_activity_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"username\":{\"key\":\"username\",\"title\":\"lang::report_field_username_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"course_category\":{\"key\":\"course_category\",\"title\":\"lang::report_field_course_category_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"courseteachers\":{\"key\":\"courseteachers\",\"title\":\"lang::report_field_courseteachers_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"graduated\":{\"key\":\"graduated\",\"title\":\"lang::report_field_graduated_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade_percent\":{\"key\":\"grade_percent\",\"title\":\"lang::report_field_grade_percent_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"who_graded_first_name\":{\"key\":\"who_graded_first_name\",\"title\":\"lang::report_field_who_graded_first_name_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"who_graded_last_name\":{\"key\":\"who_graded_last_name\",\"title\":\"lang::report_field_who_graded_last_name_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"itemtype\":{\"key\":\"itemtype\",\"title\":\"lang::report_field_itemtype_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"need_grade_assignment\":{\"key\":\"need_grade_assignment\",\"title\":\"lang::report_field_need_grade_assignment_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course_lastaccess\":{\"key\":\"course_lastaccess\",\"title\":\"lang::report_field_course_lastaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646821),
(72,'kbi_el_activity_stats_summary','lang::report_page_057_title::local_kopere_bi',67,1,'table','light','','','','SELECT kbi_cm.id, kbi_m.name AS moduletype, kbi_cm.added, kbi_cm.completion, kbi_c.fullname, cmc.num_compl AS completed, grd.grade\nFROM mdl_course_modules kbi_cm\n       JOIN mdl_modules kbi_m ON kbi_m.id = kbi_cm.module\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_cm.course\n       LEFT JOIN (SELECT coursemoduleid, COUNT(id) AS num_compl\n                  FROM mdl_course_modules_completion\n                  WHERE id > 0\n                    AND completionstate IN (1, 2)\n                  GROUP BY coursemoduleid) cmc ON cmc.coursemoduleid = kbi_cm.id\n       LEFT JOIN (SELECT kbi_gi.iteminstance,\n                         kbi_gi.itemmodule,\n                         ROUND(AVG(CASE\n                                     WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                                     ELSE kbi_g.finalgrade END), 0) AS grade\n                  FROM mdl_grade_items kbi_gi\n                         JOIN mdl_grade_grades kbi_g ON kbi_g.itemid = kbi_gi.id AND kbi_g.finalgrade IS NOT NULL\n                  WHERE kbi_gi.itemtype = \'mod\'\n                  GROUP BY kbi_gi.iteminstance, kbi_gi.itemmodule) grd\n         ON grd.itemmodule = kbi_m.name AND grd.iteminstance = kbi_cm.instance\nWHERE kbi_cm.id > 0\n  AND kbi_cm.visible = 1\n  AND kbi_cm.course = :courseid','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"moduletype\":{\"key\":\"moduletype\",\"title\":\"lang::report_field_moduletype_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"added\":{\"key\":\"added\",\"title\":\"lang::report_field_added_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"completion\":{\"key\":\"completion\",\"title\":\"lang::report_field_completion_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"completed\":{\"key\":\"completed\",\"title\":\"lang::report_field_completed_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646821),
(73,'kbi_el_activity_status_detail','lang::report_page_058_title::local_kopere_bi',68,1,'table','light','','','','SELECT ue.userid,\n       kbi_u.email,\n       kbi_u.phone1,\n       kbi_u.phone2,\n       kbi_u.institution,\n       kbi_u.department,\n       kbi_u.address,\n       kbi_u.city,\n       kbi_u.country,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_c.fullname,\n       kbi_g.timemodified                        as graduated,\n       kbi_cm.added                              as created,\n       ROUND((CASE\n                WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                ELSE kbi_g.finalgrade END), 0)   AS grade,\n       ROUND((CASE\n                WHEN kbi_g_c.rawgrademax > 0 THEN (kbi_g_c.finalgrade / kbi_g_c.rawgrademax) * 100\n                ELSE kbi_g_c.finalgrade END), 0) AS grade_course,\n       kbi_gi.gradepass,\n       kbi_g.rawgrademax,\n       kbi_g.finalgrade,\n       kbi_cm.completion,\n       kbi_cmc.completionstate,\n       kbi_m.name                                AS module_name,\n       ta.tags,\n       ue.enrol_status,\n       ue.timeend\nFROM (SELECT MIN(kbi_ue1.id) AS id, kbi_ue1.userid, kbi_e1.courseid, MIN(kbi_ue1.status) AS enrol_status, MIN(kbi_ue1.timeend) AS timeend\n      FROM mdl_user_enrolments kbi_ue1\n             JOIN mdl_enrol kbi_e1 ON kbi_e1.id = kbi_ue1.enrolid\n      GROUP BY kbi_ue1.userid, kbi_e1.courseid) ue\n       JOIN mdl_user kbi_u ON kbi_u.id = ue.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = ue.courseid\n       JOIN mdl_course_modules kbi_cm ON kbi_cm.course = kbi_c.id AND kbi_cm.instance > 0\n       JOIN mdl_modules kbi_m ON kbi_m.id = kbi_cm.module\n       LEFT JOIN mdl_grade_items kbi_gi\n         ON kbi_gi.itemtype = \'mod\' AND kbi_gi.iteminstance = kbi_cm.instance AND kbi_gi.itemmodule = kbi_m.name AND kbi_gi.gradetype = 1\n       LEFT JOIN mdl_grade_grades kbi_g ON kbi_g.itemid = kbi_gi.id AND kbi_g.userid = kbi_u.id\n       LEFT JOIN (SELECT kbi_qa.quiz,\n                         kbi_qa.userid,\n                         MAX(kbi_qa.attempt)      AS num_of_attempts,\n                         MIN(kbi_qa.timemodified) AS first_completed_date\n                  FROM mdl_quiz_attempts kbi_qa\n                         JOIN mdl_quiz kbi_q ON kbi_q.id = kbi_qa.quiz AND kbi_q.course = :courseid\n                  GROUP BY kbi_qa.quiz, kbi_qa.userid) qat ON qat.userid = kbi_u.id AND kbi_m.name = \'quiz\' AND qat.quiz = kbi_cm.instance\n       LEFT JOIN (SELECT kbi_asbm1.assignment,\n                         kbi_asbm1.userid,\n                         COUNT(*)                AS num_of_attempts,\n                         MIN(kbi_asbm1.timemodified) AS first_completed_date\n                  FROM mdl_assign_submission kbi_asbm1\n                         JOIN mdl_assign kbi_a ON kbi_a.id = kbi_asbm1.assignment AND kbi_a.course = :courseid\n                  GROUP BY kbi_asbm1.assignment, kbi_asbm1.userid) asbm\n         ON asbm.userid = kbi_u.id AND kbi_m.name = \'assign\' AND asbm.assignment = kbi_cm.instance\n       LEFT JOIN mdl_course_modules_completion kbi_cmc ON kbi_cmc.coursemoduleid = kbi_cm.id AND kbi_cmc.userid = kbi_u.id\n       LEFT JOIN (SELECT kbi_i.itemid, GROUP_CONCAT(DISTINCT kbi_t.rawname) AS tags\n                  FROM mdl_tag_instance kbi_i, mdl_tag kbi_t\n                  WHERE kbi_t.id = kbi_i.tagid\n                    AND kbi_i.itemtype = \'course_modules\'\n                  GROUP BY kbi_i.itemid) ta ON ta.itemid = kbi_cm.id\n       LEFT JOIN mdl_grade_items kbi_gi_c ON kbi_gi_c.itemtype = \'course\' AND kbi_gi_c.courseid = kbi_c.id\n       LEFT JOIN mdl_grade_grades kbi_g_c ON kbi_g_c.itemid = kbi_gi_c.id AND kbi_g_c.userid = kbi_u.id\nWHERE ue.id > 0\n  AND kbi_cm.course = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_cm.visible = 1','1h','none','{\"column\":{\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"phone1\":{\"key\":\"phone1\",\"title\":\"lang::report_field_phone1_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone1}}}\\\" target=\\\"_blank\\\">{{{phone1}}}<\\/a>\"},\"phone2\":{\"key\":\"phone2\",\"title\":\"lang::report_field_phone2_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone2}}}\\\" target=\\\"_blank\\\">{{{phone2}}}<\\/a>\"},\"institution\":{\"key\":\"institution\",\"title\":\"lang::report_field_institution_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"department\":{\"key\":\"department\",\"title\":\"lang::report_field_department_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"address\":{\"key\":\"address\",\"title\":\"lang::report_field_address_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"city\":{\"key\":\"city\",\"title\":\"lang::report_field_city_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"country\":{\"key\":\"country\",\"title\":\"lang::report_field_country_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"graduated\":{\"key\":\"graduated\",\"title\":\"lang::report_field_graduated_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"created\":{\"key\":\"created\",\"title\":\"lang::report_field_created_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade_course\":{\"key\":\"grade_course\",\"title\":\"lang::report_field_grade_course_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"gradepass\":{\"key\":\"gradepass\",\"title\":\"lang::report_field_gradepass_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"rawgrademax\":{\"key\":\"rawgrademax\",\"title\":\"lang::report_field_rawgrademax_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"finalgrade\":{\"key\":\"finalgrade\",\"title\":\"lang::report_field_finalgrade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completion\":{\"key\":\"completion\",\"title\":\"lang::report_field_completion_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"completionstate\":{\"key\":\"completionstate\",\"title\":\"lang::report_field_completionstate_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"module_name\":{\"key\":\"module_name\",\"title\":\"lang::report_field_module_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"tags\":{\"key\":\"tags\",\"title\":\"lang::report_field_tags_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"enrol_status\":{\"key\":\"enrol_status\",\"title\":\"lang::report_field_enrol_status_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"timeend\":{\"key\":\"timeend\",\"title\":\"lang::report_field_timeend_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"}}}',1780646821),
(74,'kbi_el_activity_status_detail_simple','lang::report_page_059_title::local_kopere_bi',69,1,'table','light','','','','SELECT kbi_ue.userid,\n       kbi_u.email,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_c.fullname,\n       kbi_g.timemodified                                        as graduated,\n       kbi_cm.added                                              as created,\n       ROUND((CASE\n                WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                ELSE kbi_g.finalgrade END), 0)                   AS grade,\n       ROUND((CASE\n                WHEN kbi_g_c.rawgrademax > 0 THEN (kbi_g_c.finalgrade / kbi_g_c.rawgrademax) * 100\n                ELSE kbi_g_c.finalgrade END), 0)                 AS grade_course,\n       kbi_gi.gradepass,\n       kbi_g.rawgrademax,\n       kbi_g.finalgrade,\n       kbi_cm.completion,\n       kbi_cmc.completionstate,\n       kbi_m.name                                                AS module_name,\n       kbi_gi.itemname,\n       kbi_ue.status                                             AS enrol_status,\n       kbi_ue.timeend,\n       CASE\n         WHEN kbi_ue.id > 0 AND kbi_cmc.completionstate IN (1, 2)\n                 THEN kbi_cmc.timemodified\n         ELSE NULL END                                       AS completed_date\nFROM (SELECT MAX(kbi_ue.id) AS id, MIN(kbi_ue.status) AS status, MAX(kbi_ue.timeend) AS timeend, kbi_ue.userid, kbi_e.courseid\n      FROM mdl_user_enrolments kbi_ue\n             JOIN mdl_enrol kbi_e ON kbi_e.id = kbi_ue.enrolid\n      GROUP BY kbi_e.courseid, kbi_ue.userid) ue\n       JOIN mdl_course_modules kbi_cm ON kbi_cm.course = kbi_ue.courseid\n       JOIN mdl_modules kbi_m ON kbi_m.id = kbi_cm.module\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ue.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_ue.courseid\n       JOIN mdl_grade_items kbi_gi_c ON kbi_gi_c.itemtype = \'course\' AND kbi_gi_c.courseid = kbi_ue.courseid\n       LEFT JOIN mdl_grade_items kbi_gi ON kbi_gi.itemtype = \'mod\' AND kbi_gi.iteminstance = kbi_cm.instance AND kbi_gi.itemmodule = kbi_m.name\n       LEFT JOIN mdl_grade_grades kbi_g ON kbi_g.itemid = kbi_gi.id AND kbi_g.userid = kbi_ue.userid\n       LEFT JOIN mdl_course_modules_completion kbi_cmc ON kbi_cmc.coursemoduleid = kbi_cm.id AND kbi_cmc.userid = kbi_ue.userid\n       LEFT JOIN mdl_grade_grades kbi_g_c ON kbi_g_c.itemid = kbi_gi_c.id AND kbi_g_c.userid = kbi_ue.userid\nWHERE kbi_ue.id > 0\n  AND kbi_cm.course = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_cm.visible = 1','1h','none','{\"column\":{\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"graduated\":{\"key\":\"graduated\",\"title\":\"lang::report_field_graduated_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"created\":{\"key\":\"created\",\"title\":\"lang::report_field_created_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade_course\":{\"key\":\"grade_course\",\"title\":\"lang::report_field_grade_course_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"gradepass\":{\"key\":\"gradepass\",\"title\":\"lang::report_field_gradepass_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"rawgrademax\":{\"key\":\"rawgrademax\",\"title\":\"lang::report_field_rawgrademax_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"finalgrade\":{\"key\":\"finalgrade\",\"title\":\"lang::report_field_finalgrade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completion\":{\"key\":\"completion\",\"title\":\"lang::report_field_completion_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"completionstate\":{\"key\":\"completionstate\",\"title\":\"lang::report_field_completionstate_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"module_name\":{\"key\":\"module_name\",\"title\":\"lang::report_field_module_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"itemname\":{\"key\":\"itemname\",\"title\":\"lang::report_field_itemname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"enrol_status\":{\"key\":\"enrol_status\",\"title\":\"lang::report_field_enrol_status_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"timeend\":{\"key\":\"timeend\",\"title\":\"lang::report_field_timeend_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"completed_date\":{\"key\":\"completed_date\",\"title\":\"lang::report_field_completed_date_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"}}}',1780646821),
(75,'kbi_el_activity_submission_progress_c','lang::report_page_060_title::local_kopere_bi',70,1,'table','light','','','','SELECT kbi_u.username,\n       kbi_u.idnumber,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_c.shortname,\n       kbi_c.fullname,\n       kbi_m.name                               AS mod_name,\n       kbi_cm.id                                AS instance_id,\n       kbi_ul.timeaccess,\n       kbi_ue.status,\n       kbi_ue.timeend,\n       GREATEST(\n         COALESCE(kbi_ass.submitted, 0), COALESCE(f.posted, 0), COALESCE(q.started, 0), COALESCE(gl.submitted, 0),\n         COALESCE(ch.submitted, 0)\n           )                                AS overal_submission_date,\n       GREATEST(\n         COALESCE(kbi_ass.graded, 0), COALESCE(q.graded, 0)\n           )                                AS overal_submission_graded,\n       GREATEST(\n         COALESCE(kbi_ass.grade, 0), COALESCE(q.grade, 0)\n           )                                AS overal_submission_grade,\n       teachers.teacher\nFROM mdl_user_enrolments kbi_ue\n       JOIN mdl_enrol kbi_e ON kbi_e.id = kbi_ue.enrolid\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ue.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_e.courseid\n       JOIN mdl_course_modules kbi_cm ON kbi_cm.course = kbi_c.id\n       JOIN mdl_modules kbi_m ON kbi_m.id = kbi_cm.module\n       LEFT JOIN mdl_user_lastaccess kbi_ul ON kbi_ul.userid = kbi_u.id AND kbi_ul.courseid = kbi_c.id\n       LEFT JOIN (SELECT kbi_ctx.instanceid,\n                         GROUP_CONCAT(DISTINCT CONCAT(kbi_u.firstname, \' \', kbi_u.lastname) SEPARATOR \'sql\') AS teacher\n                  FROM mdl_role_assignments kbi_ra\n                         JOIN mdl_user kbi_u ON kbi_ra.userid = kbi_u.id\n                         JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n                  WHERE kbi_ctx.contextlevel = 50\n                    AND kbi_ra.roleid = 3\n                  GROUP BY kbi_ctx.instanceid) AS teachers ON teachers.instanceid = kbi_c.id\n       LEFT JOIN (SELECT kbi_ass.userid,\n                         kbi_ass.assignment,\n                         MAX(kbi_ass.timemodified) AS submitted,\n                         MAX(kbi_ag.grade)         AS grade,\n                         MAX(kbi_ag.timemodified)  AS graded\n                  FROM mdl_assign_submission kbi_ass\n                         JOIN mdl_assign kbi_m ON kbi_m.id = kbi_ass.assignment AND kbi_m.course = :courseid\n                         LEFT JOIN mdl_assign_grades kbi_ag ON kbi_ag.assignment = kbi_ass.assignment AND kbi_ag.userid = kbi_ass.userid\n                  WHERE kbi_ass.status = \'submitted\'\n                  GROUP BY kbi_ass.userid, kbi_ass.assignment) ass\n         ON kbi_ass.userid = kbi_u.id AND kbi_ass.assignment = kbi_cm.instance AND kbi_m.name = \'assign\'\n       LEFT JOIN (SELECT kbi_fd.forum, kbi_fp.userid, MAX(kbi_fp.modified) AS posted, NULL AS grade, NULL AS graded\n                  FROM mdl_forum_discussions kbi_fd\n                         JOIN mdl_forum kbi_m ON kbi_m.id = kbi_fd.forum AND kbi_m.course = :courseid\n                         LEFT JOIN mdl_forum_posts kbi_fp ON kbi_fp.discussion = kbi_fd.id\n                  GROUP BY kbi_fd.forum, kbi_fp.userid) f ON f.userid = kbi_u.id AND f.forum = kbi_cm.instance AND kbi_m.name = \'forum\'\n       LEFT JOIN (SELECT kbi_qa.quiz,\n                         kbi_qa.userid,\n                         MIN(kbi_qa.timestart)     AS started,\n                         MAX(kbi_qgr.grade)        AS grade,\n                         MAX(kbi_qgr.timemodified) AS graded\n                  FROM mdl_quiz_attempts kbi_qa\n                         JOIN mdl_quiz kbi_m ON kbi_m.id = kbi_qa.quiz AND kbi_m.course = :courseid\n                         LEFT JOIN mdl_quiz_grades kbi_qgr ON kbi_qgr.quiz = kbi_m.id AND kbi_qgr.userid = kbi_qa.userid\n                  GROUP BY kbi_qa.quiz, kbi_qa.userid) q ON q.userid = kbi_u.id AND q.quiz = kbi_cm.instance AND kbi_m.name = \'quiz\'\n       LEFT JOIN (SELECT kbi_ge.glossaryid, kbi_ge.userid, MAX(kbi_ge.timecreated) AS submitted, NULL AS grade, NULL AS graded\n                  FROM mdl_glossary_entries kbi_ge\n                         JOIN mdl_glossary kbi_m ON kbi_m.id = kbi_ge.glossaryid AND kbi_m.course = :courseid\n                  GROUP BY kbi_ge.glossaryid, kbi_ge.userid) gl\n         ON gl.userid = kbi_u.id AND gl.glossaryid = kbi_cm.instance AND kbi_m.name = \'glossary\'\n       LEFT JOIN (SELECT kbi_ca.choiceid, kbi_ca.userid, MAX(kbi_ca.timemodified) AS submitted, NULL AS grade, NULL AS graded\n                  FROM mdl_choice_answers kbi_ca\n                         JOIN mdl_choice kbi_m ON kbi_m.id = kbi_ca.choiceid AND kbi_m.course = :courseid\n                  GROUP BY kbi_ca.choiceid, kbi_ca.userid) ch\n         ON ch.userid = kbi_u.id AND ch.choiceid = kbi_cm.instance AND kbi_m.name = \'choice\'\nWHERE kbi_ue.id > 0\n  AND kbi_c.visible = 1\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_cm.visible = 1\n  AND kbi_c.id = :courseid','1h','none','{\"column\":{\"username\":{\"key\":\"username\",\"title\":\"lang::report_field_username_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"idnumber\":{\"key\":\"idnumber\",\"title\":\"lang::report_field_idnumber_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"mod_name\":{\"key\":\"mod_name\",\"title\":\"lang::report_field_mod_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"instance_id\":{\"key\":\"instance_id\",\"title\":\"lang::report_field_instance_id_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timeaccess\":{\"key\":\"timeaccess\",\"title\":\"lang::report_field_timeaccess_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"status\":{\"key\":\"status\",\"title\":\"lang::report_field_status_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"timeend\":{\"key\":\"timeend\",\"title\":\"lang::report_field_timeend_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"overal_submission_date\":{\"key\":\"overal_submission_date\",\"title\":\"lang::report_field_overal_submission_date_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"overal_submission_graded\":{\"key\":\"overal_submission_graded\",\"title\":\"lang::report_field_overal_submission_graded_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"overal_submission_grade\":{\"key\":\"overal_submission_grade\",\"title\":\"lang::report_field_overal_submission_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"teacher\":{\"key\":\"teacher\",\"title\":\"lang::report_field_teacher_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646821),
(76,'kbi_el_uploads','lang::report_page_061_title::local_kopere_bi',71,1,'table','light','','','','SELECT MAX(kbi_f.id)             AS id,\n       kbi_f.component,\n       COUNT(kbi_f.id)           AS files,\n       COALESCE(SUM(kbi_f.filesize), 0) AS filesize\nFROM mdl_files kbi_f\nWHERE kbi_f.filesize > 0\nGROUP BY kbi_f.component\nORDER BY filesize DESC, component','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"component\":{\"key\":\"component\",\"title\":\"lang::report_field_component_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"files\":{\"key\":\"files\",\"title\":\"lang::report_field_files_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"filesize\":{\"key\":\"filesize\",\"title\":\"lang::report_field_filesize_title::local_kopere_bi\",\"type\":\"filesize\",\"mustache\":\"\"}}}',1780646821),
(77,'kbi_el_quiz_question_structure','lang::report_page_062_title::local_kopere_bi',72,1,'table','light','','','','SELECT kbi_slot.id                AS id,\n       kbi_c.id                   AS courseid,\n       kbi_c.fullname             AS course,\n       kbi_cm.id                  AS cmid,\n       kbi_qz.id                  AS quizid,\n       kbi_qz.name                AS quiz_name,\n       kbi_slot.slot,\n       kbi_slot.page              AS slot_page,\n       kbi_slot.maxmark,\n       kbi_qbe.id                 AS questionbankentryid,\n       kbi_qv.version,\n       kbi_q.id                   AS questionid,\n       kbi_q.name                 AS question_name,\n       kbi_q.qtype,\n       kbi_q.defaultmark,\n       kbi_q.length,\n       kbi_q.status               AS question_status,\n       kbi_tags.tags              AS question_tags\nFROM mdl_quiz kbi_qz\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_qz.course\n       JOIN mdl_modules kbi_m ON kbi_m.name = \'quiz\'\n       JOIN mdl_course_modules kbi_cm ON kbi_cm.course = kbi_c.id AND kbi_cm.module = kbi_m.id AND kbi_cm.instance = kbi_qz.id\n       JOIN mdl_quiz_slots kbi_slot ON kbi_slot.quizid = kbi_qz.id\n       LEFT JOIN mdl_question_references kbi_qr ON kbi_qr.component = \'mod_quiz\'\n             AND kbi_qr.questionarea = \'slot\'\n             AND kbi_qr.itemid = kbi_slot.id\n       LEFT JOIN mdl_question_bank_entries kbi_qbe ON kbi_qbe.id = kbi_qr.questionbankentryid\n       LEFT JOIN mdl_question_versions kbi_qv ON kbi_qv.questionbankentryid = kbi_qbe.id\n             AND (\n                 kbi_qv.version = kbi_qr.version\n                 OR (kbi_qr.version IS NULL AND kbi_qv.version = (\n                     SELECT MAX(kbi_qv2.version)\n                     FROM mdl_question_versions kbi_qv2\n                     WHERE kbi_qv2.questionbankentryid = kbi_qbe.id\n                 ))\n             )\n       LEFT JOIN mdl_question kbi_q ON kbi_q.id = kbi_qv.questionid\n       LEFT JOIN (\n             SELECT kbi_ti.itemid,\n                    GROUP_CONCAT(DISTINCT kbi_t.rawname ORDER BY kbi_t.rawname SEPARATOR \', \') AS tags\n             FROM mdl_tag_instance kbi_ti\n                    JOIN mdl_tag kbi_t ON kbi_t.id = kbi_ti.tagid\n             WHERE kbi_ti.itemtype = \'question\'\n             GROUP BY kbi_ti.itemid\n       ) kbi_tags ON kbi_tags.itemid = kbi_q.id\nWHERE kbi_c.visible = 1\n  AND kbi_cm.visible = 1\nORDER BY kbi_c.fullname, kbi_qz.name, kbi_slot.slot','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"cmid\":{\"key\":\"cmid\",\"title\":\"lang::report_field_cmid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"quizid\":{\"key\":\"quizid\",\"title\":\"lang::report_field_quizid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"quiz_name\":{\"key\":\"quiz_name\",\"title\":\"lang::report_field_quiz_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/mod\\/quiz\\/view.php?id={{{cmid}}}\\\" target=\\\"quiz\\\">{{{quiz_name}}}<\\/a>\"},\"slot\":{\"key\":\"slot\",\"title\":\"lang::report_field_slot_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"slot_page\":{\"key\":\"slot_page\",\"title\":\"lang::report_field_slot_page_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"maxmark\":{\"key\":\"maxmark\",\"title\":\"lang::report_field_maxmark_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"questionbankentryid\":{\"key\":\"questionbankentryid\",\"title\":\"lang::report_field_questionbankentryid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"version\":{\"key\":\"version\",\"title\":\"lang::report_field_version_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"questionid\":{\"key\":\"questionid\",\"title\":\"lang::report_field_questionid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"question_name\":{\"key\":\"question_name\",\"title\":\"lang::report_field_question_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"qtype\":{\"key\":\"qtype\",\"title\":\"lang::report_field_qtype_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"defaultmark\":{\"key\":\"defaultmark\",\"title\":\"lang::report_field_defaultmark_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"length\":{\"key\":\"length\",\"title\":\"lang::report_field_length_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"question_status\":{\"key\":\"question_status\",\"title\":\"lang::report_field_question_status_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"question_tags\":{\"key\":\"question_tags\",\"title\":\"lang::report_field_question_tags_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646821),
(78,'kbi_el_quiz_performance_statistics','lang::report_page_063_title::local_kopere_bi',73,1,'table','light','','','','SELECT kbi_qz.id                                                           AS id,\n       kbi_c.id                                                            AS courseid,\n       kbi_c.fullname                                                      AS course,\n       kbi_cm.id                                                           AS cmid,\n       kbi_qz.id                                                           AS quizid,\n       kbi_qz.name                                                         AS quiz_name,\n       COUNT(DISTINCT kbi_slot.id)                                         AS question_slots,\n       COUNT(DISTINCT kbi_qa.userid)                                       AS learners_attempted,\n       COUNT(kbi_qa.id)                                                    AS attempts,\n       SUM(CASE WHEN kbi_qa.state = \'finished\' THEN 1 ELSE 0 END)          AS finished_attempts,\n       ROUND(AVG(CASE WHEN kbi_qz.sumgrades > 0 THEN (kbi_qa.sumgrades * 100 / kbi_qz.sumgrades) ELSE NULL END), 2) AS average_score_percent,\n       ROUND(MIN(CASE WHEN kbi_qz.sumgrades > 0 THEN (kbi_qa.sumgrades * 100 / kbi_qz.sumgrades) ELSE NULL END), 2) AS minimum_score_percent,\n       ROUND(MAX(CASE WHEN kbi_qz.sumgrades > 0 THEN (kbi_qa.sumgrades * 100 / kbi_qz.sumgrades) ELSE NULL END), 2) AS maximum_score_percent,\n       ROUND(STDDEV_POP(CASE WHEN kbi_qz.sumgrades > 0 THEN (kbi_qa.sumgrades * 100 / kbi_qz.sumgrades) ELSE NULL END), 2) AS standard_deviation_percent,\n       ROUND(AVG(CASE WHEN kbi_qa.timefinish > kbi_qa.timestart THEN kbi_qa.timefinish - kbi_qa.timestart ELSE NULL END), 0) AS average_duration,\n       ROUND(SUM(CASE WHEN kbi_gi.gradepass > 0 AND kbi_gg.finalgrade >= kbi_gi.gradepass THEN 1 ELSE 0 END) * 100 / NULLIF(COUNT(kbi_qa.id), 0), 2) AS pass_rate_percent\nFROM mdl_quiz kbi_qz\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_qz.course\n       JOIN mdl_modules kbi_m ON kbi_m.name = \'quiz\'\n       JOIN mdl_course_modules kbi_cm ON kbi_cm.course = kbi_c.id AND kbi_cm.module = kbi_m.id AND kbi_cm.instance = kbi_qz.id\n       LEFT JOIN mdl_quiz_slots kbi_slot ON kbi_slot.quizid = kbi_qz.id\n       LEFT JOIN mdl_quiz_attempts kbi_qa ON kbi_qa.quiz = kbi_qz.id AND kbi_qa.preview = 0\n       LEFT JOIN mdl_grade_items kbi_gi ON kbi_gi.itemmodule = \'quiz\' AND kbi_gi.iteminstance = kbi_qz.id AND kbi_gi.courseid = kbi_c.id\n       LEFT JOIN mdl_grade_grades kbi_gg ON kbi_gg.itemid = kbi_gi.id AND kbi_gg.userid = kbi_qa.userid\nWHERE kbi_c.visible = 1\n  AND kbi_cm.visible = 1\nGROUP BY kbi_qz.id, kbi_c.id, kbi_cm.id, kbi_gi.gradepass\nORDER BY kbi_c.fullname, kbi_qz.name','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"cmid\":{\"key\":\"cmid\",\"title\":\"lang::report_field_cmid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"quizid\":{\"key\":\"quizid\",\"title\":\"lang::report_field_quizid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"quiz_name\":{\"key\":\"quiz_name\",\"title\":\"lang::report_field_quiz_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/mod\\/quiz\\/view.php?id={{{cmid}}}\\\" target=\\\"quiz\\\">{{{quiz_name}}}<\\/a>\"},\"question_slots\":{\"key\":\"question_slots\",\"title\":\"lang::report_field_question_slots_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"learners_attempted\":{\"key\":\"learners_attempted\",\"title\":\"lang::report_field_learners_attempted_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"attempts\":{\"key\":\"attempts\",\"title\":\"lang::report_field_attempts_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"finished_attempts\":{\"key\":\"finished_attempts\",\"title\":\"lang::report_field_finished_attempts_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"average_score_percent\":{\"key\":\"average_score_percent\",\"title\":\"lang::report_field_average_score_percent_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"minimum_score_percent\":{\"key\":\"minimum_score_percent\",\"title\":\"lang::report_field_minimum_score_percent_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"maximum_score_percent\":{\"key\":\"maximum_score_percent\",\"title\":\"lang::report_field_maximum_score_percent_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"standard_deviation_percent\":{\"key\":\"standard_deviation_percent\",\"title\":\"lang::report_field_standard_deviation_percent_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"average_duration\":{\"key\":\"average_duration\",\"title\":\"lang::report_field_average_duration_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"pass_rate_percent\":{\"key\":\"pass_rate_percent\",\"title\":\"lang::report_field_pass_rate_percent_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646821),
(79,'kbi_el_quiz_activity_detail_by_learner','lang::report_page_064_title::local_kopere_bi',74,1,'table','light','','','','SELECT kbi_qa.id                        as quiz_attempt_id,\n       kbi_c.fullname                   AS course_name,\n       kbi_q.name                       AS quiz_name,\n       kbi_u.id,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_qa.attempt                   AS all_att,\n       attm.highest_grade,\n       attm.lowest_grade,\n       kbi_qa.timefinish - kbi_qa.timestart AS timespend,\n       kbi_ue.enrol_status              AS enrol_status,\n       kbi_ue.timeend,\n       kbi_qa.state                     AS completion_state,\n       attm.latest_submission,\n       kbi_q.sumgrades                  AS marksmax,\n       kbi_q.grade                      AS grademax,\n       kbi_qa.sumgrades                 AS finalgrade,\n       attm.first_completed_date,\n       kbi_gi.gradepass                 AS gradepass,\n       kbi_cmc.timemodified             AS timemodified,\n       kbi_u.deleted,\n       kbi_u.suspended,\n       kbi_u.username\nFROM mdl_quiz_attempts kbi_qa\n       JOIN (SELECT kbi_qa1.quiz,\n                    kbi_qa1.userid,\n                    COUNT(kbi_qa1.id)                                                        AS at_cont,\n                    (MAX(kbi_qa1.sumgrades) / kbi_q1.sumgrades) * 100                            AS highest_grade,\n                    (MIN(kbi_qa1.sumgrades) / kbi_q1.sumgrades) * 100                            AS lowest_grade,\n                    MAX(CASE WHEN kbi_qa1.state = \'finished\' THEN kbi_qa1.timefinish ELSE 0 END) AS latest_submission,\n                    MIN(kbi_qa1.timefinish)                                                  AS first_completed_date\n             FROM mdl_quiz_attempts kbi_qa1\n                    JOIN mdl_quiz kbi_q1 ON kbi_q1.id = kbi_qa1.quiz\n             GROUP BY kbi_qa1.quiz, kbi_qa1.userid, kbi_q1.sumgrades) attm ON attm.quiz = kbi_qa.quiz AND attm.userid = kbi_qa.userid\n       JOIN mdl_quiz kbi_q ON kbi_q.id = kbi_qa.quiz\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_qa.userid\n       JOIN (SELECT kbi_e.courseid, kbi_ue.userid, MIN(kbi_ue.status) AS enrol_status, MIN(kbi_ue.timeend) AS timeend\n             FROM mdl_enrol kbi_e\n                    JOIN mdl_user_enrolments kbi_ue ON kbi_ue.enrolid = kbi_e.id\n             GROUP BY kbi_e.courseid, kbi_ue.userid) ue ON kbi_ue.courseid = kbi_q.course AND kbi_ue.userid = kbi_u.id\n       JOIN mdl_modules kbi_m ON kbi_m.name = \'quiz\'\n       JOIN mdl_course_modules kbi_cm ON kbi_cm.course = kbi_q.course AND kbi_cm.module = kbi_m.id AND kbi_cm.instance = kbi_q.id\n       JOIN mdl_grade_items kbi_gi ON kbi_gi.itemmodule = \'quiz\' AND kbi_gi.iteminstance = kbi_q.id\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_cm.course\n       LEFT JOIN mdl_course_modules_completion kbi_cmc\n         ON kbi_cmc.coursemoduleid = kbi_cm.id AND kbi_cmc.completionstate IN (1, 2) AND\n            kbi_cmc.userid = kbi_qa.userid\nWHERE kbi_q.id = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'','1h','none','{\"column\":{\"quiz_attempt_id\":{\"key\":\"quiz_attempt_id\",\"title\":\"lang::report_field_quiz_attempt_id_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course_name\":{\"key\":\"course_name\",\"title\":\"lang::report_field_course_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"quiz_name\":{\"key\":\"quiz_name\",\"title\":\"lang::report_field_quiz_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"all_att\":{\"key\":\"all_att\",\"title\":\"lang::report_field_all_att_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"highest_grade\":{\"key\":\"highest_grade\",\"title\":\"lang::report_field_highest_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"lowest_grade\":{\"key\":\"lowest_grade\",\"title\":\"lang::report_field_lowest_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"enrol_status\":{\"key\":\"enrol_status\",\"title\":\"lang::report_field_enrol_status_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"timeend\":{\"key\":\"timeend\",\"title\":\"lang::report_field_timeend_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"completion_state\":{\"key\":\"completion_state\",\"title\":\"lang::report_field_completion_state_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"latest_submission\":{\"key\":\"latest_submission\",\"title\":\"lang::report_field_latest_submission_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"marksmax\":{\"key\":\"marksmax\",\"title\":\"lang::report_field_marksmax_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"grademax\":{\"key\":\"grademax\",\"title\":\"lang::report_field_grademax_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"finalgrade\":{\"key\":\"finalgrade\",\"title\":\"lang::report_field_finalgrade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"first_completed_date\":{\"key\":\"first_completed_date\",\"title\":\"lang::report_field_first_completed_date_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"gradepass\":{\"key\":\"gradepass\",\"title\":\"lang::report_field_gradepass_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timemodified\":{\"key\":\"timemodified\",\"title\":\"lang::report_field_timemodified_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"deleted\":{\"key\":\"deleted\",\"title\":\"lang::report_field_deleted_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"suspended\":{\"key\":\"suspended\",\"title\":\"lang::report_field_suspended_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"username\":{\"key\":\"username\",\"title\":\"lang::report_field_username_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646821),
(80,'kbi_el_quiz_attempts_summary_by_course','lang::report_page_065_title::local_kopere_bi',75,1,'table','light','','','','SELECT MAX(kbi_qa.id)                              AS id,\n       kbi_c.fullname,\n       COUNT(DISTINCT kbi_q.id)                    AS quizzes,\n       SUM(kbi_qa.timefinish - kbi_qa.timestart)       AS duration,\n       COUNT(DISTINCT kbi_qa.id)                   AS attempts,\n       AVG((kbi_qa.sumgrades / kbi_q.sumgrades) * 100) AS grade,\n       (SELECT DISTINCT CONCAT(kbi_u.firstname, \' \', kbi_u.lastname)\n        FROM mdl_role_assignments kbi_ra\n               JOIN mdl_user kbi_u ON kbi_ra.userid = kbi_u.id\n               JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n        WHERE kbi_ctx.instanceid = kbi_c.id\n          AND kbi_ctx.contextlevel = 50\n          AND kbi_ra.roleid = 3\n        LIMIT 1)                               AS teacher\nFROM mdl_quiz_attempts kbi_qa\n       LEFT JOIN mdl_quiz kbi_q ON kbi_q.id = kbi_qa.quiz\n       LEFT JOIN mdl_course kbi_c ON kbi_c.id = kbi_q.course\nWHERE kbi_qa.id > 0\n  AND kbi_c.id = :courseid\n  AND kbi_c.visible = 1\nGROUP BY kbi_c.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"quizzes\":{\"key\":\"quizzes\",\"title\":\"lang::report_field_quizzes_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"duration\":{\"key\":\"duration\",\"title\":\"lang::report_field_duration_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"attempts\":{\"key\":\"attempts\",\"title\":\"lang::report_field_attempts_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"teacher\":{\"key\":\"teacher\",\"title\":\"lang::report_field_teacher_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646821),
(81,'kbi_el_quiz_attempts_summary_by_quiz','lang::report_page_066_title::local_kopere_bi',76,1,'table','light','','','','SELECT kbi_q.id,\n       kbi_q.name,\n       kbi_q.course,\n       kbi_c.fullname,\n       MAX(ql.questions)                       AS questions,\n       kbi_q.timemodified,\n       kbi_q.timeopen,\n       kbi_q.timeclose,\n       avg((kbi_qa.sumgrades / kbi_q.sumgrades) * 100) AS grade,\n       count(distinct(kbi_qa.id))                  AS attempts,\n       sum(kbi_qa.timefinish - kbi_qa.timestart)       AS duration\nFROM mdl_quiz kbi_q\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_q.course\n       LEFT JOIN mdl_quiz_attempts kbi_qa ON kbi_qa.quiz = kbi_q.id\n       LEFT JOIN (SELECT quizid, count(*) questions FROM mdl_quiz_slots GROUP BY quizid) ql ON ql.quizid = kbi_q.id\n       LEFT JOIN mdl_modules kbi_m ON kbi_m.name = \'quiz\'\n       LEFT JOIN mdl_course_modules kbi_cm ON kbi_cm.module = kbi_m.id AND kbi_cm.course = kbi_c.id AND kbi_cm.instance = kbi_q.id\nWHERE kbi_q.id > 0\n  AND kbi_q.course = :courseid\n  AND kbi_c.visible = 1\nGROUP BY kbi_q.id, kbi_c.id\nORDER BY kbi_q.name','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"name\":{\"key\":\"name\",\"title\":\"lang::report_field_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"questions\":{\"key\":\"questions\",\"title\":\"lang::report_field_questions_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timemodified\":{\"key\":\"timemodified\",\"title\":\"lang::report_field_timemodified_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"timeopen\":{\"key\":\"timeopen\",\"title\":\"lang::report_field_timeopen_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"timeclose\":{\"key\":\"timeclose\",\"title\":\"lang::report_field_timeclose_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"attempts\":{\"key\":\"attempts\",\"title\":\"lang::report_field_attempts_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"duration\":{\"key\":\"duration\",\"title\":\"lang::report_field_duration_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646821),
(82,'kbi_el_quiz_grade_detail_by_learner','lang::report_page_067_title::local_kopere_bi',77,1,'table','light','','','','SELECT kbi_qa.id,\n       kbi_q.name,\n       kbi_u.email,\n       kbi_q.course,\n       kbi_q.timeclose,\n       kbi_c.fullname,\n       kbi_qa.timestart,\n       kbi_qa.timefinish,\n       kbi_qa.state,\n       (kbi_qa.timefinish - kbi_qa.timestart)                  as duration,\n       (kbi_qa.sumgrades / MAX(kbi_q.sumgrades) * 100)         as grade,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       GROUP_CONCAT(DISTINCT kbi_t.rawname SEPARATOR \', \') as tags,\n       \'\'                                              AS cohortname\nFROM (SELECT kbi_ctx.instanceid, kbi_ra1.userid\n      FROM mdl_context kbi_ctx\n             JOIN mdl_role_assignments kbi_ra1 ON kbi_ra1.contextid = kbi_ctx.id AND kbi_ra1.roleid = 5\n      WHERE kbi_ctx.contextlevel = 50\n      GROUP BY kbi_ctx.instanceid, kbi_ra1.userid) ra\n       JOIN mdl_modules kbi_m ON kbi_m.name = \'quiz\'\n       JOIN mdl_course_modules kbi_cm ON kbi_cm.course = ra.instanceid AND kbi_cm.module = kbi_m.id\n       JOIN mdl_quiz kbi_q ON kbi_q.id = kbi_cm.instance\n       JOIN mdl_user kbi_u ON kbi_u.id = ra.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = ra.instanceid\n       LEFT JOIN mdl_quiz_attempts kbi_qa ON kbi_qa.quiz = kbi_q.id AND kbi_qa.userid = ra.userid\n       LEFT JOIN mdl_tag_instance kbi_ti ON kbi_ti.itemtype = \'course_modules\' AND kbi_ti.itemid = kbi_cm.id\n       LEFT JOIN mdl_tag kbi_t ON kbi_t.id = kbi_ti.tagid\nWHERE ra.instanceid > 0\n  AND ra.instanceid = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\nGROUP BY kbi_u.id, kbi_q.id, kbi_c.id, kbi_qa.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"name\":{\"key\":\"name\",\"title\":\"lang::report_field_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timeclose\":{\"key\":\"timeclose\",\"title\":\"lang::report_field_timeclose_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timestart\":{\"key\":\"timestart\",\"title\":\"lang::report_field_timestart_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"timefinish\":{\"key\":\"timefinish\",\"title\":\"lang::report_field_timefinish_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"state\":{\"key\":\"state\",\"title\":\"lang::report_field_state_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"duration\":{\"key\":\"duration\",\"title\":\"lang::report_field_duration_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"tags\":{\"key\":\"tags\",\"title\":\"lang::report_field_tags_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"cohortname\":{\"key\":\"cohortname\",\"title\":\"lang::report_field_cohortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646821),
(83,'kbi_el_quiz_progress_by_cohort','lang::report_page_068_title::local_kopere_bi',78,1,'table','light','','','','SELECT kbi_co.id,\n       kbi_co.name,\n       COUNT(DISTINCT kbi_qa.quiz) AS submitted,\n       COUNT(DISTINCT kbi_qa.id)   AS attempted\nFROM mdl_quiz_attempts kbi_qa\n       JOIN mdl_quiz kbi_q ON kbi_q.id = kbi_qa.quiz\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_q.course\n       JOIN mdl_cohort_members kbi_cm ON kbi_cm.userid = kbi_qa.userid\n       JOIN mdl_cohort kbi_co ON kbi_co.id = kbi_cm.cohortid\nWHERE kbi_c.id = :courseid\n  AND kbi_c.visible = 1\nGROUP BY kbi_co.id, kbi_co.name\nORDER BY kbi_co.name','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"name\":{\"key\":\"name\",\"title\":\"lang::report_field_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"submitted\":{\"key\":\"submitted\",\"title\":\"lang::report_field_submitted_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"attempted\":{\"key\":\"attempted\",\"title\":\"lang::report_field_attempted_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646821),
(84,'kbi_el_quiz_progress_by_course','lang::report_page_069_title::local_kopere_bi',79,1,'table','light','','','','SELECT kbi_c.id,\n       kbi_c.fullname,\n       COUNT(DISTINCT kbi_qa.quiz) AS submitted,\n       COUNT(DISTINCT kbi_qa.id)   AS attempted\nFROM mdl_quiz_attempts kbi_qa\n       JOIN mdl_quiz kbi_q ON kbi_q.id = kbi_qa.quiz\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_q.course\nWHERE kbi_c.id = :courseid\n  AND kbi_c.visible = 1\nGROUP BY kbi_c.id, kbi_c.fullname\nORDER BY kbi_c.fullname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"submitted\":{\"key\":\"submitted\",\"title\":\"lang::report_field_submitted_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"attempted\":{\"key\":\"attempted\",\"title\":\"lang::report_field_attempted_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646821),
(85,'kbi_el_quiz_progress_by_user','lang::report_page_070_title::local_kopere_bi',80,1,'table','light','','','','SELECT kbi_u.id,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_u.phone1,\n       kbi_u.phone2,\n       kbi_u.institution,\n       kbi_u.department,\n       kbi_u.address,\n       kbi_u.city,\n       kbi_u.country,\n       COUNT(DISTINCT kbi_qa.quiz) AS submitted,\n       COUNT(DISTINCT kbi_qa.id)   AS attempted\nFROM mdl_quiz_attempts kbi_qa\n       JOIN mdl_quiz kbi_q ON kbi_q.id = kbi_qa.quiz\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_q.course\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_qa.userid\nWHERE kbi_c.id = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\nGROUP BY kbi_u.id,\n         kbi_u.firstname,\n         kbi_u.lastname,\n         kbi_u.email,\n         kbi_u.phone1,\n         kbi_u.phone2,\n         kbi_u.institution,\n         kbi_u.department,\n         kbi_u.address,\n         kbi_u.city,\n         kbi_u.country\nORDER BY kbi_u.lastname, kbi_u.firstname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"phone1\":{\"key\":\"phone1\",\"title\":\"lang::report_field_phone1_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone1}}}\\\" target=\\\"_blank\\\">{{{phone1}}}<\\/a>\"},\"phone2\":{\"key\":\"phone2\",\"title\":\"lang::report_field_phone2_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone2}}}\\\" target=\\\"_blank\\\">{{{phone2}}}<\\/a>\"},\"institution\":{\"key\":\"institution\",\"title\":\"lang::report_field_institution_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"department\":{\"key\":\"department\",\"title\":\"lang::report_field_department_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"address\":{\"key\":\"address\",\"title\":\"lang::report_field_address_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"city\":{\"key\":\"city\",\"title\":\"lang::report_field_city_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"country\":{\"key\":\"country\",\"title\":\"lang::report_field_country_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"submitted\":{\"key\":\"submitted\",\"title\":\"lang::report_field_submitted_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"attempted\":{\"key\":\"attempted\",\"title\":\"lang::report_field_attempted_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646821),
(86,'kbi_el_forum_activity_details','lang::report_page_071_title::local_kopere_bi',81,1,'table','light','','','','SELECT kbi_fd.id,\n       kbi_c.id                                                             AS courseid,\n       kbi_c.fullname                                                       AS course_name,\n       kbi_f.name                                                           AS forum,\n       kbi_fd.name                                                          AS discusion,\n       kbi_u.id                                                             AS userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       MIN(kbi_fp.created)                                                  AS time_started,\n       MIN(stat.students_accesed)                                       AS students_accesed,\n       MIN(stat.timespend)                                              AS timespend,\n       COUNT(DISTINCT CASE WHEN kbi_fp.parent > 0 THEN kbi_fp.id ELSE NULL END) AS posts\nFROM mdl_forum kbi_f\n       JOIN mdl_forum_discussions kbi_fd ON kbi_fd.forum = kbi_f.id\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_fd.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_f.course\n       LEFT JOIN mdl_forum_posts kbi_fp ON kbi_fp.discussion = kbi_fd.id\n       JOIN mdl_modules kbi_m ON kbi_m.name = \'forum\'\n       JOIN mdl_course_modules kbi_cm ON kbi_cm.instance = kbi_f.id AND kbi_cm.module = kbi_m.id\n       LEFT JOIN (SELECT kbi_lit.param                  AS module,\n                         COUNT(DISTINCT kbi_lit.userid) AS students_accesed,\n                         SUM(kbi_lit.timespend)         AS timespend\n                  FROM mdl_context kbi_ctx\n                         JOIN mdl_role_assignments kbi_ra ON kbi_ra.contextid = kbi_ctx.id\n                         LEFT JOIN mdl_local_kopere_bi_tracking kbi_lit\n                           ON kbi_lit.page = \'module\' AND kbi_lit.courseid = kbi_ctx.instanceid AND kbi_lit.userid = kbi_ra.userid\n                  WHERE kbi_ctx.contextlevel = 50\n                    AND kbi_ra.roleid = 5\n                  GROUP BY kbi_lit.param) stat ON stat.module = kbi_cm.id\nWHERE kbi_f.id > 0\n  AND kbi_f.course = :courseid\nGROUP BY kbi_fd.id, kbi_c.id, kbi_f.name, kbi_u.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course_name\":{\"key\":\"course_name\",\"title\":\"lang::report_field_course_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"forum\":{\"key\":\"forum\",\"title\":\"lang::report_field_forum_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"discusion\":{\"key\":\"discusion\",\"title\":\"lang::report_field_discusion_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"time_started\":{\"key\":\"time_started\",\"title\":\"lang::report_field_time_started_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"students_accesed\":{\"key\":\"students_accesed\",\"title\":\"lang::report_field_students_accesed_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"posts\":{\"key\":\"posts\",\"title\":\"lang::report_field_posts_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646821),
(87,'kbi_el_forum_post_ratio','lang::report_page_072_title::local_kopere_bi',82,1,'table','light','','','','SELECT floor(kbi_d.timemodified / 86400) * 86400 as timepoint, count(distinct kbi_p.id) as posts\nFROM mdl_role_assignments kbi_ra\n       LEFT JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n       LEFT JOIN mdl_course kbi_c ON kbi_c.id = kbi_ctx.instanceid\n       LEFT JOIN mdl_forum_discussions kbi_d ON kbi_d.course = kbi_c.id\n       LEFT JOIN mdl_forum_posts kbi_p ON kbi_p.userid = kbi_ra.userid AND kbi_p.discussion = kbi_d.id\nWHERE kbi_ctx.contextlevel = 50\n  AND floor(kbi_d.timemodified / 86400) > 0\n  AND kbi_c.id = :courseid\n  AND kbi_ra.roleid = 3\nGROUP BY timepoint\nORDER BY timepoint ASC','1h','none','{\"column\":{\"timepoint\":{\"key\":\"timepoint\",\"title\":\"lang::report_field_timepoint_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"posts\":{\"key\":\"posts\",\"title\":\"lang::report_field_posts_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646821),
(88,'kbi_el_forum_post_replies','lang::report_page_073_title::local_kopere_bi',83,1,'table','light','','','','SELECT kbi_c.fullname                                                   AS course,\n       kbi_f.name                                                       AS forum,\n       kbi_fd.name                                                      AS discussion,\n       kbi_fp.subject                                                   AS post,\n       kbi_u.id                                                         AS userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_fp.created,\n       (SELECT COUNT(id) FROM mdl_forum_posts WHERE parent = kbi_fp.id) as count_reply,\n       last_reply.time                                              AS last_reply_time,\n       last_reply.firstname                                         AS last_reply_firstname,\n       last_reply.lastname                                          AS last_reply_lastname,\n       last_reply.id                                                AS last_reply_userid\nFROM mdl_forum kbi_f\n       LEFT JOIN mdl_forum_discussions kbi_fd ON kbi_fd.forum = kbi_f.id\n       LEFT JOIN mdl_forum_posts kbi_fp ON kbi_fp.discussion = kbi_fd.id\n       LEFT JOIN mdl_course kbi_c ON kbi_c.id = kbi_f.course\n       LEFT JOIN mdl_user kbi_u ON kbi_u.id = kbi_fp.userid\n       LEFT JOIN mdl_modules kbi_m ON kbi_m.name = \'forum\'\n       LEFT JOIN mdl_course_modules kbi_cm ON kbi_cm.module = kbi_m.id AND kbi_cm.course = kbi_c.id AND kbi_cm.instance = kbi_f.id\n       LEFT JOIN (SELECT *\n                  FROM (SELECT kbi_post.parent, kbi_post.created AS time, kbi_ur.firstname, kbi_ur.lastname, kbi_ur.id\n                        FROM mdl_forum_posts kbi_post\n                               JOIN mdl_user kbi_ur ON kbi_ur.id = kbi_post.userid\n                               JOIN mdl_forum_discussions kbi_d ON kbi_d.id = kbi_post.discussion\n                               JOIN mdl_forum kbi_f ON kbi_d.forum = kbi_f.id\n                        WHERE kbi_ur.id > 0\n                          AND CONCAT(kbi_post.parent, \'-\', kbi_post.created) IN(SELECT CONCAT(parent, \'-\', MAX(created))\n                                                                        FROM mdl_forum_posts\n                                                                        GROUP BY parent)\n                        ORDER BY kbi_post.created DESC) p\n                  GROUP BY p.parent, p.time, p.firstname, p.lastname, p.id) last_reply ON last_reply.parent = kbi_fp.id\nWHERE kbi_u.id IS NOT NULL','1h','none','{\"column\":{\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"forum\":{\"key\":\"forum\",\"title\":\"lang::report_field_forum_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"discussion\":{\"key\":\"discussion\",\"title\":\"lang::report_field_discussion_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"post\":{\"key\":\"post\",\"title\":\"lang::report_field_post_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"created\":{\"key\":\"created\",\"title\":\"lang::report_field_created_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"count_reply\":{\"key\":\"count_reply\",\"title\":\"lang::report_field_count_reply_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"last_reply_time\":{\"key\":\"last_reply_time\",\"title\":\"lang::report_field_last_reply_time_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"last_reply_firstname\":{\"key\":\"last_reply_firstname\",\"title\":\"lang::report_field_last_reply_firstname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"last_reply_lastname\":{\"key\":\"last_reply_lastname\",\"title\":\"lang::report_field_last_reply_lastname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"last_reply_userid\":{\"key\":\"last_reply_userid\",\"title\":\"lang::report_field_last_reply_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646821),
(89,'kbi_el_forum_posts_performance','lang::report_page_074_title::local_kopere_bi',84,1,'table','light','','','','SELECT kbi_f.id                                                                                                as fid,\n       kbi_f.name,\n       kbi_c.fullname,\n       COUNT(DISTINCT kbi_fp.id)                                                                               AS all_posts,\n       COUNT(DISTINCT kbi_fp.id) /\n       GREATEST(PERIOD_DIFF(DATE_FORMAT(NOW(), \'%Y%m\'), DATE_FORMAT(FROM_UNIXTIME(kbi_cm.added), \'%Y%m\')), 1)  as avg_month,\n       COUNT(DISTINCT kbi_fp.id) /\n       GREATEST(CEILING(DATEDIFF(DATE_FORMAT(NOW(), \'%Y%m%d\'), DATE_FORMAT(FROM_UNIXTIME(kbi_cm.added), \'%Y%m%d\')) / 7),\n                1)                                                                                         as avg_week,\n       COUNT(DISTINCT kbi_fp.id) /\n       GREATEST(DATEDIFF(DATE_FORMAT(NOW(), \'%Y%m%d\'), DATE_FORMAT(FROM_UNIXTIME(kbi_cm.added), \'%Y%m%d\')), 1) as avg_day,\n       popular_day.day                                                                                     AS popular_day,\n       popular_hour.hour                                                                                   AS popular_hour,\n       popular_week.week                                                                                   AS popular_week\nFROM mdl_forum kbi_f\n       JOIN mdl_modules kbi_m ON kbi_m.name = \'forum\'\n       LEFT JOIN mdl_course_modules kbi_cm ON kbi_cm.course = kbi_f.course AND kbi_cm.instance = kbi_f.id AND kbi_cm.module = kbi_m.id\n       LEFT JOIN mdl_course kbi_c ON kbi_c.id = kbi_f.course\n       LEFT JOIN mdl_forum_discussions kbi_fd ON kbi_fd.forum = kbi_f.id\n       LEFT JOIN mdl_forum_posts kbi_fp ON kbi_fp.discussion = kbi_fd.id\n       LEFT JOIN (SELECT a.posts, a.day, a.id\n                  FROM (SELECT COUNT(DISTINCT kbi_fp2.id)                             as posts,\n                               WEEKDAY(FROM_UNIXTIME(kbi_fp2.created, \'%Y-%m-%d %T\')) AS day,\n                               kbi_f2.id\n                        FROM mdl_forum kbi_f2\n                               LEFT JOIN mdl_forum_discussions kbi_fd2 ON kbi_fd2.forum = kbi_f2.id\n                               LEFT JOIN mdl_forum_posts kbi_fp2 ON kbi_fp2.discussion = kbi_fd2.id\n                        WHERE kbi_f2.course = :courseid\n                        GROUP BY day, kbi_f2.id\n                        ORDER BY posts DESC) AS a\n                  GROUP BY a.id) as popular_day ON popular_day.id = kbi_f.id\n       LEFT JOIN (SELECT a.posts, a.hour, a.id\n                  FROM (SELECT COUNT(DISTINCT kbi_fp2.id) as posts, FROM_UNIXTIME(kbi_fp2.created, \'%H\') AS hour, kbi_f2.id\n                        FROM mdl_forum kbi_f2\n                               LEFT JOIN mdl_forum_discussions kbi_fd2 ON kbi_fd2.forum = kbi_f2.id\n                               LEFT JOIN mdl_forum_posts kbi_fp2 ON kbi_fp2.discussion = kbi_fd2.id\n                        WHERE kbi_f2.course = :courseid\n                        GROUP BY hour, kbi_f2.id\n                        ORDER BY posts DESC) AS a\n                  GROUP BY a.id) as popular_hour ON popular_hour.id = kbi_f.id\n       LEFT JOIN (SELECT a.posts, a.week, a.id\n                  FROM (SELECT COUNT(DISTINCT kbi_fp2.id)                                             as posts,\n                               CEILING(DAYOFMONTH(FROM_UNIXTIME(kbi_fp2.created, \'%Y-%m-%d %T\')) / 7) AS week,\n                               kbi_f2.id\n                        FROM mdl_forum kbi_f2\n                               LEFT JOIN mdl_forum_discussions kbi_fd2 ON kbi_fd2.forum = kbi_f2.id\n                               LEFT JOIN mdl_forum_posts kbi_fp2 ON kbi_fp2.discussion = kbi_fd2.id\n                        WHERE kbi_f2.course = :courseid\n                        GROUP BY week, kbi_f2.id\n                        ORDER BY posts DESC) AS a\n                  GROUP BY a.id) as popular_week ON popular_week.id = kbi_f.id\nWHERE kbi_f.course = :courseid\n  AND kbi_c.visible = 1\nGROUP BY kbi_f.id\nORDER BY all_posts DESC, kbi_f.name','1h','none','{\"column\":{\"fid\":{\"key\":\"fid\",\"title\":\"lang::report_field_fid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"name\":{\"key\":\"name\",\"title\":\"lang::report_field_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"all_posts\":{\"key\":\"all_posts\",\"title\":\"lang::report_field_all_posts_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"avg_month\":{\"key\":\"avg_month\",\"title\":\"lang::report_field_avg_month_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"avg_week\":{\"key\":\"avg_week\",\"title\":\"lang::report_field_avg_week_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"avg_day\":{\"key\":\"avg_day\",\"title\":\"lang::report_field_avg_day_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"popular_day\":{\"key\":\"popular_day\",\"title\":\"lang::report_field_popular_day_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"popular_hour\":{\"key\":\"popular_hour\",\"title\":\"lang::report_field_popular_hour_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"popular_week\":{\"key\":\"popular_week\",\"title\":\"lang::report_field_popular_week_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646821),
(90,'kbi_el_forum_response_overview','lang::report_page_075_title::local_kopere_bi',85,1,'table','light','','','','SELECT kbi_c.fullname            AS course,\n       kbi_f.name                AS forum,\n       kbi_fp.subject            AS discussion_post,\n       kbi_u1.firstname          AS forum_started_by_first_name,\n       kbi_u1.lastname           AS forum_started_by_last_name,\n       kbi_fp.created            AS date_started,\n       kbi_fp2.message           AS response,\n       kbi_fp2.created           AS response_date,\n       kbi_u2.firstname          AS response_first_name,\n       kbi_u2.lastname           AS response_laste_name,\n       kbi_fp3.message           AS response_immediatey_prior,\n       kbi_fp3.created           AS response_immediatey_prior_date,\n       kbi_u3.firstname          AS response_immediatey_prior_first_name,\n       kbi_u3.lastname           AS response_immediatey_prior_last_name\nFROM mdl_forum kbi_f\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_f.course\n       JOIN mdl_modules kbi_m ON kbi_m.name = \'forum\'\n       JOIN mdl_course_modules kbi_cm ON kbi_cm.course = kbi_c.id AND kbi_cm.module = kbi_m.id AND kbi_cm.instance = kbi_f.id\n       JOIN mdl_forum_discussions kbi_fd ON kbi_fd.forum = kbi_f.id AND kbi_fd.course = kbi_c.id\n       JOIN mdl_forum_posts kbi_fp ON kbi_fp.discussion = kbi_fd.id AND kbi_fp.parent = 0\n       JOIN mdl_user kbi_u1 ON kbi_u1.id = kbi_fp.userid\n       LEFT JOIN mdl_forum_posts kbi_fp2 ON kbi_fp2.discussion = kbi_fd.id AND kbi_fp2.parent <> 0\n       LEFT JOIN mdl_user kbi_u2 ON kbi_u2.id = kbi_fp2.userid\n       LEFT JOIN mdl_forum_posts kbi_fp3 ON kbi_fp3.discussion = kbi_fd.id AND kbi_fp3.id = kbi_fp2.parent AND kbi_fp3.parent <> 0\n       LEFT JOIN mdl_user kbi_u3 ON kbi_u3.id = kbi_fp3.userid\nWHERE kbi_c.id > 0\n  AND kbi_c.id = :courseid','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"forum\":{\"key\":\"forum\",\"title\":\"lang::report_field_forum_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"discussion_post\":{\"key\":\"discussion_post\",\"title\":\"lang::report_field_discussion_post_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"forum_started_by_first_name\":{\"key\":\"forum_started_by_first_name\",\"title\":\"lang::report_field_forum_started_by_first_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"forum_started_by_last_name\":{\"key\":\"forum_started_by_last_name\",\"title\":\"lang::report_field_forum_started_by_last_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"date_started\":{\"key\":\"date_started\",\"title\":\"lang::report_field_date_started_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"response\":{\"key\":\"response\",\"title\":\"lang::report_field_response_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"response_date\":{\"key\":\"response_date\",\"title\":\"lang::report_field_response_date_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"response_first_name\":{\"key\":\"response_first_name\",\"title\":\"lang::report_field_response_first_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"response_laste_name\":{\"key\":\"response_laste_name\",\"title\":\"lang::report_field_response_laste_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"response_immediatey_prior\":{\"key\":\"response_immediatey_prior\",\"title\":\"lang::report_field_response_immediatey_prior_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"response_immediatey_prior_date\":{\"key\":\"response_immediatey_prior_date\",\"title\":\"lang::report_field_response_immediatey_prior_date_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"response_immediatey_prior_first_name\":{\"key\":\"response_immediatey_prior_first_name\",\"title\":\"lang::report_field_response_immediatey_prior_first_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"response_immediatey_prior_last_name\":{\"key\":\"response_immediatey_prior_last_name\",\"title\":\"lang::report_field_response_immediatey_prior_last_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646821),
(91,'kbi_el_learner_forum_participation_summary','lang::report_page_076_title::local_kopere_bi',86,1,'table','light','','','','SELECT MAX(kbi_fd.id)            AS id,\n       kbi_c.fullname            as course,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_f.name,\n       COUNT(DISTINCT kbi_fp.id) AS posts,\n       COUNT(DISTINCT kbi_fd.id) AS discussions\nFROM mdl_forum_discussions kbi_fd\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_fd.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_fd.course\n       LEFT JOIN mdl_forum kbi_f ON kbi_f.id = kbi_fd.forum\n       LEFT JOIN mdl_forum_posts kbi_fp ON kbi_fp.discussion = kbi_fd.id AND kbi_fp.userid = kbi_u.id\nWHERE kbi_fd.id > 0\n  AND kbi_c.id = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\nGROUP BY kbi_u.id, kbi_c.id, kbi_f.id\nORDER BY kbi_c.fullname, kbi_u.lastname, kbi_u.firstname, kbi_f.name','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"name\":{\"key\":\"name\",\"title\":\"lang::report_field_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"posts\":{\"key\":\"posts\",\"title\":\"lang::report_field_posts_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"discussions\":{\"key\":\"discussions\",\"title\":\"lang::report_field_discussions_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646821),
(92,'kbi_el_scorm_activity_detail','lang::report_page_077_title::local_kopere_bi',87,1,'table','light','','','','SELECT t.*,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_u.idnumber,\n       kbi_u.id               AS user_id,\n       kbi_s.name,\n       kbi_c.fullname,\n       kbi_cmc.completionstate,\n       kbi_cmc.timemodified   AS completiondate,\n       round(sg.score, 0) AS score,\n       l.timespend        AS timespend_on_course,\n       ue.status          AS enrol_status,\n       kbi_s.completionscorerequired,\n       kbi_s.completionstatusrequired,\n       kbi_s.completionstatusallscos,\n       kbi_s.id               AS scorm_id,\n       sg.finalgrade,\n       sg.rawgrademax,\n       kbi_cm.completionexpected,\n       kbi_cm.completiongradeitemnumber,\n       kbi_cm.completionview,\n       kbi_cm.completion,\n       kbi_s.grademethod      AS scorm_grade_method,\n       l.visits           AS visits_on_course,\n       ue.timeend,\n       \'\'                 as cohortname\nFROM mdl_scorm kbi_s\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_s.course\n       JOIN mdl_modules kbi_m ON kbi_m.name = \'scorm\'\n       JOIN mdl_course_modules kbi_cm ON kbi_cm.module = kbi_m.id AND kbi_cm.instance = kbi_s.id\n       JOIN (SELECT kbi_e.courseid, kbi_ue1.userid, MIN(kbi_ue1.status) AS status, MIN(kbi_ue1.timeend) AS timeend\n             FROM mdl_enrol kbi_e\n                    JOIN mdl_user_enrolments kbi_ue1 ON kbi_ue1.enrolid = kbi_e.id\n             WHERE kbi_e.id > 0\n               AND kbi_e.courseid = :courseid\n             GROUP BY kbi_e.courseid, kbi_ue1.userid) ue ON ue.courseid = kbi_c.id\n       JOIN mdl_user kbi_u ON kbi_u.id = ue.userid\n       LEFT JOIN (SELECT courseid,\n                         userid,\n                         SUM(timespend) AS timespend,\n                         SUM(visits)    AS visits\n                  FROM mdl_local_kopere_bi_tracking\n                  GROUP BY courseid, userid) l ON l.courseid = kbi_c.id AND l.userid = kbi_u.id\n       LEFT JOIN (SELECT MIN(kbi_sst.id)                                                              AS id,\n                         kbi_sst.userid,\n                         kbi_sst.scormid,\n                         MAX(kbi_sst.timemodified)                                                    AS timemodified,\n                         MIN(CASE WHEN kbi_sst.element = \'x.start.time\' THEN kbi_sst.value ELSE null END) AS starttime,\n                         SUM(TIME_TO_SEC(CASE\n                                           WHEN kbi_sst.element = \'cmi.core.total_time\'\n                                                   THEN kbi_sst.value\n                                           WHEN kbi_sst.element = \'cmi.total_time\'\n                                                   THEN (CASE\n                                                           WHEN kbi_sst.value LIKE \'PT%H%M%.%S\'\n                                                                   THEN STR_TO_DATE(kbi_sst.value, \'PT%HH%iM%kbi_s.%fS\')\n                                                           WHEN kbi_sst.value LIKE \'PT%H%M%S\'\n                                                                   THEN STR_TO_DATE(kbi_sst.value, \'PT%HH%iM%sS\')\n                                                           WHEN kbi_sst.value LIKE \'PT%M%.%S\'\n                                                                   THEN STR_TO_DATE(kbi_sst.value, \'PT%iM%kbi_s.%fS\')\n                                                           WHEN kbi_sst.value LIKE \'PT%M%S\'\n                                                                   THEN STR_TO_DATE(kbi_sst.value, \'PT%iM%sS\')\n                                                           WHEN kbi_sst.value LIKE \'PT%.%S\'\n                                                                   THEN STR_TO_DATE(kbi_sst.value, \'PT%kbi_s.%fS\')\n                                                           WHEN kbi_sst.value LIKE \'PT%S\'\n                                                                   THEN STR_TO_DATE(kbi_sst.value, \'PT%sS\')\n                                 END)\n                                           ELSE NULL END))                                        AS duration,\n                         GROUP_CONCAT(CASE\n                                        WHEN kbi_sst.attempt = 1 AND\n                                             kbi_sst.element IN (\'cmi.completion_status\', \'cmi.core.lesson_status\') AND\n                                             kbi_sst.value IN (\'completed\', \'passed\') THEN \'lang::report_sql_status_completed::local_kopere_bi\'\n                                        ELSE \'\' END SEPARATOR\n                                      \'\')                                                         AS first_completion_status,\n                         GROUP_CONCAT(CASE\n                                        WHEN kbi_sst.attempt = la.last_attempt_number AND\n                                             kbi_sst.element IN (\'cmi.completion_status\', \'cmi.core.lesson_status\') AND\n                                             kbi_sst.value IN (\'completed\', \'passed\')\n                                                THEN \'lang::report_sql_status_completed::local_kopere_bi\'\n                                        ELSE \'\'\n                                          END SEPARATOR\n                                      \'\')                                                         AS current_completion_status,\n                         COUNT(DISTINCT(kbi_sst.attempt))                                             as attempts\n                  FROM mdl_scorm_scoes_track kbi_sst\n                         JOIN mdl_scorm kbi_s1 ON kbi_s1.id = kbi_sst.scormid\n                         JOIN (SELECT userid, scormid, MAX(attempt) AS last_attempt_number\n                               FROM mdl_scorm_scoes_track\n                               GROUP BY userid, scormid) la ON la.userid = kbi_sst.userid AND la.scormid = kbi_sst.scormid\n                  WHERE kbi_sst.id > 0\n                    AND kbi_s1.course = :courseid\n                  GROUP BY kbi_sst.userid, kbi_sst.scormid) t ON t.scormid = kbi_s.id AND t.userid = kbi_u.id\n       LEFT JOIN mdl_course_modules_completion kbi_cmc ON kbi_cmc.coursemoduleid = kbi_cm.id AND kbi_cmc.userid = kbi_u.id\n       LEFT JOIN (SELECT kbi_gi.iteminstance,\n                         ROUND((CASE\n                                  WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                                  ELSE kbi_g.finalgrade END), 0) AS score,\n                         kbi_g.userid,\n                         kbi_g.finalgrade,\n                         kbi_g.rawgrademax\n                  FROM mdl_grade_items kbi_gi, mdl_grade_grades kbi_g\n                  WHERE kbi_gi.itemmodule = \'scorm\'\n                    and kbi_g.itemid = kbi_gi.id\n                    AND kbi_g.finalgrade IS NOT NULL\n                    AND kbi_gi.outcomeid IS NULL\n                  GROUP BY kbi_gi.iteminstance, kbi_g.userid, kbi_g.rawgrademax, kbi_g.finalgrade, kbi_gi.scaleid, kbi_g.feedback, kbi_gi.gradetype,\n                           kbi_g.rawgrademin, kbi_gi.courseid) sg ON sg.iteminstance = t.scormid and sg.userid = t.userid\nWHERE ue.userid > 0\n  AND kbi_c.id = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_cm.visible = 1\nORDER BY kbi_c.fullname, kbi_s.name, kbi_u.lastname, kbi_u.firstname','1h','none','{\"column\":{\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{user_id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"idnumber\":{\"key\":\"idnumber\",\"title\":\"lang::report_field_idnumber_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"user_id\":{\"key\":\"user_id\",\"title\":\"lang::report_field_user_id_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"name\":{\"key\":\"name\",\"title\":\"lang::report_field_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"completionstate\":{\"key\":\"completionstate\",\"title\":\"lang::report_field_completionstate_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"completiondate\":{\"key\":\"completiondate\",\"title\":\"lang::report_field_completiondate_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"score\":{\"key\":\"score\",\"title\":\"lang::report_field_score_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend_on_course\":{\"key\":\"timespend_on_course\",\"title\":\"lang::report_field_timespend_on_course_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"enrol_status\":{\"key\":\"enrol_status\",\"title\":\"lang::report_field_enrol_status_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"completionscorerequired\":{\"key\":\"completionscorerequired\",\"title\":\"lang::report_field_completionscorerequired_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completionstatusrequired\":{\"key\":\"completionstatusrequired\",\"title\":\"lang::report_field_completionstatusrequired_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"completionstatusallscos\":{\"key\":\"completionstatusallscos\",\"title\":\"lang::report_field_completionstatusallscos_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"scorm_id\":{\"key\":\"scorm_id\",\"title\":\"lang::report_field_scorm_id_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"finalgrade\":{\"key\":\"finalgrade\",\"title\":\"lang::report_field_finalgrade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"rawgrademax\":{\"key\":\"rawgrademax\",\"title\":\"lang::report_field_rawgrademax_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completionexpected\":{\"key\":\"completionexpected\",\"title\":\"lang::report_field_completionexpected_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"completiongradeitemnumber\":{\"key\":\"completiongradeitemnumber\",\"title\":\"lang::report_field_completiongradeitemnumber_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completionview\":{\"key\":\"completionview\",\"title\":\"lang::report_field_completionview_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"completion\":{\"key\":\"completion\",\"title\":\"lang::report_field_completion_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"scorm_grade_method\":{\"key\":\"scorm_grade_method\",\"title\":\"lang::report_field_scorm_grade_method_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"visits_on_course\":{\"key\":\"visits_on_course\",\"title\":\"lang::report_field_visits_on_course_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timeend\":{\"key\":\"timeend\",\"title\":\"lang::report_field_timeend_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"cohortname\":{\"key\":\"cohortname\",\"title\":\"lang::report_field_cohortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646821),
(93,'kbi_el_scorm_activity_summary_by_course','lang::report_page_078_title::local_kopere_bi',88,1,'table','light','','','','SELECT kbi_s.id,\n       kbi_c.fullname,\n       kbi_s.name,\n       kbi_s.timemodified,\n       SUM(CASE WHEN element = \'x.start.time\' THEN 1 ELSE 0 END) AS attempts,\n       MAX(sl.visits)                                            AS visits,\n       SUM(CASE\n             WHEN element = \'cmi.core.total_time\' THEN TIME_TO_SEC(value)\n             ELSE 0 END)                                         AS duration\nFROM mdl_scorm kbi_s\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_s.course\n       LEFT JOIN mdl_scorm_scoes_track kbi_sst\n         ON kbi_sst.scormid = kbi_s.id AND (element = \'cmi.core.total_time\' OR element = \'x.start.time\')\nWHERE kbi_s.id > 0\n  AND kbi_c.id = :courseid\n  AND kbi_c.visible = 1\nGROUP BY kbi_s.id, kbi_c.id\nORDER BY kbi_c.fullname, kbi_s.name','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"name\":{\"key\":\"name\",\"title\":\"lang::report_field_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timemodified\":{\"key\":\"timemodified\",\"title\":\"lang::report_field_timemodified_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"attempts\":{\"key\":\"attempts\",\"title\":\"lang::report_field_attempts_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"duration\":{\"key\":\"duration\",\"title\":\"lang::report_field_duration_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646821),
(94,'kbi_el_scorm_occurrence_s_by_course','lang::report_page_079_title::local_kopere_bi',89,1,'table','light','','','','SELECT kbi_c.id,\n       kbi_c.fullname,\n       count(kbi_s.id) as scorms,\n       (SELECT DISTINCT CONCAT(kbi_u.firstname, \' \', kbi_u.lastname)\n        FROM mdl_role_assignments kbi_ra\n               JOIN mdl_user kbi_u ON kbi_ra.userid = kbi_u.id\n               JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n        WHERE kbi_ctx.instanceid = kbi_c.id\n          AND kbi_ctx.contextlevel = 50\n          AND kbi_ra.roleid = 3\n        LIMIT 1)   AS teacher\nFROM mdl_course kbi_c\n       LEFT JOIN mdl_scorm kbi_s ON kbi_s.course = kbi_c.id\nWHERE kbi_c.category > 0\n  AND kbi_c.id = :courseid\n  AND kbi_c.visible = 1\nGROUP BY kbi_c.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"scorms\":{\"key\":\"scorms\",\"title\":\"lang::report_field_scorms_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teacher\":{\"key\":\"teacher\",\"title\":\"lang::report_field_teacher_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646821),
(95,'kbi_el_assignment_submission_status','lang::report_page_080_title::local_kopere_bi',90,1,'table','light','','','','SELECT kbi_a.name                               as assignment,\n       kbi_a.duedate,\n       kbi_c.fullname                           as course,\n       kbi_s.status,\n       kbi_s.timemodified                       AS submitted,\n       kbi_u.email,\n       kbi_u.idnumber,\n       kbi_u.phone1,\n       kbi_u.phone2,\n       kbi_u.institution,\n       kbi_u.department,\n       kbi_u.address,\n       kbi_u.city,\n       kbi_u.country,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       ROUND((CASE\n                WHEN kbi_gg.rawgrademax > 0 THEN (kbi_gg.finalgrade / kbi_gg.rawgrademax) * 100\n                ELSE kbi_gg.finalgrade END), 0) AS grade\nFROM mdl_assign kbi_a\n       LEFT JOIN (SELECT kbi_e.courseid, kbi_ue.userid\n                  FROM mdl_user_enrolments kbi_ue, mdl_enrol kbi_e\n                  WHERE kbi_e.id = kbi_ue.enrolid\n                  GROUP BY kbi_e.courseid, kbi_ue.userid) ue ON kbi_ue.courseid = kbi_a.course\n       LEFT JOIN mdl_user kbi_u ON kbi_u.id = kbi_ue.userid\n       LEFT JOIN mdl_assign_submission kbi_s ON kbi_s.assignment = kbi_a.id AND kbi_s.userid = kbi_u.id\n       LEFT JOIN mdl_course kbi_c ON kbi_c.id = kbi_a.course\n       LEFT JOIN mdl_modules kbi_m ON kbi_m.name = \'assign\'\n       LEFT JOIN mdl_course_modules kbi_cm ON kbi_cm.instance = kbi_a.id AND kbi_cm.module = kbi_m.id\n       LEFT JOIN mdl_grade_items kbi_gi\n         ON kbi_gi.courseid = kbi_c.id AND kbi_gi.itemtype = \'mod\' AND kbi_gi.itemmodule = kbi_m.name AND kbi_gi.iteminstance = kbi_cm.instance\n       LEFT JOIN mdl_grade_grades kbi_gg ON kbi_gg.itemid = kbi_gi.id AND kbi_gg.userid = kbi_u.id\nWHERE kbi_a.id > 0\n  AND kbi_c.id = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_cm.visible = 1\n  AND (kbi_s.timemodified > kbi_a.duedate or kbi_s.timemodified IS NULL)\nORDER BY kbi_c.fullname, kbi_a.name, kbi_u.lastname, kbi_u.firstname','1h','none','{\"column\":{\"assignment\":{\"key\":\"assignment\",\"title\":\"lang::report_field_assignment_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"duedate\":{\"key\":\"duedate\",\"title\":\"lang::report_field_duedate_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"status\":{\"key\":\"status\",\"title\":\"lang::report_field_status_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"submitted\":{\"key\":\"submitted\",\"title\":\"lang::report_field_submitted_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"idnumber\":{\"key\":\"idnumber\",\"title\":\"lang::report_field_idnumber_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"phone1\":{\"key\":\"phone1\",\"title\":\"lang::report_field_phone1_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone1}}}\\\" target=\\\"_blank\\\">{{{phone1}}}<\\/a>\"},\"phone2\":{\"key\":\"phone2\",\"title\":\"lang::report_field_phone2_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"tel:{{{phone2}}}\\\" target=\\\"_blank\\\">{{{phone2}}}<\\/a>\"},\"institution\":{\"key\":\"institution\",\"title\":\"lang::report_field_institution_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"department\":{\"key\":\"department\",\"title\":\"lang::report_field_department_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"address\":{\"key\":\"address\",\"title\":\"lang::report_field_address_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"city\":{\"key\":\"city\",\"title\":\"lang::report_field_city_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"country\":{\"key\":\"country\",\"title\":\"lang::report_field_country_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646821),
(96,'kbi_el_assignment_submissions_review','lang::report_page_081_title::local_kopere_bi',91,1,'table','light','','','','SELECT kbi_ass_s.id,\n       kbi_c.fullname                     AS course,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.idnumber,\n       kbi_u.id                           AS userid,\n       kbi_ass.name                       AS assignment,\n       kbi_u.lastaccess,\n       kbi_ass_s.timecreated              AS date_first_submission,\n       kbi_ass_g.grade                    AS grade_first_submission,\n       kbi_ass_g.timemodified             AS grade_time_first_submission,\n       first_submission_file.filename AS first_submission_file,\n       kbi_cmc.completionstate,\n       kbi_ass_sl.timemodified            AS date_last_submission,\n       kbi_ass_gl.grade                   AS grade_last_submission,\n       kbi_ass_gl.timemodified            AS grade_time_last_submission,\n       last_submission_file.filename  AS last_submission_file,\n       kbi_ass_s.attemptnumber,\n       kbi_ass_sl.attemptnumber           AS attemptnumber2,\n       kbi_sc.scale\nFROM mdl_course kbi_c\n       LEFT JOIN mdl_context kbi_con ON kbi_con.contextlevel = 50 AND kbi_con.instanceid = kbi_c.id\n       LEFT JOIN mdl_role_assignments kbi_ra ON kbi_ra.contextid = kbi_con.id AND kbi_ra.roleid = 5\n       LEFT JOIN mdl_user kbi_u ON kbi_u.id = kbi_ra.userid\n       LEFT JOIN mdl_assign kbi_ass ON kbi_c.id = kbi_ass.course\n       LEFT JOIN mdl_assign_submission kbi_ass_s\n         ON kbi_ass_s.assignment = kbi_ass.id AND kbi_ass_s.attemptnumber = 0 AND kbi_ass_s.userid = kbi_u.id AND kbi_ass_s.status = \'submitted\'\n       LEFT JOIN mdl_assign_grades kbi_ass_g ON kbi_ass_g.userid = kbi_ass_s.userid AND kbi_ass_g.assignment = kbi_ass_s.assignment AND\n                                            kbi_ass_g.attemptnumber = kbi_ass_s.attemptnumber\n       LEFT JOIN (SELECT kbi_f.itemid, GROUP_CONCAT(DISTINCT CONCAT(kbi_f.filename) SEPARATOR \', \') AS filename\n                  FROM mdl_files kbi_f\n                  WHERE kbi_f.component = \'assignsubmission_file\'\n                    AND kbi_f.filearea = \'submission_files\'\n                    AND kbi_f.filesize > 0\n                  GROUP BY kbi_f.itemid) first_submission_file ON first_submission_file.itemid = kbi_ass_s.id\n       LEFT JOIN mdl_assign_submission kbi_ass_sl\n         ON kbi_ass_sl.assignment = kbi_ass.id AND kbi_ass_sl.latest = 1 AND kbi_ass_sl.userid = kbi_ass_s.userid AND kbi_ass_sl.id <> kbi_ass_s.id\n       LEFT JOIN mdl_assign_grades kbi_ass_gl ON kbi_ass_gl.userid = kbi_ass_sl.userid AND kbi_ass_gl.assignment = kbi_ass_sl.assignment AND\n                                             kbi_ass_gl.attemptnumber = kbi_ass_sl.attemptnumber\n       LEFT JOIN (SELECT kbi_f.itemid, GROUP_CONCAT(DISTINCT CONCAT(kbi_f.filename) SEPARATOR \', \') AS filename\n                  FROM mdl_files kbi_f\n                  WHERE kbi_f.component = \'assignsubmission_file\'\n                    AND kbi_f.filearea = \'submission_files\'\n                    AND kbi_f.filesize > 0\n                  GROUP BY kbi_f.itemid) last_submission_file ON last_submission_file.itemid = kbi_ass_sl.id\n       JOIN mdl_modules kbi_m ON kbi_m.name = \'assign\'\n       LEFT JOIN mdl_course_modules kbi_cm ON kbi_cm.course = kbi_ass.course AND kbi_cm.module = kbi_m.id AND kbi_cm.instance = kbi_ass.id\n       LEFT JOIN mdl_course_modules_completion kbi_cmc ON kbi_cmc.userid = kbi_ass_s.userid AND kbi_cmc.coursemoduleid = kbi_cm.id\n       LEFT JOIN mdl_grade_items kbi_gi\n         ON kbi_gi.courseid = kbi_ass.course AND kbi_gi.itemtype = \'mod\' AND kbi_gi.itemmodule = \'assign\' AND kbi_gi.iteminstance = kbi_ass.id\n       LEFT JOIN mdl_scale kbi_sc ON kbi_sc.id = kbi_gi.scaleid\nWHERE kbi_u.id IS NOT NULL','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"idnumber\":{\"key\":\"idnumber\",\"title\":\"lang::report_field_idnumber_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"assignment\":{\"key\":\"assignment\",\"title\":\"lang::report_field_assignment_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"lastaccess\":{\"key\":\"lastaccess\",\"title\":\"lang::report_field_lastaccess_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"date_first_submission\":{\"key\":\"date_first_submission\",\"title\":\"lang::report_field_date_first_submission_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"grade_first_submission\":{\"key\":\"grade_first_submission\",\"title\":\"lang::report_field_grade_first_submission_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade_time_first_submission\":{\"key\":\"grade_time_first_submission\",\"title\":\"lang::report_field_grade_time_first_submission_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"first_submission_file\":{\"key\":\"first_submission_file\",\"title\":\"lang::report_field_first_submission_file_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"completionstate\":{\"key\":\"completionstate\",\"title\":\"lang::report_field_completionstate_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"date_last_submission\":{\"key\":\"date_last_submission\",\"title\":\"lang::report_field_date_last_submission_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"grade_last_submission\":{\"key\":\"grade_last_submission\",\"title\":\"lang::report_field_grade_last_submission_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade_time_last_submission\":{\"key\":\"grade_time_last_submission\",\"title\":\"lang::report_field_grade_time_last_submission_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"last_submission_file\":{\"key\":\"last_submission_file\",\"title\":\"lang::report_field_last_submission_file_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"attemptnumber\":{\"key\":\"attemptnumber\",\"title\":\"lang::report_field_attemptnumber_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"attemptnumber2\":{\"key\":\"attemptnumber2\",\"title\":\"lang::report_field_attemptnumber2_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"scale\":{\"key\":\"scale\",\"title\":\"lang::report_field_scale_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646822),
(97,'kbi_el_feedback_details','lang::report_page_082_title::local_kopere_bi',92,1,'table','light','','','','SELECT kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_mfc.timemodified                    as feedback_time,\n       kbi_cc.timecompleted,\n       kbi_mfi.presentation,\n       kbi_mfi.typ,\n       kbi_mfi.id                              AS q_id,\n       kbi_mfi.label                           AS question_number,\n       kbi_mfi.name                            as question,\n       kbi_mfv.value                           as answer,\n       kbi_mf.name                             as feedback,\n       kbi_mf.id                               as feedback_id,\n       kbi_c.id                                as course_id,\n       kbi_c.idnumber                          as course_idnumber,\n       kbi_c.fullname                          as course_name,\n       kbi_c.shortname                         as course_shortname,\n       ROUND((CASE\n                WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                ELSE kbi_g.finalgrade END), 0) AS grade\nFROM mdl_feedback kbi_mf\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_mf.course\n       JOIN mdl_feedback_item kbi_mfi ON kbi_mfi.feedback = kbi_mf.id\n       LEFT JOIN mdl_feedback_value kbi_mfv ON kbi_mfv.item = kbi_mfi.id\n       LEFT JOIN mdl_feedback_completed kbi_mfc ON kbi_mfc.id = kbi_mfv.completed\n       LEFT JOIN mdl_user kbi_u ON kbi_mfc.userid = kbi_u.id\n       LEFT JOIN mdl_grade_items kbi_gi ON kbi_gi.itemtype = \'course\' AND kbi_gi.courseid = kbi_c.id\n       LEFT JOIN mdl_grade_grades kbi_g ON kbi_g.userid = kbi_u.id AND kbi_g.itemid = kbi_gi.id AND kbi_g.finalgrade IS NOT NULL\n       LEFT JOIN mdl_course_completions kbi_cc ON kbi_cc.userid = kbi_u.id AND kbi_cc.course = kbi_c.id\nWHERE kbi_mf.id > 0\n  AND kbi_mf.course = :courseid\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1','1h','none','{\"column\":{\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"feedback_time\":{\"key\":\"feedback_time\",\"title\":\"lang::report_field_feedback_time_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"timecompleted\":{\"key\":\"timecompleted\",\"title\":\"lang::report_field_timecompleted_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"presentation\":{\"key\":\"presentation\",\"title\":\"lang::report_field_presentation_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"typ\":{\"key\":\"typ\",\"title\":\"lang::report_field_typ_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"q_id\":{\"key\":\"q_id\",\"title\":\"lang::report_field_q_id_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"question_number\":{\"key\":\"question_number\",\"title\":\"lang::report_field_question_number_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"question\":{\"key\":\"question\",\"title\":\"lang::report_field_question_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"answer\":{\"key\":\"answer\",\"title\":\"lang::report_field_answer_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"feedback\":{\"key\":\"feedback\",\"title\":\"lang::report_field_feedback_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"feedback_id\":{\"key\":\"feedback_id\",\"title\":\"lang::report_field_feedback_id_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course_id\":{\"key\":\"course_id\",\"title\":\"lang::report_field_course_id_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course_idnumber\":{\"key\":\"course_idnumber\",\"title\":\"lang::report_field_course_idnumber_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course_name\":{\"key\":\"course_name\",\"title\":\"lang::report_field_course_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"course_shortname\":{\"key\":\"course_shortname\",\"title\":\"lang::report_field_course_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"grade\":{\"key\":\"grade\",\"title\":\"lang::report_field_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646822),
(98,'kbi_el_feedback_overview_report','lang::report_page_083_title::local_kopere_bi',93,1,'table','light','','','','SELECT kbi_fi.id,\n       kbi_fi.name,\n       CASE\n         WHEN kbi_fi.typ = \'multichoicerated\'\n                 THEN AVG(\n                        SUBSTRING_INDEX(SUBSTRING_INDEX(REPLACE(kbi_fi.presentation, \'>>>>>\', \'|\'), \'\n                                        -1))\n         ELSE AVG(kbi_fv.value)\n           END AS avg_value\nFROM mdl_feedback kbi_f\n       JOIN mdl_feedback_completed kbi_fc ON kbi_fc.feedback = kbi_f.id\n       JOIN mdl_feedback_item kbi_fi ON kbi_fi.feedback = kbi_f.id\n       JOIN mdl_feedback_value kbi_fv ON kbi_fv.completed = kbi_fc.id AND kbi_fv.item = kbi_fi.id\n       LEFT JOIN mdl_modules kbi_m ON kbi_m.name = \'feedback\'\n       LEFT JOIN mdl_course_modules kbi_cm ON kbi_cm.module = kbi_m.id AND kbi_cm.instance = kbi_f.id\nWHERE kbi_f.id > 0\nGROUP BY kbi_fi.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"name\":{\"key\":\"name\",\"title\":\"lang::report_field_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646822),
(99,'kbi_el_competency_evidence','lang::report_page_084_title::local_kopere_bi',94,1,'table','light','','','','SELECT kbi_ce.id,\n       kbi_u.id AS userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_c.shortname,\n       kbi_ce.url,\n       kbi_ce.descidentifier,\n       kbi_ce.desccomponent,\n       kbi_ce.desca,\n       kbi_ce.timecreated\nFROM mdl_competency_evidence kbi_ce\n       LEFT JOIN mdl_competency_usercomp kbi_cu ON kbi_ce.usercompetencyid = kbi_cu.id\n       LEFT JOIN mdl_competency kbi_c ON kbi_c.id = kbi_cu.competencyid\n       LEFT JOIN mdl_user kbi_u ON kbi_u.id = kbi_cu.userid\nWHERE kbi_u.id IS NOT NULL\nORDER BY kbi_u.lastname, kbi_u.firstname, kbi_ce.timecreated DESC','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"url\":{\"key\":\"url\",\"title\":\"lang::report_field_url_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"descidentifier\":{\"key\":\"descidentifier\",\"title\":\"lang::report_field_descidentifier_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"desccomponent\":{\"key\":\"desccomponent\",\"title\":\"lang::report_field_desccomponent_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"desca\":{\"key\":\"desca\",\"title\":\"lang::report_field_desca_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timecreated\":{\"key\":\"timecreated\",\"title\":\"lang::report_field_timecreated_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"}}}',1780646822),
(100,'kbi_el_course_outcomes','lang::report_page_085_title::local_kopere_bi',95,1,'table','light','','','','SELECT kbi_gi.id,\n       kbi_gi.itemname                            as activity,\n       kbi_c.shortname                            as course_shortname,\n       kbi_c.fullname                             as course_fullname,\n       kbi_o.fullname                             as outcome_fullname,\n       kbi_o.shortname                            as outcome_shortname,\n       kbi_o.description                          as outcome_description,\n       kbi_sci.scale,\n       kbi_ca.name                                as category,\n       kbi_c.startdate,\n       ROUND(AVG(CASE\n                   WHEN kbi_g.rawgrademax > 0 THEN (kbi_g.finalgrade / kbi_g.rawgrademax) * 100\n                   ELSE kbi_g.finalgrade END), 0) AS average_grade,\n       COUNT(DISTINCT kbi_g.id)                   AS grades\nFROM mdl_grade_outcomes kbi_o\n       LEFT JOIN mdl_course kbi_c ON kbi_c.id = kbi_o.courseid\n       LEFT JOIN mdl_course_categories kbi_ca ON kbi_ca.id = kbi_c.category\n       LEFT JOIN mdl_scale kbi_sci ON kbi_sci.id = kbi_o.scaleid\n       LEFT JOIN mdl_grade_items kbi_gi ON kbi_gi.outcomeid = kbi_o.id\n       LEFT JOIN mdl_grade_grades kbi_g ON kbi_g.itemid = kbi_gi.id\nWHERE kbi_gi.itemtype = \'mod\'\n  AND kbi_c.id = :courseid\nGROUP BY kbi_gi.id,\n         kbi_g.itemid,\n         kbi_gi.itemname,\n         kbi_c.shortname,\n         kbi_c.fullname,\n         kbi_o.fullname,\n         kbi_o.shortname,\n         kbi_o.description,\n         kbi_sci.scale,\n         kbi_ca.name,\n         kbi_c.startdate\nORDER BY kbi_c.fullname, kbi_gi.itemname, kbi_o.fullname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"activity\":{\"key\":\"activity\",\"title\":\"lang::report_field_activity_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"course_shortname\":{\"key\":\"course_shortname\",\"title\":\"lang::report_field_course_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"course_fullname\":{\"key\":\"course_fullname\",\"title\":\"lang::report_field_course_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"outcome_fullname\":{\"key\":\"outcome_fullname\",\"title\":\"lang::report_field_outcome_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"outcome_shortname\":{\"key\":\"outcome_shortname\",\"title\":\"lang::report_field_outcome_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"outcome_description\":{\"key\":\"outcome_description\",\"title\":\"lang::report_field_outcome_description_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"scale\":{\"key\":\"scale\",\"title\":\"lang::report_field_scale_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"category\":{\"key\":\"category\",\"title\":\"lang::report_field_category_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"startdate\":{\"key\":\"startdate\",\"title\":\"lang::report_field_startdate_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"average_grade\":{\"key\":\"average_grade\",\"title\":\"lang::report_field_average_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grades\":{\"key\":\"grades\",\"title\":\"lang::report_field_grades_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646822),
(101,'kbi_el_learning_plan_progress','lang::report_page_086_title::local_kopere_bi',96,1,'table','light','','','','SELECT kbi_cp.id,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.id                                                  AS userid,\n       kbi_cp.name,\n       kbi_cp.timecreated,\n       kbi_cp.status,\n       CASE\n         WHEN ROUND((SUM(kbi_cu.proficiency) / COUNT(kbi_ctc.id)) * 100, 2) >= 100 THEN MAX(kbi_cu.timecreated)\n         ELSE 0 END                                          AS completion_date,\n       ROUND((SUM(kbi_cu.proficiency) / COUNT(kbi_ctc.id)) * 100, 2) AS progress,\n       kbi_cp.templateid\nFROM mdl_competency_template kbi_ct\n       LEFT JOIN mdl_competency_templatecomp kbi_ctc ON kbi_ctc.templateid = kbi_ct.id\n       LEFT JOIN mdl_competency_plan kbi_cp ON kbi_cp.templateid = kbi_ct.id\n       LEFT JOIN mdl_competency_usercomp kbi_cu ON kbi_cu.competencyid = kbi_ctc.competencyid AND kbi_cu.userid = kbi_cp.userid\n       LEFT JOIN mdl_user kbi_u ON kbi_u.id = kbi_cp.userid\nWHERE kbi_cp.id IS NOT NULL\nGROUP BY kbi_cp.id, kbi_u.id\nORDER BY kbi_u.lastname, kbi_u.firstname, kbi_cp.name','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"name\":{\"key\":\"name\",\"title\":\"lang::report_field_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timecreated\":{\"key\":\"timecreated\",\"title\":\"lang::report_field_timecreated_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"status\":{\"key\":\"status\",\"title\":\"lang::report_field_status_title::local_kopere_bi\",\"type\":\"status\",\"mustache\":\"\"},\"completion_date\":{\"key\":\"completion_date\",\"title\":\"lang::report_field_completion_date_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"progress\":{\"key\":\"progress\",\"title\":\"lang::report_field_progress_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"templateid\":{\"key\":\"templateid\",\"title\":\"lang::report_field_templateid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646822),
(102,'kbi_el_learning_plan_progress_details','lang::report_page_087_title::local_kopere_bi',97,1,'table','light','','','','SELECT kbi_u.id, kbi_u.firstname, kbi_u.lastname, kbi_u.email\nFROM mdl_competency_plan kbi_cp\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_cp.userid\nWHERE kbi_cp.templateid > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\nORDER BY kbi_u.lastname, kbi_u.firstname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{id}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"}}}',1780646822),
(103,'kbi_el_quiz_answer_details','lang::report_page_088_title::local_kopere_bi',98,1,'table','light','','','','SELECT CONCAT(kbi_qa.id, \'-\', kbi_qatt.slot) AS id,\n       kbi_c.id                              AS courseid,\n       kbi_c.fullname                        AS course,\n       kbi_cm.id                             AS cmid,\n       kbi_qz.id                             AS quizid,\n       kbi_qz.name                           AS quiz_name,\n       kbi_u.id                              AS userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_qa.id                             AS quiz_attempt_id,\n       kbi_qa.attempt,\n       kbi_qa.timestart,\n       kbi_qa.timefinish,\n       kbi_qa.state                          AS attempt_state,\n       kbi_qatt.slot,\n       kbi_q.id                              AS questionid,\n       kbi_q.name                            AS question_name,\n       kbi_q.qtype,\n       kbi_qatt.questionsummary,\n       kbi_qatt.responsesummary,\n       kbi_qatt.rightanswer,\n       kbi_qas.state                         AS question_state,\n       kbi_qas.fraction,\n       ROUND(kbi_qatt.maxmark * COALESCE(kbi_qas.fraction, 0), 2) AS question_grade,\n       kbi_qatt.maxmark,\n       CASE\n         WHEN kbi_qas.state = \'gradedright\' THEN 1\n         ELSE 0\n       END AS is_correct\nFROM mdl_quiz_attempts kbi_qa\n       JOIN mdl_quiz kbi_qz ON kbi_qz.id = kbi_qa.quiz\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_qz.course\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_qa.userid\n       JOIN mdl_question_attempts kbi_qatt ON kbi_qatt.questionusageid = kbi_qa.uniqueid\n       JOIN mdl_question kbi_q ON kbi_q.id = kbi_qatt.questionid\n       LEFT JOIN mdl_question_attempt_steps kbi_qas ON kbi_qas.questionattemptid = kbi_qatt.id\n             AND kbi_qas.sequencenumber = (\n                 SELECT MAX(kbi_qas2.sequencenumber)\n                 FROM mdl_question_attempt_steps kbi_qas2\n                 WHERE kbi_qas2.questionattemptid = kbi_qatt.id\n             )\n       JOIN mdl_modules kbi_m ON kbi_m.name = \'quiz\'\n       JOIN mdl_course_modules kbi_cm ON kbi_cm.course = kbi_c.id AND kbi_cm.module = kbi_m.id AND kbi_cm.instance = kbi_qz.id\nWHERE kbi_qa.preview = 0\n  AND kbi_c.visible = 1\n  AND kbi_cm.visible = 1\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username <> \'guest\'\nORDER BY kbi_c.fullname, kbi_qz.name, kbi_u.lastname, kbi_u.firstname, kbi_qa.attempt, kbi_qatt.slot','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"string\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"cmid\":{\"key\":\"cmid\",\"title\":\"lang::report_field_cmid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"quizid\":{\"key\":\"quizid\",\"title\":\"lang::report_field_quizid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"quiz_name\":{\"key\":\"quiz_name\",\"title\":\"lang::report_field_quiz_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/mod\\/quiz\\/view.php?id={{{cmid}}}\\\" target=\\\"quiz\\\">{{{quiz_name}}}<\\/a>\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"quiz_attempt_id\":{\"key\":\"quiz_attempt_id\",\"title\":\"lang::report_field_quiz_attempt_id_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"attempt\":{\"key\":\"attempt\",\"title\":\"lang::report_field_attempt_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timestart\":{\"key\":\"timestart\",\"title\":\"lang::report_field_timestart_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"timefinish\":{\"key\":\"timefinish\",\"title\":\"lang::report_field_timefinish_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"attempt_state\":{\"key\":\"attempt_state\",\"title\":\"lang::report_field_attempt_state_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"slot\":{\"key\":\"slot\",\"title\":\"lang::report_field_slot_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"questionid\":{\"key\":\"questionid\",\"title\":\"lang::report_field_questionid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"question_name\":{\"key\":\"question_name\",\"title\":\"lang::report_field_question_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"qtype\":{\"key\":\"qtype\",\"title\":\"lang::report_field_qtype_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"questionsummary\":{\"key\":\"questionsummary\",\"title\":\"lang::report_field_questionsummary_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"responsesummary\":{\"key\":\"responsesummary\",\"title\":\"lang::report_field_responsesummary_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"rightanswer\":{\"key\":\"rightanswer\",\"title\":\"lang::report_field_rightanswer_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"question_state\":{\"key\":\"question_state\",\"title\":\"lang::report_field_question_state_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"fraction\":{\"key\":\"fraction\",\"title\":\"lang::report_field_fraction_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"question_grade\":{\"key\":\"question_grade\",\"title\":\"lang::report_field_question_grade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"maxmark\":{\"key\":\"maxmark\",\"title\":\"lang::report_field_maxmark_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"is_correct\":{\"key\":\"is_correct\",\"title\":\"lang::report_field_is_correct_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646822),
(104,'kbi_el_quiz_score_details','lang::report_page_089_title::local_kopere_bi',99,1,'table','light','','','','SELECT kbi_qa.id                                                           AS id,\n       kbi_c.id                                                            AS courseid,\n       kbi_c.fullname                                                      AS course,\n       kbi_cm.id                                                           AS cmid,\n       kbi_qz.id                                                           AS quizid,\n       kbi_qz.name                                                         AS quiz_name,\n       kbi_u.id                                                            AS userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_qa.attempt,\n       kbi_qa.timestart,\n       kbi_qa.timefinish,\n       kbi_qa.state                                                        AS attempt_state,\n       COUNT(DISTINCT kbi_qatt.id)                                         AS questions,\n       SUM(kbi_qatt.maxmark)                                               AS question_maxmark,\n       ROUND(SUM(kbi_qatt.maxmark * COALESCE(kbi_qas.fraction, 0)), 2)     AS total_question_score,\n       ROUND(kbi_qa.sumgrades, 2)                                          AS rawgrade,\n       kbi_qz.sumgrades                                                    AS quiz_raw_max,\n       ROUND(CASE WHEN kbi_qz.sumgrades > 0 THEN kbi_qa.sumgrades * 100 / kbi_qz.sumgrades ELSE NULL END, 2) AS score_percent,\n       ROUND(CASE WHEN kbi_qz.sumgrades > 0 THEN kbi_qa.sumgrades * kbi_qz.grade / kbi_qz.sumgrades ELSE NULL END, 2) AS finalgrade,\n       kbi_qz.grade                                                        AS grademax,\n       kbi_gi.gradepass,\n       kbi_gg.finalgrade                                                   AS gradebook_finalgrade,\n       SUM(CASE WHEN kbi_qas.state = \'gradedright\' THEN 1 ELSE 0 END)      AS correct_answers,\n       SUM(CASE WHEN kbi_qas.state = \'gradedpartial\' THEN 1 ELSE 0 END)    AS partial_answers,\n       SUM(CASE WHEN kbi_qas.state = \'gradedwrong\' THEN 1 ELSE 0 END)      AS wrong_answers\nFROM mdl_quiz_attempts kbi_qa\n       JOIN mdl_quiz kbi_qz ON kbi_qz.id = kbi_qa.quiz\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_qz.course\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_qa.userid\n       JOIN mdl_question_attempts kbi_qatt ON kbi_qatt.questionusageid = kbi_qa.uniqueid\n       LEFT JOIN mdl_question_attempt_steps kbi_qas ON kbi_qas.questionattemptid = kbi_qatt.id\n             AND kbi_qas.sequencenumber = (\n                 SELECT MAX(kbi_qas2.sequencenumber)\n                 FROM mdl_question_attempt_steps kbi_qas2\n                 WHERE kbi_qas2.questionattemptid = kbi_qatt.id\n             )\n       JOIN mdl_modules kbi_m ON kbi_m.name = \'quiz\'\n       JOIN mdl_course_modules kbi_cm ON kbi_cm.course = kbi_c.id AND kbi_cm.module = kbi_m.id AND kbi_cm.instance = kbi_qz.id\n       LEFT JOIN mdl_grade_items kbi_gi ON kbi_gi.itemmodule = \'quiz\' AND kbi_gi.iteminstance = kbi_qz.id AND kbi_gi.courseid = kbi_c.id\n       LEFT JOIN mdl_grade_grades kbi_gg ON kbi_gg.itemid = kbi_gi.id AND kbi_gg.userid = kbi_u.id\nWHERE kbi_qa.preview = 0\n  AND kbi_c.visible = 1\n  AND kbi_cm.visible = 1\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username <> \'guest\'\nGROUP BY kbi_qa.id, kbi_c.id, kbi_cm.id, kbi_qz.id, kbi_u.id, kbi_gi.gradepass, kbi_gg.finalgrade\nORDER BY kbi_c.fullname, kbi_qz.name, kbi_u.lastname, kbi_u.firstname, kbi_qa.attempt','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"cmid\":{\"key\":\"cmid\",\"title\":\"lang::report_field_cmid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"quizid\":{\"key\":\"quizid\",\"title\":\"lang::report_field_quizid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"quiz_name\":{\"key\":\"quiz_name\",\"title\":\"lang::report_field_quiz_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/mod\\/quiz\\/view.php?id={{{cmid}}}\\\" target=\\\"quiz\\\">{{{quiz_name}}}<\\/a>\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"attempt\":{\"key\":\"attempt\",\"title\":\"lang::report_field_attempt_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timestart\":{\"key\":\"timestart\",\"title\":\"lang::report_field_timestart_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"timefinish\":{\"key\":\"timefinish\",\"title\":\"lang::report_field_timefinish_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"attempt_state\":{\"key\":\"attempt_state\",\"title\":\"lang::report_field_attempt_state_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"questions\":{\"key\":\"questions\",\"title\":\"lang::report_field_questions_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"question_maxmark\":{\"key\":\"question_maxmark\",\"title\":\"lang::report_field_question_maxmark_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"total_question_score\":{\"key\":\"total_question_score\",\"title\":\"lang::report_field_total_question_score_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"rawgrade\":{\"key\":\"rawgrade\",\"title\":\"lang::report_field_rawgrade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"quiz_raw_max\":{\"key\":\"quiz_raw_max\",\"title\":\"lang::report_field_quiz_raw_max_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"score_percent\":{\"key\":\"score_percent\",\"title\":\"lang::report_field_score_percent_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"finalgrade\":{\"key\":\"finalgrade\",\"title\":\"lang::report_field_finalgrade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grademax\":{\"key\":\"grademax\",\"title\":\"lang::report_field_grademax_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"gradepass\":{\"key\":\"gradepass\",\"title\":\"lang::report_field_gradepass_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"gradebook_finalgrade\":{\"key\":\"gradebook_finalgrade\",\"title\":\"lang::report_field_gradebook_finalgrade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"correct_answers\":{\"key\":\"correct_answers\",\"title\":\"lang::report_field_correct_answers_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"partial_answers\":{\"key\":\"partial_answers\",\"title\":\"lang::report_field_partial_answers_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"wrong_answers\":{\"key\":\"wrong_answers\",\"title\":\"lang::report_field_wrong_answers_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646822),
(105,'kbi_el_received_badges','lang::report_page_090_title::local_kopere_bi',100,1,'table','light','','','','SELECT kbi_bi.id,\n       kbi_u.id       AS userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_c.fullname as course,\n       kbi_c.id       AS cid,\n       kbi_b.name,\n       kbi_bi.dateissued,\n       kbi_bi.dateexpire\nFROM mdl_badge kbi_b\n       LEFT JOIN mdl_badge_issued kbi_bi ON kbi_bi.badgeid = kbi_b.id\n       LEFT JOIN mdl_user kbi_u ON kbi_u.id = kbi_bi.userid\n       LEFT JOIN mdl_course kbi_c ON kbi_c.id = kbi_b.courseid\nWHERE kbi_bi.id IS NOT NULL\n  AND kbi_bi.visible = 1\n  AND (kbi_b.courseid IS NOT NULL)\nORDER BY kbi_bi.dateissued DESC, kbi_u.lastname, kbi_u.firstname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{cid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"cid\":{\"key\":\"cid\",\"title\":\"lang::report_field_cid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"name\":{\"key\":\"name\",\"title\":\"lang::report_field_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"dateissued\":{\"key\":\"dateissued\",\"title\":\"lang::report_field_dateissued_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"dateexpire\":{\"key\":\"dateexpire\",\"title\":\"lang::report_field_dateexpire_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"}}}',1780646822),
(106,'kbi_el_course_access_by_day_and_period','lang::report_page_091_title::local_kopere_bi',101,1,'table','light','','','','SELECT CONCAT(kbi_t.courseid, \'-\', WEEKDAY(FROM_UNIXTIME(kbi_l.timepoint)), \'-\',\n              CASE\n                WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 6 THEN 1\n                WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 9 THEN 2\n                WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 12 THEN 3\n                WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 15 THEN 4\n                WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 18 THEN 5\n                WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 21 THEN 6\n                ELSE 7\n              END)                                                        AS id,\n       kbi_c.id                                                           AS courseid,\n       kbi_c.fullname                                                     AS course,\n       kbi_cc.name                                                        AS category_name,\n       WEEKDAY(FROM_UNIXTIME(kbi_l.timepoint))                            AS weekday_number,\n       CASE WEEKDAY(FROM_UNIXTIME(kbi_l.timepoint))\n         WHEN 0 THEN \'Monday\'\n         WHEN 1 THEN \'Tuesday\'\n         WHEN 2 THEN \'Wednesday\'\n         WHEN 3 THEN \'Thursday\'\n         WHEN 4 THEN \'Friday\'\n         WHEN 5 THEN \'Saturday\'\n         ELSE \'Sunday\'\n       END                                                                AS weekday_name,\n       CASE\n         WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 6 THEN \'00:00 - 05:59\'\n         WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 9 THEN \'06:00 - 08:59\'\n         WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 12 THEN \'09:00 - 11:59\'\n         WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 15 THEN \'12:00 - 14:59\'\n         WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 18 THEN \'15:00 - 17:59\'\n         WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 21 THEN \'18:00 - 20:59\'\n         ELSE \'21:00 - 23:59\'\n       END                                                                AS active_period,\n       SUM(kbi_l.visits)                                                  AS visits,\n       SUM(kbi_l.timespend)                                               AS timespend,\n       ROUND(SUM(kbi_l.timespend) / 3600, 2)                              AS hours_spent,\n       ROUND(SUM(kbi_l.timespend) * 100 / NULLIF(kbi_total.total_timespend, 0), 2) AS percent_of_course_time\nFROM mdl_local_kopere_bi_track_log kbi_l\n       JOIN mdl_local_kopere_bi_tracking kbi_t ON kbi_t.id = kbi_l.trackid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_t.courseid\n       LEFT JOIN mdl_course_categories kbi_cc ON kbi_cc.id = kbi_c.category\n       JOIN (\n             SELECT kbi_t2.courseid,\n                    SUM(kbi_l2.timespend) AS total_timespend\n             FROM mdl_local_kopere_bi_track_log kbi_l2\n                    JOIN mdl_local_kopere_bi_tracking kbi_t2 ON kbi_t2.id = kbi_l2.trackid\n             WHERE kbi_t2.courseid > 1\n             GROUP BY kbi_t2.courseid\n       ) kbi_total ON kbi_total.courseid = kbi_t.courseid\nWHERE kbi_t.courseid > 1\n  AND kbi_c.visible = 1\nGROUP BY kbi_c.id, kbi_cc.id, weekday_number, active_period, kbi_total.total_timespend\nORDER BY kbi_c.fullname, weekday_number, active_period','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"string\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"category_name\":{\"key\":\"category_name\",\"title\":\"lang::report_field_category_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"weekday_number\":{\"key\":\"weekday_number\",\"title\":\"lang::report_field_weekday_number_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"weekday_name\":{\"key\":\"weekday_name\",\"title\":\"lang::report_field_weekday_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"active_period\":{\"key\":\"active_period\",\"title\":\"lang::report_field_active_period_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"hours_spent\":{\"key\":\"hours_spent\",\"title\":\"lang::report_field_hours_spent_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"percent_of_course_time\":{\"key\":\"percent_of_course_time\",\"title\":\"lang::report_field_percent_of_course_time_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646822),
(107,'kbi_el_learner_access_by_day_and_period','lang::report_page_092_title::local_kopere_bi',102,1,'table','light','','','','SELECT CONCAT(kbi_t.courseid, \'-\', kbi_t.userid, \'-\', WEEKDAY(FROM_UNIXTIME(kbi_l.timepoint)), \'-\',\n              CASE\n                WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 6 THEN 1\n                WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 9 THEN 2\n                WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 12 THEN 3\n                WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 15 THEN 4\n                WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 18 THEN 5\n                WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 21 THEN 6\n                ELSE 7\n              END)                                                        AS id,\n       kbi_u.id                                                           AS userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_u.idnumber,\n       kbi_c.id                                                           AS courseid,\n       kbi_c.fullname                                                     AS course,\n       kbi_cc.name                                                        AS category_name,\n       WEEKDAY(FROM_UNIXTIME(kbi_l.timepoint))                            AS weekday_number,\n       CASE WEEKDAY(FROM_UNIXTIME(kbi_l.timepoint))\n         WHEN 0 THEN \'Monday\'\n         WHEN 1 THEN \'Tuesday\'\n         WHEN 2 THEN \'Wednesday\'\n         WHEN 3 THEN \'Thursday\'\n         WHEN 4 THEN \'Friday\'\n         WHEN 5 THEN \'Saturday\'\n         ELSE \'Sunday\'\n       END                                                                AS weekday_name,\n       CASE\n         WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 6 THEN \'00:00 - 05:59\'\n         WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 9 THEN \'06:00 - 08:59\'\n         WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 12 THEN \'09:00 - 11:59\'\n         WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 15 THEN \'12:00 - 14:59\'\n         WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 18 THEN \'15:00 - 17:59\'\n         WHEN HOUR(FROM_UNIXTIME(kbi_l.timepoint)) < 21 THEN \'18:00 - 20:59\'\n         ELSE \'21:00 - 23:59\'\n       END                                                                AS active_period,\n       SUM(kbi_l.visits)                                                  AS visits,\n       SUM(kbi_l.timespend)                                               AS timespend,\n       ROUND(SUM(kbi_l.timespend) / 3600, 2)                              AS hours_spent,\n       ROUND(SUM(kbi_l.timespend) * 100 / NULLIF(kbi_total.total_timespend, 0), 2) AS percent_of_user_course_time\nFROM mdl_local_kopere_bi_track_log kbi_l\n       JOIN mdl_local_kopere_bi_tracking kbi_t ON kbi_t.id = kbi_l.trackid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_t.courseid\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_t.userid\n       LEFT JOIN mdl_course_categories kbi_cc ON kbi_cc.id = kbi_c.category\n       JOIN (\n             SELECT kbi_t2.courseid,\n                    kbi_t2.userid,\n                    SUM(kbi_l2.timespend) AS total_timespend\n             FROM mdl_local_kopere_bi_track_log kbi_l2\n                    JOIN mdl_local_kopere_bi_tracking kbi_t2 ON kbi_t2.id = kbi_l2.trackid\n             WHERE kbi_t2.courseid > 1\n             GROUP BY kbi_t2.courseid, kbi_t2.userid\n       ) kbi_total ON kbi_total.courseid = kbi_t.courseid AND kbi_total.userid = kbi_t.userid\nWHERE kbi_t.courseid > 1\n  AND kbi_c.visible = 1\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username <> \'guest\'\nGROUP BY kbi_c.id, kbi_u.id, kbi_cc.id, weekday_number, active_period, kbi_total.total_timespend\nORDER BY kbi_c.fullname, kbi_u.lastname, kbi_u.firstname, weekday_number, active_period','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"string\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"idnumber\":{\"key\":\"idnumber\",\"title\":\"lang::report_field_idnumber_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"category_name\":{\"key\":\"category_name\",\"title\":\"lang::report_field_category_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"weekday_number\":{\"key\":\"weekday_number\",\"title\":\"lang::report_field_weekday_number_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"weekday_name\":{\"key\":\"weekday_name\",\"title\":\"lang::report_field_weekday_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"active_period\":{\"key\":\"active_period\",\"title\":\"lang::report_field_active_period_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"hours_spent\":{\"key\":\"hours_spent\",\"title\":\"lang::report_field_hours_spent_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"percent_of_user_course_time\":{\"key\":\"percent_of_user_course_time\",\"title\":\"lang::report_field_percent_of_user_course_time_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646822),
(108,'kbi_el_file_utilization_summary_by_course','lang::report_page_093_title::local_kopere_bi',103,1,'table','light','','','','SELECT kbi_r.id,\n       kbi_c.fullname,\n       kbi_r.name,\n       kbi_r.timemodified,\n       kbi_r.revision,\n       MAX(sl.visits)        AS visits,\n       MAX(sl.timespend)     AS timespend,\n       MAX(fs.files)         AS files,\n       MAX(fs.files_sorting) AS files_sorting\nFROM mdl_resource kbi_r\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_r.course\n       LEFT JOIN (SELECT kbi_cm.instance,\n                         GROUP_CONCAT(CASE\n                                        WHEN kbi_f.id IS NOT NULL THEN CONCAT(\'/\', kbi_ctx.id,\n                                                                          \'/mod_resource/content/[[revision]]\',\n                                                                          kbi_f.filepath, kbi_f.filename)\n                                        ELSE NULL END SEPARATOR \'[[,]]\') AS files,\n                         GROUP_CONCAT(kbi_f.filename)                        AS files_sorting\n                  FROM mdl_files kbi_f\n                         JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_f.contextid\n                         JOIN mdl_course_modules kbi_cm ON kbi_cm.id = kbi_ctx.instanceid\n                  WHERE kbi_f.component = \'mod_resource\'\n                    AND kbi_f.filearea = \'content\'\n                    AND kbi_f.itemid = 0\n                    AND kbi_f.filesize > 0\n                    AND kbi_cm.course = :courseid\n                  GROUP BY kbi_cm.instance) fs ON fs.instance = kbi_r.id\n       LEFT JOIN (SELECT kbi_cm.instance, SUM(kbi_lit.timespend) as timespend, SUM(kbi_lit.visits) as visits\n                  FROM mdl_local_kopere_bi_tracking kbi_lit, mdl_course_modules kbi_cm, mdl_modules kbi_m\n                  WHERE kbi_lit.page = \'module\'\n                    and kbi_cm.id = kbi_lit.param\n                    and kbi_m.id = kbi_cm.module\n                    and kbi_m.name = \'resource\'\n                  GROUP BY kbi_cm.instance) sl ON sl.instance = kbi_r.id\nWHERE kbi_r.id > 0\n  AND kbi_c.id = :courseid\n  AND kbi_c.visible = 1\nGROUP BY kbi_r.id, kbi_c.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"name\":{\"key\":\"name\",\"title\":\"lang::report_field_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timemodified\":{\"key\":\"timemodified\",\"title\":\"lang::report_field_timemodified_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"revision\":{\"key\":\"revision\",\"title\":\"lang::report_field_revision_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"visits\":{\"key\":\"visits\",\"title\":\"lang::report_field_visits_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timespend\":{\"key\":\"timespend\",\"title\":\"lang::report_field_timespend_title::local_kopere_bi\",\"type\":\"time\",\"mustache\":\"\"},\"files\":{\"key\":\"files\",\"title\":\"lang::report_field_files_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"files_sorting\":{\"key\":\"files_sorting\",\"title\":\"lang::report_field_files_sorting_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646822),
(109,'kbi_el_file_utilization_summary_by_instructor','lang::report_page_094_title::local_kopere_bi',104,1,'table','light','','','','SELECT kbi_c.id,\n       kbi_c.fullname,\n       count(kbi_r.id)                                     as resources,\n       GROUP_CONCAT(CASE\n                      WHEN kbi_f.id IS NOT NULL THEN CONCAT(\'/\', kbi_ctx.id, \'/mod_resource/content/\', kbi_r.revision, kbi_f.filepath,\n                                                        kbi_f.filename)\n                      ELSE NULL END SEPARATOR \'[[,]]\') AS files,\n       GROUP_CONCAT(kbi_f.filename)                        AS files_sorting,\n       (SELECT DISTINCT CONCAT(kbi_u.firstname, \' \', kbi_u.lastname)\n        FROM mdl_role_assignments kbi_ra\n               JOIN mdl_user kbi_u ON kbi_ra.userid = kbi_u.id\n               JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n        WHERE kbi_ctx.instanceid = kbi_c.id\n          AND kbi_ctx.contextlevel = 50\n          AND kbi_ra.roleid = 3\n        LIMIT 1)                                       AS teacher\nFROM mdl_course kbi_c\n       LEFT JOIN mdl_resource kbi_r ON kbi_r.course = kbi_c.id\n       LEFT JOIN mdl_modules kbi_m ON kbi_m.name = \'resource\'\n       LEFT JOIN mdl_course_modules kbi_cm ON kbi_cm.module = kbi_m.id AND kbi_cm.instance = kbi_r.id\n       LEFT JOIN mdl_context kbi_ctx ON kbi_ctx.contextlevel = 70 AND kbi_ctx.instanceid = kbi_cm.id\n       LEFT JOIN mdl_files kbi_f\n         ON kbi_f.component = \'mod_resource\' AND kbi_f.filearea = \'content\' AND kbi_f.itemid = 0 AND kbi_f.filesize > 0 AND\n            kbi_ctx.id = kbi_f.contextid\nWHERE kbi_c.id > 0\n  AND kbi_c.id = :courseid\n  AND kbi_c.visible = 1\nGROUP BY kbi_c.id','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"resources\":{\"key\":\"resources\",\"title\":\"lang::report_field_resources_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"files\":{\"key\":\"files\",\"title\":\"lang::report_field_files_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"files_sorting\":{\"key\":\"files_sorting\",\"title\":\"lang::report_field_files_sorting_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teacher\":{\"key\":\"teacher\",\"title\":\"lang::report_field_teacher_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646822),
(110,'kbi_el_file_utilization_summary_by_in','lang::report_page_095_title::local_kopere_bi',105,1,'table','light','','','','SELECT kbi_f.id,\n       kbi_c.id                                                                              AS courseid,\n       kbi_c.fullname,\n       kbi_u.id                                                                              AS userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.username,\n       CONCAT(\'/\', kbi_ctx.id, \'/mod_resource/content/\', kbi_r.revision, kbi_f.filepath, kbi_f.filename) AS file_path,\n       kbi_f.filename,\n       kbi_f.timecreated\nFROM mdl_course kbi_c\n       JOIN mdl_resource kbi_r ON kbi_r.course = kbi_c.id\n       JOIN mdl_modules kbi_m ON kbi_m.name = \'resource\'\n       JOIN mdl_course_modules kbi_cm ON kbi_cm.module = kbi_m.id AND kbi_cm.instance = kbi_r.id\n       JOIN mdl_context kbi_ctx ON kbi_ctx.contextlevel = 70 AND kbi_ctx.instanceid = kbi_cm.id\n       JOIN mdl_files kbi_f\n         ON kbi_f.component = \'mod_resource\' AND kbi_f.filearea = \'content\' AND kbi_f.itemid = 0 AND kbi_f.filesize > 0 AND\n            kbi_ctx.id = kbi_f.contextid\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_f.userid\nWHERE kbi_c.id > 0\n  AND kbi_c.id = :courseid\n  AND kbi_c.visible = 1\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\nORDER BY kbi_c.fullname, kbi_f.filename','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{fullname}}}<\\/a>\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"username\":{\"key\":\"username\",\"title\":\"lang::report_field_username_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"file_path\":{\"key\":\"file_path\",\"title\":\"lang::report_field_file_path_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"filename\":{\"key\":\"filename\",\"title\":\"lang::report_field_filename_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"timecreated\":{\"key\":\"timecreated\",\"title\":\"lang::report_field_timecreated_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"}}}',1780646822),
(111,'kbi_el_lesson_answers','lang::report_page_096_title::local_kopere_bi',106,1,'table','light','','','','SELECT kbi_la.id       AS id,\n       kbi_la.timeseen,\n       kbi_c.id        AS courseid,\n       kbi_c.fullname,\n       kbi_c.shortname,\n       kbi_u.id        AS userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_u.username,\n       t.id        AS teacher_userid,\n       t.firstname AS teacher_firstname,\n       t.lastname  As teacher_lastname,\n       t.email     AS teacher_email,\n       t.username  AS teacher_username,\n       kbi_l.name      AS lesson_name,\n       kbi_lp.contents AS question_name,\n       kbi_lp.qtype,\n       kbi_la.useranswer\nFROM mdl_lesson kbi_l\n       JOIN mdl_lesson_attempts kbi_la ON kbi_la.lessonid = kbi_l.id\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_l.course\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_la.userid\n       JOIN mdl_lesson_pages kbi_lp ON kbi_lp.id = kbi_la.pageid\n       LEFT JOIN (SELECT a.courseid, kbi_u.firstname, kbi_u.lastname, kbi_u.email, kbi_u.username, kbi_u.id\n                  FROM (SELECT kbi_ctx.instanceid AS courseid, MIN(kbi_ra.userid) AS userid\n                        FROM mdl_role_assignments kbi_ra\n                               JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid\n                        WHERE kbi_ctx.contextlevel = 50\n                          AND kbi_ra.roleid = 3\n                        GROUP BY kbi_ctx.instanceid) a\n                         JOIN mdl_user kbi_u ON kbi_u.id = a.userid) t ON t.courseid = kbi_c.id\nWHERE kbi_l.id > 0\n  AND kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username != \'guest\'\n  AND kbi_c.visible = 1','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"timeseen\":{\"key\":\"timeseen\",\"title\":\"lang::report_field_timeseen_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"fullname\":{\"key\":\"fullname\",\"title\":\"lang::report_field_fullname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{fullname}}}<\\/a>\"},\"shortname\":{\"key\":\"shortname\",\"title\":\"lang::report_field_shortname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"username\":{\"key\":\"username\",\"title\":\"lang::report_field_username_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teacher_userid\":{\"key\":\"teacher_userid\",\"title\":\"lang::report_field_teacher_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"teacher_firstname\":{\"key\":\"teacher_firstname\",\"title\":\"lang::report_field_teacher_firstname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teacher_lastname\":{\"key\":\"teacher_lastname\",\"title\":\"lang::report_field_teacher_lastname_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teacher_email\":{\"key\":\"teacher_email\",\"title\":\"lang::report_field_teacher_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"teacher_username\":{\"key\":\"teacher_username\",\"title\":\"lang::report_field_teacher_username_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"lesson_name\":{\"key\":\"lesson_name\",\"title\":\"lang::report_field_lesson_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"question_name\":{\"key\":\"question_name\",\"title\":\"lang::report_field_question_name_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"qtype\":{\"key\":\"qtype\",\"title\":\"lang::report_field_qtype_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"useranswer\":{\"key\":\"useranswer\",\"title\":\"lang::report_field_useranswer_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646822),
(112,'kbi_el_moodle_message_utilization','lang::report_page_097_title::local_kopere_bi',107,1,'table','light','','','','SELECT kbi_m.id,\n       kbi_uf.id                                         AS userid_from,\n       kbi_uf.firstname                                  AS firstname_from,\n       kbi_uf.lastname                                   AS lastname_from,\n       kbi_uf.email                                      AS email_from,\n       GROUP_CONCAT(DISTINCT kbi_rf.name SEPARATOR \', \') AS role_from,\n       kbi_m.timecreated,\n       kbi_ut.id                                         AS userid_to,\n       kbi_ut.firstname                                  AS firstname_to,\n       kbi_ut.lastname                                   AS lastname_to,\n       kbi_ut.email                                      AS email_to,\n       GROUP_CONCAT(DISTINCT kbi_rt.name SEPARATOR \', \') AS role_to\nFROM mdl_messages kbi_m\n       JOIN mdl_user kbi_uf ON kbi_uf.id = kbi_m.useridfrom\n       JOIN mdl_message_conversation_members kbi_mcm ON kbi_mcm.conversationid = kbi_m.conversationid AND kbi_mcm.userid <> kbi_m.useridfrom\n       JOIN mdl_user kbi_ut ON kbi_ut.id = kbi_mcm.userid\n       JOIN mdl_context kbi_ctx ON kbi_ctx.contextlevel = 10\n       LEFT JOIN mdl_role_assignments kbi_raf ON kbi_raf.contextid = kbi_ctx.id AND kbi_raf.userid = kbi_uf.id\n       LEFT JOIN mdl_role kbi_rf ON kbi_rf.id = kbi_raf.roleid\n       LEFT JOIN mdl_role_assignments kbi_rat ON kbi_rat.contextid = kbi_ctx.id AND kbi_rat.userid = kbi_ut.id\n       LEFT JOIN mdl_role kbi_rt ON kbi_rt.id = kbi_rat.roleid\nWHERE kbi_m.timecreated > 0\nGROUP BY kbi_m.id, kbi_uf.id, kbi_ut.id\nORDER BY kbi_m.timecreated DESC, kbi_uf.lastname, kbi_ut.lastname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"number\",\"mustache\":\"\"},\"userid_\":{\"key\":\"userid_\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646822),
(113,'kbi_el_student_course_progress_overview','lang::report_page_098_block_1_element_1_title::local_kopere_bi',108,1,'table','light','',NULL,NULL,'SELECT CONCAT(kbi_students.userid, \'-\', kbi_students.courseid) AS id,\n       kbi_students.userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_c.id AS courseid,\n       kbi_c.fullname AS course,\n       kbi_enrol.enrolled_at,\n       COALESCE(kbi_la.timeaccess, 0) AS course_lastaccess,\n       COALESCE(kbi_total.total_activities, 0) AS total_activities,\n       COALESCE(kbi_done.completed_activities, 0) AS completed_activities,\n       CASE\n         WHEN COALESCE(kbi_total.total_activities, 0) > 0 THEN ROUND((COALESCE(kbi_done.completed_activities, 0) / kbi_total.total_activities) * 100, 2)\n         ELSE 0\n       END AS progress_percent,\n       ROUND(kbi_grade.finalgrade, 2) AS finalgrade,\n       ROUND(kbi_grade.grade_percent, 2) AS grade_percent,\n       kbi_cc.timecompleted,\n       CASE\n         WHEN kbi_cc.timecompleted IS NOT NULL THEN \'Completed\'\n         WHEN COALESCE(kbi_done.completed_activities, 0) > 0 THEN \'In progress\'\n         WHEN COALESCE(kbi_la.timeaccess, 0) > 0 THEN \'Accessed\'\n         ELSE \'Not started\'\n       END AS student_status\nFROM (SELECT DISTINCT kbi_ra.userid,\n                kbi_ctx.instanceid AS courseid\nFROM mdl_role_assignments kbi_ra\n       JOIN mdl_role kbi_r ON kbi_r.id = kbi_ra.roleid\n       JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\nWHERE kbi_r.shortname = \'student\') kbi_students\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_students.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_students.courseid\n       LEFT JOIN (SELECT kbi_ue.userid,\n       kbi_e.courseid,\n       MIN(kbi_ue.id) AS enrolmentid,\n       COALESCE(MIN(NULLIF(kbi_ue.timestart, 0)), MIN(kbi_ue.timecreated)) AS enrolled_at,\n       MAX(kbi_ue.timeend) AS enrol_timeend\nFROM mdl_enrol kbi_e\n       JOIN mdl_user_enrolments kbi_ue ON kbi_ue.enrolid = kbi_e.id\nWHERE kbi_e.status = 0\n  AND kbi_ue.status = 0\n  AND (kbi_ue.timeend = 0 OR kbi_ue.timeend > UNIX_TIMESTAMP())\nGROUP BY kbi_ue.userid, kbi_e.courseid) kbi_enrol ON kbi_enrol.userid = kbi_students.userid AND kbi_enrol.courseid = kbi_students.courseid\n       LEFT JOIN mdl_user_lastaccess kbi_la ON kbi_la.userid = kbi_students.userid AND kbi_la.courseid = kbi_students.courseid\n       LEFT JOIN (SELECT kbi_cm.course,\n       COUNT(DISTINCT kbi_cm.id) AS total_activities\nFROM mdl_course_modules kbi_cm\nWHERE kbi_cm.deletioninprogress = 0\n  AND kbi_cm.visible = 1\n  AND kbi_cm.completion > 0\nGROUP BY kbi_cm.course) kbi_total ON kbi_total.course = kbi_students.courseid\n       LEFT JOIN (SELECT kbi_cm.course,\n       kbi_cmc.userid,\n       COUNT(DISTINCT kbi_cmc.coursemoduleid) AS completed_activities\nFROM mdl_course_modules kbi_cm\n       JOIN mdl_course_modules_completion kbi_cmc ON kbi_cmc.coursemoduleid = kbi_cm.id\nWHERE kbi_cm.deletioninprogress = 0\n  AND kbi_cm.visible = 1\n  AND kbi_cm.completion > 0\n  AND kbi_cmc.completionstate IN (1, 2)\nGROUP BY kbi_cm.course, kbi_cmc.userid) kbi_done ON kbi_done.course = kbi_students.courseid AND kbi_done.userid = kbi_students.userid\n       LEFT JOIN (SELECT kbi_gi.courseid,\n       kbi_gg.userid,\n       kbi_gi.gradepass,\n       kbi_gi.grademax,\n       kbi_gg.finalgrade,\n       CASE\n         WHEN kbi_gi.grademax > 0 AND kbi_gg.finalgrade IS NOT NULL THEN ROUND((kbi_gg.finalgrade / kbi_gi.grademax) * 100, 2)\n         ELSE NULL\n       END AS grade_percent\nFROM mdl_grade_items kbi_gi\n       JOIN mdl_grade_grades kbi_gg ON kbi_gg.itemid = kbi_gi.id\nWHERE kbi_gi.itemtype = \'course\') kbi_grade ON kbi_grade.courseid = kbi_students.courseid AND kbi_grade.userid = kbi_students.userid\n       LEFT JOIN mdl_course_completions kbi_cc ON kbi_cc.course = kbi_students.courseid AND kbi_cc.userid = kbi_students.userid\nWHERE kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username <> \'guest\'\n  AND kbi_c.visible = 1\nORDER BY kbi_c.fullname, kbi_u.lastname, kbi_u.firstname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"string\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"enrolled_at\":{\"key\":\"enrolled_at\",\"title\":\"lang::report_field_enrolled_at_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"course_lastaccess\":{\"key\":\"course_lastaccess\",\"title\":\"lang::report_field_course_lastaccess_title::local_kopere_bi\",\"type\":\"datetimeRenderer\",\"mustache\":\"\"},\"total_activities\":{\"key\":\"total_activities\",\"title\":\"lang::report_field_total_activities_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completed_activities\":{\"key\":\"completed_activities\",\"title\":\"lang::report_field_completed_activities_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"progress_percent\":{\"key\":\"progress_percent\",\"title\":\"lang::report_field_progress_percent_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"finalgrade\":{\"key\":\"finalgrade\",\"title\":\"lang::report_field_finalgrade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade_percent\":{\"key\":\"grade_percent\",\"title\":\"lang::report_field_grade_percent_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"timecompleted\":{\"key\":\"timecompleted\",\"title\":\"lang::report_field_timecompleted_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"student_status\":{\"key\":\"student_status\",\"title\":\"lang::report_field_student_status_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646822),
(114,'kbi_el_students_without_course_access','lang::report_page_099_block_1_element_1_title::local_kopere_bi',109,1,'table','light','',NULL,NULL,'SELECT CONCAT(kbi_students.userid, \'-\', kbi_students.courseid) AS id,\n       kbi_students.userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_c.id AS courseid,\n       kbi_c.fullname AS course,\n       kbi_enrol.enrolled_at,\n       kbi_u.lastaccess AS site_lastaccess,\n       COALESCE(kbi_la.timeaccess, 0) AS course_lastaccess,\n       CASE\n         WHEN kbi_enrol.enrolled_at IS NULL THEN NULL\n         ELSE DATEDIFF(NOW(), FROM_UNIXTIME(kbi_enrol.enrolled_at))\n       END AS days_since_enrolment\nFROM (SELECT DISTINCT kbi_ra.userid,\n                kbi_ctx.instanceid AS courseid\nFROM mdl_role_assignments kbi_ra\n       JOIN mdl_role kbi_r ON kbi_r.id = kbi_ra.roleid\n       JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\nWHERE kbi_r.shortname = \'student\') kbi_students\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_students.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_students.courseid\n       LEFT JOIN (SELECT kbi_ue.userid,\n       kbi_e.courseid,\n       MIN(kbi_ue.id) AS enrolmentid,\n       COALESCE(MIN(NULLIF(kbi_ue.timestart, 0)), MIN(kbi_ue.timecreated)) AS enrolled_at,\n       MAX(kbi_ue.timeend) AS enrol_timeend\nFROM mdl_enrol kbi_e\n       JOIN mdl_user_enrolments kbi_ue ON kbi_ue.enrolid = kbi_e.id\nWHERE kbi_e.status = 0\n  AND kbi_ue.status = 0\n  AND (kbi_ue.timeend = 0 OR kbi_ue.timeend > UNIX_TIMESTAMP())\nGROUP BY kbi_ue.userid, kbi_e.courseid) kbi_enrol ON kbi_enrol.userid = kbi_students.userid AND kbi_enrol.courseid = kbi_students.courseid\n       LEFT JOIN mdl_user_lastaccess kbi_la ON kbi_la.userid = kbi_students.userid AND kbi_la.courseid = kbi_students.courseid\nWHERE kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username <> \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_enrol.enrolled_at IS NOT NULL\n  AND COALESCE(kbi_la.timeaccess, 0) = 0\nORDER BY days_since_enrolment DESC, kbi_c.fullname, kbi_u.lastname, kbi_u.firstname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"string\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"enrolled_at\":{\"key\":\"enrolled_at\",\"title\":\"lang::report_field_enrolled_at_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"site_lastaccess\":{\"key\":\"site_lastaccess\",\"title\":\"lang::report_field_site_lastaccess_title::local_kopere_bi\",\"type\":\"datetimeRenderer\",\"mustache\":\"\"},\"course_lastaccess\":{\"key\":\"course_lastaccess\",\"title\":\"lang::report_field_course_lastaccess_title::local_kopere_bi\",\"type\":\"datetimeRenderer\",\"mustache\":\"\"},\"days_since_enrolment\":{\"key\":\"days_since_enrolment\",\"title\":\"lang::report_field_days_since_enrolment_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646822),
(115,'kbi_el_inactive_students_by_course','lang::report_page_100_block_1_element_1_title::local_kopere_bi',110,1,'table','light','',NULL,NULL,'SELECT CONCAT(kbi_students.userid, \'-\', kbi_students.courseid) AS id,\n       kbi_students.userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_c.id AS courseid,\n       kbi_c.fullname AS course,\n       kbi_enrol.enrolled_at,\n       kbi_u.lastaccess AS site_lastaccess,\n       COALESCE(kbi_la.timeaccess, 0) AS course_lastaccess,\n       CASE\n         WHEN COALESCE(kbi_la.timeaccess, 0) = 0 THEN NULL\n         ELSE DATEDIFF(NOW(), FROM_UNIXTIME(kbi_la.timeaccess))\n       END AS days_without_access,\n       COALESCE(kbi_total.total_activities, 0) AS total_activities,\n       COALESCE(kbi_done.completed_activities, 0) AS completed_activities,\n       CASE\n         WHEN COALESCE(kbi_total.total_activities, 0) > 0 THEN ROUND((COALESCE(kbi_done.completed_activities, 0) / kbi_total.total_activities) * 100, 2)\n         ELSE 0\n       END AS progress_percent\nFROM (SELECT DISTINCT kbi_ra.userid,\n                kbi_ctx.instanceid AS courseid\nFROM mdl_role_assignments kbi_ra\n       JOIN mdl_role kbi_r ON kbi_r.id = kbi_ra.roleid\n       JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\nWHERE kbi_r.shortname = \'student\') kbi_students\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_students.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_students.courseid\n       LEFT JOIN (SELECT kbi_ue.userid,\n       kbi_e.courseid,\n       MIN(kbi_ue.id) AS enrolmentid,\n       COALESCE(MIN(NULLIF(kbi_ue.timestart, 0)), MIN(kbi_ue.timecreated)) AS enrolled_at,\n       MAX(kbi_ue.timeend) AS enrol_timeend\nFROM mdl_enrol kbi_e\n       JOIN mdl_user_enrolments kbi_ue ON kbi_ue.enrolid = kbi_e.id\nWHERE kbi_e.status = 0\n  AND kbi_ue.status = 0\n  AND (kbi_ue.timeend = 0 OR kbi_ue.timeend > UNIX_TIMESTAMP())\nGROUP BY kbi_ue.userid, kbi_e.courseid) kbi_enrol ON kbi_enrol.userid = kbi_students.userid AND kbi_enrol.courseid = kbi_students.courseid\n       LEFT JOIN mdl_user_lastaccess kbi_la ON kbi_la.userid = kbi_students.userid AND kbi_la.courseid = kbi_students.courseid\n       LEFT JOIN (SELECT kbi_cm.course,\n       COUNT(DISTINCT kbi_cm.id) AS total_activities\nFROM mdl_course_modules kbi_cm\nWHERE kbi_cm.deletioninprogress = 0\n  AND kbi_cm.visible = 1\n  AND kbi_cm.completion > 0\nGROUP BY kbi_cm.course) kbi_total ON kbi_total.course = kbi_students.courseid\n       LEFT JOIN (SELECT kbi_cm.course,\n       kbi_cmc.userid,\n       COUNT(DISTINCT kbi_cmc.coursemoduleid) AS completed_activities\nFROM mdl_course_modules kbi_cm\n       JOIN mdl_course_modules_completion kbi_cmc ON kbi_cmc.coursemoduleid = kbi_cm.id\nWHERE kbi_cm.deletioninprogress = 0\n  AND kbi_cm.visible = 1\n  AND kbi_cm.completion > 0\n  AND kbi_cmc.completionstate IN (1, 2)\nGROUP BY kbi_cm.course, kbi_cmc.userid) kbi_done ON kbi_done.course = kbi_students.courseid AND kbi_done.userid = kbi_students.userid\nWHERE kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username <> \'guest\'\n  AND kbi_c.visible = 1\n  AND COALESCE(kbi_la.timeaccess, 0) > 0\n  AND kbi_la.timeaccess < (UNIX_TIMESTAMP() - (30 * 24 * 60 * 60))\nORDER BY days_without_access DESC, progress_percent ASC, kbi_c.fullname, kbi_u.lastname, kbi_u.firstname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"string\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"enrolled_at\":{\"key\":\"enrolled_at\",\"title\":\"lang::report_field_enrolled_at_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"site_lastaccess\":{\"key\":\"site_lastaccess\",\"title\":\"lang::report_field_site_lastaccess_title::local_kopere_bi\",\"type\":\"datetimeRenderer\",\"mustache\":\"\"},\"course_lastaccess\":{\"key\":\"course_lastaccess\",\"title\":\"lang::report_field_course_lastaccess_title::local_kopere_bi\",\"type\":\"datetimeRenderer\",\"mustache\":\"\"},\"days_without_access\":{\"key\":\"days_without_access\",\"title\":\"lang::report_field_days_without_access_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"total_activities\":{\"key\":\"total_activities\",\"title\":\"lang::report_field_total_activities_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completed_activities\":{\"key\":\"completed_activities\",\"title\":\"lang::report_field_completed_activities_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"progress_percent\":{\"key\":\"progress_percent\",\"title\":\"lang::report_field_progress_percent_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646822),
(116,'kbi_el_students_at_risk','lang::report_page_101_block_1_element_1_title::local_kopere_bi',111,1,'table','light','',NULL,NULL,'SELECT kbi_base.*,\n       CASE\n         WHEN COALESCE(kbi_base.course_lastaccess, 0) = 0 THEN \'High\'\n         WHEN kbi_base.days_without_access >= 30 AND kbi_base.progress_percent < 50 THEN \'High\'\n         WHEN kbi_base.gradepass > 0 AND kbi_base.finalgrade IS NOT NULL AND kbi_base.finalgrade < kbi_base.gradepass THEN \'High\'\n         WHEN kbi_base.days_without_access >= 14 OR kbi_base.progress_percent < 25 THEN \'Medium\'\n         ELSE \'Low\'\n       END AS risk_level,\n       CASE\n         WHEN COALESCE(kbi_base.course_lastaccess, 0) = 0 THEN \'No course access\'\n         WHEN kbi_base.days_without_access >= 30 AND kbi_base.progress_percent < 50 THEN \'Long inactivity and low progress\'\n         WHEN kbi_base.gradepass > 0 AND kbi_base.finalgrade IS NOT NULL AND kbi_base.finalgrade < kbi_base.gradepass THEN \'Grade below pass mark\'\n         WHEN kbi_base.days_without_access >= 14 THEN \'Recent inactivity\'\n         WHEN kbi_base.progress_percent < 25 THEN \'Low activity progress\'\n         ELSE \'Monitor\'\n       END AS risk_reason\nFROM (\nSELECT CONCAT(kbi_students.userid, \'-\', kbi_students.courseid) AS id,\n       kbi_students.userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_c.id AS courseid,\n       kbi_c.fullname AS course,\n       kbi_enrol.enrolled_at,\n       COALESCE(kbi_la.timeaccess, 0) AS course_lastaccess,\n       CASE\n         WHEN COALESCE(kbi_la.timeaccess, 0) = 0 THEN NULL\n         ELSE DATEDIFF(NOW(), FROM_UNIXTIME(kbi_la.timeaccess))\n       END AS days_without_access,\n       COALESCE(kbi_total.total_activities, 0) AS total_activities,\n       COALESCE(kbi_done.completed_activities, 0) AS completed_activities,\n       CASE\n         WHEN COALESCE(kbi_total.total_activities, 0) > 0 THEN ROUND((COALESCE(kbi_done.completed_activities, 0) / kbi_total.total_activities) * 100, 2)\n         ELSE 0\n       END AS progress_percent,\n       ROUND(kbi_grade.finalgrade, 2) AS finalgrade,\n       ROUND(kbi_grade.grade_percent, 2) AS grade_percent,\n       ROUND(kbi_grade.gradepass, 2) AS gradepass\nFROM (SELECT DISTINCT kbi_ra.userid,\n                kbi_ctx.instanceid AS courseid\nFROM mdl_role_assignments kbi_ra\n       JOIN mdl_role kbi_r ON kbi_r.id = kbi_ra.roleid\n       JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\nWHERE kbi_r.shortname = \'student\') kbi_students\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_students.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_students.courseid\n       LEFT JOIN (SELECT kbi_ue.userid,\n       kbi_e.courseid,\n       MIN(kbi_ue.id) AS enrolmentid,\n       COALESCE(MIN(NULLIF(kbi_ue.timestart, 0)), MIN(kbi_ue.timecreated)) AS enrolled_at,\n       MAX(kbi_ue.timeend) AS enrol_timeend\nFROM mdl_enrol kbi_e\n       JOIN mdl_user_enrolments kbi_ue ON kbi_ue.enrolid = kbi_e.id\nWHERE kbi_e.status = 0\n  AND kbi_ue.status = 0\n  AND (kbi_ue.timeend = 0 OR kbi_ue.timeend > UNIX_TIMESTAMP())\nGROUP BY kbi_ue.userid, kbi_e.courseid) kbi_enrol ON kbi_enrol.userid = kbi_students.userid AND kbi_enrol.courseid = kbi_students.courseid\n       LEFT JOIN mdl_user_lastaccess kbi_la ON kbi_la.userid = kbi_students.userid AND kbi_la.courseid = kbi_students.courseid\n       LEFT JOIN (SELECT kbi_cm.course,\n       COUNT(DISTINCT kbi_cm.id) AS total_activities\nFROM mdl_course_modules kbi_cm\nWHERE kbi_cm.deletioninprogress = 0\n  AND kbi_cm.visible = 1\n  AND kbi_cm.completion > 0\nGROUP BY kbi_cm.course) kbi_total ON kbi_total.course = kbi_students.courseid\n       LEFT JOIN (SELECT kbi_cm.course,\n       kbi_cmc.userid,\n       COUNT(DISTINCT kbi_cmc.coursemoduleid) AS completed_activities\nFROM mdl_course_modules kbi_cm\n       JOIN mdl_course_modules_completion kbi_cmc ON kbi_cmc.coursemoduleid = kbi_cm.id\nWHERE kbi_cm.deletioninprogress = 0\n  AND kbi_cm.visible = 1\n  AND kbi_cm.completion > 0\n  AND kbi_cmc.completionstate IN (1, 2)\nGROUP BY kbi_cm.course, kbi_cmc.userid) kbi_done ON kbi_done.course = kbi_students.courseid AND kbi_done.userid = kbi_students.userid\n       LEFT JOIN (SELECT kbi_gi.courseid,\n       kbi_gg.userid,\n       kbi_gi.gradepass,\n       kbi_gi.grademax,\n       kbi_gg.finalgrade,\n       CASE\n         WHEN kbi_gi.grademax > 0 AND kbi_gg.finalgrade IS NOT NULL THEN ROUND((kbi_gg.finalgrade / kbi_gi.grademax) * 100, 2)\n         ELSE NULL\n       END AS grade_percent\nFROM mdl_grade_items kbi_gi\n       JOIN mdl_grade_grades kbi_gg ON kbi_gg.itemid = kbi_gi.id\nWHERE kbi_gi.itemtype = \'course\') kbi_grade ON kbi_grade.courseid = kbi_students.courseid AND kbi_grade.userid = kbi_students.userid\nWHERE kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username <> \'guest\'\n  AND kbi_c.visible = 1\n) kbi_base\nWHERE COALESCE(kbi_base.course_lastaccess, 0) = 0\n   OR kbi_base.days_without_access >= 14\n   OR kbi_base.progress_percent < 25\n   OR (kbi_base.gradepass > 0 AND kbi_base.finalgrade IS NOT NULL AND kbi_base.finalgrade < kbi_base.gradepass)\nORDER BY FIELD(risk_level, \'High\', \'Medium\', \'Low\'), kbi_base.days_without_access DESC, kbi_base.progress_percent ASC, kbi_base.course, kbi_base.lastname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"string\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"enrolled_at\":{\"key\":\"enrolled_at\",\"title\":\"lang::report_field_enrolled_at_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"course_lastaccess\":{\"key\":\"course_lastaccess\",\"title\":\"lang::report_field_course_lastaccess_title::local_kopere_bi\",\"type\":\"datetimeRenderer\",\"mustache\":\"\"},\"days_without_access\":{\"key\":\"days_without_access\",\"title\":\"lang::report_field_days_without_access_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"total_activities\":{\"key\":\"total_activities\",\"title\":\"lang::report_field_total_activities_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completed_activities\":{\"key\":\"completed_activities\",\"title\":\"lang::report_field_completed_activities_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"progress_percent\":{\"key\":\"progress_percent\",\"title\":\"lang::report_field_progress_percent_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"finalgrade\":{\"key\":\"finalgrade\",\"title\":\"lang::report_field_finalgrade_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"grade_percent\":{\"key\":\"grade_percent\",\"title\":\"lang::report_field_grade_percent_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"gradepass\":{\"key\":\"gradepass\",\"title\":\"lang::report_field_gradepass_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"risk_level\":{\"key\":\"risk_level\",\"title\":\"lang::report_field_risk_level_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"risk_reason\":{\"key\":\"risk_reason\",\"title\":\"lang::report_field_risk_reason_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646822),
(117,'kbi_el_student_enrolments_ending_soon','lang::report_page_102_block_1_element_1_title::local_kopere_bi',112,1,'table','light','',NULL,NULL,'SELECT CONCAT(kbi_ue.id, \'-\', kbi_c.id) AS id,\n       kbi_ue.id AS enrolid,\n       kbi_u.id AS userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_c.id AS courseid,\n       kbi_c.fullname AS course,\n       kbi_e.enrol AS enrol_method,\n       COALESCE(NULLIF(kbi_ue.timestart, 0), kbi_ue.timecreated) AS enrolled_at,\n       kbi_ue.timeend AS enrol_timeend,\n       DATEDIFF(FROM_UNIXTIME(kbi_ue.timeend), NOW()) AS days_to_end,\n       CASE\n         WHEN kbi_ue.timeend < UNIX_TIMESTAMP() THEN \'Expired\'\n         WHEN kbi_ue.timeend <= (UNIX_TIMESTAMP() + (7 * 24 * 60 * 60)) THEN \'Ends in 7 days\'\n         WHEN kbi_ue.timeend <= (UNIX_TIMESTAMP() + (30 * 24 * 60 * 60)) THEN \'Ends in 30 days\'\n         ELSE \'Scheduled\'\n       END AS expiry_status\nFROM mdl_user_enrolments kbi_ue\n       JOIN mdl_enrol kbi_e ON kbi_e.id = kbi_ue.enrolid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_e.courseid\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_ue.userid\n       JOIN mdl_context kbi_ctx ON kbi_ctx.instanceid = kbi_c.id AND kbi_ctx.contextlevel = 50\n       JOIN mdl_role_assignments kbi_ra ON kbi_ra.contextid = kbi_ctx.id AND kbi_ra.userid = kbi_u.id\n       JOIN mdl_role kbi_r ON kbi_r.id = kbi_ra.roleid AND kbi_r.shortname = \'student\'\nWHERE kbi_u.deleted = 0\n  AND kbi_u.username <> \'guest\'\n  AND kbi_c.visible = 1\n  AND kbi_e.status = 0\n  AND kbi_ue.timeend > 0\n  AND (kbi_ue.timeend < UNIX_TIMESTAMP() OR kbi_ue.timeend <= (UNIX_TIMESTAMP() + (30 * 24 * 60 * 60)))\nORDER BY kbi_ue.timeend, kbi_c.fullname, kbi_u.lastname, kbi_u.firstname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"string\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"enrolid\":{\"key\":\"enrolid\",\"title\":\"lang::report_field_enrolid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"enrol_method\":{\"key\":\"enrol_method\",\"title\":\"lang::report_field_enrol_method_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"enrolled_at\":{\"key\":\"enrolled_at\",\"title\":\"lang::report_field_enrolled_at_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"enrol_timeend\":{\"key\":\"enrol_timeend\",\"title\":\"lang::report_field_enrol_timeend_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"days_to_end\":{\"key\":\"days_to_end\",\"title\":\"lang::report_field_days_to_end_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"expiry_status\":{\"key\":\"expiry_status\",\"title\":\"lang::report_field_expiry_status_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"}}}',1780646822),
(118,'kbi_el_student_course_completion_status','lang::report_page_103_block_1_element_1_title::local_kopere_bi',113,1,'table','light','',NULL,NULL,'SELECT CONCAT(kbi_students.userid, \'-\', kbi_students.courseid) AS id,\n       kbi_students.userid,\n       kbi_u.firstname,\n       kbi_u.lastname,\n       kbi_u.email,\n       kbi_c.id AS courseid,\n       kbi_c.fullname AS course,\n       kbi_c.enablecompletion,\n       kbi_enrol.enrolled_at,\n       COALESCE(kbi_la.timeaccess, 0) AS course_lastaccess,\n       kbi_cc.timecompleted,\n       CASE\n         WHEN kbi_c.enablecompletion = 0 THEN \'Completion disabled\'\n         WHEN kbi_cc.timecompleted IS NOT NULL THEN \'Completed\'\n         WHEN COALESCE(kbi_la.timeaccess, 0) > 0 OR COALESCE(kbi_done.completed_activities, 0) > 0 THEN \'In progress\'\n         ELSE \'Not started\'\n       END AS completion_status,\n       COALESCE(kbi_total.total_activities, 0) AS total_activities,\n       COALESCE(kbi_done.completed_activities, 0) AS completed_activities,\n       CASE\n         WHEN COALESCE(kbi_total.total_activities, 0) > 0 THEN ROUND((COALESCE(kbi_done.completed_activities, 0) / kbi_total.total_activities) * 100, 2)\n         ELSE 0\n       END AS progress_percent\nFROM (SELECT DISTINCT kbi_ra.userid,\n                kbi_ctx.instanceid AS courseid\nFROM mdl_role_assignments kbi_ra\n       JOIN mdl_role kbi_r ON kbi_r.id = kbi_ra.roleid\n       JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\nWHERE kbi_r.shortname = \'student\') kbi_students\n       JOIN mdl_user kbi_u ON kbi_u.id = kbi_students.userid\n       JOIN mdl_course kbi_c ON kbi_c.id = kbi_students.courseid\n       LEFT JOIN (SELECT kbi_ue.userid,\n       kbi_e.courseid,\n       MIN(kbi_ue.id) AS enrolmentid,\n       COALESCE(MIN(NULLIF(kbi_ue.timestart, 0)), MIN(kbi_ue.timecreated)) AS enrolled_at,\n       MAX(kbi_ue.timeend) AS enrol_timeend\nFROM mdl_enrol kbi_e\n       JOIN mdl_user_enrolments kbi_ue ON kbi_ue.enrolid = kbi_e.id\nWHERE kbi_e.status = 0\n  AND kbi_ue.status = 0\n  AND (kbi_ue.timeend = 0 OR kbi_ue.timeend > UNIX_TIMESTAMP())\nGROUP BY kbi_ue.userid, kbi_e.courseid) kbi_enrol ON kbi_enrol.userid = kbi_students.userid AND kbi_enrol.courseid = kbi_students.courseid\n       LEFT JOIN mdl_user_lastaccess kbi_la ON kbi_la.userid = kbi_students.userid AND kbi_la.courseid = kbi_students.courseid\n       LEFT JOIN mdl_course_completions kbi_cc ON kbi_cc.course = kbi_students.courseid AND kbi_cc.userid = kbi_students.userid\n       LEFT JOIN (SELECT kbi_cm.course,\n       COUNT(DISTINCT kbi_cm.id) AS total_activities\nFROM mdl_course_modules kbi_cm\nWHERE kbi_cm.deletioninprogress = 0\n  AND kbi_cm.visible = 1\n  AND kbi_cm.completion > 0\nGROUP BY kbi_cm.course) kbi_total ON kbi_total.course = kbi_students.courseid\n       LEFT JOIN (SELECT kbi_cm.course,\n       kbi_cmc.userid,\n       COUNT(DISTINCT kbi_cmc.coursemoduleid) AS completed_activities\nFROM mdl_course_modules kbi_cm\n       JOIN mdl_course_modules_completion kbi_cmc ON kbi_cmc.coursemoduleid = kbi_cm.id\nWHERE kbi_cm.deletioninprogress = 0\n  AND kbi_cm.visible = 1\n  AND kbi_cm.completion > 0\n  AND kbi_cmc.completionstate IN (1, 2)\nGROUP BY kbi_cm.course, kbi_cmc.userid) kbi_done ON kbi_done.course = kbi_students.courseid AND kbi_done.userid = kbi_students.userid\nWHERE kbi_u.deleted = 0\n  AND kbi_u.suspended = 0\n  AND kbi_u.username <> \'guest\'\n  AND kbi_c.visible = 1\nORDER BY completion_status, kbi_c.fullname, kbi_u.lastname, kbi_u.firstname','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"string\",\"mustache\":\"\"},\"userid\":{\"key\":\"userid\",\"title\":\"lang::report_field_userid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"firstname\":{\"key\":\"firstname\",\"title\":\"lang::report_field_firstname_title::local_kopere_bi\",\"type\":\"userfullname\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/user\\/view.php?id={{{userid}}}\\\" target=\\\"profile\\\">{{{u_fullname}}}<\\/a>\"},\"lastname\":{\"key\":\"lastname\",\"title\":\"\",\"type\":\"none\",\"mustache\":\"\"},\"email\":{\"key\":\"email\",\"title\":\"lang::report_field_email_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"mailto:{{{email}}}\\\" target=\\\"_blank\\\">{{{email}}}<\\/a>\"},\"courseid\":{\"key\":\"courseid\",\"title\":\"lang::report_field_courseid_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"course\":{\"key\":\"course\",\"title\":\"lang::report_field_course_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"<a href=\\\"{{{config.wwwroot}}}\\/course\\/view.php?id={{{courseid}}}\\\" target=\\\"course\\\">{{{course}}}<\\/a>\"},\"enablecompletion\":{\"key\":\"enablecompletion\",\"title\":\"lang::report_field_enablecompletion_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"enrolled_at\":{\"key\":\"enrolled_at\",\"title\":\"lang::report_field_enrolled_at_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"course_lastaccess\":{\"key\":\"course_lastaccess\",\"title\":\"lang::report_field_course_lastaccess_title::local_kopere_bi\",\"type\":\"datetimeRenderer\",\"mustache\":\"\"},\"timecompleted\":{\"key\":\"timecompleted\",\"title\":\"lang::report_field_timecompleted_title::local_kopere_bi\",\"type\":\"datetime\",\"mustache\":\"\"},\"completion_status\":{\"key\":\"completion_status\",\"title\":\"lang::report_field_completion_status_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"total_activities\":{\"key\":\"total_activities\",\"title\":\"lang::report_field_total_activities_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"completed_activities\":{\"key\":\"completed_activities\",\"title\":\"lang::report_field_completed_activities_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"progress_percent\":{\"key\":\"progress_percent\",\"title\":\"lang::report_field_progress_percent_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646822),
(119,'kbi_el_student_registrations_by_month','lang::report_page_104_block_1_element_1_title::local_kopere_bi',114,1,'table','light','',NULL,NULL,'SELECT DATE_FORMAT(FROM_UNIXTIME(kbi_u.timecreated), \'%Y-%m\') AS id,\n       DATE_FORMAT(FROM_UNIXTIME(kbi_u.timecreated), \'%Y-%m\') AS period_month,\n       COUNT(DISTINCT kbi_u.id) AS student_count,\n       SUM(CASE WHEN kbi_u.deleted = 0 AND kbi_u.suspended = 0 THEN 1 ELSE 0 END) AS active_students,\n       SUM(CASE WHEN kbi_u.deleted = 0 AND kbi_u.suspended = 1 THEN 1 ELSE 0 END) AS suspended_students,\n       SUM(CASE WHEN kbi_u.deleted = 1 THEN 1 ELSE 0 END) AS deleted_students\nFROM mdl_user kbi_u\n       JOIN (\n             SELECT DISTINCT kbi_ra.userid\n             FROM mdl_role_assignments kbi_ra\n                    JOIN mdl_role kbi_r ON kbi_r.id = kbi_ra.roleid\n                    JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\n             WHERE kbi_r.shortname = \'student\'\n       ) kbi_students ON kbi_students.userid = kbi_u.id\nWHERE kbi_u.username <> \'guest\'\nGROUP BY period_month\nORDER BY period_month DESC','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"string\",\"mustache\":\"\"},\"period_month\":{\"key\":\"period_month\",\"title\":\"lang::report_field_period_month_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"student_count\":{\"key\":\"student_count\",\"title\":\"lang::report_field_student_count_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"active_students\":{\"key\":\"active_students\",\"title\":\"lang::report_field_active_students_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"suspended_students\":{\"key\":\"suspended_students\",\"title\":\"lang::report_field_suspended_students_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"deleted_students\":{\"key\":\"deleted_students\",\"title\":\"lang::report_field_deleted_students_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646822),
(120,'kbi_el_student_profile_distribution','lang::report_page_105_block_1_element_1_title::local_kopere_bi',115,1,'table','light','',NULL,NULL,'SELECT CONCAT(COALESCE(NULLIF(TRIM(kbi_u.country), \'\'), \'not-informed\'), \'-\',\n              COALESCE(NULLIF(TRIM(kbi_u.city), \'\'), \'not-informed\'), \'-\',\n              COALESCE(NULLIF(TRIM(kbi_u.institution), \'\'), \'not-informed\'), \'-\',\n              COALESCE(NULLIF(TRIM(kbi_u.department), \'\'), \'not-informed\')) AS id,\n       COALESCE(NULLIF(TRIM(kbi_u.country), \'\'), \'Not informed\') AS country,\n       COALESCE(NULLIF(TRIM(kbi_u.city), \'\'), \'Not informed\') AS city,\n       COALESCE(NULLIF(TRIM(kbi_u.institution), \'\'), \'Not informed\') AS institution,\n       COALESCE(NULLIF(TRIM(kbi_u.department), \'\'), \'Not informed\') AS department,\n       COUNT(DISTINCT kbi_u.id) AS student_count,\n       SUM(CASE WHEN kbi_u.suspended = 0 AND kbi_u.deleted = 0 THEN 1 ELSE 0 END) AS active_students,\n       SUM(CASE WHEN kbi_u.suspended = 1 AND kbi_u.deleted = 0 THEN 1 ELSE 0 END) AS suspended_students\nFROM mdl_user kbi_u\n       JOIN (\n             SELECT DISTINCT kbi_ra.userid\n             FROM mdl_role_assignments kbi_ra\n                    JOIN mdl_role kbi_r ON kbi_r.id = kbi_ra.roleid\n                    JOIN mdl_context kbi_ctx ON kbi_ctx.id = kbi_ra.contextid AND kbi_ctx.contextlevel = 50\n             WHERE kbi_r.shortname = \'student\'\n       ) kbi_students ON kbi_students.userid = kbi_u.id\nWHERE kbi_u.username <> \'guest\'\nGROUP BY country, city, institution, department\nORDER BY student_count DESC, country, city, institution, department','1h','none','{\"column\":{\"id\":{\"key\":\"id\",\"title\":\"#\",\"type\":\"string\",\"mustache\":\"\"},\"country\":{\"key\":\"country\",\"title\":\"lang::report_field_country_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"city\":{\"key\":\"city\",\"title\":\"lang::report_field_city_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"institution\":{\"key\":\"institution\",\"title\":\"lang::report_field_institution_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"department\":{\"key\":\"department\",\"title\":\"lang::report_field_department_title::local_kopere_bi\",\"type\":\"string\",\"mustache\":\"\"},\"student_count\":{\"key\":\"student_count\",\"title\":\"lang::report_field_student_count_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"active_students\":{\"key\":\"active_students\",\"title\":\"lang::report_field_active_students_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"},\"suspended_students\":{\"key\":\"suspended_students\",\"title\":\"lang::report_field_suspended_students_title::local_kopere_bi\",\"type\":\"number\",\"mustache\":\"\"}}}',1780646822);
