x 1050px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(3px 3px at 880px 1200px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(1px 1px at 1020px 1350px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(2px 2px at 1180px 1480px, #fff, rgba(0,0,0,0));\\r\\n    background-size: 200px 200px;\\r\\n    background-repeat: repeat;\\r\\n    opacity: 0.5;\\r\\n    pointer-events: none;\\r\\n    z-index: 0;\\r\\n    animation: twinkle 4s ease-in-out infinite;\\r\\n}\\r\\n\\r\\n@keyframes twinkle {\\r\\n    0%, 100% { opacity: 0.3; }\\r\\n    50% { opacity: 0.8; }\\r\\n}\\r\\n\\r\\nbody.pagelayout-login #page {\\r\\n    background: transparent !important;\\r\\n    position: relative;\\r\\n    z-index: 1;\\r\\n}\\r\\n\\r\\nbody.pagelayout-login .login-container {\\r\\n    background: rgba(255, 255, 255, 0.95) !important;\\r\\n    backdrop-filter: blur(2px);\\r\\n    border-radius: 24px !important;\\r\\n    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5), 0 0 0 1px rgba(255, 255, 255, 0.1) !important;\\r\\n    padding: 2.5rem !important;\\r\\n    max-width: 450px !important;\\r\\n    margin: 2rem auto !important;\\r\\n}\\r\\n\\r\\nbody.pagelayout-login .btn-primary {\\r\\n    background: linear-gradient(135deg, #1e3a8a 0%, #0f3460 100%) !important;\\r\\n    border: none !important;\\r\\n    border-radius: 12px !important;\\r\\n    padding: 0.75rem !important;\\r\\n    width: 100% !important;\\r\\n    transition: all 0.3s ease;\\r\\n}\\r\\n\\r\\nbody.pagelayout-login .btn-primary:hover {\\r\\n    background: linear-gradient(135deg, #2563eb 0%, #1e3a8a 100%) !important;\\r\\n    transform: translateY(-2px);\\r\\n    box-shadow: 0 10px 25px -5px rgba(30, 58, 138, 0.5);\\r\\n}\\r\\n\\r\\nbody.pagelayout-login .login-logo,\\r\\nbody.pagelayout-login .navbar-brand {\\r\\n    display: none !important;\\r\\n}\\r\\n\\r\\nbody.pagelayout-login .forgot-password a {\\r\\n    color: #1e3a8a !important;\\r\\n}\\r\\n\\r\\nbody.pagelayout-login .forgot-password a:hover {\\r\\n    co