 2px at 650px 700px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(1px 1px at 750px 380px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(3px 3px at 850px 900px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(1px 1px at 950px 480px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(2px 2px at 1050px 1100px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(1px 1px at 1150px 580px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(3px 3px at 1250px 1300px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(1px 1px at 1350px 680px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(2px 2px at 1450px 1500px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(1px 1px at 1550px 780px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(3px 3px at 1650px 1700px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(1px 1px at 1750px 880px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(2px 2px at 1850px 1900px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(1px 1px at 1950px 980px, #fff, rgba(0,0,0,0));\\r\\n    background-size: 200px 200px;\\r\\n    background-repeat: repeat;\\r\\n    opacity: 0.7;\\r\\n    pointer-events: none;\\r\\n    z-index: 0;\\r\\n}\\r\\n\\r\\n\\/* Bintang berkedip (animasi) *\\/\\r\\nbody.pagelayout-login::after {\\r\\n    content: \\\"\\\";\\r\\n    position: fixed;\\r\\n    top: 0;\\r\\n    left: 0;\\r\\n    width: 100%;\\r\\n    height: 100%;\\r\\n    background-image: \\r\\n        radial-gradient(1px 1px at 30px 120px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(2px 2px at 120px 250px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(1px 1px at 220px 450px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(3px 3px at 350px 600px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(1px 1px at 470px 800px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(2px 2px at 580px 950px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(1px 1px at 720px 1050px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(3px 3px at 880px 1200px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(1px 1px at 1020px 1350px, #fff, rgba(0,0,0,0)),\\r\\n        radial-gradient(2px 2px at 1180px 1480px, #fff, rgba(0,0,0,0));\\r\\n    background-size: 200px 200px;\\r\\n    background-repeat: repeat;\\r\\n    opacity: 0.5;\\r\\n    pointer-events: none;\\r\\n    z-index: 0;\\r\\n    animation: twinkle 4s ease-in-out infinite;\\r\\n}\\r\\n\\r\\n@keyframes twinkle {\\r\\n    0%, 100% { opacity: 0.3; }\\r\\n    50% { opacity: 0.8; }\\r\\n}\\r\\n\\r\\nbody.pagelayout-login #page {\\r\\n    background: transparent !important;\\r\\n    position: relative;\\r\\n    z-index: 1;\\r\\n}\\r\\n\\r\\nbody.pagelayout-login .login-container {\\r\\n    background: rgba(255, 255, 255, 0.95) !important;\\r\\n    backdrop-filter: blur(2px);\\r\\n    border-radius: 24px !important;\\r\\n    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5), 0 0 0 1px rgba(255, 255, 255, 0.1) !important;\\r\\n    padding: 2.5rem !important;\\r\\n    max-width: 450px !important;\\r\\n    margin: 2rem auto !important;\\r\\n}\\r\\n\\r\\nbody.pagelayout-login .btn-primary {\\r\\n    background: linear-gradient(135deg, #1e3a8a 0%, #0f3460 100%) !important;\\r\\n    border: none !important;\\r\\n    border-radius: 12px !important;\\r\\n    padding: 0.75rem !important;\\r\\n    width: 100% !important;\\r\\n    transition: all 0.3s ease;\\r\\n}\\r\\n\\r\\nbody.pagelayout-login .btn-primary:hover {\\r\\n    background: linear-gradient(135deg, #2563eb 0%, #1e3a8a 100%) !important;\\r\\n    transform: translateY(-2px);\\r\\n    box-shadow: 0 10px 25px -5px rgba(30, 58, 138, 0.5);\\r\\n}\\r\\n\\r\\nbody.pagelayout-login .login-logo,\\r\\nbody.pagelayout-login .navbar-brand {\\r\\n    display: none !important;\\r\\n}\\r\\n\\r\\nbody.pagelayout-login .forgot-password a {\\r\\n    color: #1e3a8a !important;\\r\\n}\\r\\n\\r\\nbody.pagelayout-login .forgot-password a:hover {\\r\\n    color: #2563eb !important;\\r\\n}\\r\\n\\r\\n\\/* ----- 17. RESPONSIVE --