(7,6,'vidio','',1,'<p>&lt;iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/ZiEGtC3CrNM\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen&gt;&lt;/iframe&gt;</p>',1,0,NULL,5,'a:2:{s:10:\"printintro\";s:1:\"0\";s:17:\"printlastmodified\";s:1:\"1\";}',1,1780573789);
