INSERT INTO `mdl_resource` VALUES
(1,2,'Panduan Belajar','<p>Pembelajaran calistung bertujuan untuk mengembangkan kemampuan dasar peserta didik dalam membaca, menulis, dan berhitung sebagai fondasi utama dalam proses belajar. Kegiatan pembelajaran dirancang secara menarik, interaktif, dan menyenangkan agar siswa dapat mengenal huruf, suku kata, kata, serta kalimat sederhana secara bertahap. Dalam aspek menulis, siswa dilatih untuk menyalin, menulis huruf, kata, dan kalimat dengan benar serta rapi. Sementara itu, pada aspek berhitung, siswa diperkenalkan dengan konsep angka, operasi hitung sederhana seperti penjumlahan dan pengurangan, serta penerapannya dalam kehidupan sehari-hari. Metode yang digunakan meliputi permainan edukatif, media visual, lagu, dan latihan praktik langsung untuk meningkatkan pemahaman dan keterampilan siswa secara optimal.</p>',1,0,0,NULL,0,'a:1:{s:10:\"printintro\";i:1;}',0,1,1777012690),
(2,2,'Modul belajar','',1,0,0,NULL,0,'a:1:{s:10:\"printintro\";i:1;}',0,1,1778212568),
(3,2,'modul 1','',1,0,0,NULL,0,'a:1:{s:10:\"printintro\";i:1;}',0,1,1778331944),
(4,2,'jurnal pembelajaran','<p>penjumlahan</p>',1,0,0,NULL,0,'a:3:{s:10:\"printintro\";i:1;s:8:\"showsize\";i:1;s:8:\"showdate\";i:1;}',0,1,1778485733),
